window.__SUM[13]={"LR005396":{"pair":"ADAM17 -> TNFRSF1A","headline":"No curated paper confirms this pair; support rests on one BioGRID record.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"TNFRSF1A is flagged transmembrane receptor [flag]; ADAM17 non-secreted [flag].","caveats":"No papers were verified: judged rows were different_entity (4) and abstract_insufficient (5), none confirming. The only support is a BioGRID Biochemical Activity record (PMID 17010968) [DB:BioGRID], which is enzymatic activity, not ligand binding.","key_references":[],"covers":["LR002070","LR005396"]},"LR003569":{"pair":"ADAM2 -> ITGB1","headline":"Mouse egg beta1 integrins (alpha6beta1) bind fertilin beta/ADAM2; two abstract-only papers.","interaction_type":"direct binding","direction_and_effect":"Fertilin beta binds directly to alpha6beta1 on the egg surface, mediating sperm-egg fusion [PMID:9889149]. Fertilin-coated beads bind eggs via alpha6beta1 and are blocked by anti-CD9 [PMID:10518536].","molecular_requirements":"ITGB1 acts as the beta subunit with alpha6; CD9 is needed for high-avidity binding [PMID:10518536][PMID:9889149].","affinity_potency":[],"species_and_systems":"Mouse eggs and sperm; bead and photoaffinity assays [PMID:9889149][PMID:10518536]. Human pair is ortholog-inferred.","localisation_and_range":"ADAM2 flagged non-secreted [flag]; sperm-egg contact.","caveats":"Both abstract only; beta1 alone not shown sufficient.","key_references":[{"PMID":"9889149","why":"Fertilin beta binds egg alpha6beta1 directly"},{"PMID":"10518536","why":"Bead binding via alpha6beta1; CD9 role"}],"covers":["LR000019","LR003569"]},"LR003578":{"pair":"ADCYAP1 -> VIPR1","headline":"PACAP-27 and PACAP-38 bind and activate VPAC1 with nanomolar affinity in recombinant systems; abstract-level evidence from several papers.","interaction_type":"direct binding","direction_and_effect":"PACAP is an agonist at VPAC1: PACAP-27 inhibited [125I]VIP binding with Ki 1.3 nM and PACAP-38 with Ki 6.8 nM in CHO cells with human VIP1 receptor [PMID:8791009]; GtoPdb lists Agonist [DB:GtoPdb]. In CHO cells expressing human VPAC1, cAMP and calcium responses were measured, with calcium EC50 values roughly 100-fold higher than cAMP [PMID:16930633].","molecular_requirements":"Single receptor chain. PACAP carboxy-terminal shortening raised VIP1 affinity, implicating that end in VIP1/VIP2 discrimination [PMID:9928018].","affinity_potency":[{"value":"Ki 1.3 nM","assay":"inhibition of [125I]VIP binding, PACAP-27","system":"CHO cells, recombinant human VIP1 receptor","cite":"PMID:8791009"},{"value":"Ki 6.8 nM","assay":"inhibition of [125I]VIP binding, PACAP-38","system":"CHO cells, recombinant human VIP1 receptor","cite":"PMID:8791009"},{"value":"Ki 0.9 nM","assay":"inhibition of [125I]VIP binding, VIP","system":"CHO cells, recombinant human VIP1 receptor","cite":"PMID:8791009"}],"species_and_systems":"Human recombinant receptor in CHO cells [PMID:8791009][PMID:16930633]; rat and human receptors compared [PMID:9928018]; rat and mouse islets [PMID:11897681].","localisation_and_range":"Ligand flagged secreted [flag]; peptide acting on a membrane receptor.","caveats":"All read as abstracts only. In islets the abstract does not separate VPAC1 from VPAC2 [PMID:11897681]. Seven confirmed rows but two others were different_entity and one abstract_insufficient. Structures exist [DB:PDB 6VN7].","key_references":[{"PMID":"8791009","why":"Ki values for PACAP-27 and PACAP-38 at human VIP1 receptor"},{"PMID":"16930633","why":"cAMP and calcium potency at hVPAC1R"},{"PMID":"9928018","why":"PACAP analogue binding on VIP1 and VIP2"}],"covers":["LR000028","LR003578"]},"LR003587":{"pair":"ADM -> RAMP2","headline":"ADM acts through CALCRL with RAMP2; confirmed in four abstract-only papers, RAMP2 being a co-receptor chain.","interaction_type":"direct binding","direction_and_effect":"RAMP2 confers an adrenomedullin-receptor phenotype on CRLR [PMID:9620797]. [125I]rADM binding was enhanced with hRAMP2 and inhibited by 50% when hRAMP1 was coexpressed [PMID:10342881]. GtoPdb lists ADM as full agonist [DB:GtoPdb]. Structures of CLR:RAMP2 with ADM exist [DB:PDB 4RWF].","molecular_requirements":"RAMP2 must pair with CLR (CALCRL); RAMPs are needed for CRLR surface transport [PMID:9620797]. RAMP2 and RAMP3 present CRLR as core-glycosylated ADM receptor [PMID:11693189].","affinity_potency":[{"value":"EC50 0.19 +/- 0.05 nM","assay":"rADM-induced CRE-luc reporter","system":"rat CRLR in UMR-106 cells","cite":"PMID:10342881"},{"value":"pKi 8.3-9.2","assay":"GtoPdb record","system":"HEK-293 per paper","cite":"PMID:11693189"}],"species_and_systems":"Human and rat receptors with rat ADM in UMR-106 and COS-7 cells, HEK-293 cells [PMID:10342881][PMID:11693189].","localisation_and_range":"ADM flagged secreted [flag].","caveats":"All abstract only. RAMP2 alone is not a receptor; the effect needs CRLR. Four further rows were abstract_insufficient. Mouse pair ortholog-inferred.","key_references":[{"PMID":"9620797","why":"RAMP2 confers ADM receptor phenotype"},{"PMID":"10342881","why":"rADM binding with RAMP2 and potency"},{"PMID":"30139742","why":"CLR-RAMP complex structure (AM2/IMD, not ADM)"}],"covers":["LR000037","LR003587"]},"LR008483":{"pair":"AFDN -> NECTIN2","headline":"Database-only protein interaction between AFDN and NECTIN2; no paper supports a ligand-receptor role.","interaction_type":"database-asserted only","direction_and_effect":"BioGRID lists affinity capture-Western and two-hybrid records; IntAct lists pull-down, two-hybrid and co-immunoprecipitation records for NECTIN2 with AFDN [DB:BioGRID][DB:IntAct].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species of the database experiments is not reported in our evidence.","localisation_and_range":"No localisation flag for AFDN; NECTIN2 flagged receptor and transmembrane [flag].","caveats":"No papers support this pair; judged papers were different_entity (3) or unresolvable (1). Support is database-only.","key_references":[],"covers":["LR008483"]},"LR006782":{"pair":"AMH -> ACVR1","headline":"AMH is reported to signal through ACVR1 (ALK2) as a type I receptor, mostly by statement; one in vivo/in vitro mouse paper and one negative fish screen.","interaction_type":"conflicting","direction_and_effect":"The abstract states AMH signals via AMHR2 and ALK2/3, and an AMH-responsive luciferase reporter was run with AMHR2 and ALK2 expressed, where mature AMH raised activity [PMID:41700980]. GtoPdb lists agonist [DB:GtoPdb]; UniProt says AMHR2 heterodimerises with type I receptors including ACVR1 [DB:UniProt].","molecular_requirements":"AMH needs proteolytic maturation (140 kDa precursor to 25 kDa mature dimer) for bioactivity [PMID:41700980]. Signalling requires AMHR2 as type II receptor [DB:UniProt].","affinity_potency":[],"species_and_systems":"Mouse AMH in HEK293 cells and C57Bl6/J mice [PMID:41700980]; the negative result is from Nile tilapia reporter assays [PMID:41656994].","localisation_and_range":"AMH flagged secreted [flag].","caveats":"A teleost reporter screen found Alk2a/Alk2b not among activators of Amhy/Amhr2 signalling, only Alk3, Alk6a, Alk6b [PMID:41656994]. The positive paper was read as abstract only for the curator, and ACVR1 is one of several type I options; ACVR1 alone as direct receptor is not shown.","key_references":[{"PMID":"41700980","why":"AMH maturation signalling via AMHR2 and ALK2/3, in vitro and mouse"},{"PMID":"41656994","why":"Negative: fish type I receptor screen without Alk2"}],"covers":["LR006782"]},"LR000959":{"pair":"ANOS1 -> FGFR1","headline":"Anosmin-1 binds FGFR1 directly with high affinity (no number), supported by several databases.","interaction_type":"direct binding","direction_and_effect":"Anosmin-1 directly binds FGFR1 with high affinity via its N-terminal domains to the D2-D3 extracellular domains; curator labels it agonist, but the paper shows context-dependent effects [PMID:19696444]. Pre-bound anosmin-1 prevents FGFR1-FGF2-heparin ternary complex formation, while heparin-bound anosmin-1 joins a pre-formed FGF2-FGFR1 complex, with opposing chemotaxis effects on human neuronal cells [PMID:19696444].","molecular_requirements":"Binding depends on FGF2 and heparin order of assembly; selectivity is FGFR1 high, FGFR2IIIc much lower and FGFR3IIIc negligible [PMID:19696444].","affinity_potency":[],"species_and_systems":"Human proteins in vitro and Transwell chemotaxis of human neuronal cells [PMID:19696444]. Human pair only.","localisation_and_range":"ANOS1 flagged secreted; FGFR1 transmembrane [flag]; matrix and cell-surface with heparin.","caveats":"Abstract only; no numerical affinity. Databases list BioGRID reconstituted complex, IntAct cross-linking and Reactome FGFR1c:KAL1 [DB:BioGRID] [DB:IntAct] [DB:Reactome].","key_references":[{"PMID":"19696444","why":"Anosmin-1 binds FGFR1 with high affinity and modulates ternary complexes"}],"covers":["LR000959"]},"LR007097":{"pair":"APLP2 -> PIGR","headline":"Supported only by one IntAct surface plasmon resonance record; no curator-verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence. IntAct lists a surface plasmon resonance record (Q06481-P01833) citing PMID 35922511 [DB:IntAct].","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species and system not reported in our evidence.","localisation_and_range":"Both partners carry transmembrane and receptor flags [flag], so a contact-dependent interaction would be expected, but this is not shown.","caveats":"The one paper judged was classed abstract_insufficient, so no curator-verified evidence exists. Rests on a single database record.","key_references":[],"covers":["LR007097"]},"LR009257":{"pair":"APOA4 -> LRP1","headline":"One mouse study (abstract) identifies LRP1 as an APOA4 interactor needed for APOA4-induced glucose uptake.","interaction_type":"functional only","direction_and_effect":"LRP1 was identified by co-immunoprecipitation and mass spectrometry as an APOA4 partner in adipose tissue; APOA4 promoted glucose uptake in 3T3-L1 adipocytes and LRP1 knockdown abrogated glucose uptake and PI3K-AKT activation [PMID:34168225]. LRP1 is described as the cognate receptor.","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse gonadal fat tissue and 3T3-L1 adipocytes; the pair is listed for human [PMID:34168225].","localisation_and_range":"LRP1 colocalized with APOA4 in adipocytes; interaction was seen under fasting and enhanced on lipid feeding [PMID:34168225]. LRP1 carries a receptor flag [flag].","caveats":"Co-IP and knockdown do not prove direct binding. Abstract only; one review-only row and one abstract_insufficient row also exist.","key_references":[{"PMID":"34168225","why":"LRP1 as APOA4 receptor in adipose tissue"}],"covers":["LR009257"]},"LR005459":{"pair":"APOC1 -> VLDLR","headline":"No evidence that APOC1 binds VLDLR as a ligand; the one paper judged shows APOC1 inhibits lipoprotein clearance via VLDLR.","interaction_type":"database-asserted only","direction_and_effect":"The paper indicates apoC1 inhibits clearance of lipoprotein particles via the VLDLR, not via the LDLR, and VLDLR gene transfer did not reduce hyperlipidaemia in APOC1 transgenic mice [PMID:10024503]. That is an inhibitor-of-VLDL-binding effect, not APOC1 acting as a VLDLR ligand.","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"APOC1 transgenic, LDLR-deficient and wild-type mice with adenoviral gene transfer; CHO cells expressing VLDLR [PMID:10024503].","localisation_and_range":"APOC1 flagged secreted; VLDLR carries transmembrane and receptor flags [flag].","caveats":"Curators judged this paper pair_absent (two such rows), with one review-only and four abstract_insufficient. Reactome records cover VLDLR binding VLDL, not APOC1 [DB:Reactome].","key_references":[],"covers":["LR002142","LR005459"]},"LR005468":{"pair":"APP -> AGER","headline":"One 1996 abstract reports RAGE as a receptor for amyloid-beta (APP-derived peptide); no affinity shown.","interaction_type":"functional only","direction_and_effect":"RAGE was presented as a cell-surface receptor for amyloid-beta peptide, mediating its effects on neurons and microglia [PMID:8751438]. UniProt describes AGER as sensing amyloid beta/APP oligomers [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins and brain; details not reported in our evidence [PMID:8751438].","localisation_and_range":"APP flagged secreted, receptor and transmembrane; the active ligand is the secreted peptide [flag].","caveats":"Ligand evidence concerns the amyloid-beta peptide, not full-length APP. Abstract only.","key_references":[{"PMID":"8751438","why":"RAGE as amyloid-beta receptor"}],"covers":["LR002153","LR005468"]},"LR008906":{"pair":"APP -> CAV1","headline":"No paper evidence; only BioGRID co-fractionation and IntAct two-hybrid records.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence. BioGRID lists co-fractionation and a Protein-RNA entry for APP-CAV1 [DB:BioGRID]; IntAct lists a two-hybrid array association [DB:IntAct].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Not reported in our evidence beyond a receptor flag on CAV1 [flag].","caveats":"The one judged paper was classed different_entity. Database evidence is co-fractionation and two-hybrid, not binding of a ligand to a receptor.","key_references":[],"covers":["LR008906"]},"LR005477":{"pair":"APP -> LRP4","headline":"APP binds LRP4 in recombinant and cell-aggregation assays, and mouse genetics support cooperation at the neuromuscular junction.","interaction_type":"direct binding","direction_and_effect":"APP interacts with LRP4, and agrin also binds APP and cooperatively enhances APP-LRP4 interaction; APP synergistically increased agrin-induced AChR clustering in myotubes [PMID:23986861]. APP-/- combined with LRP4 ECD/ECD gave smaller and fewer NMJs and perinatal lethality [PMID:23986861].","molecular_requirements":"Agrin enhances the interaction; LRP4 is the obligate co-receptor for MuSK [PMID:23986861]. Interaction is ectodomain-dependent: LRP4 ligand-binding domain (MBP fusion) bound APP ECD (Fc fusion) [PMID:23986861].","affinity_potency":[],"species_and_systems":"Recombinant fusion proteins, 293-cell aggregation and cultured myotubes; mouse NMJ genetics [PMID:23986861]. Human pair is ortholog-inferred.","localisation_and_range":"Membrane-bound pair acting at the NMJ; cell aggregation suggests trans interaction, consistent with APP and LRP4 on neighbouring cells [PMID:23986861].","caveats":"Single paper, abstract plus excerpts, no database record. APP-LRP4 may act as a hetero-oligomeric complex with agrin rather than a simple ligand-receptor pair. Affinity not reported in our evidence.","key_references":[{"PMID":"23986861","why":"APP-LRP4-agrin interaction at the NMJ"}],"covers":["LR002162","LR005477"]},"LR009464":{"pair":"B2M -> CD1A","headline":"B2M and CD1A are recorded as a structurally resolved complex; no verified paper, database evidence only.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence; records describe a CD1A:B2M complex [DB:Reactome R-HSA-8848844] and crystal structures of CD1a with a sulfatide [DB:PDB 1ONQ] and a synthetic mycobactin lipopeptide [DB:PDB 1XZ0].","molecular_requirements":"IntAct lists direct interaction by x-ray crystallography [DB:IntAct EBI-1036784]; 29 PDB records contain both chains [DB:PDB 1ONQ].","affinity_potency":[],"species_and_systems":"Human proteins in the database records; no paper-level evidence in our evidence set.","localisation_and_range":"B2M is flagged secreted [flag]; range is otherwise not reported in our evidence.","caveats":"No curator-verified paper supports this pair; it rests on database records alone (IntAct, PDB, Reactome). Judged row was classified different_entity.","key_references":[],"covers":["LR009464"]},"LR005486":{"pair":"BGLAP -> GPR158","headline":"Mouse genetics and a pull-down support GPR158 as a hippocampal osteocalcin receptor; human pair is ortholog-inferred.","interaction_type":"functional only","direction_and_effect":"Osteocalcin acts on Gpr158 in CA3 hippocampal neurons; Gpr158 is identified as transducing osteocalcin's regulation of hippocampal-dependent memory in part through inositol 1,4,5-trisphosphate and brain-derived neurotrophic factor [PMID:28851741]. Biotin-labeled osteocalcin pulled down a complex with Gpr158 and Galpha-q, greatly reduced in Gpr158-/- membranes [PMID:28851741]. Osteocalcin did not increase cAMP [PMID:28851741]. Effect is agonist-like.","molecular_requirements":"Galpha-q is in the complex and IP3 production is greater in WT than Gpr158-/- neurons [PMID:28851741]. Other requirements not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse (knockout mice, hippocampal neurons and membranes); the human pair is ortholog-inferred [PMID:28851741].","localisation_and_range":"Osteocalcin has a secreted flag [flag]; acts from circulation on neurons, with local delivery into the hippocampus also tested [PMID:28851741].","caveats":"Abstract plus full-text excerpts of one paper. The pull-down is on solubilised membranes, not purified protein, so direct binding is not shown. No affinity reported.","key_references":[{"PMID":"28851741","why":"Gpr158 mediates osteocalcin's regulation of cognition in mice"}],"covers":["LR002172","LR005486"]},"LR003659":{"pair":"BMP10 -> ENG","headline":"Direct binding shown by SPR for soluble endoglin; it acts as an inhibitory decoy for BMP10, not a signalling receptor.","interaction_type":"direct binding","direction_and_effect":"Mouse and human endoglin ECD-Fc bound BMP9 and BMP10 directly, specifically and with high affinity in SPR (Biacore) and cell-based assays; the ECD-Fc is anti-angiogenic, reducing VEGF-induced vessel formation and tumour burden [PMID:21737454]. Curators classify it as an antagonist/decoy.","molecular_requirements":"The BMP9/BMP10 binding site is the orphan domain, residues 26-359 of human endoglin; endoglin and type II receptors bind overlapping sites on BMP9 [PMID:21737454].","affinity_potency":[],"species_and_systems":"Recombinant ECD-Fc fusions, chick chorioallantoic membrane and mouse tumour models [PMID:21737454]. Curators annotate human ligand and receptor; mouse pair is ortholog-inferred.","localisation_and_range":"The tested form is the soluble extracellular domain; membrane endoglin was not tested for BMP10 here. BMP10 is annotated as secreted [flag]. UniProt records the BMP10-ENG interaction citing this paper [DB:UniProt].","caveats":"Abstract read only; no affinity number in our evidence. The overlapping-site result is stated for BMP9, not BMP10. One further row is still pending.","key_references":[{"PMID":"21737454","why":"Soluble endoglin binds BMP9/BMP10 via orphan domain"}],"covers":["LR000110","LR003659"]},"LR003668":{"pair":"BMP2 -> BMPR1A","headline":"Well supported direct binding: crystal structure, mutational mapping, gel filtration and SPR with human proteins.","interaction_type":"direct binding","direction_and_effect":"BMP2 is the ligand and BMPR1A (BRIA) the type I receptor; effect recorded as stimulatory/agonist [DB:GtoPdb]. The BMP-2 L51P variant lost type I receptor binding only, keeping type II and noggin binding [PMID:15064755]. A GDF5 variant with higher BMPR1A affinity gained BMP2-like properties, and BMP2 was almost completely inhibited by the BMPR1A ectodomain, which the paper cites as earlier work [PMID:19956691].","molecular_requirements":"Two BRIA ectodomains bind one BMP-2 dimer at the wrist epitopes, with no contacts between the receptor domains [PMID:10881198]; BMP-2 forms a 1:2 complex with sBMPR-IA [PMID:10692589]. Leu51 and Asp53 main-chain atoms of BMP-2 are a binding hot spot [PMID:15064755]. Signalling needs a type II chain too [DB:UniProt].","affinity_potency":[{"value":"apparent KD 0.8 nM","assay":"SPR, immobilized BMPR-IA ectodomain","system":"recombinant ligand and receptor ectodomains","cite":"PMID:19735544"},{"value":"KD 48 nM","assay":"SPR with immobilized BMP2, soluble BMPR-IA (no avidity)","system":"recombinant proteins","cite":"PMID:19735544"}],"species_and_systems":"Human proteins for the crystal structure, gel filtration and SPR [PMID:10881198][PMID:10692589]; human and mouse pairs both listed. Mouse P19 cell labelling formed ALK3 and ALK6 complexes with BMP2 [PMID:9748228].","localisation_and_range":"BMP2 is flagged secreted and not transmembrane, and the receptor is flagged transmembrane (annotation flags), so signalling is paracrine/juxtacrine from a secreted ligand to a cell-surface receptor [flag].","caveats":"Three of the structural/binding papers were read as abstracts only. The 0.8 nM and 48 nM values differ by assay format [PMID:19735544]. The GDF5 paper concerns a GDF5 mutant, not BMP2 directly [PMID:19956691]. The 9748228 quote is browser-read, unverified, and uses ALK3 naming.","key_references":[{"PMID":"10881198","why":"crystal structure of BMP-2 with BRIA ectodomains"},{"PMID":"19735544","why":"SPR affinities of BMP2 for type I and II receptors"},{"PMID":"15064755","why":"mutational hot spot of BMP-2 for BRIA"}],"covers":["LR000119","LR003668"]},"LR003677":{"pair":"BMP4 -> BMPR1A","headline":"BMP4 binds BMPR1A (ALK-3) in transfected COS cells and nontransfected cells; supported by two binding papers, both abstract only.","interaction_type":"direct binding","direction_and_effect":"BMP-4 bound ALK-3 (BMPR1A) and ALK-6 efficiently, in transfected COS cells and in nontransfected MC3T3-E1 osteoblasts and human foreskin fibroblasts; effect is agonist [PMID:8006002]. A second paper maps the BMPR-IA ligand-binding domain by alanine scanning for BMP-4 binding [PMID:11241215]. UniProt describes BMP4 associating with BMPR1A [DB:UniProt].","molecular_requirements":"In the 1994 paper binding to some type I receptors occurred without a type II receptor and was increased by co-transfected C. elegans DAF-4 [PMID:8006002].","affinity_potency":[],"species_and_systems":"Transfected COS cells and nontransfected MC3T3-E1 and human foreskin fibroblasts [PMID:8006002]; recombinant extracellular domain [PMID:11241215]. Curators record human.","localisation_and_range":"BMP4 flagged secreted; BMPR1A transmembrane [flag].","caveats":"Both papers abstract only. No affinity value in our evidence. MC3T3-E1 is a mouse line per the curator's description.","key_references":[{"PMID":"8006002","why":"BMP-4 binds ALK-3 efficiently in transfected and nontransfected cells"},{"PMID":"11241215","why":"Ligand-binding site mapping of BMPR-IA for BMP-4"}],"covers":["LR000128","LR003677"]},"LR005495":{"pair":"BMP4 -> RGMA","headline":"BMP4 binds RGMA in SPR with Kd 14 nM, the weakest of the three RGMs for BMP4; one paper, human/human labels.","interaction_type":"direct binding","direction_and_effect":"RGMA is described as a BMP co-receptor family member and curators label the effect agonist [PMID:23029472]. In this paper, soluble RGMA.Fc inhibited BMP4 activity in a hepcidin-promoter assay (most robustly for BMP4 and BMP2), consistent with a binding and sequestering action by the fusion protein [PMID:23029472].","molecular_requirements":"Not reported in our evidence: which type I or type II receptors are needed with RGMA.","affinity_potency":[{"value":"Kd 14 nM","assay":"SPR","system":"RGMA vs BMP4, mean of 4-9 experiments","cite":"PMID:23029472"}],"species_and_systems":"Curators label ligand and receptor as human; assay was SPR on recombinant proteins, with the functional assay in Hep3B hepatoma cells [PMID:23029472]. Mouse pair is projected from human evidence.","localisation_and_range":"RGMA is flagged secreted in our entity annotation [flag]; the paper does not say whether the membrane form is needed in the excerpts.","caveats":"Only the abstract was read by the curators (excerpts come from full text). RGMA had the lowest affinity among RGMs for most BMPs tested [PMID:23029472]. Effect direction 'agonist' comes from curation; the tested fusion protein inhibited BMP activity.","key_references":[{"PMID":"23029472","why":"SPR affinity matrix of RGMs for BMP2/4/5/6/7"}],"covers":["LR002181","LR005495"]},"LR003686":{"pair":"BMP6 -> BMPR1B","headline":"BMP-6 binds BMPR-IB efficiently in one full-text paper (cross-linking, cell-type dependent); GtoPdb and BioGRID agree.","interaction_type":"direct binding","direction_and_effect":"BMP-6 bound BMPR-IB (ALK-6) in ROB-C26 cells, together with BMPR-II; curated effect is agonist [PMID:10504300]. GtoPdb lists BMP6 as agonist at BMPR1B [DB:GtoPdb].","molecular_requirements":"When type I receptors were singly transfected, only weak BMP-6 binding to BMPR-IB was seen; binding improved with co-transfected type II receptors [PMID:10504300].","affinity_potency":[],"species_and_systems":"125I-BMP-6 (recombinant human) cross-linking in transfected COS-7 cells; endogenous binding in mouse MC3T3-E1 and C2C12 cell lines and rat-lineage ROB-C26 cells named in the paper [PMID:10504300]. BioGRID lists a BMP6-BMPR1B reconstituted complex [DB:BioGRID]. Both human and mouse pairs are ortholog-inferred.","localisation_and_range":"BMP6 is flagged as secreted [flag].","caveats":"The BMPR-IB binding profile was cell-type dependent (ROB-C26). Single verified paper; no affinity value. Two abstract-insufficient papers not used.","key_references":[{"PMID":"10504300","why":"Efficient BMP-6 binding to BMPR-IB, cell-type dependent"}],"covers":["LR000137","LR003686"]},"LR008249":{"pair":"BMP8B -> ACVR1:BMPR2","headline":"BMP8B -> ACVR1:BMPR2 rests on GtoPdb agonist records only; no paper confirmed it.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists BMP8B as an agonist at ACVR1 and BMPR2 [DB:GtoPdb]; no verified paper supports the effect.","molecular_requirements":"Complex is assembled from separate chain records; subunit requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"No experimental system reported in our evidence.","localisation_and_range":"Not reported in our evidence; the ligand has no secretion flag in the dossier.","caveats":"Judged papers were abstract-insufficient, review-only or about a different entity; none confirmed this pair. No affinity.","key_references":[],"covers":["LR008249"]},"LR008276":{"pair":"BMP8B -> ACVR2A:BMPR1A","headline":"BMP8B -> ACVR2A:BMPR1A rests on GtoPdb agonist records only; no paper confirmed it.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists BMP8B as an agonist at ACVR2A and BMPR1A [DB:GtoPdb]; no verified paper supports the effect.","molecular_requirements":"Complex is assembled from separate chain records; subunit requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"No experimental system reported in our evidence.","localisation_and_range":"Not reported in our evidence; the ligand has no secretion flag in the dossier.","caveats":"Judged papers were abstract-insufficient, review-only or about a different entity; none confirmed this pair. No affinity.","key_references":[],"covers":["LR008276"]},"LR003695":{"pair":"BTC -> EGFR","headline":"BTC is a well-supported EGFR agonist from several papers, with sub-nanomolar to nanomolar affinity.","interaction_type":"direct binding","direction_and_effect":"BTC binds and activates EGFR as an agonist: it is equipotent with EGF in stimulating Balb/c 3T3 proliferation and competes with EGF at the same receptor [PMID:8144591]. In MIN-6 beta cells BTC induced phosphorylation of ErbB-1 and ErbB-2 only [PMID:21897861]. UniProt lists BTC among known EGFR ligands [DB:UniProt].","molecular_requirements":"BTC-TX50 phosphorylated EGFR and HER4, and EGFR (not HER4) mediated its internalisation-dependent cytotoxicity [PMID:9528863]. Truncated forms (BTC-1a, BTC-1b, BTC-2) are equally active [PMID:8144591].","affinity_potency":[{"value":"Kd 0.5 nM","assay":"receptor binding","system":"Balb/c 3T3 cells, human BTC","cite":"PMID:8144591"},{"value":"pKi 8.45","assay":"NanoBRET competition vs EGF-AF488","system":"HEK293T cells, full-length NLuc-EGFR","cite":"PMID:36505413"}],"species_and_systems":"Human BTC on Balb/c 3T3 cells, A431, rat mesangial cells [PMID:8144591]; HEK293T [PMID:36505413]; mouse MIN-6 cells and mice [PMID:21897861]. The mouse pair is listed without ortholog inference.","localisation_and_range":"BTC is flagged both secreted and transmembrane [flag]; soluble forms were purified from conditioned medium [PMID:8144591].","caveats":"All papers were read at abstract level plus excerpts; pKi in GtoPdb [DB:GtoPdb] comes from the same paper as the NanoBRET value [PMID:36505413]. A structure/scattering record exists in IntAct [DB:IntAct].","key_references":[{"PMID":"8144591","why":"Recombinant BTC; Kd 0.5 nM and EGF cross-competition at EGFR."},{"PMID":"36505413","why":"NanoBRET pKi 8.45 for BTC at full-length EGFR."},{"PMID":"9528863","why":"BTC binds EGFR and HER4; EGFR-dependent cytotoxicity."}],"covers":["LR000146","LR003695"]},"LR008735":{"pair":"C3 -> CD46","headline":"CD46 binds the C3b fragment of C3; supported by one abstract-only mapping paper and databases.","interaction_type":"direct binding","direction_and_effect":"CD46 (MCP) binds C3b and C4b and acts as a cofactor for their cleavage [PMID:1717583]. Reactome records CD46 binding C3b [DB:Reactome].","molecular_requirements":"The third and fourth short consensus repeats of CD46 were important for ligand binding and cofactor activity for C3b; SCR-2 was needed for cofactor activity [PMID:1717583].","affinity_potency":[],"species_and_systems":"Recombinant CD46 deletion mutants in ELISA (human) [PMID:1717583]. IntAct lists ELISA and PDB 5FO8 a structure [DB:IntAct][DB:PDB 5FO8].","localisation_and_range":"CD46 is flagged transmembrane [flag], so contact-dependent.","caveats":"The ligand is the C3b fragment, not intact C3. Abstract only; no affinity reported. CD46 is a regulator with cofactor activity rather than a signalling receptor in this evidence.","key_references":[{"PMID":"1717583","why":"SCR mapping of CD46 binding to C3b"}],"covers":["LR008735"]},"LR001679":{"pair":"CADM1 -> CADM3","headline":"CADM1 and CADM3 (Necl-1) bind heterophilically in adhesion and SPR assays; two papers plus Reactome.","interaction_type":"direct binding","direction_and_effect":"Necl-1 (CADM3) showed Ca2+-independent heterophilic cell-cell adhesion with Necl-2 (CADM1), nectin-1 and nectin-3, but not Necl-5 or nectin-2 [PMID:15741237]. SPRi also showed CADM1 interacting with CADM3 [PMID:30131958]. Reactome lists a Necl-1:Necl-2 trans heterodimer [DB:Reactome].","molecular_requirements":"Both are single transmembrane chains; no co-receptor requirement reported in our evidence.","affinity_potency":[],"species_and_systems":"Cell aggregation assays (15741237) and cell-free SPRi with human recombinant proteins (30131958).","localisation_and_range":"Both flagged transmembrane [flag]; trans-interaction between adjacent cells (juxtacrine). CADM3 is neural-tissue specific at non-junctional contact sites [PMID:15741237].","caveats":"15741237 is abstract only; no affinity values for CADM3 in our excerpts. The interaction is symmetric, so direction is arbitrary.","key_references":[{"PMID":"15741237","why":"Heterophilic Necl-1/Necl-2 adhesion with negative controls"},{"PMID":"30131958","why":"SPRi interaction of CADM1 with CADM3"}],"covers":["LR001679","LR005055"]},"LR005549":{"pair":"CALCA -> RAMP3","headline":"alpha-CGRP signals weakly through RAMP3-containing receptors; support is functional, abstract-level, with GtoPdb agonist records.","interaction_type":"functional only","direction_and_effect":"CTR2/RAMP3 mediated hCGRPalpha-stimulated cAMP production, but binding and signalling were markedly weaker than with CTR2/RAMP1 [PMID:14722252]. A dominant-negative RAMP3 reduced hCGRPalpha signalling below the CTR2-alone level [PMID:14722252]. GtoPdb lists full agonist records [DB:GtoPdb].","molecular_requirements":"Requires a partner receptor (CTR2 here) [PMID:14722252]; RAMP3 alone is not shown to bind CGRP. Another paper on RAMP3 with human calcitonin receptor concerns human calcitonin and amylin, not CGRP [PMID:11033437].","affinity_potency":[{"value":"pKi 6.5 to 6.8","assay":"GtoPdb agonist record","system":"database record","cite":"DB:GtoPdb"},{"value":"pEC50 7.6 to 9.7","assay":"GtoPdb agonist record","system":"database record","cite":"DB:GtoPdb"}],"species_and_systems":"Human CTR2/RAMP3 in HEK-293 cells [PMID:14722252]. Mouse pair is projected from human evidence.","localisation_and_range":"Ligand flagged secreted [flag].","caveats":"All papers read as abstracts only. [PMID:11033437] measured potency shifts for calcitonin in Xenopus melanophores, which concerns the CALCA gene product calcitonin, not alpha-CGRP. [PMID:30139742] concerns AM2/IMD binding in RAMP-CLR ECD complexes.","key_references":[{"PMID":"14722252","why":"CTR2/RAMP3 responds to hCGRPalpha, more weakly than RAMP1"}],"covers":["LR002239","LR005549"]},"LR009653":{"pair":"CALM1 -> FAS","headline":"Calmodulin-FAS has one pull-down record and a crystal structure with a peptide.","interaction_type":"direct binding","direction_and_effect":"IntAct records physical association by pull down [DB:IntAct EBI-518165]. A calmodulin-peptide crystal structure is listed [DB:PDB 3EWT].","molecular_requirements":"The structure uses a peptide, not full-length FAS [DB:PDB 3EWT].","affinity_potency":[],"species_and_systems":"Human, from databases.","localisation_and_range":"Intracellular calmodulin; no secreted flag in our evidence. Not reported in our evidence beyond the entity annotation flags.","caveats":"No papers were confirmed; support is from curated database records only. The structure is of calmodulin with a peptide, so domain scope is limited.","key_references":[],"covers":["LR009653"]},"LR009338":{"pair":"CALM1 -> KCNN4","headline":"Calmodulin binds the KCNN4 (SK4) channel, with cryo-EM structures.","interaction_type":"direct binding","direction_and_effect":"Cryo-EM structures of the human SK4/calmodulin complex exist [DB:PDB 6CNM][DB:PDB 6CNN]. UniProt says KCNN4 opens through a constitutive interaction with calmodulin, which binds intracellular calcium [DB:UniProt].","molecular_requirements":"Calmodulin is constitutively bound and senses Ca2+ [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human, cryo-EM.","localisation_and_range":"Intracellular calmodulin; no secreted flag in our evidence. Not reported in our evidence beyond the entity annotation flags.","caveats":"No papers were confirmed; support is from curated database records only.","key_references":[],"covers":["LR009338"]},"LR006818":{"pair":"CALM1 -> MYLK","headline":"Calmodulin activates MYLK; supported by GtoPdb, Reactome and NMR/crystal structures of calmodulin with a MLCK peptide.","interaction_type":"direct binding","direction_and_effect":"GtoPdb lists calmodulin as activator of MYLK [DB:GtoPdb]. UniProt says all catalytically active isoforms need Ca and calmodulin for activation [DB:UniProt]. Reactome has a MYLK:Ca2+:CALM1 complex [DB:Reactome R-HSA-445764].","molecular_requirements":"Requires Ca2+ [DB:UniProt]. Structures use calmodulin with a smooth-muscle MLCK peptide (RM20), not full-length MYLK [DB:PDB 2K0F][DB:PDB 5JQA].","affinity_potency":[],"species_and_systems":"Human proteins; structures with peptide, from databases.","localisation_and_range":"Intracellular calmodulin; no secreted flag in our evidence. Not reported in our evidence beyond the entity annotation flags.","caveats":"No papers were confirmed; support is from curated database records only. MYLK is flagged receptor [flag], which is an annotation, not evidence.","key_references":[],"covers":["LR006818"]},"LR009374":{"pair":"CALM2 -> CACNA1C","headline":"CALM2-CACNA1C rests on one IntAct pull-down record.","interaction_type":"direct binding","direction_and_effect":"IntAct records physical association by pull down [DB:IntAct EBI-1184894]. Effect is not reported in our evidence for CALM2.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human, from a database record.","localisation_and_range":"Intracellular calmodulin; no secreted flag in our evidence. Not reported in our evidence beyond the entity annotation flags.","caveats":"No papers were confirmed; support is from curated database records only. The same IntAct record appears under CALM1; the dossier does not show that the assay distinguishes CALM2 from CALM1.","key_references":[],"covers":["LR009374"]},"LR008870":{"pair":"CALM2 -> KCNQ3","headline":"CALM2-KCNQ3 is supported by a chimeric-fragment structure and UniProt.","interaction_type":"direct binding","direction_and_effect":"A crystal structure of a chimeric Kv7.2-Kv7.3 proximal C-terminal domain with calmodulin is listed [DB:PDB 5J03]. UniProt says CALM2 interacts with the heterotetrameric KCNQ2 and KCNQ3 channel [DB:UniProt].","molecular_requirements":"Chimera, KCNQ2/KCNQ3 context [DB:PDB 5J03][DB:UniProt].","affinity_potency":[],"species_and_systems":"Human, X-ray.","localisation_and_range":"Intracellular calmodulin; no secreted flag in our evidence. Not reported in our evidence beyond the entity annotation flags.","caveats":"No papers were confirmed; support is from curated database records only.","key_references":[],"covers":["LR008870"]},"LR005558":{"pair":"CBLN2 -> NRXN3","headline":"Functional evidence only for secreted CBLN2 acting with splice-variant NRXN3 (SS4+) in mouse circuits; direct binding data not in our evidence.","interaction_type":"functional only","direction_and_effect":"The paper's introduction states that Nrxn3SS4+ acts by binding secreted Cbln2, which then activates postsynaptic GluD1 receptors [PMID:36205393]. The paper's own result: in prefrontal cortex Nrxn3SS4+-Cbln2 signalling had no apparent role, while in cerebellum Nrxn3SS4+-Cbln1 regulated AMPA-receptors [PMID:36205393].","molecular_requirements":"Needs the SS4+ splice variant of NRXN3; GluD1 is the downstream postsynaptic partner [PMID:36205393]. Whether NRXN3 alone suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Constitutive Cbln2 deletions in mice (CA1-to-subiculum, prefrontal cortex, cerebellum) [PMID:36205393]. The curated fields say human, but the abstract describes mouse work. Only the mouse pair is non-inferred; the human pair is projected.","localisation_and_range":"CBLN2 is flagged secreted and NRXN3 transmembrane [flag]; the paper describes secreted Cbln2 binding neurexins [PMID:36205393].","caveats":"Binding is asserted as background, not measured in this dossier. Read as abstract only. The paper reports no role for Nrxn3SS4+-Cbln2 in prefrontal cortex [PMID:36205393].","key_references":[{"PMID":"36205393","why":"Maps neurexin-splice-variant x cerebellin combinations across circuits in mice"}],"covers":["LR002248","LR005558"]},"LR007169":{"pair":"CCL11 -> DPP4","headline":"Only a database record (IntAct enzymatic study) supports this pair; no curator-confirmed paper.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence; IntAct records an enzymatic study between the two proteins [DB:IntAct], which does not establish receptor signalling.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins only; the experimental system is not described beyond 'enzymatic study' [DB:IntAct].","localisation_and_range":"Secreted ligand, DPP4 flagged as a transmembrane receptor [flag].","caveats":"No confirmed papers. Judged rows are review-only, a different entity and abstract-insufficient. An enzymatic (substrate) interaction is not evidence of ligand-receptor signalling.","key_references":[],"covers":["LR007169"]},"LR001688":{"pair":"CCL18 -> CCR8","headline":"CCL18 is a high-affinity CCR8 agonist in transfected cells and Th2 cells; one thorough paper.","interaction_type":"direct binding","direction_and_effect":"Agonist: CCL18 induced chemotaxis, calcium flux and internalization in CCR8-transfected cells; PTX-sensitive Gai coupling; human Th2 cells migrated via CCR8 and wild-type but not Ccr8-deficient mouse Th2 cells migrated to CCL18 [PMID:23999500]. UniProt lists CCL18 as a CCR8 ligand [DB:UniProt].","molecular_requirements":"CCR8 is sufficient for CCL18-induced migration in transfectants [PMID:23999500]; no co-receptor reported.","affinity_potency":[{"value":"K 1.04 nM","assay":"competition for 125I-CCL18 binding (CCL1 0.09 nM)","system":"CCR8-transfected cells","cite":"PMID:23999500"}],"species_and_systems":"Human ligand and receptor in 4DE4 transfectants and human Th2 cells; mouse Th2 cells; EoE biopsies [PMID:23999500].","localisation_and_range":"Secreted ligand and transmembrane receptor according to entity annotation flags [flag]; paracrine/endocrine range implied by the secreted flag only.","caveats":"CCL18 partially desensitised CCL1 signalling and did not antagonize CCL1 chemotaxis. Responses in L1.2 CCR8 cells were weak [PMID:23999500]. Single group.","key_references":[{"PMID":"23999500","why":"CCR8 identified as a CCL18 receptor"}],"covers":["LR001688"]},"LR003758":{"pair":"CCL2 -> CCR3","headline":"Direct but lower-affinity binding and agonism of CCL2 at CCR3, from two papers.","interaction_type":"conflicting","direction_and_effect":"Cells expressing CCR3 were activated by MCP-1, which the paper calls an agonist of CCR3 [PMID:15207250]. In the earlier paper CC CKR3 bound MCP-1 with lower affinity than eotaxin, MCP-3 and RANTES, but MCP-1 and other chemokines did not activate the Ca2+ flux, in contrast with eotaxin, RANTES and MCP-3 [PMID:8642344].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"pKi 7.2-7.8","assay":"GtoPdb record","system":"not specified","cite":"DB:GtoPdb"}],"species_and_systems":"Human ligand and receptor; high-expression CHO-CCR3 cells [PMID:15207250] and AML14.3D10 cells [PMID:8642344]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand is flagged as secreted and not transmembrane [flag], so signalling is presumably paracrine or endocrine; receptor is flagged transmembrane [flag].","caveats":"The two papers conflict on activation: one reports agonism, the other no Ca2+ flux from MCP-1. Paper 15207250 abstract only; 8642344 full text. BioGRID and GtoPdb records cite the earlier paper [DB:BioGRID][DB:GtoPdb].","key_references":[{"PMID":"8642344","why":"CC CKR3 binds MCP-1 with lower affinity"},{"PMID":"15207250","why":"CHO-CCR3 line; MCP-1 agonist of CCR3"}],"covers":["LR000237","LR003758"]},"LR003749":{"pair":"Ccl27b -> Ccr10","headline":"Mouse pair inferred from human CCL27-CCR10 evidence; supporting experiments are mostly human transfectants.","interaction_type":"functional only","direction_and_effect":"Agonist: CCL27 (ESkine) acted on GPR2/CCR10 in transfectant migration and calcium flux [PMID:10725696][PMID:10725697], and in vivo neutralisation impaired lymphocyte recruitment to skin [PMID:11821900].","molecular_requirements":"CCR10 alone in transfectants was sufficient [PMID:10725696].","affinity_potency":[],"species_and_systems":"Pair is mouse and ortholog-inferred. PMID 10725696 cloned mouse GPR2, but its described transfectant assays are human [PMID:10725696]; PMID 10725697 and 11821900 used human systems.","localisation_and_range":"Ligand flagged secreted, receptor flag [flag].","caveats":"No direct mouse ligand-receptor assay is shown in our evidence. Abstracts only.","key_references":[{"PMID":"10725696","why":"Cloned mouse and human GPR2 as ESkine receptor"},{"PMID":"11821900","why":"In vivo skin recruitment via CCL27-CCR10"}],"covers":["LR003749"]},"LR003767":{"pair":"CCL5 -> CCR3","headline":"CCL5 (RANTES) binds CCR3 with Kd 3.1 nM and activates it (Ca2+ flux), supported by several databases.","interaction_type":"direct binding","direction_and_effect":"RANTES bound CC CKR3 (CCR3) and, with eotaxin, activated it in a Ca2+ flux assay; MIP-1 alpha and MIP-1 beta did not bind [PMID:8642344]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"RANTES Phe12 is needed for CCR3 binding, and P2 and Y3 for activation [PMID:9289016]. Reactome describes CCR3, 4 and 5 binding CCL5 [DB:Reactome R-HSA-373061].","affinity_potency":[{"value":"Kd 3.1 nM","assay":"binding to CC CKR3","system":"AML14.3D10 cells stably expressing human CCR3","cite":"PMID:8642344"},{"value":"pKi 8.5 to 9.3","assay":"GtoPdb interaction record","system":"not stated","cite":"DB:GtoPdb"}],"species_and_systems":"Human CCR3 cloned from eosinophils and stably expressed; primary human eosinophils also tested [PMID:8642344]. The mouse pair is inferred from human evidence.","localisation_and_range":"CCL4/CCL5 carry a secreted flag [flag], so paracrine or endocrine range is implied; the receptor carries receptor and transmembrane flags [flag].","caveats":"PMID:9289016 was an abstract-only read; PMID:8642344 has full-text excerpts. BioGRID lists reconstituted complexes [DB:BioGRID].","key_references":[{"PMID":"8642344","why":"Cloned CCR3; RANTES Kd 3.1 nM and Ca2+ flux"},{"PMID":"9289016","why":"RANTES N-loop and N-terminus residues for CCR3"}],"covers":["LR000257","LR003767"]},"LR005567":{"pair":"CCL5 -> DPP4","headline":"Evidence shows DPP4 (CD26) truncates RANTES to an inactive form; this is enzyme-substrate processing, not receptor binding.","interaction_type":"functional only","direction_and_effect":"CD26/DPP IV induced N-terminal truncation of RANTES; truncated RANTES(3-68) was inactive in chemotaxis at 300 ng/ml versus intact RANTES(1-68) active at 10 ng/ml, and acted as a chemotaxis inhibitor [PMID:9516414]. It inhibited M-tropic HIV-1 infection of mononuclear cells 5-fold more efficiently than intact RANTES [PMID:9516414].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human cells and proteins; experiment species human for both partners [PMID:9516414]. Mouse pair is ortholog-inferred.","localisation_and_range":"Both are flagged: CCL5 secreted, DPP4 transmembrane receptor [flag].","caveats":"Read as abstract only. No binding measurement or signalling through DPP4 is reported; DPP4 acts as a protease on RANTES, so CCC scoring of this pair as a ligand-receptor signal is questionable. No database records.","key_references":[{"PMID":"9516414","why":"DPP4 cleaves RANTES to inhibitory RANTES(3-68)"}],"covers":["LR002266","LR005567"]},"LR003776":{"pair":"CCL7 -> CCR1","headline":"Well supported: MCP-3 (CCL7) binds and activates human CCR1 in several binding and functional assays, with Ki about 8 nM.","interaction_type":"direct binding","direction_and_effect":"MCP-3 is a ligand and potent agonist at CCR1 (calcium changes, rank order MIP-1a > MCP-3 > RANTES) [PMID:8530354]; it induced directional migration of CCR1 transfectants and was the most potent chemoattractant of the three [PMID:7545673]. In a Ba/F3-hCCR1 panel, the chemokines other than MCP-2 were full agonists in GTPgammaS exchange [PMID:12381680]. GtoPdb: full agonist [DB:GtoPdb].","molecular_requirements":"CCR1 alone is sufficient in transfectants; CCR1 is promiscuous, and MCP-1 competed poorly for MCP-3 binding [PMID:8530354][PMID:7545673].","affinity_potency":[{"value":"Ki 8 nM","assay":"125I-MCP-3 binding","system":"CC CKR1 transfectants (human)","cite":"PMID:8530354"},{"value":"pKi 8.1","assay":"125I-MIP-1alpha displacement","system":"Ba/F3-hCCR1 membranes","cite":"PMID:12381680"}],"species_and_systems":"Human ligand and receptor in transfectants (293, Ba/F3) and the YT NK-like line [PMID:7545673][PMID:12381680]. Mouse pair is ortholog-inferred.","localisation_and_range":"CCL7 flagged secreted; CCR1 flagged transmembrane receptor [flag].","caveats":"All three papers read as abstracts. The pKi 8.1 comes from a multi-chemokine panel and is recorded on this row by the curators; the abstract does not state which chemokine it belongs to. UniProt also notes CCR1-NF-kB signalling in macrophage polarisation [DB:UniProt].","key_references":[{"PMID":"8530354","why":"CCL7 binds CCR1 (Ki 8 nM) and is a potent agonist"},{"PMID":"7545673","why":"CCR1 cloned from YT cells; MCP3 binding and chemotaxis"},{"PMID":"12381680","why":"Pharmacological panel at hCCR1"}],"covers":["LR000266","LR003776"]},"LR003785":{"pair":"CCL8 -> CCR2","headline":"CCL8 binds CCR2 in transfected human cells, but the evidence is partly about cleaved forms and a comparator assay; weaker than for CCR1.","interaction_type":"conflicting","direction_and_effect":"MCP-2 bound and signalled through CCR2B in HEK293 transfectants, with significant migration [PMID:9115216]. In L1.2-CCR2 cells CCL8 was a comparator agonist, less efficacious in migration than the viral chemokine vCCL4 [PMID:12554737]; GtoPdb lists a full agonist [DB:GtoPdb]. A protease-truncated MCP-2 still bound CCR2 but lacked chemoattractant activity and acted as an antagonist in migration assays [PMID:12149192].","molecular_requirements":"Processing state matters: MMP cleavage between residues 4 and 5 converts agonist to antagonist (MCP analogs bound CCR-2 and CCR-3) [PMID:12149192]. No subunit requirement is reported.","affinity_potency":[],"species_and_systems":"Human chemokines and receptors in transfected HEK293 [PMID:9115216] and murine pre-B L1.2 cells expressing CCR2 [PMID:12554737]; truncated forms also tested in THP-1 cells and rat paw inflammation [PMID:12149192]. Mouse pair is ortholog-inferred.","localisation_and_range":"Secreted ligand (CCL8 is flagged secreted) acting on a transmembrane receptor [flag].","caveats":"All three papers read as abstracts only. Direction depends on the form tested (full length agonist vs truncated antagonist). The 2003 paper uses CCL8 only as a comparator, not characterised de novo [PMID:12554737]. No affinity is reported for CCL8 itself in our evidence.","key_references":[{"PMID":"9115216","why":"MCP-2 binds and signals through CCR2B in transfectants"},{"PMID":"12149192","why":"MMP-truncated MCP-2 binds CCR2 but is an antagonist"},{"PMID":"12554737","why":"CCL8 as comparator CCR2 agonist in chemotaxis"}],"covers":["LR000275","LR003785"]},"LR006755":{"pair":"Ccl9 -> Ccr1","headline":"Mouse Ccl9 is reported to act through Ccr1 on osteoclasts, but the receptor link comes from prior work, not a direct test.","interaction_type":"functional only","direction_and_effect":"Ccl9 stimulated cytoplasmic motility and polarization in osteoclasts, and the paper states Ccl9 acts through CCR1 [PMID:12397598]. The paper reports Ccl9 and Ccr1 as the dominant chemokine and receptor expressed by osteoclasts [PMID:12397598].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse bone marrow cells differentiated to osteoclasts with M-CSF and RANKL [PMID:12397598].","localisation_and_range":"Ccl9 is flagged secreted [flag]; paracrine or autocrine on osteoclasts is implied only by expression data.","caveats":"The CCR1 attribution is asserted from earlier literature and analogy with CCL3; no blocking or knockout is shown in this paper. Abstract only. No database record.","key_references":[{"PMID":"12397598","why":"Osteoclast expression survey and Ccl9-induced motility"}],"covers":["LR006755"]},"LR001697":{"pair":"CCN1 -> SDC4","headline":"CCN1 acts through syndecan-4 together with integrin alpha6beta1 to induce fibroblast apoptosis; functional evidence only.","interaction_type":"functional only","direction_and_effect":"CCN1 induces fibroblast apoptosis through its adhesion receptors, integrin alpha6beta1 and the heparan sulfate proteoglycan syndecan-4, via transcription-independent p53 activation of Bax [PMID:16275757]. Endothelial cell adhesion to CCN1 promotes survival instead [PMID:16275757].","molecular_requirements":"Syndecan-4 is paired with integrin alpha6beta1 in the reported mechanism; syndecan-4 alone is not shown to be sufficient.","affinity_potency":[],"species_and_systems":"Rat1a fibroblasts and human skin fibroblasts (HSF), with HUVEC for the survival contrast, CCN1 as an adhesion substrate [PMID:16275757].","localisation_and_range":"CCN1 is flagged secreted [flag] but described in the papers as matrix-associated, so adhesion-type contact with receptors on neighbouring cells is plausible.","caveats":"Evidence is functional; no direct binding measure or affinity for syndecan-4 is in our evidence. Outcome is cell-type dependent (apoptosis in fibroblasts, survival in endothelial cells). Abstract plus full-text excerpts.","key_references":[{"PMID":"16275757","why":"CCN1 induces fibroblast apoptosis through alpha6beta1 and syndecan-4"}],"covers":["LR001697","LR005066"]},"LR003893":{"pair":"CCN2 -> NTRK1","headline":"CTGF activates TrkA in human mesangial cells, shown by cross-linking and phosphorylation; abstract-level, one paper.","interaction_type":"direct binding","direction_and_effect":"CTGF stimulated TrkA phosphorylation at Tyr490 and Tyr674/675, blocked by the Trk inhibitor K252a, which also blocked CTGF-induced signalling and TIEG induction; the authors conclude TrkA is a tyrosine kinase receptor for CTGF [PMID:15601748].","molecular_requirements":"Cross-linked rCTGF formed complexes with TrkA and with the neurotrophin co-receptor p75NTR [PMID:15601748]. Whether p75NTR is required is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human mesangial cells with recombinant CTGF [PMID:15601748]. The mouse pair is ortholog-inferred.","localisation_and_range":"CCN2 is flagged as secreted [flag], so paracrine or autocrine action is plausible; this is annotation, not shown by the papers.","caveats":"Abstract read only. Evidence is cross-linking and phosphorylation; no affinity value is reported in our evidence.","key_references":[{"PMID":"15601748","why":"Cross-linking and phosphorylation showing TrkA as a CTGF receptor"}],"covers":["LR000387","LR003893"]},"LR005576":{"pair":"CCN2 -> TGFBR1","headline":"Only a single-cell computational and cell-culture study links CCN2 to TGFBR1; no direct CCN2-TGFBR1 binding is shown.","interaction_type":"functional only","direction_and_effect":"A single-cell and spatial transcriptomic study of hepatocellular carcinoma proposed a positive loop between tumour cells and fibroblasts mediated by CCN2/TGF-beta-TGFBR1 pairs [PMID:39095854]. Recombinant CCN2 enhanced the effect of recombinant TGF-beta on migration and invasion of PLC cells [PMID:39095854].","molecular_requirements":"The paper describes CCN2 as a coactivator of TGF-beta-SMAD signalling by direct binding to TGF-beta, citing earlier work, so it is background rather than this paper's result [PMID:39095854]. Multiplexed immunofluorescence showed colocalisation of CCN2, TGF-beta and TGFBR1 on tumour cell membranes [PMID:39095854].","affinity_potency":[],"species_and_systems":"Human HCC single-cell and spatial data, human cell lines (LX2, PLC) [PMID:39095854].","localisation_and_range":"CCN2 is flagged as secreted [flag], so paracrine or autocrine action is plausible; this is annotation, not shown by the papers. Fibroblasts were the CCN2 source and tumour cells the receiving cells [PMID:39095854].","caveats":"Computational and co-localisation evidence only. CCN2 binding to TGFBR1 itself is not shown; the mechanism is via TGF-beta. Abstract was the only text read by curators, although full text was available.","key_references":[{"PMID":"39095854","why":"HCC tumour-fibroblast loop involving CCN2/TGF-beta-TGFBR1"}],"covers":["LR002275","LR005576"]},"LR005585":{"pair":"Cd24a -> L1cam","headline":"Mouse CD24 binds L1 through its sialylated glycan, with a binding study and a knockout functional study; both read as abstracts.","interaction_type":"direct binding","direction_and_effect":"Brain-derived HSA (mouse CD24) was capable of binding L1 [PMID:9048906]. CD24 binding to L1 depends on alpha2,3-sialic acid and, through trans-interaction with L1, promotes or inhibits neurite outgrowth depending on cell type [PMID:11283023].","molecular_requirements":"Alpha2,3-sialic acid on CD24 is required [PMID:11283023]. The L1 binding is distinct from P-selectin binding: resistant to high salt and not requiring bivalent cations [PMID:9048906]. Knockout mutants showed neurite effects run through L1 rather than GPI-linked CD24 itself [PMID:11283023]. Reactome records an L1:HSA complex [DB:Reactome].","affinity_potency":[],"species_and_systems":"Mouse brain-derived CD24 and neuronal systems; neurite outgrowth assays in knockout mutants [PMID:11283023][PMID:9048906].","localisation_and_range":"CD24 is flagged membrane-bound; the sialylated glycoform acts in trans with L1 [PMID:11283023]. The glycoform is excluded together with L1 from raft microdomains [PMID:11283023].","caveats":"Both papers read as abstract only. No affinity. Effect (promotion or inhibition of outgrowth) is cell-type dependent.","key_references":[{"PMID":"11283023","why":"Sialic-acid-dependent CD24 trans-binding to L1 mediates neurite effects"},{"PMID":"9048906","why":"Brain HSA binds L1 by a mechanism distinct from P-selectin"}],"covers":["LR005585"]},"LR007952":{"pair":"CD276 -> TREML2","headline":"Weak: one functional paper reports MDSC chemotaxis to soluble B7H3 dependent on TLT-2, a putative receptor.","interaction_type":"functional only","direction_and_effect":"Soluble B7H3 (cleavage product of CD276) drove chemotaxis of MDSCs in vitro, dependent on TLT-2 (TREML2), described as a putative receptor [PMID:34825713]. Injection of sB7H3 in naive mice induced MDSC influx and Ccl2 expression in lung [PMID:34825713].","molecular_requirements":"Soluble cleaved CD276 rather than the membrane form was used [PMID:34825713]. Other requirements not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human IPF patient plasma and mouse injection experiments; the species of the in vitro chemotaxis assay is not stated in our evidence [PMID:34825713]. Curated experiment species are recorded as human.","localisation_and_range":"Soluble (shed) CD276 acts at a distance, from the paper text [PMID:34825713]; CD276 and TREML2 are flagged transmembrane [flag].","caveats":"No direct binding, no affinity, and a second paper was judged abstract-insufficient. TREML2 dependence is described as putative.","key_references":[{"PMID":"34825713","why":"sB7H3 chemotaxis of MDSCs dependent on TLT-2"}],"covers":["LR007952"]},"LR003794":{"pair":"CD40LG -> CD40","headline":"Canonical, well supported ligand-receptor pair with binding, structural, in vitro and in vivo evidence across species.","interaction_type":"direct binding","direction_and_effect":"CD40L on activated T cells engages CD40 on APCs; mutagenesis maps interacting residues [PMID:7543281]. Anti-gp39 blocking in mice inhibited germinal-centre formation and memory B-cell generation [PMID:7516405]. Soluble CD40L enhanced ICAM-1 and FAS, and cytokines on tumour lines, and inhibited proliferation [PMID:11163401]. CD154 shedding is triggered by CD40 ligation [PMID:24189063].","molecular_requirements":"Model-guided mutagenesis implicates two clusters of residues and two adjacent gp39 monomers [PMID:7543281]. Soluble CD40L exists as monomer or homotrimer [DB:UniProt]; PDB 3QD6 is a structure of the complex [DB:PDB 3QD6].","affinity_potency":[],"species_and_systems":"Human cell lines and proteins [PMID:7543281][PMID:11163401]; murine ligand cloned [PMID:1374165]; in vivo mouse blocking [PMID:7516405].","localisation_and_range":"CD40LG flagged secreted [flag]; membrane form acts by contact, and soluble CD154 arises by shedding via ADAM10/ADAM17 on CD40 ligation [PMID:24189063].","caveats":"Most papers abstract only. No affinity values reported in our evidence. GtoPdb record lists no type or action [DB:GtoPdb].","key_references":[{"PMID":"7543281","why":"Structure-guided mutagenesis of gp39/CD40 interface"},{"PMID":"1374165","why":"Cloning of murine CD40 ligand"},{"PMID":"24189063","why":"CD154 shedding triggered by CD40"}],"covers":["LR000284","LR003794"]},"LR005594":{"pair":"CD6 -> CD44","headline":"New 2024 CD6-CD44 interaction found by proximity labeling and confirmed biochemically; one paper only.","interaction_type":"direct binding","direction_and_effect":"CD44 is a novel CD6 receptor; CD6 stimulation caused RhoA/ROCK-dependent actomyosin remodelling and tight junction disassembly in RPE cells [PMID:37820034].","molecular_requirements":"CD44, CD166 and CDCP1 cluster into a tripartite receptor complex upon CD6 binding and all components were required for tight junction disassembly [PMID:37820034].","affinity_potency":[],"species_and_systems":"RPE cells; species not stated in the abstract (curator label: human) [PMID:37820034]. Mouse pair is ortholog-inferred.","localisation_and_range":"Both transmembrane by flags (also flagged secreted) [flag]; CD6 acts as a ligand on T cells toward RPE cells [PMID:37820034].","caveats":"Abstract-only; no affinity or detail on biophysical methods in our evidence. Only one of two confirmed papers is shown. No database records.","key_references":[{"PMID":"37820034","why":"CD44 identified as CD6 receptor; tripartite complex"}],"covers":["LR002295","LR005594"]},"LR005099":{"pair":"CD96 -> NECTIN1","headline":"Human nectin-1 binds CD96 directly with low affinity (SPR, ELISA); mouse CD96 also binds nectin-1.","interaction_type":"direct binding","direction_and_effect":"Human CD96 binds the nectin-1 V-domain; this affinity is lower than nectin-1 for nectin-3 or itself, and lower than CD96 for CD155 [PMID:30759143]. Functional effect on NK cells not established in this paper [PMID:30759143]. Mouse CD96 also binds nectin-1 [PMID:17971293].","molecular_requirements":"Binding site is on the V-domain of nectin-1; SPR gave similar KD for ectodomain and V-domain; the CD96 isoform 2 ectodomain was used [PMID:30759143].","affinity_potency":[{"value":"KD 2.4 \u03bcM","assay":"surface plasmon resonance, CD96 ectodomain over nectin-1","system":"recombinant human proteins","cite":"PMID:30759143"}],"species_and_systems":"Human recombinant proteins (ELISA, SPR) [PMID:30759143]; mouse CD96 in a separate paper [PMID:17971293]. Mouse pair is ortholog-inferred.","localisation_and_range":"Membrane-bound partners; likely contact-dependent.","caveats":"Weak affinity; CD155 may outcompete nectin-1 for CD96 [PMID:30759143]. The mouse paper was read as abstract only [PMID:17971293].","key_references":[{"PMID":"30759143","why":"Human CD96-nectin-1 binding, SPR and V-domain mapping"},{"PMID":"17971293","why":"Mouse CD96 binds nectin-1"}],"covers":["LR001734","LR005099"]},"LR011498":{"pair":"CD99 -> CD99L2","headline":"Mouse CD99 and paralog CD99L2 form heterodimers; CD99 promotes CD99L2 surface trafficking. Not a classical signalling pair.","interaction_type":"direct binding","direction_and_effect":"Mouse CD99 formed heterodimers with CD99L2 (BiFC, immunoprecipitation, FRET); interaction depends on the cytoplasmic domain and enhanced CD99L2 plasma-membrane trafficking [PMID:24133166]. Reactome lists a CD99:CD99L2 complex [DB:Reactome].","molecular_requirements":"Cytoplasmic-domain dependent; CD99 also forms homodimers [PMID:24133166].","affinity_potency":[],"species_and_systems":"Mouse cells, thymocytes and CTL lines from CD99-deficient mice [PMID:24133166]; human pair is from the record only.","localisation_and_range":"Both are surface proteins [PMID:24133166].","caveats":"Abstract only. Cis heterodimerisation between paralogs, not secreted-ligand signalling; direction unsupported.","key_references":[{"PMID":"24133166","why":"CD99-CD99L2 heterodimers and trafficking"}],"covers":["LR011498"]},"LR007178":{"pair":"CGA:FSHB -> FSHR","headline":"FSH (CGA:FSHB) on FSHR is well supported by structures and curated databases, though no curated paper is yet verified.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists CGA-FSHR and FSHB-FSHR as agonists [DB:GtoPdb]. UniProt says FSHB binds FSHR to activate downstream signaling [DB:UniProt].","molecular_requirements":"UniProt describes FSHR binding the FSH heterodimer of CGA and FSHB [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human; crystal structures of FSH with FSHR ectodomain [DB:PDB 1XWD] [DB:PDB 4AY9].","localisation_and_range":"Secreted heterodimer, transmembrane receptor [flag].","caveats":"Three pending rows, no verified paper in our evidence. IntAct records x-ray crystallography [DB:IntAct]; Reactome FSHR:Follitropin [DB:Reactome]. Affinity not reported.","key_references":[],"covers":["LR007178"]},"LR011957":{"pair":"CHRD -> BMP7","headline":"Chordin binds BMP-7 in recombinant assays and inhibits BMP signalling; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"Annotated inhibitory [flag]. Chordin blocks BMP interaction with receptors [PMID:25157165]; chordin acts as an extracellular antagonist and BMP-7 is the bound partner.","molecular_requirements":"Terminal BMP-binding domains of chordin bind BMPs; cleavage of either terminal domain has little effect on chordin affinity for BMP-4 and BMP-7 [PMID:25157165].","affinity_potency":[],"species_and_systems":"Recombinant human chordin in biophysical and binding assays [PMID:25157165].","localisation_and_range":"BMP-7 flagged secreted, not transmembrane [flag]; extracellular antagonist.","caveats":"BMP-7 is flagged secreted and not transmembrane [flag], so this looks like an antagonist-binding pair rather than a receptor interaction. One paper read as abstract; no affinity value reported in our evidence.","key_references":[{"PMID":"25157165","why":"Chordin structure and binding to BMP-4 and BMP-7"}],"covers":["LR011957"]},"LR005639":{"pair":"CLU -> PLXNA4","headline":"Clusterin binds PLXNA4 directly with Kd 10.8 nM in a solid-phase assay; one full-text paper.","interaction_type":"direct binding","direction_and_effect":"CLU binds PLXNA4 in a direct, high-affinity manner; CLU co-immunoprecipitated with PLXNA4 from wild-type but not Clu-null brain lysates [PMID:27378688]. Effect on signalling is not shown; PLXNA4 is described as a CLU receptor.","molecular_requirements":"Not reported beyond PLXNA4 itself; no co-receptor described [PMID:27378688].","affinity_potency":[{"value":"Kd 10.8 nM","assay":"cell-free solid-phase binding assay","system":"immobilized human PLXNA4 with human CLU","cite":"PMID:27378688"}],"species_and_systems":"Human recombinant proteins in the binding assay; mouse brain lysates and Plxna4 knockout mice for in vivo work [PMID:27378688]. Human AD brain showed about 50% lower PLXNA4. Human pair is ortholog-inferred.","localisation_and_range":"Clusterin is flagged secreted [flag]; CSF CLU was elevated about 34% in Plxna4-/- mice [PMID:27378688].","caveats":"Single paper. Mass spectrometry hit from mouse brain. Database support is a BioGRID reconstituted-complex record [DB:BioGRID 2484893].","key_references":[{"PMID":"27378688","why":"Identifies PLXNA4 as high-affinity CLU receptor; Kd 10.8 nM"}],"covers":["LR002359","LR005639"]},"LR005648":{"pair":"CNTN3 -> APP","headline":"Direct CNTN3-APP binding mapped to domains by fusion-protein binding and alanine scanning; one abstract-level paper plus full-text excerpts.","interaction_type":"direct binding","direction_and_effect":"CNTN3 and APP bind directly; the curator labels the effect agonist, but the paper reports only binding, not signalling [PMID:31318883].","molecular_requirements":"The second fibronectin domain (Fn2) of CNTN3 mediates APP binding, and the copper-binding domain (CuBD) of APP mediates CNTN3 binding; single residues such as CNTN3 V752A and APP H137A and E183A abolished binding [PMID:31318883]. Deleting the six N-terminal Ig domains of CNTN3 had no effect [PMID:31318883].","affinity_potency":[],"species_and_systems":"APP-alkaline phosphatase and CNTN-Fc fusion proteins in 96-well binding assays; curator labels species human; the paper's own text does not say which species the constructs come from beyond that [PMID:31318883]. The mouse pair is listed as non-projected, the human pair as ortholog-inferred.","localisation_and_range":"CNTN3 is annotated non-secreted and APP secreted and transmembrane [flag]; the assays used extracellular domains, so contact-dependent binding is plausible but not tested in cells [PMID:31318883].","caveats":"Single paper, recorded as abstract only, though full-text excerpts were available; binding was in vitro with recombinant fragments. Among CNTNs, CNTN3 and CNTN4 bound APP best and CNTN1, CNTN2 and CNTN6 weakly [PMID:31318883].","key_references":[{"PMID":"31318883","why":"Domain-level and residue-level mapping of the APP-CNTN3 interface"}],"covers":["LR002368","LR005648"]},"LR005657":{"pair":"COL11A2 -> ITGB1","headline":"Only a cell-based report that integrin a2b1/DDR2 bind collagen XI; abstract-level and not chain-specific for COL11A2.","interaction_type":"functional only","direction_and_effect":"Integrin a2b1 and DDR2, but not a11b1, mediated high-affinity binding of cancer-associated fibroblasts to collagen type XI [PMID:36233024].","molecular_requirements":"ITGB1 is named only as part of a2b1 [PMID:36233024].","affinity_potency":[],"species_and_systems":"CAFs; species not reported in our evidence [PMID:36233024]. The human pair is ortholog-inferred.","localisation_and_range":"COL11A2 is annotated secreted and not transmembrane [flag].","caveats":"Abstract-only; the paper says collagen type XI without naming a chain, and does not isolate individual integrin subunits [PMID:36233024].","key_references":[{"PMID":"36233024","why":"Integrin a2b1 and DDR2 binding to collagen XI in CAFs"}],"covers":["LR002378","LR005657"]},"LR006863":{"pair":"COL13A1 -> ITGA11:ITGB1","headline":"Integrin a11b1 binds collagen XIII by SPR, pull-down and cell adhesion; this is the complex-level record.","interaction_type":"direct binding","direction_and_effect":"Integrin a11b1 mediated cell adhesion to collagen XIII in C2C12 cells where it was the only collagen receptor, and SPR and pull-down confirmed the interaction [PMID:33306155].","molecular_requirements":"Both subunits (a11 and b1) are the receptor; recognition is via the a11-I domain of GPKGER and GF(S)QGEK motifs [PMID:33306155].","affinity_potency":[],"species_and_systems":"C2C12 cells expressing human a11b1; mouse genetic crosses [PMID:33306155].","localisation_and_range":"COL13A1 is annotated non-secreted and transmembrane [flag].","caveats":"Abstract-level read; no affinity values in our evidence. Four other judged papers were review-only [PMID:33306155].","key_references":[{"PMID":"33306155","why":"a11b1-collagen XIII binding and adhesion"}],"covers":["LR006863"]},"LR006881":{"pair":"COL18A1 -> ITGA1:ITGB1","headline":"Database-asserted only: BioGRID and IntAct record COL18A1-ITGB1 binding; no curator-confirmed paper for this specific integrin.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect: not reported in our evidence.","molecular_requirements":"Databases record binding to ITGB1 only, not to the specific alpha chain, so the alpha subunit requirement is unresolved [DB:BioGRID] [DB:IntAct].","affinity_potency":[],"species_and_systems":"BioGRID lists a reconstituted complex [DB:BioGRID, PMID:19542224]; IntAct lists a pull down [DB:IntAct, PMID:17615292]. Species not reported in our evidence.","localisation_and_range":"Ligand flagged as secreted; receptor is a transmembrane complex [flag].","caveats":"No papers were judged confirmed: curator read counts are review_only and different_entity only. The pair rests on database records alone, and these name ITGB1 and not the alpha chain.","key_references":[],"covers":["LR006881"]},"LR006890":{"pair":"COL1A1 -> ITGA10:ITGB1","headline":"Database-asserted only: a BioGRID co-purification record for COL1A1-ITGB1; no curator-confirmed paper for this complex.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect: not reported in our evidence.","molecular_requirements":"The database record names ITGB1 alone, so the alpha chain is not established [DB:BioGRID].","affinity_potency":[],"species_and_systems":"BioGRID lists a co-purification for COL1A1-ITGB1 [DB:BioGRID, PMID:2156854]. Species not reported in our evidence.","localisation_and_range":"Receptor is a transmembrane complex [flag]; collagen is a matrix ligand.","caveats":"No papers were judged confirmed; curator read counts are only review_only and abstract_insufficient. Support rests on one database record.","key_references":[],"covers":["LR006890"]},"LR005666":{"pair":"COL1A2 -> DDR2","headline":"Type I collagen binds and activates DDR2, with higher affinity than for DDR1; supported by two full-text papers.","interaction_type":"direct binding","direction_and_effect":"Collagen types I, III, IV and V stimulated phosphorylation of DDR2 in 293 cells; recorded as agonist [PMID:9659899].","molecular_requirements":"Native triple-helical collagen is needed per the abstract [PMID:9659899]. DDR2 binding was detectable at 1 mg loading; type I collagen had about 3-fold higher affinity for DDR2 than DDR1 per the curator note [PMID:9659900].","affinity_potency":[],"species_and_systems":"Radiolabelled DDR2-Fc binding to bovine dermal collagen I, human receptor [PMID:9659900]; human collagen on human 293 cells [PMID:9659899].","localisation_and_range":"COL1A2 is flagged secreted and not transmembrane [flag]; type I collagen is an extracellular matrix ligand, so signalling is by cell contact with matrix (inferred from the flag; not stated in the papers read).","caveats":"No Kd reported in our evidence. Collagen I is a heterotrimer; COL1A2-specific contribution not shown. One row review_only.","key_references":[{"PMID":"9659900","why":"Slot-blot binding of DDR2 to collagen I"},{"PMID":"9659899","why":"Collagen activates DDR2 phosphorylation"}],"covers":["LR002387","LR005666"]},"LR003839":{"pair":"COL1A2 -> ITGA2","headline":"Type I collagen engages integrin alpha2 (alpha2beta1) by SPR and in functional assays; evidence is for the whole collagen.","interaction_type":"direct binding","direction_and_effect":"Both alpha1(I) and alpha2(I) chains supported Mg2+-dependent platelet adhesion via alpha2beta1 [PMID:2156854]; ITGA2-collagen interaction drives ovarian cancer peritoneal metastasis [PMID:33026975].","molecular_requirements":"Recombinant alpha2 I-domain bound collagen I [PMID:16043429]. Functional binding entity is alpha2beta1; ITGA2 stored alone.","affinity_potency":[{"value":"Kd 0.3 uM (range 0.15-1.75 uM)","assay":"SPR (BIAcore), two affinity classes","system":"recombinant human alpha2 I-domain, fibrillar collagen I","cite":"PMID:16043429"}],"species_and_systems":"Human I-domains [PMID:16043429]; human platelets [PMID:2156854]; human ovarian cancer cells [PMID:33026975]. IntAct biochemical record P08123-P17301 [DB:IntAct].","localisation_and_range":"COL1A2 is flagged secreted and not transmembrane [flag]; type I collagen is an extracellular matrix ligand, so signalling is by cell contact with matrix (inferred from the flag; not stated in the papers read).","caveats":"Collagen I tested as the (COL1A1)2COL1A2 heterotrimer, not COL1A2 alone. PMID:2156854 and PMID:33026975 were read as abstracts; the latter refers to 'collagens' as a class.","key_references":[{"PMID":"16043429","why":"SPR binding of alpha2 I-domain to collagen I"},{"PMID":"2156854","why":"Platelet adhesion via alpha2beta1"},{"PMID":"33026975","why":"ITGA2-collagen in ovarian cancer metastasis"}],"covers":["LR000333","LR003839"]},"LR006926":{"pair":"COL2A1 -> ITGA10:ITGB1","headline":"Alpha10beta1 integrin was isolated on a collagen II affinity column; one abstract-read paper, complex partner inferred from beta1-family membership.","interaction_type":"direct binding","direction_and_effect":"The integrin alpha subunit was purified from bovine chondrocytes on collagen type II; the paper calls it a collagen type II-binding integrin of the beta1 family [PMID:9685391]. Dossier lists a 'Stimulatory' label [flag].","molecular_requirements":"Both chains: alpha10 (purified, cloned) with beta1 (family member per the abstract); the abstract names alpha10 beta1 as expressed in cartilage [PMID:9685391].","affinity_potency":[],"species_and_systems":"Bovine chondrocytes (affinity) and human cDNA/cartilage [PMID:9685391].","localisation_and_range":"The complex is flagged transmembrane, and is_receptor 0 in the complex flag [flag]; collagen is a matrix ligand.","caveats":"Abstract read only. Four papers were judged review-only. Interaction class is 'Adhesion-Adhesion'.","key_references":[{"PMID":"9685391","why":"Alpha10 purified on collagen II"}],"covers":["LR006926"]},"LR003848":{"pair":"COL3A1 -> ITGA2","headline":"Alpha2 I domain binds collagen III in SPR; patient-fibroblast and ovarian-cancer studies support alpha2beta1 as a collagen III receptor.","interaction_type":"direct binding","direction_and_effect":"Recombinant alpha2 I domain bound collagens I-III [PMID:16043429]. EDS fibroblasts with COL3A1 mutations show strongly reduced alpha2beta1, the functional receptor, and purified COLLIII restored the control phenotype [PMID:14970208]. ITGA2 mediated cancer-cell adhesion to collagens and peritoneal metastasis [PMID:33026975].","molecular_requirements":"Cell studies concern alpha2beta1; ITGA2 is stored alone though the binding entity is ITGA2:ITGB1 [PMID:33026975].","affinity_potency":[],"species_and_systems":"Human recombinant I domains, human patient fibroblasts and ovarian cancer cells and mouse in vivo model not stated [PMID:16043429; PMID:14970208; PMID:33026975].","localisation_and_range":"Matrix ligand, cell-surface receptor [flag].","caveats":"Six confirmed papers, three shown. Fibroblast evidence is disease genetics, and the ovarian paper refers to 'collagens' as a class. Alpha2 affinities are not given as numbers in our excerpt.","key_references":[{"PMID":"16043429","why":"SPR of alpha2 I domain and collagen III"},{"PMID":"14970208","why":"COL3A1-mutant fibroblasts lose alpha2beta1"},{"PMID":"33026975","why":"ITGA2-collagen adhesion in ovarian cancer"}],"covers":["LR000342","LR003848"]},"LR005675":{"pair":"COL4A1 -> DDR1","headline":"Direct but weak collagen IV binding and phosphorylation of DDR1 in one full-text paper.","interaction_type":"direct binding","direction_and_effect":"Collagen IV bound DDR1 and induced receptor phosphorylation, but binding and phosphorylation were consistently weaker than with fibril-forming collagens [PMID:9659900].","molecular_requirements":"DDR1 is a collagen receptor tyrosine kinase; no co-receptor requirement is reported in our evidence. The tested material was commercial type IV collagen [PMID:9659900].","affinity_potency":[],"species_and_systems":"Human-labelled ligand and receptor, slot-blot binding and phosphorylation assays; mouse pair is projected from human [PMID:9659900].","localisation_and_range":"Ligand is flagged secreted, not transmembrane [flag]; as a collagen it is a matrix ligand, but this is not shown by the cited papers.","caveats":"Commercial type IV collagen is a generic preparation, probably mostly the COL4A1/COL4A2 heterotrimer, so binding cannot be assigned to one chain [PMID:9659900]. Binding was consistently weaker than to fibril-forming collagens [PMID:9659900]. No affinity values reported.","key_references":[{"PMID":"9659900","why":"Collagens as ligands of DDR receptors; type IV weaker than fibrillar"}],"covers":["LR002396","LR005675"]},"LR002399":{"pair":"COL4A2 -> DDR1","headline":"Direct but weak collagen IV binding and phosphorylation of DDR1 in one full-text paper.","interaction_type":"direct binding","direction_and_effect":"Collagen IV bound DDR1 and induced phosphorylation, weaker than fibril-forming collagens [PMID:9659900].","molecular_requirements":"No co-receptor requirement reported in our evidence. COL4A2 is inferred as a chain of the tested commercial type IV collagen, not tested alone [PMID:9659900].","affinity_potency":[],"species_and_systems":"Human-labelled ligand and receptor, slot-blot and phosphorylation assays; other species are projections [PMID:9659900].","localisation_and_range":"Ligand is flagged secreted, not transmembrane [flag]; as a collagen it is a matrix ligand, but this is not shown by the cited papers.","caveats":"Commercial type IV collagen is a generic preparation, probably mostly the COL4A1/COL4A2 heterotrimer, so binding cannot be assigned to one chain [PMID:9659900]. Binding was consistently weaker than to fibril-forming collagens [PMID:9659900]. No affinity values reported.","key_references":[{"PMID":"9659900","why":"Collagens as ligands of DDR receptors; type IV weaker than fibrillar"}],"covers":["LR002399","LR005678"]},"LR003857":{"pair":"Col4a3 -> Itgb1","headline":"Mouse Col4a3 to beta1 integrin supported through alpha3beta1 in two abstract-only papers on the NC1 domain.","interaction_type":"functional only","direction_and_effect":"alpha3(IV)NC1 binds alpha3beta1 integrin, inhibiting COX-2-mediated pro-angiogenic factors in endothelial cells [PMID:17426256]; human glomerular cells bound alpha3(IV)NC1 via alpha3beta1 and alpha2beta1 [PMID:19229828].","molecular_requirements":"Beta1 acts as partner of alpha3 or alpha2 [PMID:19229828]; the NC1 domain, not full-length chain, was used [PMID:19229828].","affinity_potency":[],"species_and_systems":"The pair here is mouse by projection; experiments used human glomerular epithelial cells [PMID:19229828] and endothelial cells (species not stated) [PMID:17426256].","localisation_and_range":"Ligand is flagged secreted, not transmembrane [flag]; as a collagen it is a matrix ligand, but this is not shown by the cited papers.","caveats":"Both abstract only; ITGB1 stands for alpha/beta heterodimers. Two other papers were judged a different entity.","key_references":[{"PMID":"17426256","why":"alpha3(IV)NC1 via alpha3beta1 regulates COX-2"},{"PMID":"19229828","why":"Integrins from renal cells bind alpha3 NC1"}],"covers":["LR003857"]},"LR003866":{"pair":"COL5A2 -> DDR1","headline":"Collagen V/XI hybrid containing alpha2(V) binds DDR1; commercial type V also activates DDR1.","interaction_type":"direct binding","direction_and_effect":"Commercial human type V collagen induced DDR1 phosphorylation comparable to the A204-derived ligand [PMID:9659900].","molecular_requirements":"Commercial type V is mostly COL5A1/COL5A2 and single chains were not resolved; the native A204 ligand was a hybrid of COL11A1 and COL5A2 [PMID:9659900].","affinity_potency":[],"species_and_systems":"Human-labelled ligand and receptor; mouse pair is projected [PMID:9659900].","localisation_and_range":"Ligand is flagged secreted, not transmembrane [flag]; as a collagen it is a matrix ligand, but this is not shown by the cited papers.","caveats":"Chain-level binding not shown; no affinity reported.","key_references":[{"PMID":"9659900","why":"Type V and V/XI collagens activate DDR1"}],"covers":["LR000360","LR003866"]},"LR006971":{"pair":"COL6A1 -> ITGA11:ITGB1","headline":"Weak: one abstract reports COL6A1 binding ITGB1 in glioblastoma; the alpha subunit is not named.","interaction_type":"functional only","direction_and_effect":"COL6A1 is bound to ITGB1 on endothelial cells, disrupting tight junctions via UBD-mediated claudin-5 degradation [PMID:41297453].","molecular_requirements":"The paper names only ITGB1, not the alpha partner, so ITGA11:ITGB1 is not distinguished from other beta1 heterodimers [PMID:41297453].","affinity_potency":[],"species_and_systems":"Human patient-derived glioblastoma organoids and endothelial cells [PMID:41297453].","localisation_and_range":"Ligand is flagged secreted, not transmembrane [flag]; as a collagen it is a matrix ligand, but this is not shown by the cited papers.","caveats":"Abstract only; the binding wording is an abstract statement. No affinity reported. Other rows were review_only or abstract_insufficient.","key_references":[{"PMID":"41297453","why":"COL6A1 binds endothelial ITGB1 in TMZ-resistant glioblastoma"}],"covers":["LR006971"]},"LR009095":{"pair":"COL6A1 -> ITGB1","headline":"Single abstract-level claim that COL6A1 binds ITGB1 on endothelial cells in glioblastoma; thinly supported.","interaction_type":"direct binding","direction_and_effect":"COL6A1 is reported to bind ITGB1 on endothelial cells, leading to disruption of tight junctions via UBD-mediated degradation of claudin-5 [PMID:41297453].","molecular_requirements":"ITGB1 alone is named; the partnering alpha subunit is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human glioblastoma context (patient-derived GBM organoid model, endothelial cells); paper read as abstract only [PMID:41297453].","localisation_and_range":"Ligand is flagged secreted and not transmembrane [flag]; collagen deposited in matrix is not addressed in our evidence beyond that.","caveats":"One paper, abstract only; two further papers were judged abstract-insufficient and one review-only. No databases support this pair. Assay labelled direct binding, but the sentence is a statement in an abstract.","key_references":[{"PMID":"41297453","why":"Reports COL6A1 bound to ITGB1 on endothelial cells in GBM"}],"covers":["LR009095"]},"LR003875":{"pair":"CORT -> SSTR3","headline":"Cortistatin binds SSTR3 with high affinity in two recombinant-receptor binding papers, plus GtoPdb.","interaction_type":"direct binding","direction_and_effect":"Human cortistatin-17 bound all human SSTR subtypes much like rat CST-14 and inhibited forskolin-induced cAMP production through SSTRs [PMID:9125122]. [125I]Tyr10-CST bound all five receptors with high affinity and no marked selectivity versus somatostatin [PMID:9650799]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"No co-receptor reported in our evidence.","affinity_potency":[{"value":"pKd 10.06","assay":"[125I]Tyr10-CST radioligand binding","system":"human sst3 stably expressed in CCL39 cells","cite":"PMID:9650799"},{"value":"pKi 8.7-9.9","assay":"GtoPdb full agonist","system":"not reported","cite":"PMID:15333679"}],"species_and_systems":"Human receptors in CCL39 cells [PMID:9650799]; human peptide on human SSTRs [PMID:9125122]; mouse pair ortholog-inferred.","localisation_and_range":"CORT secreted and SSTR3 transmembrane by flags [flag].","caveats":"Abstract-level reads; pan-SSTR binding, so not subtype-specific, and the radioligand is an iodinated CST14 analogue [PMID:9650799]. BioGRID also lists the pair [DB:BioGRID].","key_references":[{"PMID":"9650799","why":"Binding of cortistatin to all five human SSTRs, pKd values"},{"PMID":"9125122","why":"Human cortistatin binds all SSTR subtypes and lowers cAMP"}],"covers":["LR000369","LR003875"]},"LR003884":{"pair":"CSF2 -> SDC2","headline":"GM-CSF was reported to bind syndecan-2 on osteoblasts; one abstract-read paper, a proteoglycan co-receptor rather than a signalling receptor.","interaction_type":"direct binding","direction_and_effect":"Biotinylated recombinant human GM-CSF was found to bind syndecan-2; syndecan-2 and GM-CSF co-localised by immuno-EM, and antisense knockdown abolished mitogenic activity [PMID:10734053].","molecular_requirements":"Syndecan-2 co-immunoprecipitated with the GM-CSF receptor alpha chain, suggesting it works alongside the receptor, not instead of it [PMID:10734053].","affinity_potency":[],"species_and_systems":"Human primary osteoblasts, recombinant human GM-CSF [PMID:10734053]. Mouse pair is ortholog-inferred.","localisation_and_range":"Receptor is annotated transmembrane and non-secreted [flag]; heparan sulfate proteoglycan at the cell surface per the paper [PMID:10734053].","caveats":"Single paper, abstract only. SDC2 is a proteoglycan co-receptor, so effect on the cell depends on GM-CSF receptor alpha; BioGRID records the same study as a reconstituted complex [DB:BioGRID].","key_references":[{"PMID":"10734053","why":"GM-CSF binding to syndecan-2 in osteoblasts"}],"covers":["LR000378","LR003884"]},"LR006827":{"pair":"CSHL1 -> PRLR","headline":"Database-asserted agonist pair only; no verified paper in our evidence.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists CSHL1 as an agonist of PRLR [DB:GtoPdb]; the interaction is annotated stimulatory.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human pair; no experimental species reported in our evidence.","localisation_and_range":"Not reported in our evidence.","caveats":"Support rests on a single GtoPdb record with no affinity units [DB:GtoPdb]. One paper was judged abstract_insufficient and gives no confirmation.","key_references":[],"covers":["LR006827"]},"LR005729":{"pair":"CTSG -> FPR1","headline":"Cathepsin G is a chemotactic agonist at FPR1 per one abstract-read paper and UniProt.","interaction_type":"functional only","direction_and_effect":"Cathepsin G chemoattracts FPR-expressing RBL cells but not parental cells or cells with other chemoattractant receptors; an anti-FPR antibody and cyclosporin H abolished chemotaxis, so it is an agonist [PMID:15210802]. UniProt states it acts as a ligand for FPR1 [DB:UniProt].","molecular_requirements":"Atypical PKCzeta was essential for chemotaxis; cathepsin G is a weaker Ca2+/MAPK activator than fMLP [PMID:15210802].","affinity_potency":[],"species_and_systems":"Human FPR in rat basophilic leukemia cells and human phagocytes; mouse pair ortholog-inferred [PMID:15210802].","localisation_and_range":"CTSG flagged secreted [flag]; paracrine from neutrophil granules.","caveats":"Functional chemotaxis, no binding or affinity measurement in our evidence; abstract only; one further paper pending.","key_references":[{"PMID":"15210802","why":"Cathepsin G identified as chemotactic agonist for FPR"}],"covers":["LR002453","LR005729"]},"LR005738":{"pair":"Cxcl12 -> Gpr182","headline":"Mouse Cxcl12-Gpr182: same single paper as human, nanomolar binding and scavenging; murine chemokines gave very similar affinities.","interaction_type":"direct binding","direction_and_effect":"GPR182 bound CXCL12 without Gq/Gi or beta-arrestin signalling and internalised ligand-independently [PMID:33875597]. Gpr182-deficient mice had two- to threefold higher CXCL10 and CXCL12 plasma levels and fewer bone-marrow hematopoietic stem cells [PMID:33875597]. UniProt calls it a scavenger [DB:UniProt].","molecular_requirements":"Single chain; not reported otherwise in our evidence.","affinity_potency":[{"value":"KD 41 nM","assay":"saturation binding of fluorescent human CXCL12","system":"human GPR182 in HEK293 cells","cite":"PMID:33875597"}],"species_and_systems":"The KD was measured with human proteins; murine chemokines binding mouse GPR182 had 'very similar affinities', without a number in the excerpts; in vivo work in mice [PMID:33875597].","localisation_and_range":"Ligand flagged secreted [flag]; Gpr182 in endothelium; scavenging of circulating chemokine [PMID:33875597].","caveats":"One primary paper. The curator labelled experiment species human, whereas this dossier is a mouse pair, so the species label should be checked. Scavenger/decoy, not a signalling receptor.","key_references":[{"PMID":"33875597","why":"Binding, scavenging and knockout mice"}],"covers":["LR005738"]},"LR001769":{"pair":"CXCL12 -> ITGA5","headline":"One abstract-only 2018 paper: CXCL12 binds integrin allosteric site 2 and activates integrin alpha5beta1 independently of CXCR4.","interaction_type":"direct binding","direction_and_effect":"Integrin activation was shown by direct binding to the allosteric site 2: SDF1 activated soluble integrin alphavbeta3 in cell-free conditions and the site 2 peptide bound SDF1 [PMID:29301984]. SDF1 activated integrin alpha5beta1 on CXCR4-negative CHO cells, suppressed by site 2 peptide and not by AMD3100 [PMID:29301984]. Effect is activating. UniProt agrees [DB:UniProt].","molecular_requirements":"The binding unit appears to be the alpha/beta heterodimer, not ITGA5 alone; the paper tested alphavbeta3, alpha4beta1 and alpha5beta1 [PMID:29301984]. Proteoglycan binding of SDF1 is proposed to facilitate activation. Mutations in SDF1's predicted site 2 binding region suppressed activation.","affinity_potency":[],"species_and_systems":"Cell-free soluble integrin and CHO cells; species labelled human by the curator, not stated in the abstract. The mouse pair is projected from human.","localisation_and_range":"CXCL12 is flagged secreted [flag]; activation was proposed for SDF1 presented on proteoglycans [PMID:29301984].","caveats":"Abstract only; one paper from one group; no affinity reported. Receptor is a heterodimer and CCC tools may score subunits separately.","key_references":[{"PMID":"29301984","why":"Only paper: CXCL12 site 2 integrin activation"}],"covers":["LR001769","LR005126"]},"LR005747":{"pair":"Cxcl9 -> Gpr182","headline":"Mouse Cxcl9 is a probable scavenged ligand of Gpr182 from one in vivo knockout paper; no direct binding shown.","interaction_type":"functional only","direction_and_effect":"Gpr182 acts as a chemokine scavenger. In GPR182-deficient mice, tumours had increased CXCL9 and other chemokines, more T-cell infiltration and better antitumour immunity, reversed by CXCR3 blockade [PMID:35013216]. UniProt lists CXCL9 as scavenged by the human receptor [DB:UniProt]. Effect is decoy/scavenger.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Knockout mice with transplanted melanomas (YUMM1.7, B16) [PMID:35013216]. The curator recorded human experiment species, which conflicts with this.","localisation_and_range":"Ligand flagged secreted; receptor flagged as receptor only [flag].","caveats":"Indirect: chemokine levels in knockout tumours, not CXCL9 binding to Gpr182; CXCL9 is one of several chemokines raised [PMID:35013216]. Read as abstract plus excerpts.","key_references":[{"PMID":"35013216","why":"GPR182 knockout raises intratumoral CXCL9 and CXCL10"}],"covers":["LR005747"]},"LR007187":{"pair":"DHH -> CDON:PTCH1","headline":"No support for the complex: the only verified paper is negative (Ptch2, not Ptch1, is the Dhh receptor in tilapia); only DHH-CDON binding is in databases.","interaction_type":"database-asserted only","direction_and_effect":"Nile tilapia knockouts of ptch1 and ptch2 in stem Leydig cells indicate Ptch2 likely acts as the functional receptor for Dhh; ptch2 mutation rescued dhh-mutant testis defects, and Ptch1 was not implicated [PMID:42371991]. CDON is never mentioned [PMID:42371991]. UniProt states generically that Hedgehog binds patched receptor PTCH1 or PTCH2 and that two PTCH1 molecules engage one hedgehog molecule [DB:UniProt].","molecular_requirements":"A CDON:PTCH1 complex as a joint receptor is not demonstrated in our evidence. The PDB structure 3N1Q shows DhhN with only the CDON fibronectin domain [DB:PDB 3N1Q]; this does not show PTCH1.","affinity_potency":[],"species_and_systems":"The negative paper used Nile tilapia, in vitro and in vivo [PMID:42371991]; structural data are mammalian [DB:PDB 3N1Q].","localisation_and_range":"DHH is flagged secreted and transmembrane [flag]; no range data in our evidence.","caveats":"Abstract-level negative read, in a fish, so it does not exclude PTCH1 in mammals. Complex assembly is an annotation, not tested. Per-subunit scoring by CCC tools would require both partners.","key_references":[{"PMID":"42371991","why":"Negative: Ptch2 is the Dhh receptor in tilapia"}],"covers":["LR007187"]},"LR003929":{"pair":"DHH -> HHIP","headline":"Well supported direct binding: crystal structure of the HHIP-DHH complex, plus a paper showing Hip binds all three mammalian Hedgehogs.","interaction_type":"direct binding","direction_and_effect":"HHIP is a vertebrate-specific inhibitor of Hh signalling; the structure of human HHIP ectodomain with DHH was solved [PMID:19561611]. Hip binds all three mammalian Hedgehog proteins with an affinity comparable to that of Ptc-1, and is proposed to attenuate Hedgehog signalling as a negative feedback [PMID:10050855].","molecular_requirements":"Interaction determinants were confirmed by biophysical studies and mutagenesis; Zn2+ makes a key contribution to the Hh-HHIP interface and Ca2+ likely prevents electrostatic repulsion [PMID:19561611]. A single receptor chain is involved; no co-receptor is reported.","affinity_potency":[],"species_and_systems":"Human HHIP ectodomain and DHH in crystal structures (recombinant) [PMID:19561611]; the 1999 work concerns mammalian Hip and Hedgehog proteins [PMID:10050855]. Database records: PDB 2WG3, IntAct solid phase assay and molecular sieving, UniProt [DB:PDB 2WG3] [DB:IntAct] [DB:UniProt].","localisation_and_range":"HHIP is flagged as a receptor, not transmembrane, while DHH is flagged secreted and transmembrane [flag]; the 1999 paper describes Hip as a membrane glycoprotein [PMID:10050855].","caveats":"Both confirmed papers were read as abstract or full text without a numeric affinity for DHH in our excerpts; the 1999 paper gives affinity only as comparable to Ptc-1. Two further rows were abstract-insufficient.","key_references":[{"PMID":"19561611","why":"Crystal structure of HHIP-DHH complex"},{"PMID":"10050855","why":"Hip binds all three mammalian Hedgehog proteins"}],"covers":["LR000437","LR003929"]},"LR007916":{"pair":"DKK1 -> KREMEN1:LRP6","headline":"Structural evidence for a ternary DKK1-KREMEN1-LRP6 complex, plus strong DKK1-LRP6 binding records.","interaction_type":"direct binding","direction_and_effect":"A low-resolution crystal structure shows the ternary complex of LRP6 PE3-PE4, DKK1 CRD2 and KRM1ECD, with DKK1 CRD2 sandwiched between LRP6 PE3 and the KRM1 Kringle-WSC domains [PMID:27524201]. Kremen1 and 2 are described as co-receptors for Dkk proteins [PMID:27524201].","molecular_requirements":"All three chains are present: DKK1 binds LRP6 PE3 and KRM1 on the opposite side; modeling plus SPR suggest a KRM1 CUB-LRP6 PE2 contact [PMID:27524201]. UniProt records DKK1-KREM1 ternary complex [DB:UniProt]. BioGRID and IntAct hold DKK1-LRP6 records [DB:BioGRID] [DB:IntAct].","affinity_potency":[],"species_and_systems":"Recombinant human protein structures [PMID:27524201].","localisation_and_range":"Both Kremen1 and LRP6 are flagged transmembrane [flag].","caveats":"The ternary structure is low resolution, and the KRM1-LRP6 contact is modeled; one further row was abstract-insufficient.","key_references":[{"PMID":"27524201","why":"Ternary LRP6-DKK1-KRM1 crystal structure"}],"covers":["LR007916"]},"LR001778":{"pair":"DKK2 -> KREMEN1","headline":"Direct Kremen1-Dkk2 interaction implied in zebrafish; one abstract-only paper, indirect evidence.","interaction_type":"functional only","direction_and_effect":"EpCAM directly binds Kremen1 and disrupts the Kremen1-Dickkopf2 (Dkk2) interaction, which prevents Kremen1-Dkk2-mediated removal of Lrp6 from the cell surface [PMID:23484855].","molecular_requirements":"Kremen1-Dkk2 acts to remove Lrp6 from the surface; EpCAM antagonises this [PMID:23484855].","affinity_potency":[],"species_and_systems":"Zebrafish (hi2151/epcam mutants) [PMID:23484855]; human and mouse pairs are both ortholog-inferred.","localisation_and_range":"DKK2 flagged secreted; KREMEN1 flagged receptor [flag].","caveats":"The direct binding reported in the abstract is EpCAM-Kremen1; Dkk2-Kremen1 interaction is stated as background to the model. Abstract only; one further row also confirmed from the same context.","key_references":[{"PMID":"23484855","why":"EpCAM disrupts Kremen1-Dkk2 interaction in zebrafish"}],"covers":["LR001778","LR005134"]},"LR005756":{"pair":"DKK3 -> CKAP4","headline":"DKK3 reported to interact with CKAP4 in muscle cells to cause atrophy; single recent paper, no direct binding measurement shown.","interaction_type":"functional only","direction_and_effect":"DKK3 is secreted by skeletal muscle cells, acts in autocrine and paracrine manners and interacts with the cell surface receptor CKAP4 to induce mitochondrial dysfunction and myotube atrophy; DKK3 ablation prevented cigarette smoke-induced muscle dysfunction [PMID:39571512]. Direction is agonist-like in the curator record.","molecular_requirements":"Not reported in our evidence (no subunit or co-receptor requirement).","affinity_potency":[],"species_and_systems":"Human and mouse pair entries, both ortholog-inferred. The paper used C2C12 myocytes with DKK3 overexpression and knockdown and patient plasma cohorts [PMID:39571512].","localisation_and_range":"Secreted by muscle cells, autocrine/paracrine [PMID:39571512]; DKK3 is also flagged secreted [flag].","caveats":"Assay is labelled direct_binding but the abstract and excerpts shown describe functional effects and an interaction claim, not a binding assay or affinity. Only one paper; no database record.","key_references":[{"PMID":"39571512","why":"DKK3-CKAP4 interaction driving myotube atrophy"}],"covers":["LR002488","LR005756"]},"LR002489":{"pair":"DKK3 -> KREMEN1","headline":"DKK3 interacts with Krm1 in one 2010 paper using biochemical and functional assays; single-paper support.","interaction_type":"direct binding","direction_and_effect":"Dkk3 interacts with Krm1 and Krm2, contrary to earlier studies; Krm2 abolished Dkk3-mediated potentiation of Wnt signalling [PMID:20370576]. Curator direction is agonist for the Dkk3 pro-Wnt effect.","molecular_requirements":"Dkk3 did not interact with, or alter expression of, LRP6, so LRP6 is not needed for this binding; blocking glycosylation did not change the Dkk3-Krm interaction [PMID:20370576].","affinity_potency":[],"species_and_systems":"Human proteins per the curator record; the mouse pair is listed and the human pair is ortholog-inferred [PMID:20370576]. Specific cell system not recorded.","localisation_and_range":"Membrane-bound Kremen receptor; DKK3 flagged secreted [flag]. Range not otherwise reported.","caveats":"One paper only, no database record. Affinity not reported in our evidence. Earlier studies reported no such interaction, per this paper [PMID:20370576].","key_references":[{"PMID":"20370576","why":"Dkk3 interacts with Krm1 and Krm2, not LRP6"}],"covers":["LR002489","LR005757"]},"LR003938":{"pair":"DLK1 -> NOTCH1","headline":"DLK1 interacts with NOTCH1 EGF-like repeats and inhibits NOTCH signalling; one primary paper plus Reactome.","interaction_type":"direct binding","direction_and_effect":"DLK1 interacts with specific EGF-like repeats of the NOTCH1 extracellular region involved in canonical ligand binding, inhibiting basal NOTCH signalling in preadipocytes and mesenchymal multipotent cells; DLK1 and DLK2 act as inhibitory non-canonical ligands [PMID:21419176]. This is described from the authors' earlier reports.","molecular_requirements":"DLK1 also interacts with itself; a membrane DLK1 variant lacking the TACE recognition sequence also inhibits NOTCH signalling [PMID:21419176].","affinity_potency":[],"species_and_systems":"Cell studies in preadipocytes and mesenchymal cells; human pair ortholog-inferred, mouse pair direct [PMID:21419176]. Reactome lists a NOTCH1:DLK1 plasma membrane complex [DB:Reactome].","localisation_and_range":"DLK1 flagged both secreted and transmembrane [flag]; the TACE-sequence finding concerns shedding [PMID:21419176].","caveats":"The curated paper is mainly about DLK2 and refers to DLK1 findings from previous reports; abstract only. Two review-only papers not shown. No affinity reported.","key_references":[{"PMID":"21419176","why":"DLK1/DLK2 inhibitory non-canonical NOTCH1 ligands"}],"covers":["LR000446","LR003938"]},"LR007376":{"pair":"DLL3 -> NOTCH1","headline":"DLL3 interacts with full-length Notch1 in cis in vitro and inhibits Notch; one paper, abstract-read.","interaction_type":"direct binding","direction_and_effect":"DLL3 does not bind in trans to Notch and does not activate the receptor but shows cis-interaction and cis-inhibition in vitro; O-fucosylation-deficient DLL3 still interacted with full length Notch1 and could still inhibit Notch in cis [PMID:25856312]. Effect: inhibitory.","molecular_requirements":"DLL3 EGF repeats 2 and 5 are O-fucosylated at POFUT1 sites and modified by FNG proteins in vitro; this is not needed for the interaction [PMID:25856312].","affinity_potency":[],"species_and_systems":"Cultured cells in vitro; species not recorded [PMID:25856312]. Reactome lists a DLL3:NOTCH1 complex on the endosome membrane [DB:Reactome].","localisation_and_range":"Cis-interaction within the same cell; DLL3 is flagged not secreted and transmembrane [flag], and sits in the trans-Golgi per the abstract [PMID:25856312].","caveats":"Not a conventional trans ligand-receptor pair; cis-inhibitory role only. Abstract only; three review-only and two abstract-insufficient papers not shown.","key_references":[{"PMID":"25856312","why":"DLL3 cis-interaction and inhibition of Notch1"}],"covers":["LR007376"]},"LR001787":{"pair":"DSC2 -> DSG1","headline":"Heterophilic DSC2-DSG1 binding inferred from a family-wide study plus database records.","interaction_type":"direct binding","direction_and_effect":"All Dsgs form adhesive dimers with all Dscs with characteristic affinities, including DSC2:DSG1 [PMID:27298358]. BioGRID lists DSC2-DSG1 affinity capture-Western [DB:BioGRID]; IntAct a solid phase assay [DB:IntAct].","molecular_requirements":"Strand-swap binding; Dsc2 ectodomain crystal structure was reported [PMID:27298358].","affinity_potency":[],"species_and_systems":"Human ectodomains [PMID:27298358].","localisation_and_range":"Both annotated transmembrane [flag]; trans-cellular adhesion [PMID:27298358].","caveats":"Abstract read only; no pair-specific affinity. One of 25 companion rows from one paper.","key_references":[{"PMID":"27298358","why":"Family-wise Dsg:Dsc binding and structures"}],"covers":["LR001787"]},"LR005765":{"pair":"DSC3 -> DSC3","headline":"Homophilic DSC3 trans self-binding shown by cross-linking in human keratinocytes; abstract-level evidence only.","interaction_type":"direct binding","direction_and_effect":"DSC3 binds itself: extracellular cross-linking gave homophilic, isoform-specific adducts in HaCaT keratinocytes, consistent with trans (cell-cell) interaction [PMID:21098030]. No directional effect beyond a curator agonist-style label is reported.","molecular_requirements":"Trp-2 and Ala-80 mutation abolished Dsc2 binding specifically, not tested for DSC3, so a requirement for DSC3 is not shown [PMID:21098030]. Other subunits or co-receptors: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human HaCaT keratinocytes (cross-linking, electron microscopy) [PMID:21098030]. Pair is recorded for human and mouse (mouse projected from human).","localisation_and_range":"Membrane-bound desmosomal cadherin; trans cell-cell contact, with adducts in the detergent-insoluble fraction and probably in desmosomes by electron microscopy [PMID:21098030]. Entity flags mark it as a transmembrane receptor [flag].","caveats":"Only the abstract was read. The authors found no evidence for heterophilic or cis interaction (not fully excluded), so this paper argues against, not for, DSC3 binding Dsg partners [PMID:21098030]. No affinity reported, and no database record.","key_references":[{"PMID":"21098030","why":"Cross-linking evidence for homophilic, isoform-specific desmosomal cadherin binding"}],"covers":["LR002497","LR005765"]},"LR008393":{"pair":"DSCAM -> PTPRT","headline":"DSCAM binds PTPRT by SPR in a high-throughput human IgSF interactome study; single paper.","interaction_type":"direct binding","direction_and_effect":"The study reports binding of DSCAM-CT and DSCAML1-CT to PTPRT and PTPRM by SPR [PMID:32822567]. Signalling direction or effect is not reported in our evidence.","molecular_requirements":"Only the C-terminal ectodomain region (DSCAM-CT) was tested as analyte against PTPRs as ligands; subunit or co-receptor requirements not reported in our evidence [PMID:32822567].","affinity_potency":[],"species_and_systems":"Human recombinant proteins; SPR at 2-fold dilutions from 16 to 2,048 nM, following an ELISA-based pooled screen [PMID:32822567].","localisation_and_range":"Not reported by the paper beyond ectodomain-level binding. Entity flags mark DSCAM as secreted, transmembrane and a receptor, an annotation-only flag [flag].","caveats":"Sensorgram binding only; no Kd is given in our excerpts. Pairs from the same SPR panel (e.g. PTPRK) were untested for lack of protein. The sentence covers both DSCAM and DSCAML1 and both PTPRT and PTPRM, so this row inherits a shared statement [PMID:32822567].","key_references":[{"PMID":"32822567","why":"Human IgSF cell-surface interactome with SPR validation of DSCAM/DSCAML1 with PTPRT/PTPRM"}],"covers":["LR008393"]},"LR002498":{"pair":"DSCAM -> UNC5C","headline":"DSCAM associates with UNC5C, stimulated by netrin-1, in neurons; co-association evidence at abstract level plus UniProt.","interaction_type":"direct binding","direction_and_effect":"DSCAM interacts with UNC5C and netrin-1 stimulates the interaction in primary cortical neurons and postnatal cerebellar granule cells [PMID:22685302]. Knockdown of either, or dominant-negative mutants, suppressed netrin-1-induced growth-cone collapse in mouse cerebellar EGL cells [PMID:22685302].","molecular_requirements":"UniProt records an interaction of the DSCAM extracellular domain with the UNC5C Ig-like C2-type domain, citing this paper [DB:UniProt]. Netrin-1 acts as a stimulus; Src-family kinase inhibition reduced the DSCAM-UNC5C interaction [PMID:22685302].","affinity_potency":[],"species_and_systems":"Primary neurons and brain tissue, with mouse cerebellar EGL cells used for collapse assays [PMID:22685302]. The curator labels both partners as human; the abstract names no species for the co-association, so treat species as unclear. Pair also recorded for mouse (projected).","localisation_and_range":"Transmembrane receptors on neurons, partly co-localised in primary neurons and brain tissue [PMID:22685302]; DSCAM also carries a secreted flag [flag].","caveats":"Abstract read only; the interaction is shown as association in cells (stimulated by netrin-1), not as binding of purified proteins, and may be indirect or netrin-mediated. UniProt's domain assignment rests on the same paper [DB:UniProt].","key_references":[{"PMID":"22685302","why":"DSCAM-UNC5C association and role in netrin-1 growth-cone collapse"}],"covers":["LR002498","LR005766"]},"LR001796":{"pair":"DSG2 -> DSC1","headline":"DSG2 -> DSC1: heterophilic desmosomal cadherin binding, supported by a single family-wide paper.","interaction_type":"direct binding","direction_and_effect":"The paper reports that all desmogleins form adhesive dimers with all desmocollins, with affinities characteristic of each Dsg:Dsc pair, so this pair is covered by the family-wise heterophilic result [PMID:27298358]. Binding is trans-cellular and heterodimers are called the fundamental adhesive unit of desmosomes [PMID:27298358].","molecular_requirements":"Ectodomains of one Dsg and one Dsc are sufficient for dimer formation in the reported solution biophysics and bead aggregation; binding uses a strand-swap mechanism with charge-based heterophilic preference [PMID:27298358]. No further subunits or co-receptors reported.","affinity_potency":[],"species_and_systems":"Experiments used human proteins (solution biophysics, SPR and coated-bead aggregation) [PMID:27298358]. Pair is recorded for: human, mouse (ortholog-projected). The mouse entry is projected from human evidence.","localisation_and_range":"Membrane-bound desmosomal cadherins acting in trans between adjacent cells (juxtacrine/contact) [PMID:27298358]; entity flags mark both as receptors and transmembrane where set [flag].","caveats":"Curators read only the abstract; the paper's family-wide statement is applied to this pair, one of 25 companion rows, and no pair-specific affinity is in our dossier. The crystal structures cited cover Dsg2, Dsg3, Dsc1 and Dsc2 only [PMID:27298358]. Database records also exist (BioGRID, IntAct), which are not independent of the evidence above. [DB:BioGRID] [DB:IntAct]","key_references":[{"PMID":"27298358","why":"Family-wise Dsg:Dsc heterophilic binding by biophysics, SPR, bead aggregation and crystal structures"}],"covers":["LR001796","LR005152"]},"LR005774":{"pair":"DSG4 -> DSC1","headline":"Heterophilic DSG4:DSC1 binding by SPR from one paper; full text read by browser, quote unverifiable.","interaction_type":"direct binding","direction_and_effect":"SPR of human Dsg and Dsc ectodomains in all pairwise combinations showed strong heterophilic binding when a Dsg was passed over a Dsc surface or vice versa [PMID:27298358].","molecular_requirements":"Ectodomain-level binding; strand-swap mechanism and charge-based heterophilic preference described in the abstract [PMID:27298358].","affinity_potency":[{"value":"KD 3.6-43.9 uM","assay":"SPR (Biacore T100), all pairwise Dsg/Dsc combinations","system":"human ectodomains","cite":"PMID:27298358"}],"species_and_systems":"Human recombinant ectodomains; mouse pair is ortholog-inferred.","localisation_and_range":"Both partners are flagged as non-secreted receptors, so this is membrane-bound, contact-dependent (juxtacrine) adhesion [flag].","caveats":"The KD range spans all pairwise combinations, not DSG4:DSC1 alone. The curator note says the browser-read quote is unverifiable with spot-check pending.","key_references":[{"PMID":"27298358","why":"SPR of Dsg:Dsc heterophilic binding"}],"covers":["LR002506","LR005774"]},"LR003947":{"pair":"EBI3 -> IL6ST","headline":"EBI3 alone binds IL-6 and drives gp130 trans-signalling in one paper; as an IL-27 subunit, it also engages IL6ST.","interaction_type":"conflicting","direction_and_effect":"EBI3 activated STAT3 and proliferation in IL-6-dependent B9 cells, via IL-6 trans-signalling, less efficiently than soluble IL-6Ralpha; co-IP and SPR indicated EBI3 binds IL-6 [PMID:28280243]. Binding to gp130 itself is not shown.","molecular_requirements":"The IL-27 route needs the p28 partner; UniProt describes the IL27/EBI3 heterodimer signalling via IL27RA and IL6ST [DB:UniProt]. PDB structures contain EBI3 and IL6ST chains [DB:PDB 7U7N].","affinity_potency":[],"species_and_systems":"Human proteins; B9 mouse plasmacytoma line and Ba/F3 transfectants; abstract only.","localisation_and_range":"EBI3 is flagged as secreted; IL6ST is flagged as transmembrane [flag].","caveats":"The confirmed paper shows EBI3 binding IL-6, not IL6ST; the direct EBI3-IL6ST link is indirect. Abstract only.","key_references":[{"PMID":"28280243","why":"EBI3 binds IL-6 and drives gp130 trans-signalling"}],"covers":["LR000456","LR003947"]},"LR003956":{"pair":"EDN3 -> EDNRB","headline":"ET-3 is a well-supported agonist of ETB with binding, functional and in vivo evidence.","interaction_type":"direct binding","direction_and_effect":"ET-3 is an agonist: equal potency with ET-1 in displacing 125I-ET-1 and in Ca2+ responses [PMID:1713452]; ET-3 competed with ETB selectivity over ETA in heart tissue [PMID:8904635]; ET-3 contracts gallbladder mainly via ETB [PMID:11982704]; a mouse Edn3 knockout and lethal-spotting mutation indicate the interaction is essential for neural-crest lineages [PMID:8001160]. GtoPdb: full agonist [DB:GtoPdb].","molecular_requirements":"Domain mapping: replacing the second and third extracellular regions of ETB with ETA's raised ET-3 Ki, and a Lys-161 substitution reduced ET-3 affinity 5.6-fold [PMID:8086489]. In vivo, ET-3 must be proteolytically activated from big-EDN3 [PMID:8001160].","affinity_potency":[{"value":"Ki 5 x 10(-11) M","assay":"125I-ET-1 displacement, wild-type ETB (rose to 10(-8) M with ETA domains)","system":"CHO cells, human ETB","cite":"PMID:8086489"},{"value":"pKd 9.8 to 11.5","assay":"GtoPdb range, full agonist","system":"not stated","cite":"DB:GtoPdb"}],"species_and_systems":"Human cloned receptor in COS and CHO cells [PMID:1713452][PMID:8086489]; human and rat heart [PMID:8904635]; human and opossum gallbladder [PMID:11982704]; mouse genetics [PMID:8001160]. Both species pairs are listed. BioGRID reconstituted complex [DB:BioGRID]; PDB 6IGK [DB:PDB 6IGK].","localisation_and_range":"ET-3 annotated secreted, ETB transmembrane [flag].","caveats":"All shown papers were read as abstracts only. ETB is non-selective between ET-1 and ET-3, so ET-3 is not unique to it [PMID:1713452]. Species of the heart binding study is unspecified in the record [PMID:8904635].","key_references":[{"PMID":"8086489","why":"ET-3 binding determinants on ETB"},{"PMID":"8001160","why":"EDN3-EDNRB essential in vivo"},{"PMID":"1713452","why":"cloned human ETB, ET-1 and ET-3 equipotent"}],"covers":["LR000465","LR003956"]},"LR003965":{"pair":"EFNA1 -> EPHA8","headline":"Ephrin-A1 binds EphA8 in fibroblasts in one abstract-read paper.","interaction_type":"direct binding","direction_and_effect":"Ephrin-A1 and ephrin-A4 Fc chimeras efficiently bound EphA8 expressed in NIH3T3 fibroblasts, confirmed by EphA8 tyrosine phosphorylation on stimulation [PMID:10515610]. Agonist.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Fc-fusion ligand on EphA8-expressing NIH3T3 cells, recorded as human ligand and receptor [PMID:10515610]. Human pair ortholog-inferred, mouse not.","localisation_and_range":"EFNA1 annotated secreted and transmembrane [flag].","caveats":"One paper, abstract only; no affinity reported.","key_references":[{"PMID":"10515610","why":"ephrin-A1 chimera binds and activates EphA8"}],"covers":["LR000474","LR003965"]},"LR003974":{"pair":"EFNA3 -> EPHA1","headline":"Database-only: UniProt says EphA1 binds EFNA3 with low affinity; no papers judged.","interaction_type":"database-asserted only","direction_and_effect":"UniProt: EPHA1 binds EFNA3 and EFNA4 with low affinity and EFNA1 with high affinity, EFNA1 likely being the cognate ligand [DB:UniProt PMID:17634955]. Effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experimental species not reported in our evidence; human pair is not ortholog-inferred, mouse is.","localisation_and_range":"EFNA3 annotated transmembrane, EPHA1 transmembrane [flag].","caveats":"Low-affinity binding is a database statement only; no paper in our dossier tests it.","key_references":[],"covers":["LR000483","LR003974"]},"LR005783":{"pair":"EFNA4 -> EPHA10","headline":"Exogenous ephrin-A4 drives EPHA10-dependent migration and stemness in oral cancer cells; functional only.","interaction_type":"functional only","direction_and_effect":"Among EPHA10 ligands, exogenous EFNA4 induced the most OSCC cell migration and sphere formation and up-regulated SNAIL, NANOG and OCT4; EPHA10 was required for these effects, which were abolished by ERK inhibition [PMID:33436772].","molecular_requirements":"EPHA10 required for EFNA4-induced effects [PMID:33436772]; other subunits not reported.","affinity_potency":[],"species_and_systems":"Human oral squamous cell carcinoma cells, including an in vivo tumour model for EPHA10 [PMID:33436772]. Mouse pair is ortholog-inferred.","localisation_and_range":"EFNA4 is flagged both secreted and transmembrane; EPHA10 flagged secreted [flag].","caveats":"No direct binding assay in our evidence; read as an abstract only. Only one confirmed paper (two further judgements were review-only).","key_references":[{"PMID":"33436772","why":"EFNA4 induces EPHA10-dependent OSCC migration and stemness"}],"covers":["LR002515","LR005783"]},"LR003983":{"pair":"EFNA4 -> EPHA2","headline":"Ephrin-A4 binds EphA2 in several assays, and EFNA4 overexpression activates EPHA2 in liver cancer cells.","interaction_type":"direct binding","direction_and_effect":"An ephrin-A4 immunoglobulin chimera bound EphA2 on human tonsil dendritic-phenotype cells [PMID:10607706]. Ephrin-A4 Fc binds most EphA receptors with high apparent affinity (apparent KD in Fig. 1; values not given in our evidence) [PMID:22568954]. EFNA4 overexpression activated EPHA2 phosphorylation at Ser897 in HCC cells [PMID:34484860].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human tonsil cells [PMID:10607706]; ELISA, species unspecified [PMID:22568954]; human hepatocellular carcinoma cells [PMID:34484860]. Mouse pair is ortholog-inferred.","localisation_and_range":"EFNA4 is flagged both secreted and transmembrane [flag]; a secreted ephrin-A4 form from activated B cells is described [PMID:10607706].","caveats":"The HCC result is overexpression with phosphorylation readout, not binding [PMID:34484860]. The 22568954 result was a browser read with an unverifiable quote. BioGRID lists affinity capture records [DB:BioGRID].","key_references":[{"PMID":"10607706","why":"Ephrin-A4 chimera binds EphA2"},{"PMID":"22568954","why":"ELISA of ephrin-A4 Fc across EphA receptors"},{"PMID":"34484860","why":"EFNA4 activates EPHA2 phosphorylation in HCC"}],"covers":["LR000492","LR003983"]},"LR003992":{"pair":"EFNA5 -> EPHA3","headline":"Ephrin-A5 is a well-established, high-affinity EphA3 ligand: Kd 12 nM, crystal structure and cell effects.","interaction_type":"direct binding","direction_and_effect":"Ephrin-A5 (AL1/LERK7) is the preferred high-affinity ligand for HEK (EphA3), forming a stable 1:1 complex [PMID:9195962]. Ephrin-A5 stimulation of EphA3 inhibits 293A cell migration, reduces NG108-15 neurite outgrowth and collapses hippocampal growth cones [PMID:20697431]. Soluble ephrin-A5, ephrin-A2 and EphA3 extracellular domain abolished repulsive tectal activity in a stripe assay [PMID:9751130].","molecular_requirements":"1:1 complex stoichiometry [PMID:9195962]; the structure shows ephrin-A5 tilted on the EphA3 ligand-binding domain with extra contacts outside the canonical pocket [PMID:25993310]. Cytoplasmic Y602 and Y779 carry signalling [PMID:20697431].","affinity_potency":[{"value":"Kd 12 nM","assay":"surface plasmon resonance, size exclusion HPLC, sedimentation equilibrium (1:1 complex)","system":"HEK exodomain with ephrin-A5-Fc/FLAG fusions","cite":"PMID:9195962"}],"species_and_systems":"Human recombinant proteins and cells [PMID:9195962, PMID:25993310, PMID:20697431]; rat tectal axons [PMID:9751130]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ephrin-A5 flagged membrane-bound; EPHA3 flagged secreted and transmembrane [flag]; soluble forms were active in the stripe assay [PMID:9751130].","caveats":"Most papers were abstract-only reads; 22568954 (ELISA, high apparent affinity for most EphA receptors) was a browser read with an unverifiable quote.","key_references":[{"PMID":"9195962","why":"Kd 12 nM, 1:1 complex"},{"PMID":"25993310","why":"Crystal structure of EphA3 LBD with ephrin-A5"},{"PMID":"20697431","why":"Ephrin-A5 stimulation of EphA3 inhibits migration and neurite outgrowth"}],"covers":["LR000501","LR003992"]},"LR005792":{"pair":"EGF -> NRP1","headline":"One airway-cell study reports EGF binding to NRP1, enhanced by secretoneurin; thinly supported.","interaction_type":"direct binding","direction_and_effect":"In human airway epithelial cells, radioactive binding assays detected EGF binding to NRP1, enhanced by secretoneurin [PMID:24556756]. NRP1 is described there as a co-receptor of EGFR [PMID:24556756].","molecular_requirements":"EGFR co-receptor context; whether NRP1 alone mediates EGF signalling is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human airway epithelial cell lines 16HBE and NCI-H292 [PMID:24556756]. No database records.","localisation_and_range":"EGF is secreted; NRP1 flagged both secreted and transmembrane [flag].","caveats":"Abstract only; no affinity. Binding is described as an enhancement induced by secretoneurin, so basal binding is unclear. The curator note describes it as an indirect potentiation mechanism.","key_references":[{"PMID":"24556756","why":"EGF-NRP1 binding enhanced by secretoneurin in airway cells"}],"covers":["LR002524","LR005792"]},"LR005819":{"pair":"EPHA4 -> EFNA2","headline":"EPHA4-EFNA2 is supported by a crystal structure and pull-down records; no verified papers.","interaction_type":"direct binding","direction_and_effect":"A crystal structure of the EphA4-ephrinA2 complex is recorded [DB:PDB 2WO3]; IntAct lists a pull-down [DB:IntAct]. UniProt states EFNA2 binds EPHA3, EPHA4 and EPHA5 [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiment species not reported in our evidence.","localisation_and_range":"Neither partner is flagged secreted [flag]. The pair is oriented Eph -> ephrin in our records; the evidence describes Eph-ephrin binding without establishing which partner acts as ligand here.","caveats":"Database evidence only; two review-only rows. No affinity data.","key_references":[],"covers":["LR002551","LR005819"]},"LR005837":{"pair":"EPHA7 -> EFNA3","headline":"Database-only pair: one BioGRID Western affinity capture record; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported. Both partners carry the receptor annotation flag [flag], so ligand/receptor direction is not established by our evidence.","molecular_requirements":"Requirements: not reported in our evidence.","affinity_potency":[],"species_and_systems":"No paper was verified for this pair; species and experimental system of the database records are not reported in our evidence.","localisation_and_range":"EPHA7 carries secreted and transmembrane flags; EFNA3 carries a transmembrane flag [flag]; range is unclear.","caveats":"No curator-verified paper; support is database records only. The record is an Affinity Capture-Western entry [DB:BioGRID 280892]; affinity not reported in our evidence. Six papers were judged abstract-insufficient and two review-only.","key_references":[],"covers":["LR002569","LR005837"]},"LR005846":{"pair":"EPHB1 -> EFNB1","headline":"Eph B1-ephrin-B1 pair supported by UniProt statements and an IntAct solid-phase assay; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states ephrin-B1 shows high affinity for EPHB1/ELK and can also bind EPHB2 and EPHB3; EPHB1 entry lists EFNB1, EFNB2 and EFNB3 as cognate/functional ephrin ligands [DB:UniProt]. Activating or inhibitory effect is not reported. Both partners carry the receptor annotation flag [flag], so ligand/receptor direction is not established by our evidence.","molecular_requirements":"Requirements: not reported in our evidence.","affinity_potency":[],"species_and_systems":"No paper was verified for this pair; species and experimental system of the database records are not reported in our evidence.","localisation_and_range":"Both partners are annotated as transmembrane [flag], so any interaction would be juxtacrine (cell contact); this comes from annotation flags only.","caveats":"No curator-verified paper; support is database records only. IntAct reports a solid phase assay [DB:IntAct P98172-P54762], the closest record to a direct binding test; no affinity value is given in our evidence. Four papers were review-only.","key_references":[],"covers":["LR002578","LR005846"]},"LR002579":{"pair":"EPHB1 -> EFNB2","headline":"UniProt-only claim that EFNB2 is a cognate ligand for EPHB1; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"UniProt (EPHB1 entry) states cognate/functional ephrin ligands include EFNB1, EFNB2 and EFNB3 [DB:UniProt]. Effect is not reported. Both partners carry the receptor annotation flag [flag], so ligand/receptor direction is not established by our evidence.","molecular_requirements":"Requirements: not reported in our evidence.","affinity_potency":[],"species_and_systems":"No paper was verified for this pair; species and experimental system of the database records are not reported in our evidence.","localisation_and_range":"Both partners are annotated as transmembrane [flag], so any interaction would be juxtacrine (cell contact); this comes from annotation flags only.","caveats":"No curator-verified paper; support is database records only. Only one UniProt sentence; no assay or affinity in our evidence. Four papers were review-only.","key_references":[],"covers":["LR002579","LR005847"]},"LR005855":{"pair":"EPHB2 -> EFNB2","headline":"Eph B2-ephrin-B2 pair supported by BioGRID, IntAct and a UniProt functional statement; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states forward and reverse signalling through the EFNB2/EPHB2 complex regulate movement and adhesion of cells that tubularize the urethra and septate the cloaca [DB:UniProt]. This implies bidirectional signalling. Both partners carry the receptor annotation flag [flag], so ligand/receptor direction is not established by our evidence.","molecular_requirements":"Requirements: not reported in our evidence.","affinity_potency":[],"species_and_systems":"No paper was verified for this pair; species and experimental system of the database records are not reported in our evidence.","localisation_and_range":"Both partners are annotated as transmembrane [flag], so any interaction would be juxtacrine (cell contact); this comes from annotation flags only.","caveats":"No curator-verified paper; support is database records only. BioGRID lists a Reconstituted Complex [DB:BioGRID 315434]; IntAct lists affinity chromatography [DB:IntAct EBI-32718255] and anti-tag coimmunoprecipitation [DB:IntAct EBI-54556805]. Affinity not reported in our evidence.","key_references":[],"covers":["LR002587","LR005855"]},"LR002588":{"pair":"EPHB2 -> EFNB3","headline":"EphB2-ephrin-B3 supported by one ELISA paper (weak binding) and one neuronal functional paper; no database records.","interaction_type":"functional only","direction_and_effect":"Ephrin-B3 Fc binds most weakly of the ephrin-Bs to all EphB receptors in ELISA [PMID:22568954]. In cultured cortical neurons, a trans-synaptic EphB2 (presynaptic) to ephrin-B3 (postsynaptic) interaction regulates excitatory synapse density; ephrin-B3 is reported to limit synapse density by directly binding Erk1/2 and inhibiting Ras/MAPK signalling [PMID:20410461]. The curator labels the effect antagonist.","molecular_requirements":"Not reported in our evidence beyond the two partners. Ephrin-B3 is reported to bind heparan sulfate proteoglycans [PMID:22568954].","affinity_potency":[],"species_and_systems":"Cultured cortical neurons; curator records human for both partners, but the abstract does not state the species [PMID:20410461]. ELISA with Fc proteins, species unspecified [PMID:22568954].","localisation_and_range":"Trans-synaptic, contact-dependent signalling [PMID:20410461]. Both partners transmembrane-flagged [flag].","caveats":"Both papers were read as abstracts or by browser; the ELISA quote is marked unverifiable pending spot-check. The binding paper reports the weakest binding for this ephrin; apparent KD values are in a figure not in our evidence. The functional paper's output runs through ephrin-B3 intracellular binding of Erk1/2, so it does not by itself test EphB2 binding.","key_references":[{"PMID":"20410461","why":"Trans-synaptic EphB2-ephrin-B3 regulation of synapse density, abstract."},{"PMID":"22568954","why":"ELISA: ephrin-B3 Fc binds EphB receptors most weakly."}],"covers":["LR002588","LR005856"]},"LR005864":{"pair":"EPHB4 -> EFNB2","headline":"Well supported EphB4-ephrin-B2 binding: ELISA, a PDB structure, SPR and reconstituted-complex records, plus a cis-inhibition paper.","interaction_type":"direct binding","direction_and_effect":"Ephrin-B2 Fc binds best of the three ephrin-Bs to all EphB receptors in ELISA [PMID:22568954]. In cancer cells, coexpressed ephrin-B2 inhibits EphB4 through cis association, in addition to its trans interactions [PMID:24348920]; the curator labels this effect antagonist.","molecular_requirements":"Not reported beyond the two partners. A crystal structure contains one chain of each protein [DB:PDB 2HLE].","affinity_potency":[],"species_and_systems":"Human cancer cells [PMID:24348920] (species recorded by curator); ELISA with Fc proteins, species unspecified [PMID:22568954].","localisation_and_range":"Both partners transmembrane-flagged [flag]; Eph receptors signal in trans between cells (juxtacrine) and the paper adds cis interactions on the same cell [PMID:24348920].","caveats":"[PMID:22568954] quote was browser-read and marked unverifiable pending spot-check; [PMID:24348920] is full text available but was read as an abstract here. Apparent KD values are in a figure not in our evidence. Other records: BioGRID Reconstituted Complex [DB:BioGRID 3885527] and IntAct surface plasmon resonance [DB:IntAct P52799-P54760].","key_references":[{"PMID":"22568954","why":"ELISA: ephrin-B2 Fc binds EphB receptors best of the ephrin-Bs."},{"PMID":"24348920","why":"Coexpressed ephrin-B2 inhibits EphB4 in cancer cells via cis association."}],"covers":["LR002596","LR005864"]},"LR005873":{"pair":"F11R -> ITGAL","headline":"JAM-A (F11R) is a ligand of LFA-1; the alphaL I domain binds recombinant JAM-A directly.","interaction_type":"direct binding","direction_and_effect":"JAM-1 is a ligand of LFA-1 and contributes to LFA-1-dependent transendothelial migration of T cells and neutrophils [PMID:11812992]. Solid-phase assays confirmed direct binding of recombinant JAM-A to the immobilised locked-open alphaL I domain [PMID:15528364].","molecular_requirements":"The alphaL I domain is crucial; deleting it abolishes adhesion to JAM-A [PMID:15528364]. JAM-A Ig-like domain 2 is required [PMID:11812992]. Evidence is for the LFA-1 heterodimer; ITGAL alone has the binding site.","affinity_potency":[],"species_and_systems":"Human JAM-A and LFA-1 in Jurkat, Mono Mac 6, CHO transfectants and endothelium [PMID:15528364][PMID:11812992]. Reactome and UniProt agree [DB:Reactome][DB:UniProt]. Mouse pair is projected from human evidence [flag].","localisation_and_range":"JAM-A transmembrane; access needs cytokine-induced redistribution out of tight junctions [PMID:11812992].","caveats":"Both papers read as abstracts. No affinity.","key_references":[{"PMID":"15528364","why":"I domain of LFA-1 binds JAM-A directly"},{"PMID":"11812992","why":"JAM-1 identified as LFA-1 ligand in transmigration"}],"covers":["LR002606","LR005873"]},"LR005882":{"pair":"FBLN2 -> ITGAV","headline":"Fibulin-2 binds alpha V beta 3 only weakly; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"Mouse fibulin-2 showed lower binding to alpha V beta 3 than to alpha IIb beta 3, and almost none to alpha 5 beta 1 [PMID:7543056]. RGD-peptide affinity for alpha V beta 3 was 10- to 50-fold lower than for GRGDS [PMID:7543056].","molecular_requirements":"Binding was to the alpha V beta 3 heterodimer; the single RGD site of mouse fibulin-2 is implicated [PMID:7543056].","affinity_potency":[],"species_and_systems":"Purified integrins and recombinant mouse fibulin-2 [PMID:7543056]. Human fibulin-2 (RGD changed to RSS) bound less strongly to alpha IIb beta 3 [PMID:7543056].","localisation_and_range":"FBLN2 is flagged secreted [flag]; matrix protein per the paper [PMID:7543056].","caveats":"Low-activity binding described qualitatively; no affinity values for fibulin-2. Abstract only.","key_references":[{"PMID":"7543056","why":"Compares fibulin-2 binding to five integrins."}],"covers":["LR002615","LR005882"]},"LR007196":{"pair":"FCER2 -> ITGAV:ITGB3","headline":"Human CD23 binds integrin alphaVbeta3; SPR with RKC peptides and cell binding blocked by anti-alphaV.","interaction_type":"direct binding","direction_and_effect":"CD23 peptides bind purified alphaVbeta3 (SPR) [PMID:22560905]. sCD23 binding to alphav+beta3+ Jurkat T cells was inhibited by anti-CD51 (alphaV) mAb AMF7 and vitronectin, and sCD23 bound purified alphav protein [PMID:10037797]. Anti-beta3, anti-CD47 and LM609 did not block binding, though anti-beta3 suppressed CD23 function [PMID:10037797]. Effect labelled agonist [PMID:22560905].","molecular_requirements":"RKC motif from arg172 of CD23 required; no cation dependence [PMID:22560905]. The alphaV chain appears central; beta3 requirement is unclear since anti-beta3 and LM609 did not block binding [PMID:10037797].","affinity_potency":[],"species_and_systems":"Human CD23 and cells; purified integrin for SPR.","localisation_and_range":"CD23 is flagged secreted and transmembrane [flag]; soluble CD23 used.","caveats":"Peptide-based SPR; cell binding evidence is blocking antibody based. No affinity reported. Interaction classed Receptor-Receptor.","key_references":[{"PMID":"22560905","why":"RKC peptide binding to alphaVbeta3 by SPR"},{"PMID":"10037797","why":"sCD23 binding to alphaV integrin cells and function"}],"covers":["LR007196"]},"LR005891":{"pair":"FGF1 -> ITGAV","headline":"Direct FGF1 binding to integrin alphaVbeta3 with a stated Kd about 1 microm; supports signalling but not initial FGFR1 activation.","interaction_type":"direct binding","direction_and_effect":"FGF1 directly bound soluble and cell-surface integrin alphavbeta3, blocked by mAb 7E3 and cyclic RGDfV; the R50E mutant lost integrin binding and was defective in proliferation, migration and chemotaxis while still inducing FGFR1/FRS2alpha phosphorylation and AKT/ERK activation [PMID:18441324]. UniProt states the binding is essential for FGF1 signaling [DB:UniProt].","molecular_requirements":"The partner is the alphavbeta3 heterodimer (ITGAV:ITGB3); beta3 CYDMKTTC loop implicated; FGF1's integrin site overlaps its heparin site but differs from its FGFR site [PMID:18441324]. UniProt describes a ternary complex with FGFR1 and ITGAV:ITGB3 [DB:UniProt].","affinity_potency":[{"value":"KD about 1 microm","assay":"direct binding to soluble and cell-surface alphavbeta3","system":"human FGF1, human integrin","cite":"PMID:18441324"}],"species_and_systems":"Human FGF1 and human integrin alphavbeta3 [PMID:18441324]. Mouse record is ortholog-inferred.","localisation_and_range":"FGF1 is flagged secreted [flag]; interaction occurs with cell-surface integrin [PMID:18441324].","caveats":"Abstract only. Only weak binding to several beta1 integrins tested [PMID:18441324]. ITGAV alone is not separated from the alphaVbeta3 heterodimer. Single primary paper.","key_references":[{"PMID":"18441324","why":"FGF1 binds alphavbeta3, Kd about 1 microm; R50E mutant"}],"covers":["LR002625","LR005891"]},"LR000599":{"pair":"FGF20 -> FGFR4","headline":"FGF20 is reported in a mitogenic screen to activate FGFR4 with high activity; single indirect source.","interaction_type":"functional only","direction_and_effect":"FGF9, 16 and 20 activated FGFRc isoforms and FGFR4 with high activity in the BaF3 mitogenic assay [PMID:16597617].","molecular_requirements":"Not reported in our evidence beyond FGFR4 being activated; heparan sulfate need is not stated.","affinity_potency":[],"species_and_systems":"BaF3 FGFR-expressing cell lines; species unspecified [PMID:16597617]. Mouse pair is ortholog-inferred.","localisation_and_range":"FGF20 flagged secreted; FGFR4 flagged secreted and transmembrane [flag].","caveats":"One paper, a subfamily-level statement; no direct binding or FGF20-specific data. Quote was browser-read and flagged unverifiable. Review and abstract_insufficient rows are not shown.","key_references":[{"PMID":"16597617","why":"BaF3 mitogenic screen of the FGF family"}],"covers":["LR000599","LR004083"]},"LR005909":{"pair":"FLRT1 -> ADGRL3","headline":"Ecto-LPHN3-Fc bound FLRT1 strongly; one full-text paper.","interaction_type":"direct binding","direction_and_effect":"Ecto-LPHN3-Fc bound strongly to FLRT1 and FLRT2 as well as FLRT3 [PMID:22405201]. Effect of binding on signalling not reported for FLRT1 in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Receptor-ligand binding and pull-downs; species recorded as human [PMID:22405201]. Human pair is ortholog-inferred, mouse is not.","localisation_and_range":"FLRT1 flagged secreted and transmembrane [flag]; FLRT proteins are single-pass transmembrane [PMID:22405201], so contact-mediated.","caveats":"Single confirming paper; mass-spec pull-downs focused on FLRT3. No affinity. No database records.","key_references":[{"PMID":"22405201","why":"LPHN3 binds FLRT1/2/3"}],"covers":["LR002643","LR005909"]},"LR005918":{"pair":"FLRT2 -> UNC5A","headline":"FLRT2 binds UNC5A directly in a full-text extracellular binding screen; one paper, no affinity reported.","interaction_type":"direct binding","direction_and_effect":"A high-throughput extracellular binding screen found all three FLRTs binding all four Unc5s near saturation (mean Abs650nm value = 2.14), with ELISA titration on purified protein and CHO.K1 cell aggregation [PMID:26633812]. FLRT2 stripes repelled 18% of neurons, whereas Unc5A stripes gave no attractive or repulsive response (n=257/257, 100% permissive) with reduced outgrowth and viability [PMID:26633812]. UniProt states the UNC5A extracellular domain interacts with the FLRT2 extracellular domain [DB:UniProt, PMID:25374360].","molecular_requirements":"Purified ectodomains were used for the ELISA titrations and full-length proteins for the cell aggregation assay; subunit or co-receptor requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Binding screen used purified ectodomains and CHO.K1 cells; neurite assays used mouse retinal neurons. The record covers a human and a mouse pair; the paper's species labels in the curated row are human for both partners [PMID:26633812].","localisation_and_range":"Both partners carry transmembrane flags and the cell aggregation assay indicates interaction between opposing cell surfaces (contact-mediated) [PMID:26633812]; FLRT2 is also flagged secreted [flag].","caveats":"Direct binding is supported by one paper plus a UniProt statement; no functional effect specific to FLRT2-UNC5A is reported. Unc5A stripes did not repel neurons [PMID:26633812].","key_references":[{"PMID":"26633812","why":"Full-text screen showing all FLRT x Unc5 pairs bind near saturation."}],"covers":["LR002652","LR005918"]},"LR005927":{"pair":"FLRT3 -> UNC5D","headline":"Binding is supported by a screen but a 2011 study found Unc5D specific for FLRT2, so evidence conflicts.","interaction_type":"conflicting","direction_and_effect":"All twelve FLRT x Unc5 pairs, including FLRT3 and Unc5D, bound near saturation (mean Abs650nm value = 2.14) [PMID:26633812]. The 2011 abstract reports that Unc5D binds specifically to FLRT2 and calls FLRT3 the partner of Unc5B, so the curators judged the FLRT3-Unc5D pair absent from it [PMID:21673655].","molecular_requirements":"FLRT3, ADGRL3 and UNC5D are listed in complexes [DB:UniProt].","affinity_potency":[],"species_and_systems":"Screen: purified ectodomains, CHO.K1 aggregation [PMID:26633812]; 2011: abstract only, neocortex [PMID:21673655].","localisation_and_range":"FLRT3 annotated secreted and transmembrane, UNC5D transmembrane [flag].","caveats":"Specificity statements in the abstract argue against FLRT3-Unc5D, though it does not test the pair explicitly [PMID:21673655]. Human pair is ortholog-inferred. No affinity.","key_references":[{"PMID":"26633812","why":"Screen shows FLRT3-Unc5D binding"},{"PMID":"21673655","why":"Reports Unc5D specificity for FLRT2"}],"covers":["LR002661","LR005927"]},"LR008582":{"pair":"FN1 -> ITGA3:ITGB1","headline":"No curated paper confirms fibronectin binding to alpha3beta1; support is database records, partly for other integrins.","interaction_type":"database-asserted only","direction_and_effect":"BioGRID lists FN1 with ITGA3 and ITGB1 reconstituted-complex records [DB:BioGRID], and IntAct lists SPR and FACS records [DB:IntAct]. PDB and Reactome rows concern alpha5beta1 with fibronectin [DB:PDB 7NWL] [DB:Reactome]. Direction and effect are not reported.","molecular_requirements":"Both ITGA3 and ITGB1 chains are recorded in BioGRID separately [DB:BioGRID]; heterodimer-level evidence for this pair is not in our evidence.","affinity_potency":[],"species_and_systems":"Human; assay species not stated in our evidence.","localisation_and_range":"FN1 flagged secreted; matrix-to-cell contact is inferred only from flags [flag].","caveats":"Judged papers were 1 review-only and 1 abstract-insufficient; none confirmed. A separate dossier has an SPR paper on alpha3beta1 and fibronectin.","key_references":[],"covers":["LR008582"]},"LR002669":{"pair":"FTL -> SCARA5","headline":"L-ferritin is bound by the SCARA5 SRCR domain in biochemical assays; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"SCARA5 recognises L-ferritin (FTL) through its SRCR domain, Ca2+-dependently [PMID:32907880]. Signalling effect is not reported in our evidence.","molecular_requirements":"The SRCR domain of SCARA5 is the ferritin-recognising region [PMID:32907880]. Other requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Biochemical binding assays; crystal structures of the SCARA5 SRCR domain were solved for human and mouse [PMID:32907880].","localisation_and_range":"FTL is flagged as secreted and non-transmembrane; SCARA5 is flagged as a transmembrane receptor [flag].","caveats":"Based on an abstract only, no affinity reported. H-ferritin is bound too [PMID:32907880].","key_references":[{"PMID":"32907880","why":"Biochemical binding of L- and H-ferritin to the SCARA5 SRCR domain"}],"covers":["LR002669"]},"LR005936":{"pair":"GC -> LRP2","headline":"Thinly supported: one abstract-only paper with antibody blockade and co-localisation of Gc-globulin with megalin; no direct binding data.","interaction_type":"functional only","direction_and_effect":"Megalin/gp330 is reported to mediate Ca2+-dependent internalisation of Gc-globulin by hepatic stellate cells; a neutralising anti-megalin antibody decreased intracellular gc-globulin, an effect enhanced by EDTA, and confocal microscopy showed co-localisation [PMID:18194670]. This is clearance/uptake, not signalling.","molecular_requirements":"Ca2+ dependence is reported [PMID:18194670]. Megalin was one of at least four candidate gc-globulin receptors on these cells (megalin, CD44, cubilin, annexin A2) [PMID:18194670]; whether others are needed is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Hepatic stellate cells with hepatocyte-derived gc-globulin; curators label both partners human, but the abstract does not state the species [PMID:18194670]. Both human and mouse pairs are ortholog-projected.","localisation_and_range":"GC is flagged secreted and LRP2 as a receptor [flag].","caveats":"Abstract-only. A competitive antibody and co-localisation do not prove direct binding. BioGRID lists an affinity-capture western record for GC-LRP2 [DB:BioGRID].","key_references":[{"PMID":"18194670","why":"Megalin-dependent uptake of gc-globulin by hepatic stellate cells"}],"covers":["LR002671","LR005936"]},"LR008258":{"pair":"GDF1 -> ACVR1C:ACVR2B","headline":"Database-asserted only: GtoPdb lists an agonist action; no confirmed paper.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists GDF1 as an agonist at the ACVR1C and ACVR2B subunits (listed separately) [DB:GtoPdb]; no paper confirms it in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"No experimental system reported in our evidence.","localisation_and_range":"GDF1 is flagged secreted [flag].","caveats":"No confirmed paper. Two papers were review-only, two abstract-insufficient and one different_entity. Affinity and species are not reported in our evidence.","key_references":[],"covers":["LR008258"]},"LR002678":{"pair":"GDF10 -> TGFBR1","headline":"Functional evidence: GDF10 selectively activates TbetaRI/II-dependent Smad3 phosphorylation in mouse mammary tumour cells.","interaction_type":"functional only","direction_and_effect":"GDF10 selectively activated TGF-beta receptor (TbetaRI/II)-dependent Smad3 phosphorylation; overexpression attenuated tumour formation and silencing reversed it [PMID:21518866]. GtoPdb lists agonist [DB:GtoPdb].","molecular_requirements":"Signalling needs the TbetaRI-TbetaRII heterodimer; Sca-1 disrupts that heterodimerization [PMID:21518866].","affinity_potency":[],"species_and_systems":"Murine mammary tumour cells and mice per the abstract [PMID:21518866]; the mouse pair is not ortholog-inferred, the human pair is.","localisation_and_range":"GDF10 is flagged secreted and non-transmembrane [flag], so signalling would be paracrine or autocrine; range not studied in our evidence.","caveats":"Single abstract-only paper; no direct binding to TGFBR1 chain alone and no affinity.","key_references":[{"PMID":"21518866","why":"GDF10 activates TbetaRI/II-Smad3; Sca-1 disrupts the heterodimer"}],"covers":["LR002678","LR005943"]},"LR005945":{"pair":"GDF11 -> ACVR1C","headline":"GDF11 can interact with ALK7 but signals mainly through ALK4 and ALK5; a weaker secondary receptor.","interaction_type":"functional only","direction_and_effect":"GDF11 can interact with ALK7 but predominantly activates the Smad3 reporter through ALK4 and ALK5 [PMID:16845371].","molecular_requirements":"Not reported for ALK7 beyond interaction in a type I receptor panel [PMID:16845371].","affinity_potency":[],"species_and_systems":"Mouse embryo context in the abstract [PMID:16845371]; both human and mouse pairs are ortholog-inferred.","localisation_and_range":"GDF11 flagged secreted [flag].","caveats":"Single abstract-only paper; ALK7 is not shown to mediate the paper's in vivo phenotypes (a heterozygous Alk7 mutation did not potentiate them). No affinity.","key_references":[{"PMID":"16845371","why":"GDF11 interacts with ALK7 among a type I receptor panel"}],"covers":["LR002680","LR005945"]},"LR000689":{"pair":"GDF11 -> ACVR2B","headline":"GDF11 binds ActRIIB (ACVR2B) in mouse work and has IntAct SPR and PDB records.","interaction_type":"direct binding","direction_and_effect":"Gdf11 binds both ActRIIA and ActRIIB and induces Smad2 phosphorylation [PMID:12414726]. An Alk5 heterozygous mutation potentiated Gdf11-null-like phenotypes in an Acvr2b-null background, a genetic interaction [PMID:16845371].","molecular_requirements":"ActRIIA and ActRIIB cooperate and can compensate; type I partner includes ALK5 and ALK4 [PMID:12414726][PMID:16845371].","affinity_potency":[],"species_and_systems":"Mouse genetics and biochemistry [PMID:12414726][PMID:16845371]; IntAct records surface plasmon resonance for O95390-Q13705 [DB:IntAct]; PDB 7MRZ [DB:PDB 7MRZ].","localisation_and_range":"GDF11 flagged secreted [flag].","caveats":"Both papers abstract-only; one row is still pending and one abstract-insufficient. No affinity value in our evidence. Human pair is ortholog-inferred.","key_references":[{"PMID":"12414726","why":"Gdf11 binds ActRIIA and ActRIIB"},{"PMID":"16845371","why":"Genetic interaction of Acvr2b with Alk5 in GDF11 signalling"}],"covers":["LR000689","LR004173"]},"LR000698":{"pair":"GDF5 -> BMPR1A","headline":"GDF5 binds BMPR1A, but more weakly than BMPR1B; supported by binding and functional papers.","interaction_type":"direct binding","direction_and_effect":"CDMP-1 (GDF5) bound BMPR-IB and BMPR-II and weakly BMPR-IA [PMID:9525338]. GDF5 activity on osteoblast differentiation is reported through Smad1/5/8 [PMID:11282024]. UniProt describes BMPR1A as lower affinity than BMPR1B [DB:UniProt]. Stimulatory in the interaction record.","molecular_requirements":"Binding was tested with immobilised BMPR1A and BMPR1B ectodomains by Biacore; mutant N445T GDF5 did not differ significantly from wild-type [PMID:19956691]. Type II partner is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Recombinant ligand and ectodomains; C2C12 mouse myoblast cells; curators label human [PMID:19956691][PMID:11282024].","localisation_and_range":"The receptor is flagged transmembrane [flag].","caveats":"Binding is weak and Kd values for BMPR1A are not in our excerpts. [PMID:11282024] does not test BMPR1A directly. Two of five confirmed rows and one different_entity row are not shown.","key_references":[{"PMID":"19956691","why":"Biacore of GDF5 with BMPR1A and BMPR1B ectodomains"},{"PMID":"9525338","why":"CDMP-1 receptor binding, weak for BMPR-IA"}],"covers":["LR000698","LR004182"]},"LR005954":{"pair":"GDF7 -> ACVR2B","headline":"GDF7 binds ACVR2B directly (KD 1.0 nM for rhBMP12); one paper plus a GtoPdb record.","interaction_type":"direct binding","direction_and_effect":"Binding: rhBMP12 (GDF7) bound ACVR2B with similar affinity to rhBMP13 (GDF6) [PMID:21702718]. GtoPdb lists an agonist record [DB:GtoPdb]. Functional support specific to ACVR2B is not reported in our evidence.","molecular_requirements":"Type II receptor; a type I partner is not tested in this dossier's evidence. Not reported in our evidence.","affinity_potency":[{"value":"KD 1.0 nM","assay":"surface plasmon resonance, KD (kin), rhBMP12 (GDF7) vs ACVR2B ectodomain-Fc","system":"recombinant human proteins","cite":"PMID:21702718"}],"species_and_systems":"Recombinant human BMP12 and receptor ectodomains in binding assays; musculoskeletal marker assays in C3H10T1/2 cells and rat ectopic implants [PMID:21702718]. The mouse pair is projected from human evidence.","localisation_and_range":"Ligand is flagged secreted and the receptor chain(s) as receptor [flag], which would imply paracrine signalling to a membrane receptor; localisation is not otherwise reported in our evidence.","caveats":"Binding is not activation: rhBMP12 gave no detectable SMAD1/5/8 activation in C3H10T1/2 cells [PMID:21702718]. ACVR2B affinity was similar to type I receptor affinity [PMID:21702718]. rhBMP12 is mapped to GDF7 via alternate names. Only one paper in the dossier.","key_references":[{"PMID":"21702718","why":"Kinetic binding of rhBMP12 (GDF7) to type I and II receptors."}],"covers":["LR002689","LR005954"]},"LR007970":{"pair":"GDNF -> GFRA1:RET","headline":"Well supported ternary complex: GDNF, GFRA1 and RET form a structurally characterised complex.","interaction_type":"direct binding","direction_and_effect":"RET binds a bipartite ligand of GDNF plus GFR alpha1, and a hybrid EM/SAXS model shows RET extracellular domain enveloping the ligand complex [PMID:25242331]. The signal is RET activation [DB:UniProt].","molecular_requirements":"GFRA1-mediated contacts are crucial, while few direct contacts are made by GDNF; the RET cysteine-rich domain contacts both ligand components [PMID:25242331]. UniProt gives a 2:2:2 stoichiometry [DB:UniProt]. Both GFRA1 and RET are therefore needed for scoring.","affinity_potency":[],"species_and_systems":"Purified proteins and structural modelling, human [PMID:25242331].","localisation_and_range":"GDNF is flagged secreted [flag]; the complex is cell-surface.","caveats":"Structural model is low resolution (EM/SAXS) and read from the abstract [PMID:25242331]. PDB 4UX8 and 6Q2N are listed [DB:PDB 4UX8][DB:PDB 6Q2N].","key_references":[{"PMID":"25242331","why":"EM/SAXS model of RET-GDNF-GFRa1 ternary complex"}],"covers":["LR007970"]},"LR004199":{"pair":"GHRH -> GHRHR","headline":"GHRH binds and activates the GHRH receptor; two cloning papers (abstract-only) plus structure and database support.","interaction_type":"direct binding","direction_and_effect":"Human GHRH binds the GHRHR with high affinity and stimulates cAMP production in transfected cells, consistent with agonism [PMID:1333056][PMID:7680413]. A specific GHRH antagonist blocked both binding and the second-messenger response [PMID:7680413]. GtoPdb lists an agonist [DB:GtoPdb].","molecular_requirements":"Receptor alone expressed in cells was sufficient for binding and cAMP signalling [PMID:7680413]; co-receptors not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human receptor expressed in HEK293 and COS cells with human GHRH [PMID:1333056][PMID:7680413]. The mouse pair is projected from human evidence (ortholog-inferred). A structure is listed [DB:PDB 7CZ5].","localisation_and_range":"Ligand flagged secreted, receptor transmembrane [flag]. GHRHR mRNA was mostly in anterior pituitary, so action is endocrine-type [PMID:7680413].","caveats":"Both papers read as abstracts only; no affinity value reported in our evidence.","key_references":[{"PMID":"1333056","why":"Cloned GHRHR; membrane binding of human GHRH and cAMP"},{"PMID":"7680413","why":"Human GHRH-R cloned; saturable binding, cAMP, antagonist block"}],"covers":["LR000716","LR004199"]},"LR006836":{"pair":"GHRH -> VIPR1","headline":"GHRH competes weakly for the human VPAC1 receptor; a low-affinity cross-reaction supported by one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"In CHO cells expressing human VIP1 receptor, human GRF (GHRH) inhibited [125I]VIP binding with Ki 0.6 microM, far weaker than VIP (0.9 nM) and PACAP-27 (1.3 nM) [PMID:8791009]. GtoPdb lists it as an agonist with pKi [DB:GtoPdb]; the paper itself reports binding competition, not a GHRH-driven cAMP response.","molecular_requirements":"Single recombinant receptor; no subunit requirements reported.","affinity_potency":[{"value":"Ki 0.6 microM","assay":"inhibition of [125I]VIP binding","system":"CHO cells stably expressing human VIP1 receptor","cite":"PMID:8791009"}],"species_and_systems":"Human receptor in recombinant hamster CHO cells; human GRF [PMID:8791009].","localisation_and_range":"Ligand secreted, receptor transmembrane [flag].","caveats":"Low affinity relative to VIP, so physiological relevance is uncertain (an inference from the numbers). Abstract only. The evidence-sentence class says agonist but the abstract shows binding competition only.","key_references":[{"PMID":"8791009","why":"Ki 0.6 microM for GRF at recombinant human VIP1 receptor"}],"covers":["LR006836"]},"LR009563":{"pair":"GNAI2 -> P2RY12","headline":"Database-asserted only: a cryo-EM structure (PDB 7XXI) contains both chains; no curated paper.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence. The structure is of P2Y12R in complex with 2MeSADP and Gi [DB:PDB 7XXI].","molecular_requirements":"PDB 7XXI contains a chain of P04899 and a chain of Q9H244 [DB:PDB 7XXI]; whether other subunits are needed is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Cryo-EM (electron microscopy) structure; species of the construct not reported in our evidence [PMID:37155313].","localisation_and_range":"Not reported in our evidence.","caveats":"No paper in our evidence supports this pair; it rests on database records alone. A shared structure shows co-assembly in a complex, not a ligand-receptor relationship. One curated judgement: 'different_entity'.","key_references":[{"PMID":"37155313","why":"Source paper of PDB 7XXI (P2Y12R-2MeSADP-Gi cryo-EM); not curated by us"}],"covers":["LR009563"]},"LR008519":{"pair":"GNAS -> GCGR","headline":"Database-asserted only: UniProt lists GCGR as interacting with GNAS; no curated paper.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Assay and species not reported in our evidence [PMID:32193322][PMID:38346960].","localisation_and_range":"GCGR is annotated as a transmembrane receptor [flag]; GNAS is intracellular.","caveats":"No paper in our evidence supports this pair; it rests on database records alone. One curated judgement: 'different_entity'.","key_references":[],"covers":["LR008519"]},"LR002696":{"pair":"GP1BA -> ITGB2","headline":"Evidence is for the alphaM beta2 heterodimer, with the binding site on alphaM; ITGB2 alone is not shown to bind GP Ibalpha.","interaction_type":"direct binding","direction_and_effect":"GP Ibalpha binding to Mac-1 (alphaM beta2) is mapped to the P201-K217 sequence of the alphaM I domain: swapping it for alphaL sequence abolished adhesion, and grafting it onto alphaL made alphaL beta2 bind GP Ibalpha [PMID:14530377]. Synthetic P201-K217 peptide bound GP Ibalpha directly and blocked alphaM beta2 adhesion [PMID:14530377]. Effect is adhesion.","molecular_requirements":"The paper maps binding to the alphaM I domain, not beta2; the ITGB2 row inherits complex-level evidence (curator note). Chain-only binding by ITGB2 is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins; alphaM beta2-expressing 293 cells [PMID:14530377]. Mouse pair is ortholog-inferred.","localisation_and_range":"GP Ibalpha is the platelet counter receptor and Mac-1 is on leukocytes, so contact-dependent platelet-leukocyte adhesion [PMID:14530377]; both are annotated non-secreted [flag].","caveats":"ITGB2 is only the partner chain of Mac-1; a CCC tool scoring ITGB2 alone would rest on complex-level evidence. No affinity reported in our evidence.","key_references":[{"PMID":"14530377","why":"Maps the binding site to alphaM; complex-level evidence"}],"covers":["LR002696","LR005961"]},"LR005963":{"pair":"GPC3 -> LRRTM4","headline":"Glypicans bind LRRTM4 in a heparan-sulfate-dependent manner; GPC3 evidence is class-level.","interaction_type":"direct binding","direction_and_effect":"Glypican acts as a presynaptic partner of postsynaptic LRRTM4 in a trans-synaptic interaction; the abstract calls glypican a receptor for LRRTM4. LRRTM4 positively regulates excitatory synapse development, and its synaptogenic activity requires neuronal-surface heparan sulfate [PMID:23911103].","molecular_requirements":"Binding is heparan-sulfate (HS) dependent and selective for LRRTM4 over LRRTM2 [PMID:23911103]. LRRTM4-Fc bound strongly to all glypican isoforms tested in cell-surface assays [PMID:23911103]. LRRTM4 forms separate complexes with neurexin and glypican, not a tripartite complex (GPC4 data) [PMID:23911103].","affinity_potency":[],"species_and_systems":"Rat brain homogenate pulldown, HA-tagged mouse glypican cDNAs in HEK293T cells, cultured hippocampal neurons [PMID:23911103]; the curators labelled the experiment species human. Pair is ortholog-inferred for both species.","localisation_and_range":"Glypican is a GPI-anchored HSPG (full text) and annotated as secreted [flag]; LRRTM4 is a transmembrane receptor [flag]. Interaction is trans-synaptic and needs local glypican concentration, since soluble GPC4 did not induce LRRTM4 clustering [PMID:23911103].","caveats":"Evidence is for 'glypican' as a class. GPC3 was among glypicans detected in the LRRTM4-Fc sample, but the abstract does not name it and direct cell-free binding was shown for GPC4 only [PMID:23911103]. GPC3 is annotated non-secreted [flag] while others are secreted: annotation inconsistent.","key_references":[{"PMID":"23911103","why":"Unbiased discovery of glypican-LRRTM4 binding and its role in synapse development"}],"covers":["LR002698","LR005963"]},"LR005972":{"pair":"GPR15LG -> GPR15","headline":"GPR15LG is a well-supported agonist of GPR15; functional evidence in two papers, plus GtoPdb, UniProt and PDB structures.","interaction_type":"functional only","direction_and_effect":"GPR15LG is an agonist of GPR15: it induced dose-dependent beta-arrestin-2 recruitment to GPR15 in NanoBit assays [PMID:40394646], and a ligand purified from porcine colon agonistically activated GPR15 [PMID:28900043]. Gpr15l-deficient skin grafts were protected in mice, implying a role in effector T cell responses [PMID:28900043]. GtoPdb lists an agonist [DB:GtoPdb].","molecular_requirements":"No co-receptor requirement is reported in our evidence.","affinity_potency":[{"value":"EC50 400 nM","assay":"beta-arrestin-2 recruitment, NanoBit","system":"GPR15-expressing cells","cite":"PMID:40394646"}],"species_and_systems":"Ligand purified from porcine colon, tested on human GPR15; human and mouse tissue expression; mouse graft experiments [PMID:28900043]. Recombinant human-protein assays [PMID:40394646].","localisation_and_range":"GPR15LG is flagged as secreted [flag]; the paper calls it a chemokine-like ligand [PMID:28900043]. Structures with both chains are in PDB [DB:PDB 8ZQE] [DB:PDB 9WXM].","caveats":"Three further papers are still pending. The 28900043 abstract does not report a direct binding assay. In 40394646 the GPR15 data are a side result to the CXCR4 work.","key_references":[{"PMID":"28900043","why":"Purification and functional characterisation of GPR15LG as a GPR15 agonist"},{"PMID":"40394646","why":"Beta-arrestin-2 recruitment EC50 for GPR15"}],"covers":["LR002707","LR005972"]},"LR005189":{"pair":"GRN -> TNFRSF1B","headline":"Progranulin is reported to bind TNFR2 directly and antagonise TNF-alpha, from one mouse-focused paper.","interaction_type":"direct binding","direction_and_effect":"PGRN bound directly to TNF receptors and disturbed the TNF\u03b1-TNFR interaction; PGRN is called an antagonist of TNF\u03b1 signalling [PMID:21393509].","molecular_requirements":"The abstract says 'TNFRs' in plural; TNFR2 is not named separately. Atsttrin showed selective TNFR binding [PMID:21393509].","affinity_potency":[],"species_and_systems":"Mostly mouse in vivo arthritis models [PMID:21393509]; human pair is ortholog-inferred. IntAct lists solid-phase assay and pull-down records [DB:IntAct].","localisation_and_range":"GRN is flagged secreted; TNFRSF1B is flagged secreted, receptor and transmembrane [flag].","caveats":"Abstract-only reading; receptor-specific (TNFR2) binding is inferred from a plural statement.","key_references":[{"PMID":"21393509","why":"PGRN binds TNFRs and blocks TNF\u03b1"}],"covers":["LR001834","LR005189"]},"LR009275":{"pair":"GSTP1 -> TRAF2","headline":"Physical association is recorded in BioGRID and IntAct only; no curated paper judged.","interaction_type":"database-asserted only","direction_and_effect":"Stimulatory effect is annotated, but no curated paper confirms it.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Records include affinity capture-Western, reconstituted complex and co-localisation (BioGRID), and co-immunoprecipitation and pull-down (IntAct) [DB:BioGRID] [DB:IntAct]; species of experiments not stated.","localisation_and_range":"No secretion or receptor flags are given for either entity [flag].","caveats":"Rests on database records alone. Neither entity is flagged as ligand or receptor; this looks like an intracellular protein interaction rather than a ligand-receptor pair.","key_references":[],"covers":["LR009275"]},"LR006809":{"pair":"GUCA1B -> GUCY2D","headline":"GCAP2 binds and regulates RetGC1; binding is supported by SPR on a cyclase peptide and functional work in cells.","interaction_type":"direct binding","direction_and_effect":"GCAP-2 activates ROS-GC1 in a calcium-dependent manner [PMID:30283299]. GCAP1 and GCAP2 activated RetGC1 non-additively and compete for it [PMID:25616661]. GtoPdb lists an activator [DB:GtoPdb].","molecular_requirements":"GCAP1 and GCAP2 appear to bind RetGC1 mutually exclusively, not at independent sites; the kinase homology and dimerization domains were needed for GCAP binding, and substitutions W708R and I734T prevented binding of both [PMID:25616661]. A catalytic-domain/C-terminal peptide of ROS-GC1 binds GCAP-2 [PMID:30283299].","affinity_potency":[{"value":"low micromolar range","assay":"surface plasmon resonance and fluorescence, ROS-GC peptide with GCAP-2","system":"in vitro","cite":"PMID:30283299"}],"species_and_systems":"Peptide cross-linking/SPR in vitro [PMID:30283299]; HEK293 cells and RetGC2-/-GCAPs1,2-/- mouse retinas [PMID:25616661]. Species of proteins in the first study not stated.","localisation_and_range":"Intracellular-side interaction of a membrane cyclase [PMID:30283299]; GCAP2 is not flagged secreted.","caveats":"The SPR measured a peptide of the cyclase, not the full receptor, and the affinity is only stated as 'low micromolar range'. Both papers were read as abstracts.","key_references":[{"PMID":"30283299","why":"SPR and cross-linking of ROS-GC1 peptide with GCAP-2"},{"PMID":"25616661","why":"GCAP1/GCAP2 bind RetGC1 competitively"}],"covers":["LR006809"]},"LR006764":{"pair":"H60c -> Klrk1","headline":"H60c is a mouse NKG2D ligand identified by NKG2D-Ig binding and NK-cell target susceptibility.","interaction_type":"direct binding","direction_and_effect":"H60 family proteins are GPI-anchored cell-surface ligands for mouse activating NKG2D; ectopic RAE-1 and H60 expression confers NK-cell target susceptibility [PMID:10894171].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse ligand and receptor; mNKG2D-Ig fusion protein used to identify ligands [PMID:10894171].","localisation_and_range":"GPI-anchored cell-surface protein, so contact-dependent (juxtacrine) signalling [PMID:10894171]; entity flagged not secreted [flag].","caveats":"No affinity reported. The family is treated together in the paper; the excerpts do not separate H60a, H60b and H60c individually.","key_references":[{"PMID":"10894171","why":"RAE-1/H60 family as NKG2D ligands"}],"covers":["LR006764"]},"LR005981":{"pair":"HMGB1 -> AGER","headline":"Direct binding of amphoterin (HMGB1) to RAGE shown with purified proteins in a 1995 abstract-read paper; database records add support.","interaction_type":"direct binding","direction_and_effect":"Rat amphoterin bound purified sRAGE in a saturable, dose-dependent way, blocked by anti-RAGE IgG or sRAGE. RAGE blockade also prevented binding to embryonic rat neurons and inhibited neurite formation on amphoterin-coated substrates [PMID:7592757]. Activating or inhibitory effect beyond this is not reported in our evidence.","molecular_requirements":"Not reported in our evidence beyond soluble RAGE ectodomain binding [PMID:7592757].","affinity_potency":[],"species_and_systems":"Rat amphoterin (brain-purified or recombinant), rat neurons and bovine-lung-derived fractions [PMID:7592757]. The human and mouse pairs are ortholog-inferred, not directly tested.","localisation_and_range":"HMGB1 is flagged secreted [flag]; paracrine action on cells is implied by the neuron binding assay [PMID:7592757].","caveats":"Single curated paper, abstract only, and rat/bovine material. Databases list BioGRID affinity capture, IntAct SPR and PDB 8I9M [DB:BioGRID][DB:IntAct][DB:PDB 8I9M].","key_references":[{"PMID":"7592757","why":"Amphoterin binds RAGE; blocked by anti-RAGE and sRAGE"}],"covers":["LR002733","LR005981"]},"LR005990":{"pair":"HMGB1 -> SCARA5","headline":"SCARA5 recognises HMGB1 and clears it, shown only in fish models; human and mouse pairs are ortholog-inferred.","interaction_type":"functional only","direction_and_effect":"SCARA5 is identified as an HMGB1 recognition receptor that negatively regulates HMGB1-mediated inflammation. Tetraodon SCARA5 associates with TnHMGB1 and mediates its endocytosis into lysosomes; overexpression suppresses CpG-ODN responses and ablation intensifies them [PMID:27647835].","molecular_requirements":"Association occurs through the A and B boxes, depends on the cysteine redox state, and is inhibited by the T box [PMID:27647835].","affinity_potency":[],"species_and_systems":"Pufferfish (Tetraodon nigroviridis) and zebrafish (Danio rerio) proteins and models; no human or mouse experiments in our evidence [PMID:27647835].","localisation_and_range":"HMGB1 is flagged secreted [flag]; SCARA5 mediates endocytosis [PMID:27647835].","caveats":"All evidence is from fish orthologs, read from the abstract only; transfer to human or mouse is inference.","key_references":[{"PMID":"27647835","why":"SCARA5 as an HMGB1 receptor in pufferfish and zebrafish"}],"covers":["LR002742","LR005990"]},"LR000779":{"pair":"IAPP -> CALCR","headline":"Amylin acts on CALCR alone and, more potently, with RAMPs; nine confirmed papers in human cell systems, so well supported though RAMP-dependent.","interaction_type":"direct binding","direction_and_effect":"Amylin binds and activates the calcitonin receptor: human and rat amylin activated CALCR alone and all three CALCR+RAMP complexes in cAMP assays [PMID:24169554]; GtoPdb lists full agonist action [DB:GtoPdb]. In breast cancer cells, amylin stimulated cAMP with EC50 1.4 nM [PMID:9487987]. A tumour study reports amylin signalling through CalcR and RAMP3 to inhibit glycolysis [PMID:25409149].","molecular_requirements":"RAMPs change the pharmacology: RAMP1 and -3 increased [125I]amylin binding to hCTR2 by 262 and 338% [PMID:10342886]; the RAMP N-terminal domain dictates competition specificity [PMID:16531504]. CALCR alone also responds [PMID:24169554]. Structures with a CALCR chain exist [DB:PDB 8F0J].","affinity_potency":[{"value":"IC50 3.6 nM","assay":"inhibition of [125I]amylin binding by human amylin","system":"MCF-7 human breast carcinoma cells","cite":"PMID:9487987"},{"value":"IC50 3.1 nM","assay":"inhibition of [125I]amylin binding by human amylin","system":"RAEC cells with hCTR2 + RAMP1","cite":"PMID:10342886"},{"value":"IC50 4.0 nM","assay":"inhibition of [125I]amylin binding by human amylin","system":"RAEC cells with hCTR2 + RAMP3","cite":"PMID:10342886"},{"value":"EC50 1.4 nM","assay":"cAMP accumulation by human amylin","system":"MCF-7 cells","cite":"PMID:9487987"}],"species_and_systems":"Human CALCR (hCTR2, CTRa) in transfected rabbit endothelial, COS-7 and HEK293S cells, and MCF-7 cells, with rat or human amylin; one tumour paper in vivo [PMID:10342886] [PMID:16531504] [PMID:24169554] [PMID:9487987] [PMID:25409149]. Mouse pair is ortholog-inferred.","localisation_and_range":"IAPP is flagged secreted and CALCR transmembrane [flag]; amylin is a circulating or local peptide acting on cell-surface receptors.","caveats":"Without RAMP, amylin binding to CALCR is weak (0.9 fmol per 50,000 cells) [PMID:10342886]. Authors of PMID:9487987 argue the MCF-7 amylin site may be distinct from CALCR. Papers read as abstracts only; one review-only row excluded.","key_references":[{"PMID":"10342886","why":"[125I]amylin binding and IC50 values with CTR2 plus RAMP1/2/3"},{"PMID":"24169554","why":"cAMP responses of CALCR alone and AMY1-3 to amylin"},{"PMID":"16531504","why":"RAMP domain contributions to amylin receptor binding and signalling"}],"covers":["LR000779","LR004237"]},"LR008564":{"pair":"ICAM1 -> ITGAL:ITGB2","headline":"ICAM-1 is a known ligand of LFA-1 (ITGAL:ITGB2) per databases and structures; the single curated paper is weak background evidence.","interaction_type":"database-asserted only","direction_and_effect":"UniProt says ITGAL:ITGB2 is a receptor for ICAM1, ICAM2 and ICAM3 [DB:UniProt]. BioGRID lists FRET, reconstituted complex and co-crystal records [DB:BioGRID]; PDB 1MQ8 and 3TCX contain chains of ICAM1 and ITGAL [DB:PDB 1MQ8]. Reactome lists ITGAL:ITGB2 with ICAM1 dimer [DB:Reactome].","molecular_requirements":"The receptor is the ITGAL:ITGB2 complex per UniProt; which subunit is required is not reported in our evidence.","affinity_potency":[],"species_and_systems":"The curated paper used a cell-free microsphere system with human proteins [PMID:14507735].","localisation_and_range":"Complex listed at the plasma membrane, ICAM1 as a dimer on follicular dendritic cells [DB:Reactome].","caveats":"The one confirmed paper states ICAM binding to activated integrins as background in a rolling/adhesion biophysics study, read as abstract only [PMID:14507735]. Three papers were abstract_insufficient. Support comes mainly from databases.","key_references":[{"PMID":"14507735","why":"Weak: ICAM-integrin firm adhesion in a cell-free system"}],"covers":["LR008564"]},"LR002759":{"pair":"ICAM2 -> CD209","headline":"DC-SIGN (CD209) supports tethering and rolling on ICAM-2; one functional abstract plus Reactome and UniProt records.","interaction_type":"functional only","direction_and_effect":"DC-SIGN-positive cells tether and roll on ICAM-2 under shear flow, and the interaction regulates chemokine-induced dendritic cell transmigration across endothelium [PMID:11017109]. ICAM-2 is the vascular ligand and DC-SIGN the receptor on dendritic cells [PMID:11017109].","molecular_requirements":"UniProt describes binding to mannose-like carbohydrates on ICAM2/ICAM3 [DB:UniProt]; subunit or isoform requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human cells and proteins [PMID:11017109]; no mouse pair listed.","localisation_and_range":"Receptor is flagged transmembrane [flag]; ICAM-2 acts as a surface ligand on endothelium, so contact-dependent [PMID:11017109].","caveats":"Abstract only; the evidence is a rolling/tethering readout rather than measured binding. No affinity. Reactome records the binding reaction citing the same paper [DB:Reactome].","key_references":[{"PMID":"11017109","why":"Tethering and rolling of DC-SIGN cells on ICAM-2"}],"covers":["LR002759"]},"LR000788":{"pair":"ICAM2 -> ITGAL","headline":"ICAM-2 binds the LFA-1 alpha chain (CD11a) I domain with structural and binding support; ranked below ICAM-1 in affinity.","interaction_type":"direct binding","direction_and_effect":"ICAM-2 is an LFA-1 ligand with affinity order ICAM-1 > ICAM-2 > ICAM-3 for a locked-open alphaL I domain [PMID:11353828]; off-rates differ among ICAM-1, -2 and -3 and relate to residues around a metal coordination bond in the alphaLbeta2 interface [PMID:15728350]. Pig ICAM-2 supported firm adhesion of human LFA-1 cells [PMID:15023143].","molecular_requirements":"The binding data use the isolated alphaL I domain, so the alpha chain alone is sufficient for binding in those assays [PMID:11353828]; UniProt describes the receptor as ITGAL:ITGB2 [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human proteins [PMID:11353828][PMID:15728350]; the adhesion study used pig ICAM-2 with human LFA-1 [PMID:15023143]. Mouse pair is ortholog-inferred.","localisation_and_range":"Membrane-bound adhesion molecule, contact-dependent; UniProt: leukocyte cell-cell adhesion on resting cells [DB:UniProt].","caveats":"All three papers are abstract-only. The adhesion paper uses pig ICAM-2 [PMID:15023143]. No numeric affinities in our evidence.","key_references":[{"PMID":"11353828","why":"Affinity ranking ICAM-1 > ICAM-2 > ICAM-3 for alphaL I domain"},{"PMID":"15728350","why":"Crystal structure and kinetics for ICAM-1/2/3 with alphaL"}],"covers":["LR000788","LR004246"]},"LR000797":{"pair":"ICAM4 -> ITGAL","headline":"Two human studies show LFA-1 (alphaL) binding to ICAM-4-Fc, with domain 1 as the binding region; human pair is ortholog-inferred.","interaction_type":"direct binding","direction_and_effect":"Transfectants expressing alphaLbeta2 bind ICAM-4-Fc [PMID:15355350]. Anti-CD11a, anti-CD11b, anti-CD18 antibodies blocked L-cell adhesion to ICAM-4-Fc, and the interaction needed Ca2+ and Mg2+ [PMID:10846180]. UniProt lists ICAM4 among ITGAL/ITGB2 ligands [DB:UniProt].","molecular_requirements":"The alphaL/beta2 complex is the receptor. LFA-1 binds the first Ig-like domain of ICAM-4; Leu80, Trp93, Arg97 (CFG face) and Trp77 (E-F loop) of domain D1 may contact LFA-1 [PMID:10846180].","affinity_potency":[],"species_and_systems":"Human ICAM-4-Fc with human integrin transfectants and L-cells [PMID:15355350, PMID:10846180].","localisation_and_range":"ICAM4 carries both secreted and transmembrane flags [flag], so range is unclear; the papers used recombinant ICAM-4-Fc and cell-surface ICAM-4, consistent with contact-dependent adhesion.","caveats":"Both papers abstract only; the second is a functional adhesion assay. Affinity not reported. No mouse experiments.","key_references":[{"PMID":"10846180","why":"LFA-1 and Mac-1 binding sites on ICAM-4"},{"PMID":"15355350","why":"alphaLbeta2 transfectant binding to ICAM-4-Fc"}],"covers":["LR000797","LR004251"]},"LR008375":{"pair":"ICAM5 -> PRTG","headline":"Binding seen in a high-throughput human IgSF interactome screen with SPR validation; no other evidence.","interaction_type":"direct binding","direction_and_effect":"In an ELISA-based screen of recombinant human proteins, PRTG (with PUNC e11) bound ICAM5; Table 1 lists the ICAM5-PRTG PPI among SPR-validated pairs. Direction and effect are not reported in our evidence [PMID:32822567].","molecular_requirements":"Recombinant extracellular-domain Fc fusions; subunit requirements are not reported in our evidence [PMID:32822567].","affinity_potency":[],"species_and_systems":"Human recombinant proteins, in vitro screen and SPR [PMID:32822567].","localisation_and_range":"ICAM5 carries a secreted flag [flag]; the paper describes it as brain-expressed [PMID:32822567].","caveats":"Single high-throughput paper; affinity for this pair is not reported in our evidence.","key_references":[{"PMID":"32822567","why":"Human IgSF interactome with SPR validation"}],"covers":["LR008375"]},"LR005198":{"pair":"Icosl -> Icos","headline":"Well-supported mouse costimulatory ligand-receptor pair; one paper read as abstract, plus several database records.","interaction_type":"functional only","direction_and_effect":"B7RP-1 (Icosl) co-stimulates T cells in vitro independently of CD28, acting as a receptor ligand for ICOS (agonist) [PMID:10617205]. B7RP-1-Fc transgenic mice show lymphoid hyperplasia and enhanced hypersensitivity [PMID:10617205].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse ligand and receptor, in vitro T-cell costimulation and transgenic mice [PMID:10617205]. Database records concern the human proteins: BioGRID reconstituted complex, IntAct (SPR, FACS, solid phase assay, far western), Reactome ICOS:ICOSL complex, PDB 6X4G [DB:BioGRID] [DB:IntAct] [DB:Reactome] [DB:PDB 6X4G].","localisation_and_range":"Icosl is annotated non-secreted, so a membrane-bound, contact-dependent ligand [flag]. B7RP-1 is expressed on B cells and macrophages and ICOS on activated and memory T cells [PMID:10617205].","caveats":"The paper was read as an abstract only, and its assay is functional rather than direct binding [PMID:10617205]. Binding assays in the database are for human proteins.","key_references":[{"PMID":"10617205","why":"Describes the murine ICOS/B7RP-1 pair and its costimulatory activity"}],"covers":["LR005198"]},"LR007268":{"pair":"IFNA1 -> IFNAR1:IFNAR2","headline":"No paper supports this complex entity; support is GtoPdb entries for each chain.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists IFNA1 as an agonist of IFNAR1 and of IFNAR2 separately [DB:GtoPdb].","molecular_requirements":"Complex of IFNAR1 and IFNAR2 as defined in the entity [flag]; no paper here tests the heterodimer.","affinity_potency":[],"species_and_systems":"Human; no experimental species reported in our evidence.","localisation_and_range":"IFNA1 is flagged secreted; the complex is flagged receptor and transmembrane [flag].","caveats":"No verified papers: judged rows were review-only, different entity or abstract-insufficient. Rests on database records alone.","key_references":[],"covers":["LR007268"]},"LR008555":{"pair":"IFNA13 -> IFNAR1:IFNAR2","headline":"No paper evidence; only GtoPdb entries for the individual chains.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists IFNA13 as agonist of IFNAR1 and IFNAR2 separately [DB:GtoPdb].","molecular_requirements":"Not tested as a complex in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Complex flagged receptor and transmembrane [flag].","caveats":"No verified papers; judged rows were abstract-insufficient, review-only or different-entity.","key_references":[],"covers":["LR008555"]},"LR007277":{"pair":"IFNA6 -> IFNAR1:IFNAR2","headline":"IFNA6 binds the IFNAR1:IFNAR2 receptor; support is a class-wide binding study on the individual chains plus GtoPdb.","interaction_type":"direct binding","direction_and_effect":"IFNA6 acts as an agonist on the type I interferon receptor; the curator-verified study reports binding of human alpha-IFN subtypes to isolated receptor chains [PMID:21856167]. GtoPdb lists this as an agonist interaction with no affinity units [DB:GtoPdb].","molecular_requirements":"Both chains are named: for alpha-IFNs IFNAR2 binds tightly (0.4-5 nM) and IFNAR1 weakly (0.5-5 \u03bcM) [PMID:21856167]. Binding was measured on isolated chains, not on the assembled heterodimer.","affinity_potency":[{"value":"0.4-5 nM","assay":"affinity determination, 12 human alpha-IFN subtypes collectively, isolated IFNAR2 chain","system":"human proteins","cite":"PMID:21856167"},{"value":"0.5-5 \u03bcM","assay":"affinity determination, 12 human alpha-IFN subtypes collectively, isolated IFNAR1 chain","system":"human proteins","cite":"PMID:21856167"}],"species_and_systems":"Human ligand and human receptor chains, isolated recombinant chains (abstract-level reading) [PMID:21856167].","localisation_and_range":"Ligand is flagged secreted and not transmembrane [flag], so it acts as a diffusible paracrine or endocrine signal. The receptor is flagged transmembrane [flag].","caveats":"The affinity range is stated for 'Alpha-IFNs' as a class, not IFNA6 individually; only IFN-alpha1 (220 nM) is singled out as weaker, and the paper was read as an abstract only [PMID:21856167].","key_references":[{"PMID":"21856167","why":"binding of 12 human alpha-IFN subtypes to isolated IFNAR1 and IFNAR2"}],"covers":["LR007277"]},"LR007286":{"pair":"IFNL3 -> IFNLR1:IL10RB","headline":"IFN-lambda3 signals through IFNLR1:IL10RB; abstract-level evidence from receptor discovery and a cell study.","interaction_type":"direct binding","direction_and_effect":"IFN-lambda3 (IL-28B) is an agonist; GtoPdb lists Agonist for IFNL3-IFNLR1 and IFNL3-IL10RB [DB:GtoPdb]. In human cells, IFNL3 treatment led to IFNLR1 and IL10RB colocalization, and IFNL-induced JAK1, TYK2, STAT1 and STAT2 phosphorylation and ISG induction were measured [PMID:42213608].","molecular_requirements":"Both chains are required: the receptor is a heterodimer of IL-10Rbeta and IL-28Ralpha [PMID:12469119]. The shorter IFNLR1 variant 2 (missing part of the JAK1-interacting domain) supported less ISG induction than full-length variant 1 [PMID:42213608].","affinity_potency":[],"species_and_systems":"Human proteins and cells: HEK293T and stem cell-derived hepatocytes [PMID:42213608]; human cells [PMID:12469119]. PDB 5T5W and 9BPV hold structures [DB:PDB 5T5W].","localisation_and_range":"IFNL3 is flagged secreted and non-transmembrane [flag].","caveats":"Both papers read as abstracts only. The curators note this row duplicates another subunit ordering.","key_references":[{"PMID":"12469119","why":"receptor identification"},{"PMID":"42213608","why":"IFNL3-dependent IFNLR1/IL10RB colocalization and signalling"}],"covers":["LR007286"]},"LR002768":{"pair":"IGF1 -> ITGB4","headline":"Integrin alpha6beta4 directly binds IGF1 in one verified study; ITGB4 is the beta chain.","interaction_type":"direct binding","direction_and_effect":"alpha6beta4 directly bound IGF1 but not the R36E/R37E mutant, and IGF1 induced an alpha6beta4-IGF1-IGF1R ternary complex. In low-adhesion conditions IGF1 signaling, survival and soft-agar colony formation were alpha6beta4-dependent [PMID:22351760].","molecular_requirements":"Grafting the beta4 sequence WPNSDP (residues 167-172) onto integrin beta1 markedly enhanced IGF1 binding, implicating this beta4 loop in recognition [PMID:22351760]. The heterodimer was tested.","affinity_potency":[],"species_and_systems":"Not reported in our evidence beyond a direct binding assay [PMID:22351760]. The mouse pair is ortholog-inferred.","localisation_and_range":"IGF1 is flagged secreted [flag].","caveats":"Abstract-only read; no affinity value is reported in our evidence.","key_references":[{"PMID":"22351760","why":"alpha6beta4 binds IGF1; beta4 WPNSDP loop"}],"covers":["LR002768","LR006014"]},"LR002777":{"pair":"IGFBP7 -> IGF1R","headline":"One abstract-level study: IGFBP7 binds the IGF1R extracellular region competitively with IGF-1 and blocks activation.","interaction_type":"direct binding","direction_and_effect":"IGFBP7 pretreatment interfered with IGF1R activation and internalization by IGF-1/2, leaving inactive IGF1R on the cell surface and blocking PI3K-AKT signalling; binding of IGFBP7 and IGF-1 to IGF1R was mutually exclusive. Curator effect: antagonist [PMID:23250396].","molecular_requirements":"The N-terminal 97 amino acids of IGFBP7 were important for binding the extracellular portion of IGF1R and for preventing activation [PMID:23250396].","affinity_potency":[],"species_and_systems":"Human normal and breast cancer cells; curator notes human ligand and receptor [PMID:23250396]. The mouse pair is projected from human.","localisation_and_range":"IGFBP7 is annotated as secreted and IGF1R as transmembrane [flag].","caveats":"Abstract-only read; no affinity reported. Prolonged IGFBP7 exposure also activated 4E-BP1 and sensitised to apoptosis [PMID:23250396].","key_references":[{"PMID":"23250396","why":"IGFBP7 binds IGF1R competitively with IGF-1, blocks activation"}],"covers":["LR002777","LR006023"]},"LR004289":{"pair":"IL12B -> IL12RB1","headline":"IL12B (p40) binds IL12RB1 by binding and structural data, but papers are abstract-only and often concern IL-12 or p40 homodimer generally.","interaction_type":"direct binding","direction_and_effect":"p40 homodimer binds the IL-12 receptor without mediating biologic activity and inhibits IL-12-induced proliferation with an IC50 of 65 ng/ml [PMID:7527811]; mouse (p40)2 acts as an IL-12 antagonist [PMID:7843232]. GtoPdb lists IL12B-IL12RB1 as agonist [DB:GtoPdb].","molecular_requirements":"p40 interacts with the beta subunit of IL-12R, while p35 is required for signalling [PMID:7843232]. A human IL-23 crystal structure indicates p40 binds IL-12Rbeta1 with high affinity [PMID:29287995]. The ternary IL-23:IL-23R:IL-12Rbeta1 complex had low stability [PMID:29287995].","affinity_potency":[{"value":"IC50 of 20 to 70 ng/ml","assay":"80-kDa p40 dimer inhibiting 125I-IL-12 binding","system":"KIT225/K6 human T cells","cite":"PMID:7527811"}],"species_and_systems":"Human COS-expressed p40 on KIT225/K6 cells [PMID:7527811]; mouse p40 on COS cells expressing human IL-12R beta, with little activity on human PHA blasts [PMID:7843232]; human crystal structure [PMID:29287995]. Mouse pair is ortholog-inferred.","localisation_and_range":"IL12B is flagged secreted [flag].","caveats":"All papers are abstract-only reads. Several tests concern the IL-12 receptor as a whole, not IL12RB1 alone [PMID:7527811]. The knockout paper concerns IL12RB2 [PMID:11086056]. Affinity values for IL12B-IL12RB1 are not given (GtoPdb notes pKd only as a unit) [DB:GtoPdb].","key_references":[{"PMID":"7843232","why":"p40 interacts with IL-12R beta subunit"},{"PMID":"7527811","why":"p40 monomer and dimer bind IL-12R"},{"PMID":"29287995","why":"structure; p40 binds shared IL-12Rbeta1"}],"covers":["LR000859","LR004289"]},"LR007295":{"pair":"IL13 -> IL13RA1:IL4R","headline":"IL13 acts on the IL13RA1:IL4R type II receptor; reconstitution and mutagenesis papers support it, read as abstracts.","interaction_type":"direct binding","direction_and_effect":"IL13 binds IL13RA1 and, with IL4R alpha, forms a signalling complex: IL-4 and IL-13 activated Stat6 only in cells expressing both IL-4R alpha and IL-13R alpha1 [PMID:9013879]. An engineered variant IL-13E13K binds the IL-13 receptor with 4-fold higher affinity than wild type but is an antagonist [PMID:11278629]; this is a designed variant, not natural.","molecular_requirements":"Both chains needed for high affinity and signalling: IL-13R alpha1 alone binds IL-13 at low affinity, the pair at high affinity [PMID:9013879]. The D1 domain of IL-13Ralpha1 is the critical binding unit for IL-13 but not IL-4 [PMID:19586918]. In the variant study the chains were not resolved [PMID:11278629].","affinity_potency":[{"value":"Kd approximately 4 nM","assay":"IL-13 binding to IL-13R alpha1 alone","system":"CHO cells expressing recombinant human IL-13R alpha1","cite":"PMID:9013879"},{"value":"Kd approximately 30 pM","assay":"IL-13 binding to IL-4R alpha plus IL-13R alpha1","system":"CHO cells co-expressing both chains","cite":"PMID:9013879"}],"species_and_systems":"Human proteins; recombinant transfected cells and receptor mutants [PMID:9013879] [PMID:19586918]; TF-1 cells and primary monocytes for the variant [PMID:11278629].","localisation_and_range":"IL13 flagged secreted [flag]; receptor complex flagged transmembrane [flag].","caveats":"All three papers read as abstracts only. The variant paper does not resolve which receptor chains were bound, so its assignment to this complex is inferred. One review-only paper excluded.","key_references":[{"PMID":"9013879","why":"Cloning of IL-13R alpha1; reconstitution with IL-4R alpha, Kd values"},{"PMID":"19586918","why":"Structural requirements of the shared receptor, D1 domain"},{"PMID":"11278629","why":"IL-13E13K antagonist variant"}],"covers":["LR007295"]},"LR004298":{"pair":"IL16 -> CD4","headline":"IL16 acts through CD4 with direct binding and functional evidence across human and mouse cells.","interaction_type":"direct binding","direction_and_effect":"IL-16 (LCF) is a CD4 ligand that elicits eosinophil migration (ED50 10(-12) to 10(-11) M) [PMID:1851800]. LCF-induced migration requires membrane-expressed CD4 [PMID:7910967]. IL-16 induced c-fos in CD4-expressing cerebellar granule neurons [PMID:10479680]. Agonist [PMID:1851800].","molecular_requirements":"LCF needs both autoaggregation of its monomers and membrane CD4 [PMID:7910967]. The D4 domain of CD4 contains the IL-16 binding site [PMID:10438516]. Monovalent OKT4 Fab competitively inhibited the response [PMID:1851800].","affinity_potency":[{"value":"ED50 10(-12) to 10(-11) M","assay":"eosinophil migration (potency, not affinity)","system":"human eosinophils, recombinant LCF","cite":"PMID:1851800"}],"species_and_systems":"Human eosinophils and lymphocytes [PMID:1851800] [PMID:7910967]; mouse cerebellar neurons [PMID:10479680]; D4 peptide inhibition of IL-16 binding in vitro [PMID:10438516].","localisation_and_range":"IL16 flagged secreted [flag]; secreted from a neuronal precursor after caspase-3 processing [PMID:10479680].","caveats":"Mostly abstract reads; 10479680 and 10438516 are functional rather than direct binding. Bivalent/tetrameric LCF is required, so monomer behaviour is uncertain [PMID:7910967]. Binding affinity not reported in our evidence.","key_references":[{"PMID":"1851800","why":"CD4 affinity purification; eosinophil migration"},{"PMID":"10438516","why":"CD4 D4 domain binds IL-16"},{"PMID":"7910967","why":"CD4 required for LCF migration"}],"covers":["LR000868","LR004298"]},"LR002786":{"pair":"IL17A -> IL17RD","headline":"IL-17RD directly binds IL-17A (not IL-17F or the A/F heterodimer) and acts as a second IL-17A receptor; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Agonist. IL-17RD directly bound IL-17A but not IL-17F or IL-17A/F, and IL-17A-induced gene expression was defective in Il17rd-deficient keratinocytes [PMID:31175175]. Il17rd deficiency in nonhemopoietic cells attenuated imiquimod-induced psoriasis-like skin inflammation [PMID:31175175].","molecular_requirements":"IL-17RD formed a heterodimer with IL-17RA [PMID:31175175]. IL-17RC and IL-17RD differentially activate IL-17A signalling, and compound mutation produced complete deficits in keratinocytes; IL-23 induction depends on both [PMID:31175175].","affinity_potency":[],"species_and_systems":"Curators recorded human for ligand and receptor, but the abstract also describes Il17rd-deficient keratinocytes and mouse psoriasis-model work; the species of each experiment is not stated in the abstract [PMID:31175175].","localisation_and_range":"Not reported in our evidence beyond IL-17A being annotated as secreted and IL-17RD as a receptor [flag].","caveats":"Single paper read as an abstract only; no affinity reported. The human pair is ortholog-inferred while the mouse pair is not.","key_references":[{"PMID":"31175175","why":"Direct IL-17A binding to IL-17RD and Il17rd-deficient phenotypes"}],"covers":["LR002786","LR006029"]},"LR001859":{"pair":"IL17C -> IL17RE","headline":"IL-17RE is reported as a receptor specific to IL-17C, working with IL-17RA; two abstract-only papers.","interaction_type":"functional only","direction_and_effect":"Agonist. IL-17C activated signalling through the IL-17RE-IL-17RA complex to induce antibacterial peptides and proinflammatory genes; IL-17RE-deficient mice had lower antibacterial gene expression, greater bacterial burden and early mortality [PMID:21993849]. IL-17C bound a receptor complex of IL-17RA and IL-17RE on epithelial cells [PMID:21993848]. GtoPdb lists agonist [DB:GtoPdb].","molecular_requirements":"IL-17RE signals with IL-17RA [PMID:21993849, PMID:21993848]. Whether IL-17RE alone binds IL-17C is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiment species is recorded as unspecified for PMID:21993849, although the abstract describes IL-17RE-deficient mice [PMID:21993849]; human is recorded for PMID:21993848. Both human and mouse pairs are listed as non-inferred.","localisation_and_range":"IL-17C annotated as secreted and non-transmembrane [flag]; IL-17RE as a receptor [flag]. PMID:21993848 describes autocrine action on epithelial cells.","caveats":"Both papers read as abstracts only; no affinity values. PMID:21993849 is classed functional_in_vitro rather than direct binding.","key_references":[{"PMID":"21993849","why":"IL-17RE as the functional receptor for IL-17C; knockout mice"},{"PMID":"21993848","why":"IL-17C autocrine signalling through IL-17RA/IL-17RE"}],"covers":["LR001859","LR005205"]},"LR000878":{"pair":"IL1A -> IL1R1","headline":"IL-1alpha binds the same type I receptor as IL-1beta; old competition-binding evidence in murine and human cells.","interaction_type":"direct binding","direction_and_effect":"IL-1 alpha uses the receptor shared with IL-1 beta on both murine and human cells [PMID:2946959]; GtoPdb lists agonist [DB:GtoPdb].","molecular_requirements":"UniProt says IL1A binds IL1R1 together with IL1RAP to form the high affinity receptor complex [DB:UniProt]; this paper does not address IL1RAP.","affinity_potency":[],"species_and_systems":"Murine T cells/fibroblasts and human cells, from the abstract [PMID:2946959].","localisation_and_range":"Ligand carries the secreted annotation flag [flag], which implies paracrine/endocrine range; receptor localisation beyond the receptor flag is not reported in our evidence.","caveats":"Abstract only; no affinity or assay detail reported in our evidence. One more paper is pending.","key_references":[{"PMID":"2946959","why":"IL-1 alpha and IL-1 beta share one receptor on murine and human cells"}],"covers":["LR000878","LR004308"]},"LR002795":{"pair":"IL1RAP -> PTPRD","headline":"IL1RAP and PTPRD bind directly, with crystal structures and neuronal assays; trans-synaptic adhesion.","interaction_type":"direct binding","direction_and_effect":"PTPdelta binds IL-1RAcP trans-synaptically and bidirectionally induces pre- and postsynaptic differentiation [PMID:25908590]. IL-1RAcP interacted with PTPdelta through the extracellular domain in cortical neurons [PMID:22357843]. An interactome screen also reports IL1RAP interacting with all three LAR-PTPRs [PMID:32822567].","molecular_requirements":"Crystal structure of the complex shows the PTPdelta Ig1-Fn2 domains bind IL-1RAcP extracellular domain 1:1; Ig1-Ig2 of PTPdelta is insufficient, and IL-1RAcP Ig1 contacts PTPdelta Ig2/Ig3 while Ig3 of IL-1RAcP does not [PMID:25908590]. Splice inserts of PTPdelta tune binding; absence of meA gave threefold reduced affinity [PMID:25908590]. W27A mutation of IL-1RAcP reduced affinity sevenfold [PMID:25908590].","affinity_potency":[],"species_and_systems":"Crystallography on recombinant human domains and neuronal assays [PMID:25908590]; cultured cortical neurons [PMID:22357843]; SPR/ELISA screen of human proteins [PMID:32822567]. Mouse is the non-inferred species in the database record.","localisation_and_range":"Both are membrane proteins [flag]; interaction is across the synapse (trans, contact-dependent) [PMID:25908590].","caveats":"Direction is arbitrary: the interaction is bidirectional adhesion, not a classic secreted ligand. Two abstracts were read as abstract only [PMID:22357843]. Affinity values are in tables not shown in our evidence.","key_references":[{"PMID":"25908590","why":"Crystal structures of PTPdelta with IL-1RAcP"},{"PMID":"22357843","why":"IL-1RAcP interacts with PTPdelta in cortical neurons"},{"PMID":"32822567","why":"Interactome screen reporting IL1RAP with LAR-PTPRs"}],"covers":["LR002795","LR006038"]},"LR000887":{"pair":"IL20 -> IL20RA","headline":"IL-20 signals through IL20RA with IL20RB, but IL20RA alone does not bind IL-20 in the one binding study.","interaction_type":"direct binding","direction_and_effect":"IL-20 induces STAT3 phosphorylation through the type I complex IL-20Ralpha/IL-20Rbeta and the type II complex IL-22R/IL-20Rbeta [PMID:11564763] [PMID:12351624]. GtoPdb lists Agonist [DB:GtoPdb]; annotated Stimulatory.","molecular_requirements":"IL20RA is part of a ternary 1:1:1 complex with IL-20 and the second receptor; sIL-20R1 does not bind IL-19 or IL-20 on its own, and the ligand first binds receptor II [PMID:14580208]. Type II signalling uses IL22RA1 instead of IL20RA [PMID:11564763].","affinity_potency":[],"species_and_systems":"Recombinant human soluble ectodomains from Drosophila S2 cells with size-exclusion chromatography [PMID:14580208]; transfected cell lines for signalling [PMID:12351624]. Mouse pair projected.","localisation_and_range":"IL-20 flagged secreted [flag].","caveats":"Binding evidence is for the heterodimer, not IL20RA alone; individual-chain evidence is inherited from complex-level data. All papers abstract only.","key_references":[{"PMID":"14580208","why":"sIL-20R1 does not bind IL-20 alone; ternary complex forms"},{"PMID":"11564763","why":"IL-20 signals through two receptor complexes"},{"PMID":"12351624","why":"Receptor redundancy among IL-19, IL-20, IL-24"}],"covers":["LR000887","LR004317"]},"LR000896":{"pair":"IL23A -> IL23R","headline":"IL-23 binds IL-23R directly through p19; crystal structure and receptor identification support it, with IL-12Rbeta1 as shared partner.","interaction_type":"direct binding","direction_and_effect":"The crystal structure shows IL-23R binds IL-23 exclusively via its N-terminal immunoglobulin domain [PMID:29287995]. Human IL-23, but not IL-12, has detectable affinity for human IL-23R [PMID:12023369]. Agonist per GtoPdb [DB:GtoPdb].","molecular_requirements":"IL-23 uses only its p19 subunit to contact IL-23R, with an interface of about 900 A2 and 51 residues [PMID:29287995]. IL-23R pairs with IL-12Rbeta1 for IL-23 responsiveness; antibodies to either chain block responses [PMID:12023369].","affinity_potency":[],"species_and_systems":"Human proteins; crystal structure of the IL-23:IL-23R:Nb22E11 complex at 2.8 A [PMID:29287995]; NK line and Ba/F3 transfectants [PMID:12023369].","localisation_and_range":"IL23A is flagged secreted [flag].","caveats":"Abstracts only for both papers. No affinity value is given in our evidence. The ternary complex with IL-12Rbeta1 was unstable and not solved [PMID:29287995].","key_references":[{"PMID":"29287995","why":"crystal structure of IL-23:IL-23R"},{"PMID":"12023369","why":"identification of IL-23R pairing with IL-12Rbeta1"}],"covers":["LR000896","LR004326"]},"LR010976":{"pair":"IL37 -> IL18RAP","headline":"Database-asserted only; one paper pending.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists Agonist [DB:GtoPdb]. UniProt says IL-37 binds a receptor composed of IL18R1 and IL18RAP [DB:UniProt].","molecular_requirements":"IL18RAP appears with IL18R1 in the receptor [DB:UniProt].","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Ligand annotated as secreted [flag]; receptor-side localisation not otherwise reported.","caveats":"No judged papers; direct binding to IL18RAP alone is not shown.","key_references":[],"covers":["LR010976"]},"LR007925":{"pair":"INHA:INHBA -> ACVR1:ACVR2A","headline":"Inhibin-A (INHA:INHBA) to ACVR1:ACVR2A: database support, mostly via activin A; no curated paper.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists INHA and INHBA with ACVR2A as agonist [DB:GtoPdb]. UniProt notes activin A can form a non-signalling complex with ACVR1 and a type II receptor, rendering receptors unavailable to BMPs [DB:UniProt]. Inhibin-A effect is not directly evidenced in our evidence.","molecular_requirements":"Type II chain ACVR2A binds activin A/inhibin per databases; UniProt says it binds inhibin-A/INHA-INHBA [DB:UniProt]. PDB 7U5P shows ACVR2A ligand-binding region with activin A [DB:PDB 7U5P]. Type I chain ACVR1 is not specifically evidenced.","affinity_potency":[],"species_and_systems":"Species not reported in our evidence. X-ray structure PDB 7U5P (35643319) [DB:PDB 7U5P]; BioGRID has INHA and INHBA with ACVR2A [DB:BioGRID 275207][DB:BioGRID 2513581].","localisation_and_range":"Ligand heterodimer flagged secreted [flag].","caveats":"No paper evidence supports this pair; it rests on database records. Both judged papers were review_only. The PDB structure is activin A (INHBA) with the receptor, not the INHA:INHBA heterodimer; evidence concerns INHBA rather than the inhibin heterodimer.","key_references":[],"covers":["LR007925"]},"LR007934":{"pair":"INHA:INHBB -> ACVR1B:ACVR2B","headline":"Inhibin A:activin B to ACVR1B:ACVR2B rests on database records for single chains only; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"No curator-verified paper; GtoPdb lists the component pairs as agonist [DB:GtoPdb]. BioGRID records INHBB-ACVR2B (Affinity Capture-Western) [DB:BioGRID]; IntAct has a coimmunoprecipitation record [DB:IntAct]; Reactome lists activin binding to ACVR2A,B:ACVR1B [DB:Reactome].","molecular_requirements":"Receptor is a type I plus type II pair (ACVR1B:ACVR2B); whether this specific heterodimeric ligand binds this exact combination is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human pair; no experimental species reported in our evidence (no verified papers).","localisation_and_range":"Ligand carries a secreted flag and receptor a transmembrane flag [flag]; suggests endocrine or paracrine action on membrane receptors.","caveats":"Rests on databases alone; the two papers judged were review_only, so none confirms this pair. Database records concern individual subunits or related complexes, not necessarily this exact combination. ","key_references":[],"covers":["LR007934"]},"LR008717":{"pair":"INHBA -> SMAD3","headline":"Activin A to SMAD3 has no verified evidence; only a UniProt downstream-signalling statement.","interaction_type":"database-asserted only","direction_and_effect":"UniProt says INHBA signalling through type I and type II receptors leads to phosphorylation of SMAD2 and SMAD3 [DB:UniProt].","molecular_requirements":"Acts via cell-surface receptors; SMAD3 is an intracellular mediator, not described as a ligand-binding receptor in our evidence.","affinity_potency":[],"species_and_systems":"Human; no experimental species reported in our evidence.","localisation_and_range":"Ligand secreted flag [flag]; SMAD3 is not a membrane receptor.","caveats":"Likely a downstream signalling link rather than a ligand-receptor interaction. One paper was review_only and five abstract_insufficient.","key_references":[],"covers":["LR008717"]},"LR007259":{"pair":"INHBA:INHBB -> ACVR1:ACVR2B","headline":"Activin A/B ligand complex to an ACVR1:ACVR2B receptor complex; supported by database records only, ACVR1 chain weakly.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists INHBA-ACVR2B and INHBB-ACVR2B as agonist interactions [DB:GtoPdb]. UniProt notes activin A can engage ACVR1 in a non-signaling complex that blocks BMP signaling [PMID:26333933].","molecular_requirements":"Type II ACVR2B binding is supported by BioGRID affinity-capture and reconstituted-complex records [PMID:9202237] [PMID:22267736] and a structure of activin A with an ActRIIB-Alk4 fusion [DB:PDB 7OLY]. No record here pairs ACVR1 as the type I partner; Reactome lists ACVR1B [DB:Reactome].","affinity_potency":[],"species_and_systems":"Not reported in our evidence beyond human database records.","localisation_and_range":"Ligand is flagged secreted [flag], so likely paracrine/endocrine; receptor is flagged transmembrane [flag].","caveats":"No paper-level evidence is held for this pair (only review-only or abstract-insufficient rows), so it rests on database records alone. The ACVR1 chain has no direct support, and the UniProt text implies inhibition rather than agonism for ACVR1.","key_references":[],"covers":["LR007259"]},"LR008933":{"pair":"INHBB -> SMAD3","headline":"Activin B to SMAD3 is not a ligand-receptor pair; only a UniProt text mention.","interaction_type":"database-asserted only","direction_and_effect":"UniProt text says receptors phosphorylate intracellular signalling mediators after ligand binding [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Ligand flagged secreted [flag]; SMAD3 is not flagged as a receptor or transmembrane.","caveats":"No papers; rows were review-only, different-entity or abstract-insufficient. SMAD3 is downstream of the receptors, not a direct partner.","key_references":[],"covers":["LR008933"]},"LR004379":{"pair":"JAG2 -> NOTCH1","headline":"Jagged2 binds Notch1 directly in vitro; database records are extensive but only one paper is detailed.","interaction_type":"direct binding","direction_and_effect":"Soluble Notch1 bound Jagged2 on cells and in solid-phase assays, Ca2+-dependent [PMID:11006133]. GtoPdb lists it as agonist [DB:GtoPdb]. Annotation: stimulatory.","molecular_requirements":"Ca2+ required [PMID:11006133].","affinity_potency":[],"species_and_systems":"Human proteins in the one paper [PMID:11006133]. The human pair is ortholog-inferred; a mouse record exists.","localisation_and_range":"JAG2 is flagged as not secreted [flag].","caveats":"Abstract-only; affinities not given in our evidence. BioGRID, GtoPdb and Reactome records support it [DB:BioGRID][DB:GtoPdb][DB:Reactome].","key_references":[{"PMID":"11006133","why":"Direct binding of Jagged2 to Notch1"}],"covers":["LR000956","LR004379"]},"LR001868":{"pair":"JAM2 -> F11R","headline":"Genetic evidence in zebrafish suggests Jam1a-Jam2a interaction supports Notch signalling; no direct binding shown.","interaction_type":"functional only","direction_and_effect":"Zebrafish jam1a loss of function caused loss of Notch signalling and HSCs; activating Notch rescued HSCs in jam1a or jam2a deficient embryos [PMID:25119047]. The authors conclude Jam1a-Jam2a interactions facilitate Notch signal transduction [PMID:25119047].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Zebrafish embryos; the pair is ortholog-inferred for human and mouse [PMID:25119047].","localisation_and_range":"JAM2 flagged as not secreted, receptor transmembrane [flag]; the paper describes cell contact between somite and precursors [PMID:25119047].","caveats":"No binding assay, and zebrafish genes are mapped to human. The dossier lists experiment species as human, which the paper contradicts. No database records.","key_references":[{"PMID":"25119047","why":"Zebrafish Jam1a-Jam2a genetics"}],"covers":["LR001868","LR005213"]},"LR000968":{"pair":"KNG1 -> RXFP4","headline":"A single report of bradykinin and kallidin activating GPR100 (RXFP4) in CHO cells; not replicated in our evidence and the active ligands are kinins.","interaction_type":"functional only","direction_and_effect":"Bradykinin and kallidin elicited a calcium response in CHO cells stably expressing GPR100, with EC50 in the low nanomolar range, whereas des-Arg analogues were inactive [PMID:14530218].","molecular_requirements":"Signalling was through Galphaq rather than Galphai/o, using Galpha16 and aequorin as readout; the ligands are kinin peptides, not intact KNG1 [PMID:14530218].","affinity_potency":[],"species_and_systems":"Human GPR100 expressed in CHO cells with aequorin and Galpha16 [PMID:14530218].","localisation_and_range":"KNG1 is secreted [flag]; peripheral hormone-like action suggested by the paper's expression data [PMID:14530218].","caveats":"One paper only, abstract read; no replication in our evidence. The curator note says the claim was not independently replicated and GPR100 is regarded as RXFP4 whose replicated ligand is relaxin-3, so treat as doubtful. The EC50 is not given as a number.","key_references":[{"PMID":"14530218","why":"GPR100 calcium response to bradykinin and kallidin"}],"covers":["LR000968","LR004390"]},"LR010877":{"pair":"KRTAP4-12 -> AQP1","headline":"Only a yeast two-hybrid IntAct record; no evidence that this is a ligand-receptor interaction.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"IntAct lists a two-hybrid physical association from a large-scale screen; species and system not reported in our evidence [DB:IntAct].","localisation_and_range":"Not reported in our evidence.","caveats":"The only judged paper was review_only, so no curator-verified evidence exists. A two-hybrid hit does not show a ligand-receptor relationship, and KRTAP4-12 is a keratin-associated protein, so this is likely a screening artefact.","key_references":[],"covers":["LR010877"]},"LR010769":{"pair":"KRTAP4-12 -> CATSPER1","headline":"Only a yeast two-hybrid IntAct record; no evidence that this is a ligand-receptor interaction.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"IntAct lists a two-hybrid physical association from a large-scale screen; species and system not reported in our evidence [DB:IntAct].","localisation_and_range":"Not reported in our evidence.","caveats":"The only judged paper was review_only, so no curator-verified evidence exists. A two-hybrid hit does not show a ligand-receptor relationship, and KRTAP4-12 is a keratin-associated protein, so this is likely a screening artefact.","key_references":[],"covers":["LR010769"]},"LR002849":{"pair":"L1CAM -> L1CAM","headline":"Homophilic L1 interaction: one functional adhesion paper plus database records; other judged papers abstract_insufficient.","interaction_type":"functional only","direction_and_effect":"Breast cancer cell adhesion to activated endothelium was via ALCAM or L1 itself, identified by blocking antibodies and recombinant-protein flow assays [PMID:22983139]. Databases list trans-homodimer [DB:Reactome R-HSA-191438], two-hybrid [DB:BioGRID] and solid phase assay [DB:IntAct].","molecular_requirements":"Reactome describes an L1 trans-homodimer at the plasma membrane [DB:Reactome R-HSA-191438].","affinity_potency":[],"species_and_systems":"Human breast cancer cells and endothelial cells [PMID:22983139]. Mouse pair is ortholog-inferred.","localisation_and_range":"Trans (cell-contact) homophilic binding [DB:Reactome]; L1CAM also flagged secreted [flag].","caveats":"Paper is abstract only and 'potential binding partners'; ALCAM versus L1 not resolved. Seven judged papers insufficient, one pending.","key_references":[{"PMID":"22983139","why":"L1 on endothelium as potential partner"}],"covers":["LR002849","LR006084"]},"LR004397":{"pair":"LAMA1 -> ITGA1","headline":"A recombinant laminin alpha1 N-terminal fragment binds purified alpha1beta1 integrin; abstract-only read.","interaction_type":"direct binding","direction_and_effect":"Fragment alpha1VI/V bound purified alpha1beta1 and alpha2beta1 integrins, whereas fragment alpha1V alone did not [PMID:9688542]. Effect (activating or inhibitory) not reported in our evidence.","molecular_requirements":"The binding site localises to the LN module (domain VI); the integrin was tested as the alpha1beta1 heterodimer, so ITGB1 is also needed in our evidence [PMID:9688542].","affinity_potency":[],"species_and_systems":"Recombinant laminin alpha1 fragments and purified integrins; species not stated in the abstract [PMID:9688542].","localisation_and_range":"Ligand flagged secreted [flag]; a matrix ligand.","caveats":"Abstract only; the fragment, not full-length LAMA1, was tested. The ITGA1 pair is assigned from an alpha1beta1 heterodimer result. BioGRID lists a reconstituted complex [DB:BioGRID].","key_references":[{"PMID":"9688542","why":"Laminin alpha1 LN module binds alpha1beta1 integrin"}],"covers":["LR000976","LR004397"]},"LR000977":{"pair":"LAMA1 -> ITGA2","headline":"A recombinant laminin alpha1 N-terminal fragment binds purified alpha2beta1 integrin; abstract-only read.","interaction_type":"direct binding","direction_and_effect":"Fragment alpha1VI/V bound purified alpha1beta1 and alpha2beta1 integrins, whereas fragment alpha1V alone did not [PMID:9688542]. The interaction record carries a Stimulatory effect label [flag].","molecular_requirements":"The site localises to the LN module (domain VI); the integrin was tested as the alpha2beta1 heterodimer, so ITGB1 is also needed in our evidence [PMID:9688542].","affinity_potency":[],"species_and_systems":"Recombinant laminin alpha1 fragments and purified integrins; species not stated in the abstract [PMID:9688542].","localisation_and_range":"Ligand flagged secreted [flag]; a matrix ligand.","caveats":"Abstract only; a fragment rather than full-length LAMA1 was tested. Pair is assigned from a heterodimer result. BioGRID lists a reconstituted complex [DB:BioGRID].","key_references":[{"PMID":"9688542","why":"LN module binds alpha2beta1 integrin"}],"covers":["LR000977","LR004398"]},"LR000986":{"pair":"LAMA2 -> ITGB1","headline":"Laminin-211/221 shows only partial, non-saturating binding to alpha7beta1; weak direct evidence plus abstract-only functional support.","interaction_type":"direct binding","direction_and_effect":"Laminin-211/221 showed only partial saturation at the highest recombinant integrin concentration tested [PMID:16413178]. Alpha7beta1 mediates myoblast migration on laminin-2 [PMID:11278916]. Labelled Stimulatory [flag].","molecular_requirements":"ITGB1 acts as part of alpha-beta heterodimers; alpha7beta1 is the one tested here [PMID:11278916].","affinity_potency":[],"species_and_systems":"Human recombinant integrins [PMID:16413178]; human myoblasts [PMID:11278916]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand flagged secreted; receptor flagged not secreted [flag].","caveats":"The curator calls the positive weak; Kd was not determinable (ND(+)) and the ligand is the trimer, not LAMA2 alone [PMID:16413178]. Two other confirmed rows are not shown.","key_references":[{"PMID":"16413178","why":"Partial saturation with laminin-211/221"},{"PMID":"11278916","why":"Alpha7beta1 migration on laminin-2"}],"covers":["LR000986","LR004406"]},"LR006089":{"pair":"LAMA3 -> ITGA6","headline":"Direct binding of laminin-332 (carrying LAMA3) to recombinant integrin alpha6beta1; one full-text study, assembled trimer only.","interaction_type":"direct binding","direction_and_effect":"Laminin-332 bound recombinant integrin alpha6beta1 in solid-phase saturation binding; the integrin is the receptor, laminin the ligand [PMID:16413178].","molecular_requirements":"LAMA3 is one chain of laminin-332 (alpha3beta3gamma2); the paper never tests single chains, and the receptor tested was the alpha6beta1 heterodimer, so ITGA6 alone is not shown to suffice [PMID:16413178].","affinity_potency":[{"value":"Kd 7.5 nM","assay":"solid-phase saturation binding, laminin-332 vs recombinant alpha6beta1 ectodomain","system":"human recombinant","cite":"PMID:16413178"}],"species_and_systems":"Human recombinant integrin and purified human laminin; mouse pair is ortholog-inferred only [PMID:16413178].","localisation_and_range":"LAMA3 is flagged secreted and not transmembrane [flag]; laminin acts as a basement-membrane matrix ligand (not stated in the paper text we hold).","caveats":"Assembled heterotrimer evidence only; no cellular or in vivo data in our evidence. Two further papers were judged abstract-insufficient.","key_references":[{"PMID":"16413178","why":"Kd table of recombinant integrins vs laminin isoforms"}],"covers":["LR002855","LR006089"]},"LR002858":{"pair":"LAMA3 -> SDC4","headline":"Syndecan-4-transfected cells adhere to laminin alpha3 LG4; functional evidence only, abstract-level read.","interaction_type":"functional only","direction_and_effect":"293T cells transfected with syndecan-2 or -4, but not glypican-1, specifically adhered to LG4 and the A3G75aR peptide; adhesion was inhibited by heparitinase I treatment [PMID:11373281].","molecular_requirements":"Adhesion mapped to a LG4 peptide (NSFMALYLSKGR); heparan sulfate chains implicated [PMID:11373281].","affinity_potency":[],"species_and_systems":"Transfected 293T cells; species not stated in our evidence [PMID:11373281].","localisation_and_range":"LAMA3 flagged secreted [flag]; SDC4 transmembrane flag not given in dossier.","caveats":"No direct binding assay for syndecan-4 in our evidence (direct binding was shown for syndecan-2). Abstract-only read.","key_references":[{"PMID":"11373281","why":"Syndecan-4 transfectants adhere to LG4"}],"covers":["LR002858","LR006092"]},"LR000995":{"pair":"LAMA5 -> ITGA3","headline":"Laminin alpha5 (as laminin-511/521) binds integrin alpha3beta1 with nM affinity; shown as heterotrimer and heterodimer, not single chains.","interaction_type":"direct binding","direction_and_effect":"Laminin-511/521 binds recombinant integrin alpha3beta1 [PMID:16413178]; laminin-10/11 is a high-affinity alpha3beta1 ligand, and CD151 potentiates the binding [PMID:15677332]. Blocking antibodies against alpha3 or beta1 inhibited A549 adhesion to laminin-10/11 [PMID:9624186]. Marked as stimulatory in the interaction annotation.","molecular_requirements":"Laminin alpha5 acts within a beta/gamma heterotrimer, and ITGA3 acts with ITGB1 (alpha3beta1); neither single chain was tested alone [PMID:16413178]. CD151 sustains the activated integrin conformation [PMID:15677332].","affinity_potency":[{"value":"Kd 3.4 nM","assay":"solid-phase saturation binding, recombinant integrin ectodomain to purified laminin isoforms (laminin-511/521 vs alpha3beta1)","system":"human recombinant proteins","cite":"PMID:16413178"}],"species_and_systems":"Human recombinant integrin and purified laminin [PMID:16413178]; human A549 cells [PMID:9624186]. Mouse pair is projected from human evidence (ortholog-inferred).","localisation_and_range":"LAMA5 is flagged secreted [flag] and ITGA3 is flagged as a receptor [flag]; beyond these annotation flags, range is not reported in our evidence.","caveats":"Chain-level assignment is inferred from the heterotrimer. Two of the three supporting papers were read as abstracts only [PMID:15677332][PMID:9624186]; the latter is an antibody-blocking adhesion readout.","key_references":[{"PMID":"16413178","why":"Kd of recombinant alpha3beta1 for laminin-511/521"},{"PMID":"15677332","why":"Laminin-10/11 high-affinity alpha3beta1 ligand; CD151 role"},{"PMID":"9624186","why":"Antibody-blocked adhesion to laminin-10/11"}],"covers":["LR000995","LR004414"]},"LR006098":{"pair":"LAMB1 -> DAG1","headline":"Laminin beta1 chain (in laminin-10/11, laminin A/B1/B2) binds alpha-dystroglycan in brain and nerve; chain-level, abstract-only evidence.","interaction_type":"direct binding","direction_and_effect":"Laminin-10/11 preferentially bound brain alpha-dystroglycan over skeletal-muscle alpha-dystroglycan [PMID:16709410]. Peripheral-nerve alpha-dystroglycan binds laminin (A/B1/B2) and merosin (M/B1/B2) [PMID:7925941]. Annotated stimulatory.","molecular_requirements":"Binding to the alpha-dystroglycan form depends on tissue glycosylation (brain-specific glycoepitope) [PMID:16709410]; in nerve it is Ca2+-dependent and heparin-inhibitable [PMID:7925941]. LAMB1 was not tested alone.","affinity_potency":[],"species_and_systems":"Mammalian brain and peripheral nerve extracts; species not reported in our evidence. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"LAMB1 is flagged secreted [flag] and DAG1 is flagged as a receptor [flag]; beyond these annotation flags, range is not reported in our evidence.","caveats":"Both papers were read as abstracts only and tested whole laminins, so LAMB1 is inferred. An IntAct record from a cross-linking study lists Q14118-P07942 [DB:IntAct] [PMID:30914516]; no affinity values reported.","key_references":[{"PMID":"16709410","why":"Laminin-10/11 binds brain alpha-dystroglycan preferentially"},{"PMID":"7925941","why":"Nerve alpha-dystroglycan binds laminin and merosin"}],"covers":["LR002864","LR006098"]},"LR002867":{"pair":"LAMB2 -> ITGA6","headline":"LAMB2 (as part of laminin-511/521) binds integrin alpha6 with sub-nanomolar to nanomolar affinity; chain-level, assembled-laminin evidence.","interaction_type":"direct binding","direction_and_effect":"Laminin-511/521, which contains LAMB2, binds the integrin alpha6beta1 ectodomain in solid-phase assays [PMID:16413178]. A second paper reports radioligand-binding and cell-adhesion assays showing alpha6beta4 is a receptor for several laminin isoforms [PMID:7721947]. Direction: laminin ligand to integrin receptor; effect is adhesion/binding, nothing more reported.","molecular_requirements":"The binder tested is the alpha6beta1 heterodimer, and the ligand is the assembled laminin heterotrimer; LAMB2 alone and ITGA6 alone were not tested [PMID:16413178]. PDB 7CEC lists a structure with chains of P11047 and P23229 [DB:PDB 7CEC].","affinity_potency":[{"value":"Kd 0.73 nM","assay":"solid-phase saturation binding, recombinant integrin ectodomain to purified laminin isoform; integrin alpha6beta1 vs laminin-511/521","system":"recombinant human integrin, purified laminin","cite":"PMID:16413178"}],"species_and_systems":"Human recombinant proteins in the solid-phase study [PMID:16413178]. The 804G bladder epithelial cell study used rat cells with laminin of unstated origin [PMID:7721947]. Mouse pair is projected from human.","localisation_and_range":"Ligand is annotated as secreted [flag]; the receptor is annotated as a receptor [flag]. Matrix versus soluble range is not reported in our evidence.","caveats":"Kd values are for the whole laminin heterotrimer, not the single chain; the paper never tests individual chains. The second paper was read as an abstract only and concerns alpha6beta4, with laminin 4 only inferred as LAMA2/LAMB2/LAMC1 by the curator.","key_references":[{"PMID":"16413178","why":"Kd for alpha6beta1 vs laminin-511/521, full text"},{"PMID":"7721947","why":"alpha6beta4 binds several laminins, abstract only"}],"covers":["LR002867","LR006101"]},"LR002876":{"pair":"LEFTY1 -> ACVR2A","headline":"Lefty is proposed to antagonise Nodal by competing for ActRIIA/ActRIIB; evidence is functional, from one abstract.","interaction_type":"functional only","direction_and_effect":"Processed Lefty proteins inhibited Nodal signalling, and this was rescued by excess ActRIIA or ActRIIB, suggesting competitive binding as an antagonist [PMID:11952836].","molecular_requirements":"Receptor identity is shared with Nodal: ActRIIA or ActRIIB acts as type II receptor [PMID:11952836]. Either could mediate rescue.","affinity_potency":[],"species_and_systems":"Frog animal cap assays, with genetic interaction of lefty2 and ActRIIB in mouse [PMID:11952836]. Human pair is ortholog-projected.","localisation_and_range":"LEFTY1 is flagged secreted [flag]; the paper discusses diffusion.","caveats":"Abstract only; binding is inferred from rescue, not measured; LEFTY1 specifically is not distinguished from other Lefty proteins in the abstract.","key_references":[{"PMID":"11952836","why":"Lefty inhibition rescued by excess ActRIIA/B"}],"covers":["LR002876","LR006110"]},"LR001877":{"pair":"LGALS1 -> CD69","headline":"Galectin-1 binds CD69 directly and carbohydrate-dependently; function in Th17 regulation, from one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"SPR and anti-CD69 blocking showed a direct, specific, carbohydrate-dependent interaction; CD69 mediates the negative effect of galectin-1 on Th17 differentiation [PMID:24752896]. UniProt records the same negative role [DB:UniProt].","molecular_requirements":"CD69 extracellular domain fusion proteins were used; galectin-1 was identified on human dendritic cells by pulldown and mass spectrometry [PMID:24752896]. Other subunits not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human dendritic cells and recombinant proteins; functional assays used human and mouse T cells. The mouse pair is ortholog-inferred [PMID:24752896].","localisation_and_range":"Galectin-1 flagged secreted and also a receptor [flag]; present on immature dendritic cells per UniProt [DB:UniProt].","caveats":"Abstract-only read; no affinity values reported. The curator labelled direction antagonist, but the paper describes a negative regulatory effect on Th17 differentiation.","key_references":[{"PMID":"24752896","why":"SPR and blocking show galectin-1/CD69 binding; Th17 role"}],"covers":["LR001877","LR005219"]},"LR002885":{"pair":"LGALS3 -> ITGB4","headline":"Galectin-3 binds beta4 integrin via beta1,6GlcNAc-branched N-glycans, promoting adhesion and migration; abstract only.","interaction_type":"direct binding","direction_and_effect":"Binding of galectin-3 to beta4-integrin via beta1,6GlcNAc-branched N-glycans promoted beta4-integrin-mediated cancer cell adhesion and migration [PMID:29549127].","molecular_requirements":"Glycan dependent: beta1,6GlcNAc branching on beta4-integrin; bisecting GlcNAc suppressed migration and tumorigenesis [PMID:29549127].","affinity_potency":[],"species_and_systems":"Human cutaneous squamous cell carcinoma tissue and transformed keratinocytes [PMID:29549127]. Mouse pair ortholog-inferred.","localisation_and_range":"Galectin-3 flagged secreted; ITGB4 flagged receptor [flag].","caveats":"Abstract-only read; binding is N-glycan dependent, so depends on cell glycosylation; no affinity data.","key_references":[{"PMID":"29549127","why":"Galectin-3/beta4-integrin binding via beta1,6-branched N-glycans"}],"covers":["LR002885","LR006119"]},"LR002894":{"pair":"LGALS3BP -> SIGLEC6","headline":"Supported only by a BioGRID Reconstituted Complex record; our curators judged no paper to support this pair.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"BioGRID cites PMID 25320078 [DB:BioGRID]; species of the experiment is not reported in our evidence.","localisation_and_range":"Ligand carries a secreted flag [flag].","caveats":"The only support is a BioGRID record (Reconstituted Complex) [DB:BioGRID]. The curated judgment of the cited paper was 'different_entity', meaning it did not support this specific pair, so the record may be spurious (the paper's abstract names Siglec-9, -5 and -10).","key_references":[],"covers":["LR002894"]},"LR001895":{"pair":"LRFN5 -> LRFN5","headline":"LRFN5 (SALM5) appears to form homomeric complexes; one abstract-only co-IP paper.","interaction_type":"direct binding","direction_and_effect":"SALMs 1-3 co-immunoprecipitated with each other whereas SALMs 4 and 5 did not, suggesting SALM4 and SALM5 mainly form homomeric complexes [PMID:18227064]. The curator notes that in heterologous cells all five SALMs formed both heteromeric and homomeric complexes [PMID:18227064].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Co-immunoprecipitation in rat brain and heterologous cells [PMID:18227064]. The mouse pair is not ortholog-inferred; the human pair is.","localisation_and_range":"LRFN5 is flagged transmembrane [flag]; a homomeric adhesion-type complex.","caveats":"Abstract only. The homomeric inference is partly from a negative (no co-IP with SALMs 1-3). Direction and functional effect not reported in our evidence; self-pair is not a classical ligand-receptor.","key_references":[{"PMID":"18227064","why":"SALM co-IP showing homomeric complexes of SALM5"}],"covers":["LR001895","LR005237"]},"LR002939":{"pair":"LRRTM4 -> NRXN1","headline":"LRRTM4 binds neurexin-1 beta directly in cell-free assays, independent of splice site 4; one primary paper.","interaction_type":"direct binding","direction_and_effect":"Recombinant LRRTM4-Fc bound Nrx1beta with or without S4, and His-LRRTM4 ectodomain co-precipitated with Nrx1beta(-S4)-Fc in a cell-free assay; the authors conclude LRRTM4 has two binding partners, neurexin and glypican [PMID:23911103]. Signalling effect on neurexin is not reported in our evidence.","molecular_requirements":"Unlike LRRTM2, LRRTM4 binds neurexin independent of S4, so it can bind a broader array of neurexin isoforms [PMID:23911103]. The tested form was Nrx1beta; other NRXN1 isoforms are not reported.","affinity_potency":[],"species_and_systems":"Experiments used recombinant Fc-tagged ectodomains, 293T cells and rat brain homogenate [PMID:23911103]. Species of the recombinant proteins is not stated in the excerpts. UniProt lists LRRTM1-4 interaction for the neurexin entry, by similarity [DB:UniProt].","localisation_and_range":"Both partners flagged membrane-bound [flag], so contact-dependent (juxtacrine) signalling is expected.","caveats":"Only one confirming paper; the headline of that paper is glypican, and neurexin was complementary. The sentence about LPHN3 is a negative control, not evidence about this pair [PMID:23911103]. Mouse pair is projected from human.","key_references":[{"PMID":"23911103","why":"Direct LRRTM4-Nrx1beta binding, S4-independent"}],"covers":["LR002939","LR006164"]},"LR008852":{"pair":"LUM -> ITGB1","headline":"Supported only by a Reactome record of lumican binding integrin alpha2beta1; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Reactome lists LUM (lumican) binding integrin alpha2beta1 and a LUM:Integrin alpha2beta1 complex at the plasma membrane [DB:Reactome]. Direction and effect not reported.","molecular_requirements":"The Reactome complex is with the alpha2beta1 heterodimer, so ITGB1 is paired with ITGA2 [DB:Reactome].","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Lumican flagged secreted and ITGB1 not secreted [flag].","caveats":"One review_only and three abstract_insufficient judgements; no paper confirms binding. Treat as unverified.","key_references":[],"covers":["LR008852"]},"LR002948":{"pair":"MDGA1 -> APP","headline":"MDGA1 MAM domain binds APP directly with nanomolar affinity; this is supported by full-text excerpts.","interaction_type":"direct binding","direction_and_effect":"MDGA1 binds APP, and acts as antagonist of synaptic inhibition: MDGA1-mediated disinhibition requires the MAM domain and depends on presynaptic APP [PMID:35074912].","molecular_requirements":"The MDGA1 MAM domain binds the extension domain of APP; binding is extracellular Ca2+-dependent. MDGA1-Fc bound APP and APLP2 but not APLP1 cells, and MDGA2-Fc did not bind APP [PMID:35074912].","affinity_potency":[{"value":"Kd 84.74 nM","assay":"cell-surface binding, Scatchard analysis of MDGA1-Fc","system":"HEK293T cells expressing HA-APP","cite":"PMID:35074912"}],"species_and_systems":"HEK293T cells, purified recombinant proteins, mouse hippocampal neurons and brain membranes; labelled human/human in the curated row [PMID:35074912].","localisation_and_range":"MDGA1 is flagged not secreted; APP flagged secreted and transmembrane [flag]. Trans-synaptic contact (postsynaptic MDGA1, presynaptic APP) [PMID:35074912].","caveats":"Single paper. Overexpression of MDGA1 impaired novel object recognition in mice [PMID:35074912]. No database records.","key_references":[{"PMID":"35074912","why":"MDGA1 MAM-APP binding and trans-synaptic function"}],"covers":["LR002948","LR006173"]},"LR004469":{"pair":"MDK -> ITGA4","headline":"Midkine binds integrin alpha4beta1 and alpha6beta1 in mouse embryo and cell assays; evidence is for heterodimers, from one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Midkine binds these integrins; alpha4beta1 and alpha6beta1 are concluded to be functional midkine receptors. Anti-alpha4 antibody inhibited midkine-dependent migration of osteoblastic cells and anti-alpha6 inhibited neurite outgrowth of embryonic neurons; midkine raised paxillin tyrosine phosphorylation [PMID:15466886].","molecular_requirements":"Needs alpha4 with beta1: purified alpha4beta1 bound midkine [PMID:15466886].","affinity_potency":[],"species_and_systems":"Mouse embryo (13-day) extracts and cell assays; curated as human/human, but the experiments used mouse material [PMID:15466886]. Mouse pair is ortholog-inferred.","localisation_and_range":"MDK is flagged secreted, not transmembrane [flag]; paracrine growth factor.","caveats":"Single paper, abstract only. The integrins may cooperate with other midkine receptors (PTPRZ, LRP, ALK) [PMID:15466886]. UniProt records the interaction [DB:UniProt]. Alpha4 alone and alpha4beta7 not tested in our evidence.","key_references":[{"PMID":"15466886","why":"midkine-integrin binding and function"}],"covers":["LR001056","LR004469"]},"LR004478":{"pair":"MEPE -> PHEX","headline":"SPR shows MEPE binds soluble PHEX in a Zn-dependent way via the ASARM motif; one abstract-only paper plus IntAct.","interaction_type":"direct binding","direction_and_effect":"Soluble PHEX interacted specifically and dose-dependently with immobilised MEPE by SPR [PMID:15664000]. PHEX is described as binding without cleaving MEPE, protecting it from other proteases and limiting ASARM release [PMID:15664000].","molecular_requirements":"Interaction is Zn-dependent and localised to the MEPE C-terminal ASARM motif; phosphorylated ASARM peptide inhibited it (KD(app) 15 microM, 68% maximal inhibition) while control and RGD peptides did not [PMID:15664000].","affinity_potency":[{"value":"EC50 553 nM","assay":"SPR, secPHEX over immobilised MEPE","system":"recombinant soluble PHEX and MEPE","cite":"PMID:15664000"}],"species_and_systems":"Human proteins by SPR; in vivo ASARM peptide effects tested in mouse [PMID:15664000]. Mouse pair is ortholog-inferred.","localisation_and_range":"MEPE is flagged secreted [flag]; PHEX is a membrane endopeptidase, used as soluble form here [PMID:15664000].","caveats":"Single abstract-only paper; PHEX is an enzyme, so this is a binding partner rather than a signalling receptor. IntAct records the same SPR experiment [DB:IntAct].","key_references":[{"PMID":"15664000","why":"SPR of PHEX-MEPE, EC50 553 nM, ASARM motif dependence"}],"covers":["LR001065","LR004478"]},"LR008816":{"pair":"MIA -> CDH7","headline":"Cadherin-7 identified as a MIA-binding protein by SELDI-MS and co-IP in melanoma cells; abstract only.","interaction_type":"direct binding","direction_and_effect":"Cadherin-7 was identified as a new MIA-binding protein by surface-enhanced laser desorption/ionization-mass spectrometry and co-immunoprecipitation [PMID:19200257]. Altered cadherin-7 expression reduced melanoma cell migration [PMID:19200257].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human melanoma cells [PMID:19200257].","localisation_and_range":"MIA is flagged secreted; CDH7 flagged transmembrane [flag].","caveats":"Abstract only; the authors 'speculate' about MIA/cadherin-7 regulating cell adhesion. No affinity and no effect direction established. The curator's evidence sentence describes MIA in general, not CDH7 binding.","key_references":[{"PMID":"19200257","why":"MIA-cadherin-7 identified by SELDI-MS and co-IP"}],"covers":["LR008816"]},"LR006179":{"pair":"MIA -> ITGA4","headline":"MIA binds integrin alpha4 (as alpha4beta1) in melanoma cells by far-Western and co-IP and reduces integrin activity; abstract only.","interaction_type":"direct binding","direction_and_effect":"MIA interacts with integrin alpha4beta1 and alpha5beta1, down-regulating integrin activity and MAPK signalling, an antagonist-type effect [PMID:16517605].","molecular_requirements":"The paper identifies alpha4beta1 and alpha5beta1 heterodimers, so both subunits belong to the complex [PMID:16517605]. MIA also binds fibronectin [PMID:16517605].","affinity_potency":[],"species_and_systems":"Human malignant melanoma cells [PMID:16517605]. Mouse pair is ortholog-inferred.","localisation_and_range":"MIA is flagged secreted [flag].","caveats":"Abstract only; no affinity. Evidence is for the integrin heterodimers, not a single chain; the abstract does not say which assay showed which integrin.","key_references":[{"PMID":"16517605","why":"MIA binds alpha4beta1/alpha5beta1 integrins and reduces MAPK signalling"}],"covers":["LR002954","LR006179"]},"LR002957":{"pair":"MIF -> ACKR3","headline":"MIF is reported as a novel direct ligand of atypical receptor ACKR3 (CXCR7) in one paper, with binding and B-cell functional data.","interaction_type":"direct binding","direction_and_effect":"MIF promoted human CXCR7 internalization up to 40% and acted as an agonist. CXCR7 blockade suppressed MIF-mediated ERK and ZAP-70 activation and fully abrogated primary murine B-cell chemotaxis to MIF but not to CXCL12; Cxcr7-/- B cells lost the MIF transmigration response [PMID:26139098].","molecular_requirements":"CXCR7 forms complexes with CXCR4 and CD74 for MIF, in overexpression and in a human B-cell line, but internalization did not depend on CXCR4 [PMID:26139098]. Whether CXCR7 alone suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human CXCR7 internalization and receptor complexes in human cells (including a B-cell line); chemotaxis in primary murine B cells and Cxcr7-/- mice. The mouse pair is inferred from human evidence [PMID:26139098].","localisation_and_range":"MIF carries a secreted flag [flag]; acts as a soluble chemokine-like ligand [PMID:26139098].","caveats":"Binding evidence is competition binding, co-IP and sulfo-SBED crosslinking, described only from the abstract; no affinity reported. Single paper [PMID:26139098].","key_references":[{"PMID":"26139098","why":"MIF engages CXCR7: internalization, direct interaction, B-cell chemotaxis"}],"covers":["LR002957","LR006182"]},"LR004487":{"pair":"MMP7 -> CD151","headline":"proMMP-7 binds CD151 in human carcinoma cells; interaction maps to the propeptide and CD151 C-terminal loop; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"CD151 captures proMMP-7 at the cell membrane, and in situ zymography showed proteinase activity around CD151-expressing cells that anti-CD151 or anti-MMP-7 antibodies abolished [PMID:16200075]. This suggests CD151 supports pericellular proMMP-7 activation.","molecular_requirements":"Yeast two-hybrid deletion mapping placed the interaction between the propeptide of proMMP-7 and the COOH-terminal extracellular loop of CD151 [PMID:16200075].","affinity_potency":[],"species_and_systems":"Yeast two-hybrid, immunoprecipitation from CaR-1 human rectal carcinoma cells and CD151 stable transfectants, 125I-proMMP-7 binding, confocal colocalisation, and human lung adenocarcinoma tissue [PMID:16200075]. The mouse pair is ortholog-inferred.","localisation_and_range":"MMP7 is flagged as secreted [flag]; CD151 is a transmembrane protein, so this is a cell-surface docking interaction [PMID:16200075].","caveats":"CD151 is a tetraspanin-type partner that captures a protease rather than a classical signalling receptor. Abstract only. Mouse row inferred from human.","key_references":[{"PMID":"16200075","why":"Yeast two-hybrid, co-IP and membrane binding of proMMP-7 to CD151"}],"covers":["LR001075","LR004487"]},"LR006188":{"pair":"MMP9 -> IFNAR1","headline":"One abstract reports MMP-9 binding IFNAR1 and driving its degradation in HBV infection; no assay detail beyond the abstract.","interaction_type":"direct binding","direction_and_effect":"MMP-9 binds IFNAR1 and promotes IFNAR1 phosphorylation, ubiquitination, redistribution and degradation, interfering with IFNAR1 binding to IFN-\u03b1; this represses IFN/JAK/STAT signalling (antagonist-like) [PMID:28122987].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human PBMCs and macrophages from HBV-infected patients and healthy donors [PMID:28122987]. The mouse pair is ortholog-inferred.","localisation_and_range":"MMP9 is flagged as secreted [flag]. Where MMP-9 meets IFNAR1 is not reported in our evidence.","caveats":"Single paper, abstract only; the binding method is not stated in our evidence. The effect is on receptor degradation, not agonism or classical antagonism.","key_references":[{"PMID":"28122987","why":"MMP-9 binds IFNAR1 and promotes its degradation in HBV infection"}],"covers":["LR002963","LR006188"]},"LR002966":{"pair":"MPZ -> MPZ","headline":"Homophilic MPZ Ig-domain oligomerisation shown by structural methods; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Self-association between myelin membranes; the IgMPZ extracellular domain oligomerises and holds apposing myelin membranes together [PMID:37542466].","molecular_requirements":"NMR and SAXS confirm the tetramerisation interface; dimerisation uses a distinct interface not yet identified [PMID:37542466].","affinity_potency":[],"species_and_systems":"Solution NMR/SAXS of human-labelled IgMPZ; the mouse pair is ortholog-inferred. Prior crystal model was from rat protein [PMID:37542466].","localisation_and_range":"Membrane-bound adhesion protein (not secreted) [flag]; acts by contact across myelin membranes [PMID:37542466].","caveats":"Abstract only. Structural oligomerisation, not signalling; whether it acts as a ligand-receptor pair in the signalling sense is not reported in our evidence.","key_references":[{"PMID":"37542466","why":"Structural analysis of MPZ homomeric interfaces"}],"covers":["LR002966","LR006191"]},"LR006197":{"pair":"MYL12A -> CD69","headline":"Myl9/12 reported as functional CD69 ligands in mouse asthma models; abstract-only and not isoform-specific.","interaction_type":"functional only","direction_and_effect":"Myl9 and Myl12 are described as new functional ligands for CD69; blocking CD69-Myl9/12 interaction ameliorated allergic airway inflammation [PMID:28783682].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse ovalbumin- and house dust mite-induced asthma models, plus human nasal polyp tissue staining [PMID:28783682].","localisation_and_range":"Ligand is flagged secreted [flag]; platelet-derived Myl9/12 localised to blood vessel luminal surfaces and net-like intravascular structures [PMID:28783682].","caveats":"Abstract only; the abstract does not give binding affinity or a binding assay. Evidence is functional (antibody blockade, in vivo) [PMID:28783682]. Myl9/12 are reported jointly; the abstract does not separate Myl12a from Myl12b.","key_references":[{"PMID":"28783682","why":"Myl9/12 identified as functional CD69 ligands; blockade reduces airway inflammation"}],"covers":["LR002972","LR006197"]},"LR004496":{"pair":"MYOC -> FZD4","headline":"Myocilin-AP fusion bound FZD4 in a browser-read Results sentence; modulates Wnt signalling.","interaction_type":"direct binding","direction_and_effect":"Myocilin-AP bound Fzd1, Fzd3, Fzd4, Fzd7, Fzd10 and sFRPs; myocilin modulated Wnt signalling and its stress fiber activity was blocked by sFRP1/sFRP3 and beta-catenin siRNA [PMID:19188438]. Effect of myocilin on the receptor (agonist versus modulator) is not clear from our evidence.","molecular_requirements":"Binding was to cysteine-rich domains of Frizzled receptors; sFRPs also bound, so Wnt pathway modulators are involved [PMID:19188438]. Co-receptor requirements not reported in our evidence.","affinity_potency":[],"species_and_systems":"Myocilin expressed in HEK293 cells, tested on human trabecular meshwork and NIH 3T3 cells; construct species for the binding sentence not stated. Mouse pair is ortholog-inferred [PMID:19188438].","localisation_and_range":"Myocilin is flagged secreted [flag]; acts as a secreted modulator in conditioned medium [PMID:19188438].","caveats":"Binding sentence was browser-read and unverified (spot-check pending); dossier abstract only. Binding is AP-fusion to receptor CRDs, not full receptor, and shared across several Fzd paralogs, so paralog specificity is weak. Two further judged rows were classed as a different entity.","key_references":[{"PMID":"19188438","why":"Myocilin-AP binding to Fzd CRDs and Wnt signalling modulation"}],"covers":["LR001085","LR004496"]},"LR002984":{"pair":"NECTIN3 -> NECTIN1","headline":"Direct trans-interaction with measured 1 nM Kd in human nectins; adhesion pair rather than classic signalling.","interaction_type":"direct binding","direction_and_effect":"Nectin1 and nectin3 trans-interact heterophilically; the interaction is mediated by V-to-V domain contacts, and nectin3 and HSV-1 glycoprotein D compete for the shared site [PMID:12011057]. Direction and signalling effect are not reported in our evidence.","molecular_requirements":"The nectin1 V domain is the major region for trans-heterointeraction with nectin3 [PMID:11544254]; C domains raise affinity [PMID:12011057].","affinity_potency":[{"value":"KD 1 nM","assay":"nectin1/nectin3 trans-interaction affinity","system":"recombinant human nectin ectodomains","cite":"PMID:12011057"}],"species_and_systems":"Human proteins per curator fields; mouse pair is ortholog-projected.","localisation_and_range":"Membrane-bound trans adhesion (cell junction) [DB:Reactome]; nectin1 carries a secreted flag [flag].","caveats":"Abstract only. PMID 11544254 reports it as confirmation of earlier work rather than new data. Nectin1 homophilic KD is 1 microm [PMID:12011057].","key_references":[{"PMID":"12011057","why":"KD of nectin1/nectin3 is 1 nM"},{"PMID":"11544254","why":"Confirms nectin3/nectin1 trans-heterointeraction"}],"covers":["LR002984","LR006209"]},"LR002993":{"pair":"NLGN3 -> PTPRD","headline":"Experimentally shown non-canonical NLGN3-PTPdelta interaction (splice-dependent) that competes with neurexin binding; mouse-based single paper.","interaction_type":"direct binding","direction_and_effect":"NLGN3 binds PTPdelta splice variants lacking the meB peptide in cell surface binding, cell aggregation and coimmunoprecipitation from mouse brain; PTPdelta-meB(-) beads need NLGN3 to induce excitatory and inhibitory postsynaptic differentiation in neurons [PMID:33758193].","molecular_requirements":"Only PTPdelta variants lacking meB bind; meB(+) variants do not. LAR and PTPsigma variants lacking meB interact much more weakly. Among murine NLGN1-4, NLGN3 alone showed significant binding [PMID:33758193].","affinity_potency":[],"species_and_systems":"Mouse cortical/striatal neurons, mouse brain co-IP and HEK293T cells; curator lists human; the mouse pair is not ortholog-inferred [PMID:33758193].","localisation_and_range":"Both partners are transmembrane [flag]; HEK293T aggregation indicates trans, contact-mediated binding [PMID:33758193].","caveats":"PTPdelta and NRXN1beta compete for NLGN3 binding in a competitive binding assay [PMID:33758193]. ITC was performed but values are not in our evidence. Abstract plus excerpts only.","key_references":[{"PMID":"33758193","why":"NLGN3-PTPdelta binding, competition with NRXN1beta"}],"covers":["LR002993","LR006217"]},"LR008267":{"pair":"NODAL -> ACVR1B:ACVR2A","headline":"Complex row without Cripto: one 2025 abstract places Nodal on the type II receptor and ALK4, but stresses Cripto-1 is required.","interaction_type":"functional only","direction_and_effect":"Nodal bound to the type II receptor uses Cripto-1 to recruit ALK4, forming a ternary complex for SMAD2/3 activation [PMID:39840816].","molecular_requirements":"ALK4 recruitment requires Cripto-1 [PMID:39840816]; this row lacks the co-receptor, so it may under-describe the functional complex. The abstract says 'type II receptor' and does not name ACVR2A.","affinity_potency":[],"species_and_systems":"AlphaFold3 modelling, SPR protein interaction analysis and functional studies in NTERA-2 cells; species not stated in the abstract [PMID:39840816].","localisation_and_range":"Nodal flagged secreted [flag]; Cripto-1 is called a co-receptor [PMID:39840816].","caveats":"Single paper read as abstract only; one further paper judged review-only. BioGRID lists NODAL-ACVR2A as a reconstituted complex [DB:BioGRID].","key_references":[{"PMID":"39840816","why":"Mechanism: Cripto-1 recruits ALK4 to Nodal-type II receptor"}],"covers":["LR008267"]},"LR007367":{"pair":"NODAL -> ACVR1B:ACVR2A:TDGF1","headline":"Functional support for the classical Nodal complex with Cripto (TDGF1), from a zebrafish genetics paper and a colon cancer paper.","interaction_type":"functional only","direction_and_effect":"Papers describe Nodal signalling through type I/II Activin receptors with TDGF1; in zebrafish Acvr1b-a and Acvr1b-b are major redundant mediators of Nodal signalling [PMID:36149406]. TDGF1 co-activates a Thr88-dependent Nodal/Smad2 cascade in colon cancer cells [PMID:42439618].","molecular_requirements":"Type I (Acvr1b), type II (Acvr2) and co-receptor Tdgf1 are the classical complex [PMID:36149406]; Acvr2 homologs act partly redundantly [PMID:36149406].","affinity_potency":[],"species_and_systems":"Zebrafish embryos with mutants, morpholinos and CRISPR knockouts [PMID:36149406]; colon cancer cells and in vivo tumour model [PMID:42439618].","localisation_and_range":"Nodal flagged secreted [flag]; the zebrafish paper reports receptor binding can influence Nodal distribution [PMID:36149406].","caveats":"Both papers read as abstract only (one with excerpts). The classical-model sentence in PMID:36149406 is background, not tested directly here; PMID:42439618 does not name ACVR1B/ACVR2A and studies TDGF1 rather than binding.","key_references":[{"PMID":"36149406","why":"Zebrafish genetics of Acvr1b/Acvr2 receptors in Nodal signalling"},{"PMID":"42439618","why":"TDGF1 and Nodal/Smad2 signalling in colon cancer"}],"covers":["LR007367"]},"LR008429":{"pair":"NOTCH3 -> JAG1","headline":"Jagged1 directly binds soluble Notch3 in a Ca2+-dependent solid-phase assay; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Each DSL protein directly bound immobilised soluble Notch3, with different affinities [PMID:11006133]. Jagged1 is the ligand; the row is stored reversed.","molecular_requirements":"Ca2+-dependent [PMID:11006133].","affinity_potency":[],"species_and_systems":"Human; solid-phase binding with soluble Notch3 [PMID:11006133]. Abstract only.","localisation_and_range":"JAG1 flagged transmembrane [flag]; contact-dependent.","caveats":"Affinities differ but are not quantified. BioGRID, IntAct and Reactome records exist [DB:BioGRID, DB:Reactome R-HSA-157132].","key_references":[{"PMID":"11006133","why":"Solid-phase binding of Jagged1 to Notch3"}],"covers":["LR008429"]},"LR008609":{"pair":"NOTCH4 -> JAG1","headline":"Notch4 peptibody binds JAG1 and DLL4 by SPR and co-IP; one paper, five abstracts insufficient.","interaction_type":"direct binding","direction_and_effect":"Notch1 and Notch4 peptibodies showed strong but distinct binding to DLL4 and JAG1 in SPR with co-IP, and interfered with Notch signalling in endothelial cells [PMID:36376768].","molecular_requirements":"The peptibodies use EGF-like repeats 10-14 of Notch4 or Notch1 as the binding core [PMID:36376768].","affinity_potency":[],"species_and_systems":"Engineered Fc peptibodies; endothelial cells, 3D sprouting and neonatal mouse retina for Notch1 peptibody; species of SPR proteins not reported [PMID:36376768].","localisation_and_range":"JAG1 is the membrane ligand; the peptibody is a secreted decoy [PMID:36376768].","caveats":"The binding is for a truncated Notch4 fragment, not the native receptor, and the abstract does not give affinity. Five other abstracts were insufficient. Reactome lists JAG1:NOTCH4 [DB:Reactome R-HSA-9604245].","key_references":[{"PMID":"36376768","why":"SPR/co-IP of Notch4 peptibody with JAG1 and DLL4"}],"covers":["LR008609"]},"LR004559":{"pair":"NRG2 -> ERBB4","headline":"NRG2 activates ERBB4 (and ERBB3); supported by two 1997 abstract-level papers plus BioGRID and Reactome records.","interaction_type":"direct binding","direction_and_effect":"NRG2 acts as an agonist: its EGF-like domain binds ErbB3 and ErbB4 and NRG2 stimulates ErbB tyrosine phosphorylation [PMID:9168115]. Recombinant NRG2-beta activates only cell lines with ErbB3 and/or ErbB4 [PMID:9168114].","molecular_requirements":"ErbB2, ErbB3 and ErbB4 were all phosphorylated in cells expressing all three; with defined combinations only ErbB3 and/or ErbB4 lines responded, so ERBB4 alone as a single chain is not separately resolved in the abstracts [PMID:9168114]. Reactome lists NRG2 complexes with ERBB4 homodimers [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human ligand and receptor in both papers (cell lines); adult rat tissues used for expression only [PMID:9168114]. The mouse pair is projected from human evidence.","localisation_and_range":"Annotated as secreted and transmembrane, so likely both a membrane-bound and a released form [flag]; not tested in the papers.","caveats":"Both papers were read as abstracts only. NRG2 elicits different ErbB phosphorylation profiles from NRG-1 [PMID:9168115]. No affinity reported. GtoPdb record has no action or affinity [DB:GtoPdb].","key_references":[{"PMID":"9168115","why":"NRG2 EGF-like domain binds ErbB3 and ErbB4"},{"PMID":"9168114","why":"NRG2-beta activates only ErbB3/ErbB4-containing cells"}],"covers":["LR001150","LR004559"]},"LR004568":{"pair":"NTF3 -> NTRK3","headline":"NT-3 is the cognate TrkC ligand, supported by binding, structural mapping and signalling papers, though all read as abstracts.","interaction_type":"direct binding","direction_and_effect":"gp145trkC is a functional receptor for NT-3 and does not bind NGF or BDNF [PMID:1653651]. NT-3 signalling through TrkC promotes apoptosis in medulloblastoma cells [PMID:9973222]. Curator labels it agonist [PMID:9488719].","molecular_requirements":"TrkC primarily uses loop EF for binding [PMID:9488719]. Reactome lists NTF3:NTRK3 homodimer complexes [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human receptor models and mutational analysis [PMID:9488719]; neuronal cells expressing defined Trk receptors [PMID:7679912]; medulloblastoma cells and nude mouse xenografts [PMID:9973222]. Mouse pair is ortholog-inferred.","localisation_and_range":"NTF3 flagged secreted, NTRK3 transmembrane [flag].","caveats":"All papers read as abstracts only; one review-only row is not shown. GtoPdb record has no action or affinity [DB:GtoPdb].","key_references":[{"PMID":"1653651","why":"trkC identified as NT-3 receptor"},{"PMID":"9488719","why":"Loop EF of TrkC as NT-3 binding determinant"},{"PMID":"7679912","why":"NT-3 preferred for TrkC in neuronal and non-neuronal cells"}],"covers":["LR001159","LR004568"]},"LR004577":{"pair":"NTN1 -> UNC5D","headline":"Netrin-1 to UNC5D rests on a general family statement; no UNC5D-specific netrin evidence in our dossier.","interaction_type":"functional only","direction_and_effect":"The cited paper states in background that netrin-1 induces repulsive axon guidance by binding the Unc5 receptor family (Unc5A-Unc5D) [PMID:21673655]. Its own finding is that Unc5D binds FLRT2 [PMID:21673655].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Background statement in a paper using mouse neocortex development; Reactome lists UNC-5 binding netrin-1 in general [DB:Reactome]. The human pair is ortholog-inferred.","localisation_and_range":"Netrin-1 is secreted and UNC5D is transmembrane [flag].","caveats":"The paper does not test netrin-1 with UNC5D and notes Unc5 functions independent of netrin-1 [PMID:21673655]. Abstract only. Treat this as weakly supported.","key_references":[{"PMID":"21673655","why":"Background statement on netrin-1/Unc5 family; main finding concerns FLRT2"}],"covers":["LR001168","LR004577"]},"LR004586":{"pair":"NXPH1 -> NRXN2","headline":"Neurexophilin-1 binds the LNS2 domain of neurexin-2 with nanomolar affinity, shown by a 2019 full-text study and earlier abstract data.","interaction_type":"direct binding","direction_and_effect":"Nxph1 binds the LNS2SS2- domains of Nrxn1, Nrxn2 and Nrxn3 with similar nanomolar affinities [PMID:31566781]. Neurexophilins 1 and 3 bind the second LNS domain in all three alpha-neurexins [PMID:9856994].","molecular_requirements":"LNS2 domain is required; all splice variants bind in the 1998 study [PMID:9856994]. The I401Q mutation in Nrxn2 LNS2SS2- decreases Nxph1 affinity from the nanomolar to the micromolar range [PMID:31566781].","affinity_potency":[],"species_and_systems":"Mouse Nrxn2 was assessed in the 2019 study [PMID:31566781]; recombinant mouse proteins in [PMID:9856994]. Both species pairs are ortholog-inferred.","localisation_and_range":"Secreted ligand [flag] and membrane neurexin [flag].","caveats":"Exact affinity values sit in a table not shown in our excerpts. The 1998 paper was read as an abstract only. The 2019 evidence sentence is a section-lead sentence rather than a result.","key_references":[{"PMID":"31566781","why":"Structures of Nxph1 with Nrxn LNS2 and isoform specificity"},{"PMID":"9856994","why":"NXPH1 and NXPH3 bind LNS2 of all three alpha-neurexins"}],"covers":["LR001177","LR004586"]},"LR006269":{"pair":"OMG -> PTPRF","headline":"OMG binds PTPRF by SPR in the micromolar range; the curated record is labelled as a screen hit, which the table contradicts.","interaction_type":"direct binding","direction_and_effect":"OMG is the ligand and PTPRF the receptor. SPR showed micromolar-range binding of OMG to all three R2A RPTPs including PTPRF [PMID:36178190]. PTPRF was also described as enriched in the OMG CRISPRa screen [PMID:36178190]. Effect (agonist or antagonist) is not reported in our evidence.","molecular_requirements":"PTPRF ectodomain alone; no co-receptor requirement reported in our evidence.","affinity_potency":[{"value":"micromolar range","assay":"SPR, OMG vs RPTP ectodomains","system":"recombinant human proteins","cite":"PMID:36178190"}],"species_and_systems":"Human OMG and PTPRF recombinant ectodomains by SPR; pooled CRISPRa screen in cells [PMID:36178190]. Mouse pair is projected from human.","localisation_and_range":"OMG is flagged non-secreted [flag]; the paper treats it as a secreted ligand used as a multimerised bait, so range (contact versus diffusible) is not settled in our evidence. PTPRF is a flagged transmembrane receptor [flag].","caveats":"Single paper. The paper's Table 1 lists the OMG-PTPRF interaction with source PHA (homology-based) and assay SPR, while the text says PTPRF was enriched in the screen; the two are not reconciled in our excerpts [PMID:36178190]. No exact Kd reported. No database records.","key_references":[{"PMID":"36178190","why":"CRISPRa screen plus SPR for OMG-RPTP binding"}],"covers":["LR003045","LR006269"]},"LR004595":{"pair":"OSM -> IL6ST","headline":"OSM engages gp130 (IL6ST) as the shared signalling chain; supported by structure, functional papers and databases, but not alone.","interaction_type":"direct binding","direction_and_effect":"OSM binds gp130 through its site 2 epitope centred on Gly120 [PMID:10997905], and in rat hepatoma cells human and mouse OSM engaged gp130 together with their OSMRbeta subunits [PMID:10854424]. Both LIF and OSM activate gp130.LIFR, whereas gp130.OSMRbeta is activated by OSM only [PMID:8999038]. GtoPdb lists OSM as an agonist of IL6ST [DB:GtoPdb].","molecular_requirements":"gp130 works with a second chain, either LIFR or OSMR [PMID:8999038][PMID:10854424]. UniProt says low-affinity binding to IL6ST induces heterodimerisation with LIFR or OSMR [DB:UniProt]. Our evidence does not show gp130 alone signalling for OSM.","affinity_potency":[],"species_and_systems":"Human OSM structure and mutagenesis [PMID:10997905]; human/mouse OSM in rat hepatoma cells [PMID:10854424]; human cell systems [PMID:8999038][PMID:16051226]. Mouse pair is projected from human.","localisation_and_range":"OSM is a flagged secreted, non-transmembrane ligand; IL6ST is a flagged transmembrane receptor [flag]. Paracrine/endocrine range follows from the secreted flag.","caveats":"All four papers shown were read as abstracts only. The structure is of OSM alone, not a complex [PMID:10997905]. The IL6ST entity name in the dossier is 'Interleukin-27 receptor', which looks like a label mismatch for gp130. PDB 8V29 and 8V2A are listed with chains of P13725 and P40189 [DB:PDB 8V29]. Reactome and IntAct records exist [DB:Reactome].","key_references":[{"PMID":"10997905","why":"Crystal structure; gp130 site 2 epitope"},{"PMID":"8999038","why":"OSM acts via gp130-LIFR and gp130-OSMRbeta"},{"PMID":"10854424","why":"Human and mouse OSM engage gp130 with OSMRbeta"}],"covers":["LR001186","LR004595"]},"LR006278":{"pair":"Pcdhb17 -> Pcdhb17","headline":"Mouse Pcdhb17 engages homophilic trans interactions in K562 aggregation assays; single full-text paper.","interaction_type":"direct binding","direction_and_effect":"Pcdh-\u03b217 engages in homophilic interactions in cell-aggregation assays and is detected at the cell surface [PMID:25171406]. Self-binding, no separate ligand and receptor.","molecular_requirements":"Clustered protocadherin trans interaction is homophilic and isoform-specific; cis multimers with other isoforms may form the actual cell-surface unit, so one isoform alone may not reproduce the interface.","affinity_potency":[],"species_and_systems":"Mouse isoform in K562 cells [PMID:25171406].","localisation_and_range":"Membrane-bound cell-adhesion molecule; trans homophilic contact between cells (juxtacrine), not secreted [flag].","caveats":"Isoforms 91-97% identical in EC2-EC3 do not cross-react, so paralogs cannot substitute [PMID:25171406]. Mouse only; no human pair.","key_references":[{"PMID":"25171406","why":"homophilic aggregation of beta17 and others"}],"covers":["LR006278"]},"LR006773":{"pair":"Pcdhb8 -> Pcdhb8","headline":"Mouse Pcdhb8 binds itself homophilically in trans with strict isoform specificity; two full-text papers.","interaction_type":"direct binding","direction_and_effect":"\u03b28 engages homophilic trans interactions and does not cross-react with \u03b26 [PMID:25171406]; a \u03b26 mutant with five \u03b28 residues binds \u03b28 strongly but not \u03b26 by SPR [PMID:35253643].","molecular_requirements":"Clustered protocadherin trans interaction is homophilic and isoform-specific; cis multimers with other isoforms may form the actual cell-surface unit, so one isoform alone may not reproduce the interface.","affinity_potency":[],"species_and_systems":"Mouse proteins: K562 aggregation and SPR of EC1-4 fragments [PMID:25171406] [PMID:35253643].","localisation_and_range":"Membrane-bound cell-adhesion molecule; trans homophilic contact between cells (juxtacrine), not secreted [flag].","caveats":"Isoforms 91-97% identical in EC2-EC3 do not cross-react, so paralogs cannot substitute [PMID:25171406]. Mouse only; no human pair.","key_references":[{"PMID":"25171406","why":"homophilic specificity"},{"PMID":"35253643","why":"SPR with beta6 residue swaps"}],"covers":["LR006773"]},"LR005279":{"pair":"PLA2G2A -> ITGB3","headline":"sPLA2-IIA binds and activates alphavbeta3; beta3 is one chain of the heterodimer.","interaction_type":"direct binding","direction_and_effect":"sPLA2-IIA bound integrin alphavbeta3 with high affinity [PMID:18635536]. It directly activated purified soluble and cell-surface alphavbeta3 and enhanced ligand binding in ELISA and flow cytometry [PMID:25398877]. BioGRID lists a reconstituted complex [DB:BioGRID 1528284]. Agonist.","molecular_requirements":"alphavbeta3 heterodimer; Arg-74 and Arg-100 of sPLA2-IIA are needed [PMID:18635536]. Beta3 alone: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human ligand and human receptor; integrin binding and cell assays [PMID:18635536][PMID:25398877]. Mouse pair is ortholog-inferred.","localisation_and_range":"Secreted, from the PLA2G2A secreted flag [flag].","caveats":"The 18635536 evidence sentence is background text. Affinity (KD 2 x 10(-7) M) is for alphavbeta3 in the same paper [PMID:18635536]. 25398877 full-text read is marked unverified.","key_references":[{"PMID":"18635536","why":"alphavbeta3 binding and mutagenesis"},{"PMID":"25398877","why":"Direct activation of alphavbeta3 via site 2"}],"covers":["LR001942","LR005279"]},"LR007385":{"pair":"PLAUR -> ITGAV:ITGB3","headline":"Direct cell-based binding of soluble uPAR to alphaVbeta3 (ITGAV:ITGB3) integrin in one paper; no affinity.","interaction_type":"direct binding","direction_and_effect":"Soluble uPAR (suPAR D2D3) bound integrin-transfected CHO cells in a cation-dependent manner, blocked by anti-integrin and anti-uPAR antibodies [PMID:11053440]. It acts as a ligand, signalling consequence not reported in our evidence.","molecular_requirements":"Binding shown to the alpha-beta heterodimer on cells; subunit contribution not resolved [PMID:11053440]. ","affinity_potency":[],"species_and_systems":"Human uPAR on hamster (CHO) cells [PMID:11053440].","localisation_and_range":"uPAR is described as a GPI-anchored protein lacking a transmembrane structure that acts as an integrin ligand, in trans between apposed cells, as well as an associated protein in cis [PMID:11053440]. Cell-cell contact range.","caveats":"Single paper (full text); no affinity. The paper reports heterodimers; this complex row is classed Receptor-Receptor. Three further papers were judged abstract-insufficient.","key_references":[{"PMID":"11053440","why":"uPAR binds integrins alpha4beta1, alpha6beta1, alpha9beta1, alphavbeta3 on CHO cells"}],"covers":["LR007385"]},"LR004649":{"pair":"PPBP -> CXCR2","headline":"NAP-2 (PPBP) is a high-affinity, potent agonist of CXCR2 shown by binding and calcium-flux assays.","interaction_type":"direct binding","direction_and_effect":"CXCR2-transfected Jurkat cells bound all three chemokines with high affinity [PMID:8137938]. CXCR2 binds NAP-2 with equally high affinity as IL-8 [PMID:8195702]. In HEK293 calcium flux, NAP-2 acts as an agonist at IL8RB (CXCR2) with EC50 7 nM [PMID:8702798]. GtoPdb records a full agonist [DB:GtoPdb]. A CXCR1/2 inhibitor blocks CXCL7-driven ccRCC growth in nude mice [PMID:24335961].","molecular_requirements":"Not reported in our evidence beyond receptor chain CXCR2 alone being sufficient in transfected cells.","affinity_potency":[{"value":"EC50 7 nM","assay":"calcium flux","system":"HEK293 cells with IL8RB (CXCR2)","cite":"PMID:8702798"},{"value":"pIC50 6.3-9.3","assay":"GtoPdb affinity range","system":"not specified","cite":"PMID:8702798"}],"species_and_systems":"Human receptors in transfected Jurkat, COS-1 and HEK293 cells [PMID:8137938][PMID:8195702][PMID:8702798]; nude mice [PMID:24335961]. Mouse pair is ortholog-inferred. All read as abstracts.","localisation_and_range":"PPBP flagged secreted [flag]; chemoattractant (paracrine) action per assays [PMID:8702798].","caveats":"The in vivo paper uses a dual CXCR1/CXCR2 inhibitor and cannot attribute the effect to CXCR2 alone [PMID:24335961]. KD ~2 nM comes from a curator note rather than the abstract text shown [PMID:8195702]. The dossier does not give mouse experiments.","key_references":[{"PMID":"8702798","why":"CXCR2 agonist potency and competition binding for NAP-2"},{"PMID":"8195702","why":"High-affinity NAP-2 binding at CXCR2"},{"PMID":"8137938","why":"High-affinity binding in CXCR2 Jurkat transfectants"}],"covers":["LR001248","LR004649"]},"LR004658":{"pair":"PROK1 -> PROKR2","headline":"Well supported agonist-receptor pair: PROK1 binds and activates PROKR2 in transfected cells; evidence from abstracts only.","interaction_type":"direct binding","direction_and_effect":"PROK1 and PROK2 induced nanomolar calcium responses in CHO cells expressing PK-R2 and bound with high affinity [PMID:12054613]. Recombinant prokineticins activated both receptors, with calcium, phosphoinositide and MAPK signalling [PMID:11886876]. GtoPdb lists full agonist [DB:GtoPdb]. PK1 also stimulated Ca2+ responses in PKR2-expressing cells [PMID:15772293].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human protein experiments in CHO and other heterologous systems; bovine adrenal capillary endothelial cells showed MAPK phosphorylation and DNA synthesis [PMID:12054613]. Mouse pair is ortholog-inferred.","localisation_and_range":"Both PROK1 and the receptor are annotated secreted and transmembrane respectively [flag], so paracrine signalling onto membrane receptors.","caveats":"Abstract-only reading for all papers. Selectivity between PKR1 and PKR2 is stated but not quantified [PMID:12054613]. GtoPdb gives pIC50 ranges only [DB:GtoPdb].","key_references":[{"PMID":"12054613","why":"Deorphanisation of PK-R2 by EG-VEGF/prokineticins."},{"PMID":"11886876","why":"Cloning and activation of both receptors by nanomolar prokineticins."}],"covers":["LR001258","LR004658"]},"LR008447":{"pair":"PSEN1 -> NCSTN","headline":"Presenilin-1 and nicastrin are subunits of the same gamma-secretase complex, not a ligand-receptor pair.","interaction_type":"database-asserted only","direction_and_effect":"Not a signalling direction. Databases record physical association: UniProt describes a complex of presenilin homodimer, NCSTN, APH1 and PEN2 [DB:UniProt], and structures exist [DB:PDB 4UIS].","molecular_requirements":"Both are members of the multi-subunit gamma-secretase [DB:UniProt]; Reactome lists a PS1:NCSTN complex at the plasma membrane [DB:Reactome].","affinity_potency":[],"species_and_systems":"Co-IP, co-fractionation and cryo-EM records in BioGRID, IntAct and PDB; human proteins [DB:BioGRID].","localisation_and_range":"Membrane protein complex; no secretion or range data in our evidence.","caveats":"No papers passed curation (judged different_entity or unresolvable). This is a subunit-subunit interaction, not ligand to receptor.","key_references":[],"covers":["LR008447"]},"LR004667":{"pair":"PSPN -> GFRA4","headline":"GFRalpha4 is the ligand-binding subunit for persephin; supported by two binding papers and databases.","interaction_type":"direct binding","direction_and_effect":"Persephin binds GFRalpha4, and with RET promotes Ret autophosphorylation and neuronal survival, acting as an agonist [PMID:11116144][PMID:9740802]. Persephin binds efficiently only to GFR alpha-4 [PMID:9740802].","molecular_requirements":"GFRalpha4 is the ligand-binding subunit and RET is also required for signalling [PMID:9740802][PMID:11116144]. UniProt says PSPN acts via its coreceptor GFRA4 [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human proteins in GFRA4-transfected cells with endogenous Ret [PMID:11116144]; mouse persephin binding chicken GFR alpha-4 and mouse sympathetic neurons by microinjection [PMID:9740802].","localisation_and_range":"Ligand flagged secreted [flag]; GFRalpha4 is GPI-linked [PMID:11116144].","caveats":"Both papers read as abstracts, one with full-text excerpts. The 1998 study notes persephin's lower affinity for GFR alpha-4 may reflect testing mouse persephin on chicken receptor [PMID:9740802]. Alone, GFRA4 is insufficient for signalling.","key_references":[{"PMID":"9740802","why":"Persephin binds GFR alpha-4 and needs Ret for survival response."},{"PMID":"11116144","why":"Human GFRalpha4 characterised as PSPN ligand-binding subunit."}],"covers":["LR001267","LR004667"]},"LR006368":{"pair":"PTN -> ITGB2","headline":"PTN directly binds the alphaM I domain of Mac-1 (alphaMbeta2); evidence concerns the ITGAM chain, so ITGB2 support is by complex.","interaction_type":"direct binding","direction_and_effect":"PTN engages Mac-1 (CD11b-CD18) as a receptor for macrophage adhesion and migration, with Erk1/2 phosphorylation [PMID:28939773].","molecular_requirements":"Direct binding was shown with the alphaMI domain, which is on the alphaM chain, not beta2 [PMID:28939773]. Mac-1 cooperates with cell-surface proteoglycans, since anti-Mac-1 mAb and heparin were both required to block adhesion [PMID:28939773].","affinity_potency":[],"species_and_systems":"Human; HEK293 cells expressing Mac-1 and recombinant proteins [PMID:28939773]. Mouse pair is ortholog-inferred.","localisation_and_range":"PTN is flagged as secreted [flag], so signalling would be paracrine.","caveats":"Abstract only; no affinity. The experimental contact is on ITGAM, so ITGB2 alone is not shown to bind PTN; CCC tools scoring ITGB2 should treat it as a subunit of Mac-1. No database records for this exact chain.","key_references":[{"PMID":"28939773","why":"PTN-Mac-1 adhesion and alphaMI binding"}],"covers":["LR003147","LR006368"]},"LR004676":{"pair":"PTN -> PTPRB","headline":"No supporting evidence in our dossier beyond a BioGRID co-localisation record; papers were rejected or insufficient.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence; human and mouse (ortholog-inferred) pair.","localisation_and_range":"PTN is flagged as secreted [flag], so signalling would be paracrine.","caveats":"Judged rows were different_entity (3), abstract_insufficient (2) and review_only (1); BioGRID holds only a co-localisation record [DB:BioGRID], which is not binding evidence.","key_references":[],"covers":["LR001276","LR004676"]},"LR006377":{"pair":"PTPRD -> IL1RAP","headline":"Supported by trans-synaptic binding data and a crystal structure with PTPdelta; splice-variant dependent.","interaction_type":"direct binding","direction_and_effect":"PTPdelta binds IL-1RAcP across the synapse and bidirectionally induces pre- and postsynaptic differentiation [PMID:25908590]. IL-1RAcP interacted with PTPdelta through its extracellular domain in cultured cortical neurons [PMID:22357843].","molecular_requirements":"Specificity set by PTPdelta splice inserts; IL-1RAcP interacts via its Ig1 domain and the Ig3 domain does not contact PTPdelta in the complex [PMID:25908590]. Both IL-1RAcP isoforms differ in C-terminus [PMID:22357843].","affinity_potency":[],"species_and_systems":"Crystal structures and neuron assays [PMID:25908590]; cultured cortical neurons, species not specified [PMID:22357843].","localisation_and_range":"Both flagged transmembrane [flag]; trans-synaptic, contact-dependent.","caveats":"Abstract-level curation; no affinity for IL-1RAcP in our evidence. Reactome and BioGRID records support the pair [DB:Reactome, DB:BioGRID].","key_references":[{"PMID":"25908590","why":"crystal structure of PTPdelta with IL-1RAcP and IL1RAPL1"},{"PMID":"22357843","why":"IL-1RAcP interacts with PTPdelta ectodomain"}],"covers":["LR003156","LR006377"]},"LR008456":{"pair":"PTPRF -> INSR","headline":"Supported only by UniProt interaction statements; no judged paper confirms it and the pair is classed receptor-receptor.","interaction_type":"database-asserted only","direction_and_effect":"UniProt subunit lines for INSR and PTPRF say each interacts with the other [DB:UniProt]. The curated record marks the effect as Stimulatory, but our evidence does not describe the direction or effect.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported; the UniProt lines carry PMIDs 10615944 and 8995282 but no experiment details are in the dossier [DB:UniProt].","localisation_and_range":"Both flagged receptor and transmembrane [flag]; PTPRF is not a secreted ligand, so this is a membrane-membrane, contact or in-cis relationship at most.","caveats":"No paper was confirmed: of the judged rows, 2 are review_only and 9 are different_entity. Support is a database assertion alone. The 'Stimulatory' label is not supported by anything shown here. PTPRF is a phosphatase and INSR is its possible substrate, but that is not stated in the dossier.","key_references":[],"covers":["LR008456"]},"LR006386":{"pair":"PTPRG -> CNTN4","headline":"PTPRG carbonic-anhydrase-like domain binds CNTN4 Ig repeats 2-3 by crystallography; one primary paper.","interaction_type":"direct binding","direction_and_effect":"PTPRG interacts with CNTN3, 4, 5 and 6, whereas PTPRZ binds only CNTN1 [PMID:20133774]. Effect direction is not reported in our evidence.","molecular_requirements":"Crystal structures show the carbonic anhydrase-like domains of PTPRZ/PTPRG interact directly with the second and third Ig repeats of contactins; the CNTN4 complex used mouse CNTN4 with mouse PTPRG's carbonic-anhydrase-like domain [PMID:20133774].","affinity_potency":[],"species_and_systems":"Curated as human proteins; the co-crystal used mouse CNTN4 and mouse PTPRG domains [PMID:20133774]. Human pair is ortholog-inferred; mouse pair is not.","localisation_and_range":"Not stated in the paper text shown; entity flags: CNTN4 flagged secreted, PTPRG not secreted [flag].","caveats":"Structure paper was read only as abstract; the abstract-level result shows PTPRG binds CNTN3, 4, 5 and 6 and no affinity is reported in our evidence. The only co-complex structure in the abstract is CNTN4 with PTPRG, so this is the best-supported member.","key_references":[{"PMID":"20133774","why":"Crystal structures of PTPRG/PTPRZ with contactins; CNTN specificity"}],"covers":["LR003165","LR006386"]},"LR001949":{"pair":"PTPRK -> PTPRK","headline":"PTPRK is a homophilic adhesion receptor: self-binding shown by aggregation in 1994 and stabilisation at cell contacts in 2019.","interaction_type":"direct binding","direction_and_effect":"R-PTP-kappa mediates homophilic intercellular interaction; its extracellular domain functions as an adhesion substrate and induces aggregation of coated beads [PMID:8264577]. In epithelial cells PTPRK is stabilised at cell-cell contacts, and it dephosphorylates at least five substrates (Afadin, PARD3, delta-catenin family members) [PMID:30924770]. Curated effect: agonist.","molecular_requirements":"Extracellular domain alone suffices for adhesion; adhesion needs no PTPase activity or proteolytic cleavage and is calcium independent [PMID:8264577]. A recombinant PTPRK ECD screened against a secreted-protein microarray found no additional ligands [PMID:30924770].","affinity_potency":[],"species_and_systems":"Human proteins; heterologous cells and beads in 1994 [PMID:8264577]; epithelial cells (MCF10A, Hs27 lysates) in 2019 [PMID:30924770]. Human and mouse pairs listed, neither projected.","localisation_and_range":"Membrane-bound, trans homophilic interaction at cell-cell contacts [PMID:30924770] [PMID:8264577].","caveats":"Self-pair: the ligand and receptor are the same protein, so scoring needs a single-subunit expression rule. The 2019 paper's homophilic claim rests on contact stabilisation and its text excerpts, and its main findings concern substrates; the 1994 paper was read as abstract only. IntAct reports a dimerization assay [DB:IntAct].","key_references":[{"PMID":"8264577","why":"Homophilic binding of R-PTP-kappa"},{"PMID":"30924770","why":"PTPRK stabilised at cell contacts; substrates"}],"covers":["LR001949","LR005285"]},"LR006395":{"pair":"PTPRZ1 -> CNTN2","headline":"Phosphacan (PTPRZ1) was found to bind TAG-1/axonin-1 (CNTN2) with high affinity in one 1996 abstract; no structure.","interaction_type":"direct binding","direction_and_effect":"Phosphacan/PTP-zeta/beta was a high-affinity ligand of TAG-1/axonin-1; binding fell by about 70% after chondroitinase treatment, so chondroitin sulfate chains contribute, but N-deglycosylation had no effect [PMID:8663515].","molecular_requirements":"The phosphacan form, a chondroitin sulfate proteoglycan, was tested; the chondroitin sulfate chains contribute to binding [PMID:8663515]. Whether full-length receptor-type PTPRZ1 binds is not reported.","affinity_potency":[{"value":"Kd 0.04 nM","assay":"binding of phosphacan to TAG-1/axonin-1 (reported as dissociation constant)","system":"nervous-tissue proteoglycan and TAG-1/axonin-1","cite":"PMID:8663515"}],"species_and_systems":"Species is not stated in the abstract; the curated row lists human, but the dossier shows no basis for that [PMID:8663515]. Both pairs are ortholog-inferred.","localisation_and_range":"PTPRZ1 is flagged secreted [flag]; phosphacan is the secreted proteoglycan form.","caveats":"Abstract-only evidence from one paper and the assay type is not stated beyond 'dissociation constants'. Phosphacan is a processed form, not the receptor-type isoform.","key_references":[{"PMID":"8663515","why":"Phosphacan binds TAG-1/axonin-1 with Kd 0.04 nM"}],"covers":["LR003174","LR006395"]},"LR005288":{"pair":"PVR -> CD96","headline":"PVR (CD155) binds CD96 across human and mouse; adhesion/activating on NK cells, but CD96 also competes with CD226 and limits NK function.","interaction_type":"conflicting","direction_and_effect":"CD96/CD155 interaction is preserved between human and mouse, and antibodies block complex formation and T-cell adhesion to CD155 cells [PMID:17971293]. CD96 promotes NK cell adhesion to PVR cells, stimulates cytotoxicity of activated NK cells and mediates acquisition of PVR from target cells [PMID:15034010]. Another paper found CD96 competed with CD226 for CD155 and limited NK cell function by direct inhibition [PMID:24658051].","molecular_requirements":"On thymocytes mCD155 was the only available mCD96 receptor [PMID:17971293]; murine CD96 also binds nectin-1 [PMID:17971293]. CD226 and CD96 compete for the same ligand [PMID:24658051].","affinity_potency":[],"species_and_systems":"Mouse proteins and T cells in the first paper [PMID:17971293]; human NK cells in the second [PMID:15034010]. Curated species for the CD226-competition paper is human, though its abstract describes Cd96-/- mice [PMID:24658051].","localisation_and_range":"Membrane proteins; cell adhesion and trogocytosis of PVR indicate contact-dependent interaction [PMID:15034010].","caveats":"The papers disagree on effect (stimulatory in 15034010, inhibitory in 24658051), so effect depends on context. All abstract-only. No affinity reported in our evidence. PDB structure [DB:PDB 6ARQ] and Reactome record exist.","key_references":[{"PMID":"17971293","why":"CD96/CD155 interaction conserved in man and mouse"},{"PMID":"15034010","why":"CD96 mediates NK adhesion and cytotoxicity via PVR"},{"PMID":"24658051","why":"CD96 competes with CD226 and limits NK function"}],"covers":["LR001952","LR005288"]},"LR004685":{"pair":"RARRES2 -> CCRL2","headline":"Chemerin binds CCRL2 with low-nanomolar affinity in two full-text papers, but the receptor does not signal; it acts as a binding/concentrating receptor.","interaction_type":"direct binding","direction_and_effect":"Chemerin is a nonsignaling ligand of human and mouse CCRL2; unlike classical silent receptors it is not rapidly internalized, and CCRL2 is proposed to concentrate chemerin for the signaling receptor CMKLR1 [PMID:18794339]. In human receptors, no significant G-protein activation or beta-arrestin recruitment was seen with CCRL2 [PMID:27716822].","molecular_requirements":"Full-length chemerin binds; the C-terminal chemerin-9 nonapeptide did not compete efficiently for CCRL2 binding, and a C-terminal chemerin peptide tracer bound CMKLR1 and GPR1 but not CCRL2 [PMID:27716822].","affinity_potency":[{"value":"EC50 = 1.6 nM","assay":"radioligand competition, human chemerin","system":"mouse CCRL2-HA L1.2 transfectants","cite":"PMID:18794339"},{"value":"EC50 = 0.2 nM","assay":"radioligand competition","system":"human CCRL2 L1.2 transfectants","cite":"PMID:18794339"},{"value":"kD of 1.6 nM","assay":"saturation binding","system":"mouse CCRL2 transfectants","cite":"PMID:18794339"},{"value":"KD of 2.35 nM","assay":"saturation binding, [125I]-chemerin","system":"CHO-K1 cells expressing human CCRL2","cite":"PMID:27716822"}],"species_and_systems":"Recombinant L1.2 and CHO-K1 transfectants and mouse peritoneal mast cells, with human chemerin; mouse in vivo data show CCRL2 on mast cells enhances tissue swelling in passive cutaneous anaphylaxis [PMID:18794339]. Human receptor tested in [PMID:27716822].","localisation_and_range":"Chemerin is flagged secreted; CCRL2 is a transmembrane receptor [flag]. The paper proposes local concentration of chemerin at the CCRL2-expressing cell surface [PMID:18794339].","caveats":"CCRL2 is non-signaling, so effect is not agonism; curators' labels (neutral, antagonist) differ between papers. Both papers were read in full text, but the curated effect_direction is not an actual measured antagonism. UniProt notes lower affinity than for CMKLR1 [DB:UniProt]. One further row is pending.","key_references":[{"PMID":"18794339","why":"Identifies chemerin as nonsignaling CCRL2 ligand; EC50 and kD binding"},{"PMID":"27716822","why":"Compares chemerin binding and signaling at CMKLR1, GPR1 and CCRL2"}],"covers":["LR001286","LR004685"]},"LR004694":{"pair":"RGMA -> NEO1","headline":"RGM binds neogenin with sub-nanomolar affinity in chick retina work; the paper says RGM, not specifically RGMA.","interaction_type":"direct binding","direction_and_effect":"Expression cloning identified neogenin as an RGM binding site; anti-neogenin antibody and soluble neogenin ectodomain blocked temporal retinal axon avoidance of RGM, and DRG axons gained responsiveness when neogenin was expressed [PMID:15258590]. The annotation is inhibitory [flag], fitting axon repulsion [PMID:15258590].","molecular_requirements":"Of netrin receptors tested only neogenin bound RGM [PMID:15258590]. Other requirements not reported in our evidence.","affinity_potency":[{"value":"sub-nanomolar","assay":"expression cloning binding","system":"chick","cite":"PMID:15258590"}],"species_and_systems":"Chick retinal axons and DRG axons; curator lists human ligand and chicken receptor [PMID:15258590]. Both human and mouse pairs are ortholog-inferred.","localisation_and_range":"RGMA is flagged secreted [flag]. A Reactome complex NEO1:RGD is recorded on the plasma membrane [DB:Reactome R-HSA-374583].","caveats":"Abstract-only; the abstract says RGM without naming RGMA; no numeric Kd given.","key_references":[{"PMID":"15258590","why":"Neogenin identified as RGM receptor"}],"covers":["LR001295","LR004694"]},"LR001958":{"pair":"ROBO1 -> ROBO1","headline":"ROBO1 homophilic binding through its extracellular domain, shown in one abstract-read paper and one IntAct record.","interaction_type":"direct binding","direction_and_effect":"Extracellular domains of Robo1 and Robo2 are homophilic adhesion molecules [PMID:12504588]; Robo1 expressed in 3T3 cells stimulated neurite outgrowth from Robo-positive neurons, blocked by an antibody to the first Ig domain or soluble Robo-Fc [PMID:12504588]. IntAct lists a polymerization record [DB:IntAct].","molecular_requirements":"The first Ig domain of Robo1/2 is implicated by antibody blockade [PMID:12504588]. Coreceptors are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human Robo1 and Robo2 transfected into 3T3 cells (cell line species not stated in our evidence); neurons were retinal, olfactory and cerebellar granule cells, species not stated [PMID:12504588]. Mouse pair is ortholog-inferred.","localisation_and_range":"Receptor flagged as transmembrane, not secreted [flag]; homophilic adhesion implies contact-dependent (juxtacrine) signalling.","caveats":"Single paper read as abstract only; direction is meaningless for a homophilic pair. Robo1 also interacts with Robo2 [PMID:12504588].","key_references":[{"PMID":"12504588","why":"Robo1/Robo2 homophilic adhesion and neurite outgrowth"}],"covers":["LR001958","LR005291"]},"LR010958":{"pair":"RSPO2 -> WNT1","headline":"RSPO2 -> WNT1 rests only on UniProt statements; ligand-ligand pair.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states WNT1 interacts with RSPO1, RSPO2 and RSPO3 (by similarity), and RSPO2 (Q6UXX9) interacts with WNT1 (by similarity) [DB:UniProt]. Effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species and assay not stated; UniProt cites PMIDs 26902720 and 21727895 [DB:UniProt].","localisation_and_range":"Both secreted per flag [flag].","caveats":"No judged papers; one judged row concerned a different entity. Both UniProt statements are by similarity.","key_references":[],"covers":["LR010958"]},"LR006449":{"pair":"S100A9 -> AGER","headline":"S100A8/A9 interacts with RAGE in a diabetic mouse model (abstract-only); pharmacological blockade, no binding assay.","interaction_type":"functional only","direction_and_effect":"In hyperglycaemic mice, neutrophil-derived S100A8/A9 interact with RAGE on hepatic Kupffer cells, increasing IL-6 and driving thrombocytosis; inhibiting S100A8/A9 binding to RAGE with paquinimod reduced thrombocytosis and atherogenesis [PMID:28504650]. UniProt states S100A9 binds TLR4 and AGER as an alarmin [DB:UniProt]. Agonist-like.","molecular_requirements":"The evidence concerns the S100A8/A9 complex, not S100A9 alone [PMID:28504650].","affinity_potency":[],"species_and_systems":"Diabetic mouse model and human type 2 diabetes plasma samples; the human pair is ortholog-inferred and the mouse pair is not [PMID:28504650].","localisation_and_range":"Ligand flagged as secreted [flag]; secreted, so paracrine/endocrine range is plausible. RAGE acts on Kupffer cells [PMID:28504650].","caveats":"Abstract only. Curator label direct_binding rests on pharmacological blockade; no direct binding data. UniProt text is a general function statement.","key_references":[{"PMID":"28504650","why":"S100A8/A9-RAGE axis in diabetic thrombocytosis, paquinimod blockade"}],"covers":["LR003232","LR006449"]},"LR006458":{"pair":"S100B -> ALCAM","headline":"S100B signals through CD166/ALCAM in mouse endothelial cells; functional evidence from one abstract-only paper.","interaction_type":"functional only","direction_and_effect":"Binding of S100B to CD166/ALCAM induced dose- and time-dependent NF-kappaB expression in wild type and RAGE(-/-) mouse endothelial cells; ALCAM siRNA completely inhibited S100B-induced NF-kappaB activation in RAGE(-/-) but not in WT cells [PMID:23729438]. Agonist.","molecular_requirements":"Acts independently of RAGE in RAGE(-/-) cells; ALCAM(-/-) and RAGE(-/-) show reciprocal upregulation, with ALCAM(-/-) RAGE(-/-) mice showing a 27% reduction in DTH [PMID:23729438].","affinity_potency":[],"species_and_systems":"Mouse endothelial cells and mice; the human pair is ortholog-inferred, the mouse pair is not [PMID:23729438].","localisation_and_range":"Ligand secreted [flag]; ALCAM flagged secreted and transmembrane [flag].","caveats":"Abstract only; a direct binding assay is not described in our evidence, and no affinity is reported. Compensation by RAGE complicates knockout results.","key_references":[{"PMID":"23729438","why":"ALCAM as S100B receptor, RAGE-independent NF-kB activation"}],"covers":["LR003242","LR006458"]},"LR009383":{"pair":"SCGB1A1 -> LMBR1L","headline":"Uteroglobin interacting with the lipocalin-1 receptor (LMBR1L); supported by one paper and UniProt, with a conflicting report.","interaction_type":"database-asserted only","direction_and_effect":"Uteroglobin interaction with the lipocalin-1 receptor suppresses cancer cell migration and invasion [PMID:16423471]. UniProt records the interaction as observed in PMID:16423471 [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human uteroglobin and receptor in cancer cell migration/invasion assays [PMID:16423471].","localisation_and_range":"Uteroglobin is flagged secreted [flag].","caveats":"The curated evidence sentence is background citing earlier work. UniProt notes the interaction was not observed in PubMed:23964685 [DB:UniProt], a conflicting result. No affinity is attached to this pair in our evidence.","key_references":[{"PMID":"16423471","why":"Uteroglobin-Lip-1R binding and inhibition of migration"}],"covers":["LR009383"]},"LR006467":{"pair":"SCUBE2 -> KDR","headline":"SCUBE2 is reported as a VEGFR2 co-receptor forming a complex with VEGF and KDR; one paper, abstract only.","interaction_type":"direct binding","direction_and_effect":"SCUBE2 forms a complex with VEGF and VEGFR2 and acts as a coreceptor, facilitating VEGF binding and augmenting VEGFR2 signalling; overexpression increases and knockdown or knockout reduces VEGF-induced angiogenesis and VEGFR2 phosphorylation [PMID:27834687].","molecular_requirements":"SCUBE2 acts together with VEGF and VEGFR2 (ternary complex), not as a stand-alone ligand [PMID:27834687].","affinity_potency":[],"species_and_systems":"Human endothelial cells (lentiviral overexpression and shRNA) plus EC-specific Scube2 knockout mice, Matrigel plugs and hind-limb ischemia [PMID:27834687]. BioGRID lists affinity capture-western [DB:BioGRID].","localisation_and_range":"SCUBE2 is flagged secreted [flag]; the paper calls it a peripheral membrane protein on endothelial cells [PMID:27834687].","caveats":"One paper read as abstract only; no affinity. It is a co-receptor role, so direct binding of SCUBE2 to KDR alone is not shown in our evidence. UniProt notes the interaction [DB:UniProt].","key_references":[{"PMID":"27834687","why":"SCUBE2 as VEGFR2 coreceptor, co-IP and mouse knockout"}],"covers":["LR003251","LR006467"]},"LR005297":{"pair":"SELE -> CD44","headline":"E-selectin binds native CD44 glycoforms in vitro, with slow kinetics for dimeric E-selectin; one abstract-only paper plus databases.","interaction_type":"direct binding","direction_and_effect":"CD44 captured from hematopoietic cell extracts binds recombinant monomeric E-selectin transiently with fast on- and off-rates, and dimeric E-selectin with remarkably slow on- and off-rates [PMID:26124272]. Reactome lists E-selectin binding an E-selectin ligand [DB:Reactome].","molecular_requirements":"Binding requires sialyl Lewis x on both O- and N-glycans; association is salt sensitive [PMID:26124272]. Oligomeric state of E-selectin changes kinetics.","affinity_potency":[],"species_and_systems":"Native human CD44 from hematopoietic cell extracts on an SPR chip with recombinant E-selectin [PMID:26124272]. IntAct lists co-IP and solid-phase assays [DB:IntAct].","localisation_and_range":"SELE is flagged transmembrane and not secreted [flag], consistent with contact-dependent leukocyte tethering [PMID:26124272].","caveats":"Read as abstract only; no numeric affinity in our evidence. CD44 acts here as a glycoprotein carrying sialyl Lewis x, so binding is glycan dependent; role as a signalling receptor is not reported.","key_references":[{"PMID":"26124272","why":"SPR kinetics of E-selectin binding to native CD44"}],"covers":["LR001965","LR005297"]},"LR004739":{"pair":"SEMA3A -> PLXNA2","headline":"Structural and cell evidence that SEMA3A contacts PlexinA2 within an Nrp1-stabilised ternary complex.","interaction_type":"direct binding","direction_and_effect":"Within each heterotrimer, semaphorin contacts plexin, similar to co-receptor-independent complexes; Nrp1 stabilises a canonical but weakened Sema3-PlxnA interaction [PMID:23104057]. Sema3A, not Sema3C or Sema3F, induces contraction of NP1/PlexA2-expressing COS-7 cells [PMID:11239433]. Effect agonist [PMID:23104057].","molecular_requirements":"Needs Nrp1 co-receptor: Nrp1 cross-braces two Sema3A-PlxnA2 pairings, the Nrp1 a1 domains wedged between Sema3A and PlxnA2 sema domains [PMID:23104057]. NP1 is required with PlexA2 in the cell assay [PMID:11239433]. Reactome: Sema3A binds Nrp-1 bound to PlexinA [DB:Reactome].","affinity_potency":[],"species_and_systems":"Crystal structure of a mouse semaphorin-plexin-Nrp complex (dossier labels species human) [PMID:23104057]; COS-7 assays with mouse-labelled proteins [PMID:11239433].","localisation_and_range":"SEMA3A is flagged as secreted and not transmembrane [flag], so it acts as a diffusible paracrine cue on membrane receptors.","caveats":"The Sema3A-PlxnA2 interaction is weak and the structure is low resolution; the Sema3A-PlxnA2 interface was not among the mutated interfaces [PMID:23104057]. The structural paper was assessed from abstract plus excerpts, the second assay is cell-based, not binding.","key_references":[{"PMID":"23104057","why":"Low-resolution Sema3A-PlxnA2-Nrp1 complex structure"},{"PMID":"11239433","why":"Sema3A contracts NP1/PlexA2 COS-7 cells"}],"covers":["LR001343","LR004739"]},"LR004748":{"pair":"SEMA3E -> PLXND1","headline":"Well-supported direct, neuropilin-independent receptor pair with biochemical, genetic and database support.","interaction_type":"direct binding","direction_and_effect":"Sema3E acts as a repulsive cue for plexin-D1-expressing endothelial cells [PMID:15550623]. Sema3E and Plexin D1 knockdown reduced metastatic potential of human carcinoma cells in mice [PMID:20664171]. Sema3E-Plexin-D1 signaling negatively regulates VEGF-induced Dll4-Notch signaling [PMID:21724832]. Curators labelled the first paper agonist.","molecular_requirements":"Sema3E-plexin-D1 signaling did not require neuropilins [PMID:15550623]. A screen found Sema3E interacts directly with PlxnD1 without Nrp1 or Nrp2 [PMID:26633812]. Database records: IntAct surface plasmon resonance between SEMA3E and PLXND1 [DB:IntAct]; Reactome lists SEMA3E binds to PLXND1 [DB:Reactome]; UniProt notes SH3BP1 dissociates upon SEMA3E binding to PLXND1 [DB:UniProt].","affinity_potency":[],"species_and_systems":"Mouse in vivo vascular patterning [PMID:15550623]; human tumor cells in mice [PMID:20664171]; mouse retina [PMID:21724832]; screen with human recombinant proteins [PMID:26633812]. Both species' pairs are not ortholog-inferred.","localisation_and_range":"SEMA3E is annotated secreted [flag]; Sema3E from somites acts on adjacent vessels, a paracrine action [PMID:15550623].","caveats":"Three of four shown papers are abstract-only. The screen sentence in PMID 26633812 is a general statement crediting earlier work for the Sema3E-PlxnD1 direct interaction. No affinity from papers; database record is an SPR assay [DB:IntAct]. Two review_only rows are not shown.","key_references":[{"PMID":"15550623","why":"Sema3E-plexin-D1 patterns vasculature, neuropilin-independent"},{"PMID":"26633812","why":"Biochemical screen reporting direct Sema3-Plxn interactions"},{"PMID":"20664171","why":"Sema3E-PlexinD1 in metastasis"}],"covers":["LR001352","LR004748"]},"LR001967":{"pair":"SEMA4A -> LILRB2","headline":"Human SEMA4A is reported to bind ILT-4 (LILRB2) on activated CD4+ T cells; single paper, abstract-level.","interaction_type":"direct binding","direction_and_effect":"ILT-4 was identified as a receptor for human SEMA4A on activated CD4+ T cells by two cloning strategies; SEMA4A-Fc bound ILT-4-transfected 293T cells and binding was blocked by ILT-4-Fc [PMID:29467366].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human cells and tissue; the paper contrasts human with murine Sema4A, which acts via Tim-2 [PMID:29467366].","localisation_and_range":"SEMA4A and LILRB2 are both flagged secreted or transmembrane [flag]; SEMA4A was used as a soluble Fc fusion [PMID:29467366].","caveats":"Single paper, read as abstract; excerpts partly parsed. No affinity reported. Effect direction (agonist or inhibitory) is not stated.","key_references":[{"PMID":"29467366","why":"two cloning strategies identify ILT-4 as hSEMA4A receptor"}],"covers":["LR001967"]},"LR006494":{"pair":"SEMA4B -> PLXNB2","headline":"Plexin-B2 is reported as the Sema4B receptor on microglia, supported by matching knockouts in one 2024 paper; functional rather than binding evidence.","interaction_type":"functional only","direction_and_effect":"In vitro experiments indicate Plexin-B2 is the Sema4B receptor on microglia; astrocytic Sema4B enhances injury-induced microglia reactivity, and microglia/macrophage-specific Plexin-B2 knockout mice show similar attenuated reactivity and neuronal cell death after injury (agonist) [PMID:38781210].","molecular_requirements":"Plexin-B2 only; no co-receptor reported in our evidence. Sema4B/Plexin-B2 double heterozygotes also show reduced reactivity, supporting a shared pathway [PMID:38781210].","affinity_potency":[],"species_and_systems":"Experiments used mice (knockouts, cortical stab wound) and in vitro microglia/astrocyte cultures; the dossier labels species as human but the paper text describes mouse work [PMID:38781210]. The human pair is ortholog-inferred.","localisation_and_range":"Sema4B described as a transmembrane protein expressed by astrocytes [PMID:38781210]; our entity flag says not secreted [flag]. Action is by contact or shedding, not established here.","caveats":"No direct binding measurement or affinity in our evidence; abstract plus excerpts only mention that receptor identification was in vitro. No database support.","key_references":[{"PMID":"38781210","why":"Astrocyte-to-microglia Sema4B-Plexin-B2 axis, with knockouts"}],"covers":["LR003278","LR006494"]},"LR004757":{"pair":"SEMA4D -> CD72","headline":"SEMA4D (CD100) binds CD72 on lymphocytes in human and mouse studies; well supported by binding and functional papers.","interaction_type":"direct binding","direction_and_effect":"Expression cloning identified CD72 as the lymphocyte CD100 receptor; CD100 stimulation dephosphorylates CD72 and dissociates SHP-1, turning off CD72 negative signalling [PMID:11114375]. Human CD100-Fc specifically bound CD72-expressing cells and co-stimulated B cells and dendritic cells and induced TNF-alpha, IL-6 and IL-8 [PMID:12882840]. Platelet work shows the same SHP-1 dissociation [PMID:17244710].","molecular_requirements":"CD72 is named alone; the platelet paper also names plexin-B1 as a second SEMA4D receptor [PMID:17244710].","affinity_potency":[{"value":"Kd ~3e-7 M","assay":"receptor affinity on lymphocytes","system":"lymphocytes","cite":"PMID:11114375"}],"species_and_systems":"Human recombinant hCD100-Fc and CD72 [PMID:12882840]; platelets with Sema4d-null mice and ADAM17-null mouse platelets [PMID:17244710].","localisation_and_range":"Sema4D is flagged both secreted and transmembrane [flag]. Platelet paper shows membrane-bound sema4D acting on nearby platelets, then ADAM17-dependent shedding of the extracellular domain [PMID:17244710].","caveats":"All papers abstract only. The Kd of ~3e-7 M is a receptor measurement on lymphocytes, not on purified CD72 [PMID:11114375]. Database records: BioGRID, IntAct, Reactome [DB:BioGRID][DB:Reactome]. Mouse pair is ortholog-inferred.","key_references":[{"PMID":"11114375","why":"Expression cloning of CD72 as CD100 receptor"},{"PMID":"12882840","why":"Human CD100-Fc binds human CD72, functional readouts"},{"PMID":"17244710","why":"CD72 and plexin-B1 in platelets"}],"covers":["LR001361","LR004757"]},"LR004766":{"pair":"SEMA7A -> ITGB1","headline":"Beta1 integrin is supported only as part of alpha1beta1 in an abstract-only immune study; no chain-specific data.","interaction_type":"functional only","direction_and_effect":"Sema7A stimulates cytokine production in monocytes and macrophages through alpha1beta1 integrin [PMID:17377534]. The modulatory effect is annotated stimulatory. Reactome lists a SEMA7A:Integrin alpha1beta1 complex [DB:Reactome].","molecular_requirements":"Beta1 acts with alpha1 in this study; beta1 alone is not shown to suffice.","affinity_potency":[],"species_and_systems":"Curator notes describe human monocytes/macrophages and Sema7a-/- mice [PMID:17377534].","localisation_and_range":"Ligand carries secreted and transmembrane flags [flag]; the abstract describes it as GPI-anchored [PMID:17377534].","caveats":"Abstract only; chain-only attribution from a heterodimer, no affinity data.","key_references":[{"PMID":"17377534","why":"Sema7A signals via alpha1beta1 integrin"}],"covers":["LR001370","LR004766"]},"LR004775":{"pair":"SERPING1 -> SELP","headline":"C1 inhibitor binds P-selectin via glycans and inhibits adhesion; one abstract-only paper shared with E-selectin.","interaction_type":"direct binding","direction_and_effect":"Plasma C1INH bound P- and E-selectins by FACS and immunoprecipitation, and inhibited endothelial-leukocyte adhesion with significant (>50%) inhibition at 250 microg/mL or higher [PMID:14568956].","molecular_requirements":"Binding relies on sialyl Lewis(x)-related N-glycan moieties of C1INH [PMID:14568956].","affinity_potency":[],"species_and_systems":"Species not specified in the curated row; plasma C1INH and tissue-culture adhesion model [PMID:14568956]. BioGRID lists an affinity-capture-western record [DB:BioGRID].","localisation_and_range":"P-selectin is flagged as receptor and transmembrane [flag]; contact-dependent.","caveats":"Same single paper as the E-selectin pair; no affinity reported; the stored evidence sentence is the paper title; abstract only.","key_references":[{"PMID":"14568956","why":"C1INH binds selectins and blocks adhesion"}],"covers":["LR001380","LR004775"]},"LR003299":{"pair":"SFTPD -> OSCAR","headline":"OSCAR-Fc binds the SP-D collagenous region and SP-D triggers TNF-alpha release in OSCAR-dependent fashion; one paper with full-text excerpts.","interaction_type":"direct binding","direction_and_effect":"Agonist: monocytes secrete TNF-alpha upon SP-D exposure in an OSCAR-dependent fashion [PMID:25716998].","molecular_requirements":"SP-D collagenous region carries a putative OSCAR-binding motif (SP-D residues 106-114 GPPGPPGVP) [PMID:25716998]. Reactome lists OSCAR with collagen/SP-D [DB:Reactome].","affinity_potency":[],"species_and_systems":"OSCAR-Fc fusion protein with recombinant SP-D and native SP-D from human bronchoalveolar lavage; human CCR2+ inflammatory monocytes; mouse pair is ortholog-inferred [PMID:25716998].","localisation_and_range":"SP-D is flagged secreted [flag].","caveats":"One paper; abstract-based read depth though excerpts are present. No affinity reported in the excerpts.","key_references":[{"PMID":"25716998","why":"OSCAR as receptor for SP-D, TNF-alpha release in monocytes"}],"covers":["LR003299","LR006514"]},"LR001976":{"pair":"SHH -> GAS1","headline":"SHH-GAS1 is supported by one functional axon-repulsion paper plus database records; direct binding is not measured in the dossier.","interaction_type":"functional only","direction_and_effect":"Shh secreted from gut epithelium excludes enteric axons from central projection; this requires its binding partner Gas1 and Smo in enteric neurons. Axons turn away from a point source of Shh in a Gas1-dependent manner [PMID:25535338]. UniProt describes GAS1 as a co-receptor that takes ShhN from the CDON-BOC heterodimer and transfers it to PTCH1 or PTCH2 [DB:UniProt].","molecular_requirements":"Gas1 and Smo are required in enteric neurons; Gnaz (a Galphai) mediates the repulsive response [PMID:25535338]. A structure with a chain of SHH and a chain of GAS1 exists [DB:PDB 7RHQ].","affinity_potency":[],"species_and_systems":"Enteric neurons differentiated from neurospheres in vitro plus Gnaz-mutant intestines [PMID:25535338]; species not specified in the abstract.","localisation_and_range":"GAS1 is flagged not secreted [flag]; SHH is secreted [flag], acting as a paracrine cue at a distance [PMID:25535338].","caveats":"Abstract-only. The paper's effect is axon repulsion, not canonical activation, so the effect may be context dependent. Direct binding is asserted by the phrase 'binding partner' and by the PDB entry, not measured in the dossier.","key_references":[{"PMID":"25535338","why":"Gas1-dependent Shh repulsion of enteric axons"}],"covers":["LR001976","LR005306"]},"LR004784":{"pair":"SHH -> LRP2","headline":"SHH is bound by LRP2 as an apical binding protein in forebrain; one confirmed abstract, human pair ortholog-inferred.","interaction_type":"direct binding","direction_and_effect":"LRP2 acts as an apical SHH-binding protein that sequesters SHH in its target field and controls internalization and trafficking of SHH/patched 1 complexes; overexpression of LRP2 variants increases SHH signaling [PMID:22340494].","molecular_requirements":"LRP2 acts alongside patched 1; Lrp2-deficient mice and cephalic explants fail to respond to SHH despite functional patched 1 and smoothened [PMID:22340494].","affinity_potency":[],"species_and_systems":"Mouse embryos and cephalic explants, plus cells [PMID:22340494]. The curated primary pair is mouse; human is ortholog-inferred.","localisation_and_range":"Apical, membrane-associated at the target field [PMID:22340494]; SHH is flagged secreted [flag].","caveats":"Abstract-only read. Two more papers were review-only. No affinity or direct assay reported in the dossier.","key_references":[{"PMID":"22340494","why":"LRP2 binds and sequesters SHH in forebrain"}],"covers":["LR001389","LR004784"]},"LR001985":{"pair":"SLIT2 -> APP","headline":"SLIT2 binds the APP E1 domain; one abstract-level paper supports APP as a Slit receptor.","interaction_type":"direct binding","direction_and_effect":"Slit binds APP through the E1 domain, triggering APP ectodomain shedding and FE65/Pak1/Rac1 signalling; APP loss abolishes Slit repulsion in olfactory explants [PMID:28785723].","molecular_requirements":"E1 domain of APP is the binding region [PMID:28785723]. Co-receptor needs not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse explants and knockouts, HEK293 co-culture, and C. elegans APL-1 genetics; the Slit2 used was Myc-tagged and expressed in HEK293 cells [PMID:28785723]. Dossier covers human and mouse pairs.","localisation_and_range":"SLIT2 is flagged secreted and APP flagged secreted and transmembrane [flag]; Slit2 was supplied by co-cultured cells and cell-surface binding was detected [PMID:28785723].","caveats":"Single paper; binding statement is taken from the abstract (read depth abstract only), and excerpts show expression and mutant phenotypes rather than binding data. No affinity.","key_references":[{"PMID":"28785723","why":"APP as Slit receptor, E1 binding, axon guidance"}],"covers":["LR001985","LR005314"]},"LR004793":{"pair":"SLIT3 -> ROBO2","headline":"SLIT3 associates directly with ROBO2 in a binding ELISA with osteoblast lysate; one paper.","interaction_type":"direct binding","direction_and_effect":"Binding ELISA showed SLIT3-associated ROBO1 and ROBO2 increased with osteoblast lysate, indicating direct association [PMID:29504949]. Functional effect via ROBO2 specifically is not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Osteoblast lysate ELISA; mouse pair non-inferred, human ortholog-inferred [PMID:29504949].","localisation_and_range":"SLIT3 is flagged secreted, ROBO2 transmembrane [flag]. Reactome lists a ROBO2:SLIT3 plasma-membrane complex [DB:Reactome].","caveats":"Quote browser-read, spot-check pending; ROBO1 and ROBO2 are reported together so ROBO2-specific binding is not separated. Eight abstracts insufficient and three different-entity rows not shown. No affinity.","key_references":[{"PMID":"29504949","why":"Binding ELISA of SLIT3 with ROBO1 and ROBO2"}],"covers":["LR001398","LR004793"]},"LR001994":{"pair":"SLITRK5 -> PTPRD","headline":"Slitrk5 binds PTPdelta through its LRR1 domain; one full-text paper with a Kd of about 100 nM in the curator notes.","interaction_type":"direct binding","direction_and_effect":"Slitrk5 binds PTPdelta through its LRR1 domain; under basal conditions it interacts mainly with PTPdelta, then shifts to cis-interaction with TrkB on BDNF [PMID:26004511].","molecular_requirements":"LRR1 domain of Slitrk5 is required [PMID:26004511].","affinity_potency":[{"value":"Kd ~100 nM","assay":"soluble PTPdelta-Fc binding to cells (curator note; not in excerpts)","system":"HEK293T expressing full-length Slitrk5","cite":"PMID:26004511"}],"species_and_systems":"HEK293T cells with soluble PTPdelta-Fc; neurons for TrkB work [PMID:26004511]. Mouse pair ortholog-inferred.","localisation_and_range":"Trans-synaptic (PTPdelta presynaptic) versus cis (TrkB) [PMID:26004511]; SLITRK5 flagged transmembrane [flag].","caveats":"Single paper; the Kd appears only in the curator notes, not in the supplied excerpts. A competing BDNF-induced cis-interaction with TrkB can displace PTPdelta binding [PMID:26004511].","key_references":[{"PMID":"26004511","why":"Slitrk5 LRR1 binding to PTPdelta"}],"covers":["LR001994","LR005323"]},"LR010985":{"pair":"SLURP2 -> CHRNA5","headline":"CHRNA5 is listed as a SLURP2 interaction partner in UniProt only; no curated paper evidence in our dossier.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states that SLURP2 interacts with CHRNA3, CHRNA4, CHRNA5, CHRNA7, CHRNB2 and CHRNB4 [DB:UniProt]. Direction and effect are not reported in our evidence.","molecular_requirements":"Not reported in our evidence. CHRNA5 is a nicotinic subunit; the UniProt statement does not specify a subunit combination [DB:UniProt].","affinity_potency":[],"species_and_systems":"Not reported in our evidence; the UniProt record cites PMID 27485575 without detail on the experiment [DB:UniProt].","localisation_and_range":"SLURP2 is flagged as secreted [flag]; CHRNA5 carries no receptor flag in our entity record [flag].","caveats":"No paper was judged for this pair. The support is a single database line that appears to be a list of partners from one study, and it may reflect subunit co-purification rather than a direct SLURP2-CHRNA5 interaction.","key_references":[],"covers":["LR010985"]},"LR007394":{"pair":"SOSTDC1 -> LRP5","headline":"Wise/Sostdc1 inhibits Lrp5/6-dependent Wnt signalling in mouse tooth genetics; binding to LRP5 itself is not shown in our evidence.","interaction_type":"functional only","direction_and_effect":"Wise suppresses vestigial tooth bud survival by acting as an inhibitor of Lrp5- and Lrp6-dependent Wnt signalling; reducing Lrp5 and Lrp6 dosage rescues Wise-null tooth phenotypes [PMID:20724449]. Antagonist/inhibitor.","molecular_requirements":"Lrp5 and Lrp6 are both implicated; the abstract does not separate them [PMID:20724449].","affinity_potency":[],"species_and_systems":"Mouse in vivo (tooth development, genetic dosage) [PMID:20724449]. Human pair is not ortholog-inferred in the record but the experiment is mouse.","localisation_and_range":"Ligand is flagged secreted [flag]; range not addressed in the paper's abstract.","caveats":"Abstract only, genetic evidence; no physical binding to LRP5 shown. One further paper was judged review_only. No database records. No affinity.","key_references":[{"PMID":"20724449","why":"Wise inhibits Lrp5/6-dependent Wnt in mouse tooth; Lrp5/6 dosage rescue"}],"covers":["LR007394"]},"LR010967":{"pair":"SPARC -> PDGFB","headline":"No curator-verified paper; the pair rests on one BioGRID record of a reconstituted complex.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence beyond a BioGRID SPARC-PDGFB Reconstituted Complex record [DB:BioGRID]. The interaction is classed Ligand-Ligand with an inhibitory modulatory label, so it is not a ligand-receptor pair as such.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Underlying BioGRID record cites PMID:1311092 (reconstituted complex); the paper was not judged in our evidence.","localisation_and_range":"Both partners are flagged secreted, PDGFB not a transmembrane receptor [flag].","caveats":"Five papers were judged different_entity; no confirmed paper. PDGFB is a ligand, not a receptor, so a CCC tool should not treat it as a receptor.","key_references":[],"covers":["LR010967"]},"LR006539":{"pair":"SPP1 -> ITGB6","headline":"Osteopontin is identified as an alphavbeta6 ligand by one abstract-level paper; direct but single-source.","interaction_type":"direct binding","direction_and_effect":"alphavbeta6 is identified as an osteopontin receptor by affinity chromatography and cell adhesion [PMID:16005200]. Effect direction not reported in our evidence.","molecular_requirements":"alphavbeta6 binds the RGD site (RGD peptide or RAA mutation abolishes adhesion); thrombin cleavage is not needed for optimal adhesion [PMID:16005200].","affinity_potency":[],"species_and_systems":"Species not specified in the abstract; recombinant OPN forms in cell adhesion assays [PMID:16005200].","localisation_and_range":"SPP1 is flagged secreted [flag].","caveats":"Single paper, abstract only; no database record. The mouse pair is ortholog-inferred.","key_references":[{"PMID":"16005200","why":"Identifies alphavbeta6 as an OPN receptor"}],"covers":["LR003332","LR006539"]},"LR006548":{"pair":"TAFA1 -> CMKLR2","headline":"The cited paper shows FAM19A1 (TAFA1) acting through GPR1, not directly CMKLR2; support depends on an alias match.","interaction_type":"functional only","direction_and_effect":"Antagonist-labelled by curators. The paper identifies GPR1 as a functional receptor for FAM19A1, and GPR1's N-terminal domain neutralised FAM19A1 effects on neural stem cells [PMID:29799787].","molecular_requirements":"FAM19A1 interacted with GPR1 via its N-terminal domain; ROCK/ERK1/2 and ROCK/STAT3 pathways were required [PMID:29799787].","affinity_potency":[],"species_and_systems":"Neural stem cell proliferation assays with recombinant FAM19A1 [PMID:29799787].","localisation_and_range":"TAFA1 is flagged secreted [flag]; the paper calls FAM19A1 a classic secretory protein [PMID:29799787].","caveats":"Abstract only. The curator note says GPR1 is gene-symbol-aliased to CMKLR2, so this pair rests on aliasing, not a CMKLR2 experiment [PMID:29799787]. No database records.","key_references":[{"PMID":"29799787","why":"FAM19A1 identified as GPR1 ligand in neural stem cells"}],"covers":["LR003341","LR006548"]},"LR006557":{"pair":"TAFA5 -> RNF167","headline":"TAFA5 binds the RNF167 ectodomain by SPR in one screening paper; no affinity or function reported.","interaction_type":"direct binding","direction_and_effect":"SPR sensorgrams showed human TAFA-5 binding to RNF167-ECD, as did TAFA-2, PTN and MDK [PMID:36178190]. RNF167 was a shared hit across PTN, TAFA-2 and TAFA-5 CRISPRa screens [PMID:36178190]. Effect on RNF167 is not reported in our evidence.","molecular_requirements":"The RNF167 ectodomain alone was used [PMID:36178190].","affinity_potency":[],"species_and_systems":"Recombinant human proteins, SPR [PMID:36178190]. Mouse pair projected by orthology.","localisation_and_range":"TAFA5 annotated secreted [flag]; RNF167 annotated receptor [flag].","caveats":"Single screening paper. The authors state RING E3 ligase interactions typically show weak affinity and fast kinetics [PMID:36178190]. Receptor role for an E3 ligase is not demonstrated.","key_references":[{"PMID":"36178190","why":"SPR binding of TAFA-5 to RNF167-ECD after CRISPRa screen"}],"covers":["LR003354","LR006557"]},"LR006566":{"pair":"TENM4 -> ADGRL3","headline":"Cell-aggregation evidence that teneurin-4 cells adhere to latrophilin-expressing cells; no binding data for ADGRL3 specifically.","interaction_type":"functional only","direction_and_effect":"Cells expressing Lphn1/2/3 formed large aggregates with cells expressing Ten2 or Ten4, indicating intercellular adhesion [PMID:24273166].","molecular_requirements":"Binding is mapped to the lectin-like domain of latrophilins in the abstract; ADGRL3 specific requirements are not reported in our evidence [PMID:24273166].","affinity_potency":[],"species_and_systems":"HEK293T cell aggregation assay; species unspecified. The human pair and the mouse pair are both ortholog-inferred [PMID:24273166].","localisation_and_range":"Both partners have transmembrane flags [flag]; the adhesion assay is consistent with contact-dependent interaction.","caveats":"The aggregation assay does not distinguish ADGRL3 from the other latrophilins in the abstract-level evidence. Pulldown binding in the same paper is described in our evidence for Lphn1 only. The curator quote is a browser read, unverifiable, spot-check pending.","key_references":[{"PMID":"24273166","why":"Latrophilin cells aggregate with Ten4 cells"}],"covers":["LR003363","LR006566"]},"LR004856":{"pair":"TG -> LRP2","headline":"Purified rat megalin (LRP2) binds rat thyroglobulin in solid-phase assays with Kd 9.2 nM.","interaction_type":"direct binding","direction_and_effect":"Megalin binds thyroglobulin; the authors propose it may participate in thyroglobulin endocytosis from the colloid [PMID:9492085].","molecular_requirements":"Binding was calcium dependent and almost completely inhibited by excess Tg, lactoferrin, lipoprotein lipase, apolipoprotein J and RAP; megalin bound both monomeric (330 kD) and dimeric (660 kD) Tg [PMID:9492085].","affinity_potency":[{"value":"Kd 9.2 nM","assay":"solid-phase binding, estimated Kd +/- 0.6 nM","system":"purified rat megalin and rat thyroglobulin","cite":"PMID:9492085"}],"species_and_systems":"Rat proteins in vitro; human and mouse pairs are both ortholog-inferred [PMID:9492085].","localisation_and_range":"TG is annotated secreted [flag]; megalin is described as acting on absorptive epithelial cells including thyroid [PMID:9492085].","caveats":"Abstract only. Three anti-megalin antibodies only partially inhibited binding. Rat data; endocytic function is proposed, not shown.","key_references":[{"PMID":"9492085","why":"Megalin binds thyroglobulin, Kd 9.2 nM"}],"covers":["LR001461","LR004856"]},"LR004838":{"pair":"TGFB1 -> TGFBR1","headline":"Established type I TGF-beta receptor; binding needs TGFBR2, and structure and expression data support it.","interaction_type":"direct binding","direction_and_effect":"Tsk 7L (ALK5) is a type I receptor for TGF-beta [PMID:8235612]. GtoPdb lists agonist [DB:GtoPdb]. A structure shows TGF-beta bound to betaglycan, TGFBR1 and TGFBR2 [PMID:40011426]. A tumour-fibroblast loop via TGFB1-TGFBR1 is reported [PMID:39095854].","molecular_requirements":"Requires coexpression of type II receptor (TGFBR2) for ligand binding [PMID:8235612]; ligand specificity conferred by the type II receptor [PMID:8235612]. Betaglycan hands off ligand to the receptors [PMID:40011426].","affinity_potency":[],"species_and_systems":"Human proteins [PMID:8235612]; structures used TGF-beta3 variants and rat BG, with TGF-beta1 in a low-resolution cryo-EM map [PMID:40011426]; human HCC data [PMID:39095854].","localisation_and_range":"TGFB1 is flagged secreted [flag]. Receptors are membrane-bound; colocalisation seen on tumour cell membranes [PMID:39095854].","caveats":"TGFBR1 alone does not bind ligand [PMID:8235612]; the structural paper mainly used TGF-beta3 and TGF-beta2. PMID:39095854 is single-cell/spatial inference with limited direct testing. One review-only paper and one different-entity paper excluded. Affinity values not given in the dossier.","key_references":[{"PMID":"8235612","why":"TGFBR1 needs type II receptor for TGF-beta binding"},{"PMID":"40011426","why":"Structure of TGF-beta with betaglycan, TGFBR1, TGFBR2"}],"covers":["LR001443","LR004838"]},"LR006575":{"pair":"TGFB3 -> ITGB1","headline":"Integrin beta1 chain: alpha8beta1 adheres to LAP-TGF-beta3; evidence is chain-only and concerns the propeptide.","interaction_type":"functional only","direction_and_effect":"alpha8-transfected cells adhered to LAP-TGFbeta3 better than mock cells, RGD-dependent [PMID:12415008].","molecular_requirements":"The binder is the alpha8beta1 heterodimer; beta1 alone is not tested [PMID:12415008].","affinity_potency":[],"species_and_systems":"Transfected cells, adhesion assays; species not reported in our evidence.","localisation_and_range":"Ligand flagged secreted and transmembrane [flag].","caveats":"The bound species is the latency-associated peptide (LAP) complex, not mature TGF-beta. Abstract-only.","key_references":[{"PMID":"12415008","why":"alpha8beta1 adhesion to LAP-TGFbeta3"}],"covers":["LR003374","LR006575"]},"LR004847":{"pair":"TGFB3 -> TGFBR2","headline":"Directly bound by TGFBR2: a crystal structure and SPR kinetics, plus database records; TGF-beta3 is the ligand.","interaction_type":"direct binding","direction_and_effect":"TGF-beta initiates receptor assembly by binding with high affinity to the type II receptor [PMID:11850637]. GtoPdb lists the interaction as agonist [DB:GtoPdb].","molecular_requirements":"The 2.15 A structure shows the human TGFBR2 ectodomain binding both ends of homodimeric TGF-beta3 [PMID:11850637]. One dimeric ligand binds two receptors [PMID:12729750]. The type I receptor is recruited afterwards [PMID:11850637].","affinity_potency":[{"value":"Kd approximately 5pM (TGF-beta1 and -beta3)","assay":"SPR (BIACORE), immobilised type II receptor ectodomain; avidity contributes","system":"purified proteins, species unspecified","cite":"PMID:12729750"}],"species_and_systems":"Crystal structure used human proteins [PMID:11850637]. SPR papers do not state species [PMID:12729750][PMID:11382746]. The mouse pair is projected from human.","localisation_and_range":"The ligand is flagged secreted [flag]; it is also flagged transmembrane [flag]. Range is not discussed in our evidence.","caveats":"All three papers were read as abstracts only. The stated affinity is an avidity-enhanced apparent value.","key_references":[{"PMID":"11850637","why":"Crystal structure of the TGFBR2 ectodomain with TGF-beta3"},{"PMID":"12729750","why":"SPR kinetics, stoichiometry and affinity"},{"PMID":"11382746","why":"SPR kinetics of TGF-beta isoforms with type II ectodomain"}],"covers":["LR001452","LR004847"]},"LR004865":{"pair":"THBS1 -> LRP1","headline":"THBS1 binds LRP1 with high affinity; LRP1 acts as an endocytic clearance receptor, well supported by three binding papers.","interaction_type":"direct binding","direction_and_effect":"LRP1 mediates uptake and lysosomal degradation of THBS1; anti-LRP antibodies blocked 125I-TSP1 uptake in smooth muscle cells and fibroblasts but not endothelial cells [PMID:7775583]. This is clearance rather than signalling.","molecular_requirements":"The amino-terminal heparin-binding domain (residues 1-214) binds LRP [PMID:9045712]; a 1-90 fragment keeps high-affinity LRP-1 binding without heparin binding [PMID:14991768]. Binding does not need heparan sulfate proteoglycans, but endocytosis does [PMID:14991768]. Cell-surface proteoglycans are involved in clearance [PMID:7775583].","affinity_potency":[{"value":"Kd 5 nM","assay":"solid-phase binding","system":"LRP with TSP1","cite":"PMID:7775583"},{"value":"KD 10 to 25 nM","assay":"binding of GST-HBD (dimer) to purified LRP","system":"mouse TSP-1 residues 1-214","cite":"PMID:9045712"},{"value":"KD 830 nM","assay":"binding of monomeric rHBD to purified LRP","system":"mouse TSP-1 HBD","cite":"PMID:9045712"}],"species_and_systems":"Human and mouse cells and proteins (curated species human; the mouse pair is ortholog-inferred); smooth muscle cells, endothelial cells, fibroblasts, purified LRP [PMID:7775583, PMID:9045712].","localisation_and_range":"THBS1 is flagged secreted [flag]; ECM-associated protein that binds cell-surface proteoglycans before internalisation [PMID:7775583].","caveats":"Endothelial-cell uptake of TSP1 was not LRP-mediated [PMID:7775583]. Affinity depends on oligomeric state (dimeric vs monomeric HBD) [PMID:9045712]. All abstract-level except partial full text for PMID:7775583. BioGRID reconstituted-complex records agree [DB:BioGRID].","key_references":[{"PMID":"7775583","why":"Identifies LRP as endocytic THBS1 receptor, Kd 5 nM"},{"PMID":"9045712","why":"Maps binding to the N-terminal heparin-binding domain"},{"PMID":"14991768","why":"Binding separable from HSPG-dependent endocytosis"}],"covers":["LR001470","LR004865"]},"LR006584":{"pair":"THBS1 -> SCARB2","headline":"THBS1 binds a LIMPII (SCARB2) CD36-homologous peptide in solid-phase assays and plasma-membrane-targeted LIMPII confers adhesion; single abstract.","interaction_type":"direct binding","direction_and_effect":"Purified 125I-TSP1 bound immobilised GST/LIMPII in a time-dependent and saturable manner, and a plasma-membrane-targeted LIMPII chimera let melanoma cells bind TSP1 and adhere to TSP1-coated surfaces [PMID:9478926]. Effect direction not reported beyond adhesion.","molecular_requirements":"Binding was shown with a LIMPII peptide corresponding to the TSP1-binding domain of CD36, as a GST fusion, not full-length SCARB2; the site is conserved with CD36 [PMID:9478926].","affinity_potency":[],"species_and_systems":"Recombinant GST fusion in solid-phase assay; Bowes melanoma cells transfected with a chimeric LIMPII cDNA; the paper's species is not stated in the abstract, though curation labels it human [PMID:9478926]. Both pair species rows are ortholog-inferred.","localisation_and_range":"SCARB2 is a lysosomal membrane protein; surface presentation was achieved only by a plasma-membrane-targeted chimera, and cell surface LIMPII may act as an adhesion receptor only in some circumstances [PMID:9478926].","caveats":"Abstract only; peptide fragment, not full-length receptor; the physiological relevance of surface binding is uncertain. BioGRID reconstituted-complex record [DB:BioGRID].","key_references":[{"PMID":"9478926","why":"LIMPII fusion binds THBS1; chimera confers adhesion"}],"covers":["LR003383","LR006584"]},"LR003389":{"pair":"THBS4 -> ITGB5","headline":"THBS4 binds ITGB5 by immunoprecipitation in HCC cells; browser-read quote pending spot-check.","interaction_type":"direct binding","direction_and_effect":"Immunoprecipitation confirmed that THBS4 can bind ITGB1, ITGB5 and ITGA5 [PMID:32567740].","molecular_requirements":"Alpha partner for ITGB5 not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human HCC cells; mouse pair ortholog-inferred [PMID:32567740].","localisation_and_range":"THBS4 flagged secreted [flag].","caveats":"Quote is browser-read and unverified; IntAct co-IP record [DB:IntAct].","key_references":[{"PMID":"32567740","why":"THBS4 co-IP with ITGB5 in HCC"}],"covers":["LR003389","LR006590"]},"LR006593":{"pair":"THY1 -> ITGA5","headline":"Thy-1 binds alpha5beta1 integrin at single-molecule level; cooperates with syndecan-4. Single abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Thy-1 independently binds alpha5beta1 integrin and syndecan-4; with both present they bind cooperatively, forming a trimolecular complex with a 'dynamic catch' (force prolongs bond lifetime) [PMID:25216363].","molecular_requirements":"Evidence is for the alpha5beta1 heterodimer; alone binding to alpha5beta1 is sufficient, though both co-receptors together bind cooperatively [PMID:25216363].","affinity_potency":[],"species_and_systems":"Single-molecule force spectroscopy; melanoma cell mechanosignalling; ligand and receptor listed as human [PMID:25216363].","localisation_and_range":"Membrane-bound Thy-1 (not secreted [flag]) on endothelium engaging integrin on cancer cells; contact-dependent [PMID:25216363].","caveats":"Abstract only; no affinity values reported in our evidence.","key_references":[{"PMID":"25216363","why":"Thy-1/alpha5beta1/syndecan-4 dynamic catch"}],"covers":["LR003392","LR006593"]},"LR008195":{"pair":"THY1 -> ITGAM:ITGB2","headline":"Thy-1 binds the Mac-1 (alphaMbeta2) complex in cells and purified form; two abstract-only papers.","interaction_type":"direct binding","direction_and_effect":"Leukocyte adhesion to activated endothelium and transendothelial migration are mediated by Thy-1/Mac-1 [PMID:15004192].","molecular_requirements":"Complex of ITGAM and ITGB2. Purified-protein binding was shown for Mac-1 [PMID:15004192]; the alphaM I-domain also binds Thy-1 with roughly half the affinity of alphaX I-domain [PMID:15850796].","affinity_potency":[],"species_and_systems":"Human: monocytes, PMN, dermal microvascular endothelial cells, purified proteins [PMID:15004192]; recombinant I-domain assay [PMID:15850796].","localisation_and_range":"Membrane-bound partners; contact-dependent [flag].","caveats":"Abstract only. The alphaM result is a lower-affinity comparator with no absolute value [PMID:15850796]. The same complex is stored under two subunit orderings in the database.","key_references":[{"PMID":"15004192","why":"Thy-1/Mac-1 binding and transmigration"},{"PMID":"15850796","why":"alphaM I-domain binds Thy-1"}],"covers":["LR008195"]},"LR003398":{"pair":"THY1 -> ITGB3","headline":"Thy-1 binds alphavbeta3 integrin (SPR, force spectroscopy); ITGB3 row inherits heterodimer evidence.","interaction_type":"direct binding","direction_and_effect":"Thy-1 and alphavbeta3 mediate bidirectional neuron-astrocyte communication, stimulating astrocyte migration and retraction of neuronal prolongations [PMID:29212879]; anti-Thy-1 antibodies blocked astrocyte stimulation but not cell binding [PMID:18346467].","molecular_requirements":"Both alphav and beta3 needed for neuron-astrocyte association; Thy-1 binds the alphavbeta3 heterodimer [PMID:18346467].","affinity_potency":[],"species_and_systems":"Optical tweezers [PMID:29212879]; DI TNC1 astrocytes, species unspecified [PMID:18346467].","localisation_and_range":"Membrane-bound trans contact between neuron and astrocyte [PMID:18346467].","caveats":"Abstract only; beta3 alone not tested separately; no affinity values.","key_references":[{"PMID":"18346467","why":"Thy-1/alphavbeta3 SPR and astrocyte signalling"},{"PMID":"29212879","why":"Force-dependent kinetics"}],"covers":["LR003398","LR006599"]},"LR004874":{"pair":"TIMP2 -> ITGB1","headline":"TIMP-2 acts through beta1 integrin on endothelial cells (mouse system); one abstract-read paper plus BioGRID.","interaction_type":"direct binding","direction_and_effect":"TIMP-2 abrogated angiogenic-factor-induced endothelial proliferation in vitro and angiogenesis in vivo independently of MMP inhibition, requiring alpha3beta1 binding; it reduced beta1-associated PTP activity and dissociated SHP-1 from beta1 [PMID:12887919]. BioGRID has a reconstituted-complex record for TIMP2-ITGB1 [DB:BioGRID].","molecular_requirements":"Requires alpha3beta1; beta1 alone is not shown sufficient in our evidence [PMID:12887919].","affinity_potency":[],"species_and_systems":"Curated as mouse/mouse experiments; human pair is not ortholog-inferred in the interactions list, while the mouse pair is [PMID:12887919].","localisation_and_range":"TIMP2 flagged secreted; ITGB1 flagged receptor [flag].","caveats":"Abstract-only evidence; two other papers were abstract_insufficient. Species labels differ between this and the ITGA3:ITGB1 record from the same paper.","key_references":[{"PMID":"12887919","why":"TIMP-2 angiogenesis inhibition via alpha3beta1"}],"covers":["LR001479","LR004874"]},"LR004883":{"pair":"TNC -> ITGAV","headline":"AlphaV integrins bind tenascin-C in human cells (alphavbeta3, alphavbeta6); several papers, mostly abstract-only.","interaction_type":"direct binding","direction_and_effect":"Affinity purification identified alpha2beta1 and alphavbeta3 as tenascin-binding receptors on endothelial cells; alphaVbeta3 antibody gave 35% attachment inhibition [PMID:7693733]. TN-C interaction with alphavbeta3 modifies smooth muscle cell shape and EGF-dependent growth [PMID:9314546]. Oral SCC adhesion involves alpha(v) integrins [PMID:9219848].","molecular_requirements":"AlphaV pairs with beta3 or beta6 in these papers; alphavbeta3 binding is mediated by the SRRGDMS site [PMID:7693733].","affinity_potency":[],"species_and_systems":"Human cells: HUVEC [PMID:7693733], smooth muscle cells [PMID:9314546], oral SCC lines [PMID:9219848].","localisation_and_range":"Ligand flagged as secreted, non-transmembrane [flag]; presented as extracellular matrix, so acts locally on adjacent cells.","caveats":"All read as abstracts. Single-chain entry; beta partner varies. Two further rows abstract_insufficient.","key_references":[{"PMID":"7693733","why":"Affinity purification of alphavbeta3 as tenascin receptor"},{"PMID":"9314546","why":"TN-C/alphavbeta3 in SMC EGF growth"},{"PMID":"9219848","why":"alpha(v) integrins in oral SCC adhesion to TN-C"}],"covers":["LR001488","LR004883"]},"LR008618":{"pair":"TNFRSF11B -> TNFSF10","headline":"OPG (TNFRSF11B) is proposed as a decoy for TRAIL by UniProt text only; no curated paper confirms the binding.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states OPG may act as a decoy receptor for TRAIL and protect against apoptosis [DB:UniProt][PMID:22664871]. TRAIL may bind OPG, which cannot induce apoptosis [DB:UniProt][PMID:10549288][PMID:26457518]. Here OPG is the listed ligand and TRAIL the receptor, which reverses the usual decoy-receptor direction.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Three UniProt text entries [DB:UniProt]; no experimental species given.","localisation_and_range":"TRAIL is flagged secreted and transmembrane; OPG is flagged as not a receptor and not transmembrane [flag].","caveats":"No papers were confirmed: two were judged to concern a different entity. The wording 'may' and 'possibly' indicates uncertainty [DB:UniProt][PMID:26457518]. No experimental evidence is in our dossier.","key_references":[],"covers":["LR008618"]},"LR007439":{"pair":"TNFSF12 -> TNFRSF25","headline":"Evidence argues against TWEAK binding DR3 (TNFRSF25); only a UniProt annotation supports the pair.","interaction_type":"conflicting","direction_and_effect":"A binding study using human and murine TWEAK found that TWEAK and WSL-1/TRAMP (DR3) do not interact in vitro, that TWEAK binds cells lacking WSL-1/TRAMP, and that cells from knockout mice retain TWEAK interaction [PMID:11094155]. UniProt, by contrast, lists DR3 as a receptor for TWEAK [DB:UniProt].","molecular_requirements":"Not applicable; no supported interaction in our evidence.","affinity_potency":[],"species_and_systems":"Human and mouse TWEAK, in vitro binding and knockout-mouse cells [PMID:11094155]. The other verified negative row (a bladder tumour scRNA-seq study) concerns TNFSF12-TNFRSF12A, not DR3 [PMID:39386756].","localisation_and_range":"Not reported in our evidence for this pair.","caveats":"Both curated papers are abstract-level, with one abstract_insufficient. The conclusion in 11094155 is that DR3 is not the major receptor, which does not fully exclude a minor interaction.","key_references":[{"PMID":"11094155","why":"TWEAK and WSL-1/TRAMP do not interact"}],"covers":["LR007439"]},"LR004892":{"pair":"TNFSF13 -> FAS","headline":"A single 2000 paper reports APRIL (as TRDL-1alpha) coprecipitating Fas; isolated, unreplicated evidence.","interaction_type":"direct binding","direction_and_effect":"Purified FLAG-tagged TRDL-1alpha, identical in sequence to APRIL, killed Jurkat cells with kinetics like FasL, and in vitro binding showed it coprecipitated Fas and HVEM, suggesting it as an alternate ligand [PMID:10706119]. Effect: pro-death in Jurkat cells, proposed.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins and Jurkat cells [PMID:10706119]. BioGRID lists a reconstituted complex from the same paper [DB:BioGRID]. The mouse pair has no mouse experiment in our evidence.","localisation_and_range":"APRIL is flagged secreted and not transmembrane [flag].","caveats":"Only one paper, read as an abstract; the abstract says the data 'suggested' an alternate ligand role. Coprecipitation does not show Fas as a physiological receptor. No affinity data.","key_references":[{"PMID":"10706119","why":"TRDL-1alpha (APRIL) coprecipitates Fas"}],"covers":["LR001501","LR004892"]},"LR001499":{"pair":"TNFSF13B -> TNFRSF13C","headline":"BAFF binds BAFF-R, shown by co-crystal structure and binding studies; strongly supported.","interaction_type":"direct binding","direction_and_effect":"BAFF-R was identified as a third BAFF receptor with highly specific binding [PMID:11509692]; crystal structure of soluble TALL-1 with the BAFF-R extracellular domain at 2.5 A [PMID:12721620]. Annotated stimulatory [flag].","molecular_requirements":"One disulphide bridge in BAFF-R sets specificity for TALL-1 over APRIL, confirmed by in vitro binding [PMID:12721620]. Reactome shows a 3xBAFFR:BAFF trimer complex [DB:Reactome]. Soluble TALL-1 acts as a virus-like assembly [PMID:12721620].","affinity_potency":[],"species_and_systems":"Human proteins [PMID:12721620][PMID:11509692]; BAFF-R locus disrupted in A/WySnJ mice, which resemble BAFF-deficient mice [PMID:11509692].","localisation_and_range":"BAFF flagged secreted and transmembrane; BAFF-R transmembrane [flag].","caveats":"Both papers abstract only. Structures also in PDB [DB:PDB 1OQE][DB:PDB 3V56]. No affinity value in our evidence.","key_references":[{"PMID":"12721620","why":"Co-crystal structure of BAFF with BAFF-R"},{"PMID":"11509692","why":"Identification of BAFF-R as specific BAFF receptor"}],"covers":["LR001499","LR004890"]},"LR011399":{"pair":"TNN -> ITGA8:ITGB1","headline":"Database-asserted only: UniProt describes tenascin-N as a probable ligand of integrin alpha8:beta1; no curated paper evidence.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states the protein 'seems to be a ligand' for ITGA8:ITGB1, ITGAV:ITGB1 and ITGA4:ITGB1 (By similarity) [DB:UniProt]. Effect on signalling not reported in our evidence.","molecular_requirements":"Complex of ITGA8 with ITGB1 named in the UniProt text [DB:UniProt]; whether either chain alone suffices not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experimental system not reported in our evidence; the UniProt entry cites PMID 17909022 but no curated paper row exists.","localisation_and_range":"Described as an extracellular matrix protein [DB:UniProt]; entity flags give no secretion annotation.","caveats":"No papers were judged (both rows pending). Support is a similarity-based database statement only [DB:UniProt].","key_references":[],"covers":["LR011399"]},"LR004829":{"pair":"Trf -> Tfrc","headline":"Transferrin binds the transferrin receptor; three older abstract-read papers show dimeric receptor binding two transferrin molecules.","interaction_type":"direct binding","direction_and_effect":"Transferrin binds the transferrin receptor (TfR); HFE and iron-loaded transferrin compete for TfR in solution and at the cell surface [PMID:15056661]. An anti-TfR antibody precipitated radiolabelled transferrin bound to receptors [PMID:6270680].","molecular_requirements":"The active solubilized receptor is a dimer capable of binding two transferrin molecules [PMID:6268632]. Heterodimeric TfR showed no cooperativity in heterotropic ligand binding [PMID:15056661].","affinity_potency":[],"species_and_systems":"Human placental trophoblast membrane [PMID:6268632]; human MOLT-4 T-cell line [PMID:6270680]; soluble TfR and transfected cells, species not stated [PMID:15056661]. The listed pair is mouse and ortholog-inferred, so the experiments are in other species than the pair.","localisation_and_range":"Trf is flagged secreted [flag]; the receptor is a cell surface protein per the papers [PMID:6270680].","caveats":"All abstract-read; one further paper was judged abstract_insufficient. No affinity value in the dossier. Direct binding in PMID 6270680 is indirect (antibody precipitation).","key_references":[{"PMID":"15056661","why":"Competition of HFE and transferrin for TfR, no cooperativity"},{"PMID":"6268632","why":"Dimeric receptor binds two transferrin molecules"},{"PMID":"6270680","why":"Transferrin precipitated with TfR antibody in MOLT-4 cells"}],"covers":["LR004829"]},"LR006629":{"pair":"UMOD -> TRPM6","headline":"Uromodulin physically interacts with the TRPM6 channel and raises its surface abundance; one abstract-level mouse and cell study.","interaction_type":"direct binding","direction_and_effect":"UMOD enhances TRPM6 cell-surface abundance and current density from the extracellular space and impairs dynamin-dependent TRPM6 endocytosis, so effect is stabilising/increasing channel activity rather than classical agonism [PMID:30139743].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Umod-knockout mice (reduced apical Trpm6 staining in the distal convoluted tubule) plus biotinylation and whole-cell patch-clamp assays [PMID:30139743]; cell species not reported in the abstract. The mouse pair is ortholog-inferred; the human pair is the dossier's primary.","localisation_and_range":"Ligand flagged secreted [flag]; the paper reports urinary UMOD secretion rising on a low-magnesium diet in mice [PMID:30139743], acting from the extracellular space.","caveats":"Read as an abstract only. The physical interaction is stated, but the binding method and any affinity are not reported in our evidence. TRPM6 is an ion channel, not a classical receptor, and no receptor annotation flag is given beyond is_receptor.","key_references":[{"PMID":"30139743","why":"UMOD interacts with TRPM6 and increases its surface abundance"}],"covers":["LR003428","LR006629"]},"LR006638":{"pair":"UNC5C -> FLRT2","headline":"UNC5C and FLRT2 show complementary expression and mutual repulsion of mouse retinal neurons; binding is supported only by the wider screen.","interaction_type":"functional only","direction_and_effect":"Neurons repelled by Unc5C stripes expressed FLRT2 (n=26/26), and neurons repelled by FLRT2 stripes expressed Unc5C (n=30/30) [PMID:26633812]. FLRT2-transfected neurons were repelled by Unc5C stripes [PMID:26633812]. The authors propose mutual repulsion through bidirectional signalling, and describe Unc5C as a repulsive ligand for the FLRT2 receptor [PMID:26633812].","molecular_requirements":"Not reported in our evidence; full-length FLRT2 was expressed in the gain-of-function assay [PMID:26633812].","affinity_potency":[],"species_and_systems":"Mouse retinal neurons in ex vivo stripe assays and in vivo staining; the human pair is ortholog-inferred [PMID:26633812].","localisation_and_range":"Unc5C is annotated as a transmembrane receptor and FLRT2 as secreted and transmembrane [flag]. Their laminar patterns are complementary: Unc5C in S1/3/5 and FLRT2 in S2/4 of the inner plexiform layer [PMID:26633812].","caveats":"This row was judged on the abstract, with excerpts, and rests on expression and repulsion, not a binding measurement for this pair. Only a minority of neurons (5-18%) responded to stripes [PMID:26633812].","key_references":[{"PMID":"26633812","why":"FLRT2-Unc5C expression and repulsion in mouse retina"}],"covers":["LR003437","LR006638"]},"LR007079":{"pair":"VCAM1 -> ITGAD:ITGB2","headline":"Complex pair backed by UniProt and BioGRID; the one curated paper's abstract names alphaMbeta2, not alphaDbeta2.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states integrin ITGAD:ITGB2 is a receptor for ICAM3 and VCAM1 [DB:UniProt]. The eosinophil adhesion paper reports VCAM-1 modules 1 and 4 engaged by different integrins [PMID:16943205].","molecular_requirements":"Requires both ITGAD and ITGB2 chains per the complex entity [flag].","affinity_potency":[],"species_and_systems":"Human eosinophils adhering to recombinant VCAM-1 constructs [PMID:16943205].","localisation_and_range":"VCAM1 flagged secreted and transmembrane [flag].","caveats":"The curated paper was read as abstract only, and the abstract identifies alpha4beta1 and alphaMbeta2 (CD11b/18), not alphaDbeta2 [PMID:16943205]. Direct alphaDbeta2 binding is supported by PMID 10438935 only through UniProt and BioGRID [DB:UniProt][DB:BioGRID].","key_references":[{"PMID":"16943205","why":"eosinophil integrins on VCAM-1 modules 1 and 4 (names alphaMbeta2)"}],"covers":["LR007079"]},"LR004919":{"pair":"VCAM1 -> ITGB1","headline":"VCAM-1 is a ligand for VLA-4 (alpha4beta1) in adhesion assays; five confirmed rows, all abstract-level, ITGB1 chain recorded alone.","interaction_type":"functional only","direction_and_effect":"VLA-4 on transfected K-562 cells gave specific adhesion to VCAM-1 that anti-VLA-4 antibodies completely inhibited [PMID:1689216]. Myeloma cell adhesion to VCAM-1 upregulated MIP-1alpha and MIP-1beta [PMID:19057841]. Anti-alpha4 integrin reduced monocyte adhesion to human saphenous vein [PMID:12097820].","molecular_requirements":"The receptor is alpha4beta1; the alpha4 subunit was transfected and blocked, so ITGB1 alone is not shown sufficient [PMID:1689216].","affinity_potency":[],"species_and_systems":"Human cell lines and primary cells; K-562 transfectants [PMID:1689216], myeloma/stromal cells [PMID:19057841], monocytes and saphenous vein [PMID:12097820]. Mouse pair is ortholog-inferred.","localisation_and_range":"Cell-surface adhesion; VCAM1 flagged secreted and transmembrane [flag].","caveats":"All abstract only; functional evidence for the heterodimer, not ITGB1 itself. Species not stated in PMID 1689216 or 9235944. Reactome records alpha4beta1:VCAM1 [DB:Reactome].","key_references":[{"PMID":"1689216","why":"VLA-4 identified as VCAM-1 receptor"},{"PMID":"19057841","why":"VLA-4/VCAM-1 adhesion drives MIP-1 production in myeloma"},{"PMID":"12097820","why":"VCAM-1/alpha4 integrin in monocyte adhesion"}],"covers":["LR001530","LR004919"]},"LR004928":{"pair":"VEGFA -> ITGA9","headline":"VEGF-A is a direct ligand of integrin alpha9beta1, supported by one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Adhesion and migration of human endothelial cells on VEGF-A depend on alpha9beta1, and an alpha9beta1-blocking antibody inhibited VEGF-A165- or -121-induced angiogenesis [PMID:17363377].","molecular_requirements":"Cooperative input from alpha9beta1 and VEGF-R2 is needed for adhesion and migration; the beta1 partner is part of the receptor. Unlike alpha3beta1 or alphavbeta3, alpha9beta1 also binds the 121 isoform [PMID:17363377].","affinity_potency":[],"species_and_systems":"Human endothelial cells and human VEGF-A [PMID:17363377].","localisation_and_range":"Not reported in our evidence.","caveats":"Single paper read as abstract only; no affinity reported. Function requires VEGFR-2 as well [PMID:17363377].","key_references":[{"PMID":"17363377","why":"VEGF-A direct ligand of alpha9beta1"}],"covers":["LR001539","LR004928"]},"LR004937":{"pair":"VEGFC -> ITGB1","headline":"VEGF-C binds alpha9beta1 integrin; ITGB1 is credited only as a chain of this heterodimer, from a single paper.","interaction_type":"direct binding","direction_and_effect":"Recombinant VEGF-C bound purified alpha9beta1 integrin; adhesion and migration on VEGF-C were alpha9beta1-dependent in mouse embryonic fibroblasts, SW-480 cells and microvascular endothelial cells [PMID:15590642].","molecular_requirements":"ITGB1 alone is not tested; the paired alpha9 chain (ITGA9) is required by the evidence, which concerns the alpha9beta1 heterodimer [PMID:15590642].","affinity_potency":[],"species_and_systems":"Recombinant protein plus cell adhesion assays, species of the cells as stated above [PMID:15590642]. Interactions are ortholog-inferred.","localisation_and_range":"VEGFC flagged secreted and ITGB1 not flagged secreted [flag].","caveats":"Chain-only evidence: ITGB1 appears because it pairs with alpha9; beta1 pairs with many alpha chains, so this row may overstate specificity. Single abstract-read paper; no affinity.","key_references":[{"PMID":"15590642","why":"VEGF-C binds alpha9beta1 integrin"}],"covers":["LR001548","LR004937"]},"LR006647":{"pair":"VSIR -> SELPLG","headline":"VISTA binds PSGL-1 in an acid-pH-dependent way, with histidines on the VISTA rim mediating binding; single abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"VISTA engages and suppresses T cells selectively at acidic pH; antibodies that block the VISTA-PSGL-1 interaction at acidic pH reversed VISTA-mediated immune suppression in vivo [PMID:31645726]. VISTA acts as the inhibitory partner on T cells.","molecular_requirements":"Multiple histidine residues along the rim of the VISTA extracellular domain mediate binding to PSGL-1 [PMID:31645726].","affinity_potency":[],"species_and_systems":"Human protein experiments; in vivo antibody reversal reported [PMID:31645726].","localisation_and_range":"Both are flagged non-secreted transmembrane [flag]; contact-dependent signalling is implied by flags only.","caveats":"No affinity value in this dossier. Binding is strongly pH-dependent, so measured affinity at neutral pH may differ; neutral-pH values not reported in our evidence. Mouse pair is ortholog-inferred.","key_references":[{"PMID":"31645726","why":"Histidine-dependent, acid-pH VISTA binding to PSGL-1"}],"covers":["LR003446","LR006647"]},"LR004946":{"pair":"VTN -> ITGA2B","headline":"Vitronectin binds activated human platelets through the GPIIb/IIIa complex; one abstract-only paper with a measured Kd.","interaction_type":"direct binding","direction_and_effect":"Purified vitronectin bound thrombin-stimulated human platelets in a calcium-dependent, specific, saturable manner; binding was inhibited by the RGDS tetrapeptide and anti-GPIIb/IIIa antibodies, and anti-vitronectin antibodies inhibited platelet aggregation [PMID:1692034]. Database records also list the pair [DB:BioGRID] [DB:Reactome].","molecular_requirements":"The receptor in the paper is the GPIIb/IIIa complex, so ITGA2B alone is not shown to suffice; the partner chain (ITGB3) is likely needed but the paper tests the complex, not the chain [PMID:1692034]. Affinity depends on platelet activation state.","affinity_potency":[{"value":"Kd 320 nM","assay":"binding of purified vitronectin to platelets, 8,000 sites per platelet","system":"thrombin-stimulated human platelets","cite":"PMID:1692034"},{"value":"Kd 93 and 116 nM","assay":"binding to platelets","system":"epinephrine- or ADP-stimulated human platelets","cite":"PMID:1692034"}],"species_and_systems":"Human ligand and human platelets [PMID:1692034]. The mouse pair is projected from human evidence (ortholog-inferred).","localisation_and_range":"Vitronectin is flagged as secreted and not transmembrane [flag]; the integrin is a membrane receptor, so signalling is by cell contact with soluble or matrix-bound ligand. The dossier's papers do not describe range further.","caveats":"Single paper read as abstract only. Affinity varies with the activator used (320 nM versus 93 and 116 nM) [PMID:1692034]. Reactome and BioGRID entries are database assertions.","key_references":[{"PMID":"1692034","why":"Kd and RGD/antibody inhibition of vitronectin binding to stimulated platelets"}],"covers":["LR001557","LR004946"]},"LR004955":{"pair":"VTN -> PLAUR","headline":"Vitronectin binds uPAR (PLAUR) on its SMB domain; supported by one abstract-only paper and crystal structures.","interaction_type":"direct binding","direction_and_effect":"uPAR and PAI-1 bind the same site in vitronectin (the amino-terminal somatomedin B domain), and PAI-1 competes with uPAR for SMB binding; PAI-1 dissociates bound VN from uPAR and detaches U937 cells from VN [PMID:8830783]. The paper's curated effect label is agonist.","molecular_requirements":"The uPAR-binding sequence lies in the central region of the SMB domain [PMID:8830783]. Co-receptor or subunit requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human ligand and receptor; U937 cells and domain-swapping/mutagenesis studies [PMID:8830783]. The mouse pair is ortholog-inferred, not tested. Structures of the complex are listed [DB:PDB 3BT1] [DB:PDB 3BT2] [DB:PDB 4K24], with an X-ray record [DB:IntAct].","localisation_and_range":"Vitronectin is flagged secreted and uPAR is flagged secreted, receptor and transmembrane [flag]; vitronectin acts as a matrix substrate for adhesion [PMID:8830783].","caveats":"The paper was read as abstract only. Binding is competed by PAI-1, so PAI-1 levels may change signalling. No affinity is reported in our evidence.","key_references":[{"PMID":"8830783","why":"uPAR and PAI-1 share the SMB binding site on vitronectin"}],"covers":["LR001566","LR004955"]},"LR006656":{"pair":"VWF -> ITGB3","headline":"Endothelial cells adhere to VWF via beta3 integrins (alphavbeta3, GPIIb/IIIa); three confirmed abstract-only papers, functional.","interaction_type":"functional only","direction_and_effect":"Anti-beta3 antibodies fully blocked endothelial cell adhesion to vWF and detached seeded cells; anti-beta1 antibodies were poorly active [PMID:2545728]. An RGDS peptide or anti-alphavbeta3 antibody reduced VWF strings on HUVEC [PMID:18927433]. RGDS mutants of vWF lost binding to activated platelets [PMID:1737795]. Curated effect is stimulatory.","molecular_requirements":"beta3 pairs with alphav or alphaIIb; the papers do not isolate beta3 alone. RGDS is required [PMID:1737795].","affinity_potency":[],"species_and_systems":"Human endothelial cells, platelets and recombinant vWF from CHO cells [PMID:2545728] [PMID:1737795] [PMID:18927433]. Mouse pair is ortholog-inferred. IntAct and Reactome records exist [DB:IntAct] [DB:Reactome].","localisation_and_range":"Not reported in our evidence.","caveats":"All three papers are abstract-only; antibody and peptide blocking, not direct binding. Evidence is at complex level. One further paper was abstract_insufficient.","key_references":[{"PMID":"2545728","why":"anti-beta3 antibodies block endothelial adhesion to vWF"},{"PMID":"18927433","why":"alphavbeta3 anchors VWF strings"},{"PMID":"1737795","why":"RGDS mutation impairs platelet GPIIb/IIIa binding"}],"covers":["LR003456","LR006656"]},"LR004964":{"pair":"WNT1 -> FZD7","headline":"WNT1 acts through FZD7 in a functional rescue assay in human cells; no direct binding is shown.","interaction_type":"functional only","direction_and_effect":"FZD2 or FZD7 each rescued Wnt1- and Wnt3-dependent TCF4/Wnt reporter activity in FZD-knockout cells, so WNT1 signals through FZD7 to canonical beta-catenin signalling [PMID:28733458].","molecular_requirements":"FZD7 alone rescued Wnt1 signalling, though FZD2 did too, so FZD7 is sufficient but not unique [PMID:28733458]. LRP co-receptor requirement was not tested in the excerpts.","affinity_potency":[],"species_and_systems":"Human HEK293T cells with multiplex CRISPR knockout of FZD1/2/7, full text read [PMID:28733458]. The mouse pair is projected from human.","localisation_and_range":"WNT1 is flagged as secreted [flag], so signalling would be paracrine or autocrine; this comes from the annotation flag, not from a paper.","caveats":"Loss-of-function plus rescue supports functional dependence, not physical binding. Reactome lists a generic WNT:FZD plasma-membrane complex [DB:Reactome].","key_references":[{"PMID":"28733458","why":"CRISPR FZD-knockout rescue of Wnt1 by FZD7"}],"covers":["LR001575","LR004964"]},"LR007466":{"pair":"WNT1 -> FZD8:RYK","headline":"Only a computational abstract supports WNT1 binding to FZD8; RYK is not addressed.","interaction_type":"database-asserted only","direction_and_effect":"A computational SNP study reports that Wnt1 binds most strongly with FZD8-CRD among FZD-CRDs and models the Wnt1-FZD8-CRD complex by molecular dynamics [PMID:41740485]. BioGRID lists a WNT1-FZD8 reconstituted complex [DB:BioGRID].","molecular_requirements":"RYK is not individually named in the evidence; only FZD8 is supported.","affinity_potency":[],"species_and_systems":"Human sequences, in silico, abstract only [PMID:41740485].","localisation_and_range":"WNT1 is flagged as secreted [flag], so signalling would be paracrine or autocrine; this comes from the annotation flag, not from a paper.","caveats":"No wet-lab evidence for the complex; RYK unsupported.","key_references":[{"PMID":"41740485","why":"Computational Wnt1-FZD8-CRD binding"}],"covers":["LR007466"]},"LR006665":{"pair":"WNT10A -> LRP6","headline":"Functional evidence only: Wnt10a-induced signalling was blocked by anti-LRP6 Fabs in human reporter cells; abstract read only.","interaction_type":"functional only","direction_and_effect":"Wnt10a signalling was specifically inhibited by Wnt1-class anti-LRP6 Fab fragments (A1-Fab, A2-Fab) in a SuperTopFlash reporter in HEK293 cells, consistent with LRP6 acting as a Wnt co-receptor; the Fabs bind LRP6 propeller 1 [PMID:20713706].","molecular_requirements":"Wnt1-class ligands appear to depend on LRP6 propeller 1; Frizzled involvement is not reported in our evidence [PMID:20713706].","affinity_potency":[],"species_and_systems":"Human ligand and receptor, HEK293 reporter cells [PMID:20713706]; mouse entry is ortholog-inferred.","localisation_and_range":"Ligand flagged secreted; LRP6 flagged transmembrane [flag].","caveats":"Antibody blocking is indirect: it shows pathway dependence, not direct WNT10A binding. The curator note says the quote was browser-read and unverified, and the abstract text is truncated; the text is abstract only [PMID:20713706].","key_references":[{"PMID":"20713706","why":"Wnt10a-class signalling blocked by anti-LRP6 propeller 1 Fabs"}],"covers":["LR003465","LR006665"]},"LR008159":{"pair":"WNT10B -> FZD6:LRP5","headline":"Co-IP in HEK293T shows Fzd6 pulls down Wnt10b; no evidence concerns LRP5.","interaction_type":"direct binding","direction_and_effect":"Fzd6 co-precipitated SMOC-2, Wnt3a and Wnt10b, and SMOC-2 overexpression enhanced the Wnt10b-Fzd6 binding [PMID:30594556].","molecular_requirements":"Evidence concerns FZD6 and, separately, LRP6; LRP5 is not mentioned in the excerpts [PMID:30594556].","affinity_potency":[],"species_and_systems":"Co-cultured HEK293T cells with tagged human-curated proteins (Fzd6-HA, Wnt10b-myc) [PMID:30594556].","localisation_and_range":"Ligand flagged secreted [flag]; the assay used co-cultured ligand and receptor cells.","caveats":"Chain-only evidence: nothing here supports LRP5. SMOC-2, a third partner, modulates the binding. Overexpressed tagged proteins.","key_references":[{"PMID":"30594556","why":"Fzd6 co-precipitates Wnt10b in co-culture IP"}],"covers":["LR008159"]},"LR008087":{"pair":"WNT10B -> FZD7:LRP6","headline":"FZD7 is reported as the WNT10B receptor in human trophoblast cells; the LRP6 chain is not addressed.","interaction_type":"functional only","direction_and_effect":"WNT10B signalling stimulated cytoskeletal remodelling via Rac1, with FZD7 identified as the cognate receptor to up-regulate cell migration [PMID:29979633].","molecular_requirements":"Only FZD7 is named; a role for LRP6 is not reported in our evidence [PMID:29979633].","affinity_potency":[],"species_and_systems":"BeWo and JAR trophoblast cells [PMID:29979633]; pair is human.","localisation_and_range":"Ligand flagged secreted; LRP6 flagged transmembrane [flag].","caveats":"Chain-only evidence from an abstract; the complex was not tested. A second paper was review-only.","key_references":[{"PMID":"29979633","why":"FZD7 identified as cognate WNT10B receptor"}],"covers":["LR008087"]},"LR010688":{"pair":"WNT10B -> FZD8:LRP6","headline":"Complex-level pair with no curated paper; rests on one IntAct co-immunoprecipitation record only.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect (agonist or antagonist) not reported in our evidence. The only support is an IntAct record of association by anti-tag coimmunoprecipitation [DB:IntAct EBI-21797268].","molecular_requirements":"Receptor is listed as a two-chain complex; whether both chains, or either alone, are required is not reported in our evidence. ","affinity_potency":[],"species_and_systems":"Pair is human; the experimental system of the IntAct record is not reported in our evidence.","localisation_and_range":"Ligand is flagged secreted [flag]; the receptor chains are flagged as receptors, with LRP chain transmembrane [flag]. Range is not otherwise reported in our evidence.","caveats":"Only one paper row, judged review-only; the pair rests on the database record alone.","key_references":[],"covers":["LR010688"]},"LR004973":{"pair":"WNT2 -> LRP6","headline":"Functional only: WNT2 signalling is blocked by Wnt1-class anti-LRP6 Fabs; no direct WNT2-LRP6 binding shown.","interaction_type":"functional only","direction_and_effect":"Wnt2 signalling was inhibited by Wnt1-specific anti-LRP6 Fab fragments (A1-Fab, A2-Fab), implying LRP6 propeller 1 is involved [PMID:20713706].","molecular_requirements":"LRP6 is a co-receptor for Wnt; the paper does not test whether a Frizzled is needed for Wnt2 here [PMID:20713706].","affinity_potency":[],"species_and_systems":"SuperTopFlash reporter in HEK293 cells, human [PMID:20713706]. Mouse pair is projected from human evidence.","localisation_and_range":"WNT2 is annotated as secreted [flag]; LRP6 is transmembrane [flag].","caveats":"Antibody blockade is indirect evidence of the ligand-receptor contact. Full text was read in a browser and the quote is marked unverified in the curation notes [PMID:20713706].","key_references":[{"PMID":"20713706","why":"Anti-LRP6 Fabs block Wnt2-class signalling"}],"covers":["LR001584","LR004973"]},"LR003479":{"pair":"WNT2B -> FZD3","headline":"Direct binding evidence: WNT2B transfers to purified FZD3-CRD from carrier proteins (preprint, human proteins).","interaction_type":"direct binding","direction_and_effect":"WNT2B was rapidly transferred from SFRP2 and GPC4 to FZD3-CRD; the paper labels WNT2B non-canonical, and FZD3 rescue of FZD-knockout cells supports functional specificity [PMID:39229119].","molecular_requirements":"The cysteine-rich domain of FZD3 was sufficient for transfer; FZD3 or FZD6 (not FZD7) rescued FZD-knockout cells [PMID:39229119]. Carrier proteins SFRP2 or GPC4 were used.","affinity_potency":[],"species_and_systems":"Purified human proteins and HEK293 cells; adrenal context [PMID:39229119]. Mouse pair is ortholog-inferred.","localisation_and_range":"WNT2B is annotated as secreted [flag].","caveats":"bioRxiv preprint, not peer reviewed [PMID:39229119]. Binding was measured as transfer from a carrier, with no affinity value reported.","key_references":[{"PMID":"39229119","why":"WNT2B transferred to FZD3-CRD; non-canonical signalling"}],"covers":["LR003479","LR006679"]},"LR005369":{"pair":"WNT2B -> FZD7","headline":"Co-IP and knockout data support Fzd7 as a Wnt2b receptor in intestinal stem cells.","interaction_type":"direct binding","direction_and_effect":"Fzd7 binds Wnt2b by co-immunoprecipitation of epitope-tagged proteins in HEK293T cells, extending an earlier Wnt3 finding [PMID:25892522]. Conditional Fzd7 deletion causes intestinal stem cell loss in vivo [PMID:25892522].","molecular_requirements":"Fzd7 alone was tested; closely related Fzds could not fully compensate for Fzd7 loss [PMID:25892522].","affinity_potency":[],"species_and_systems":"HEK293T co-IP and mouse intestine/organoid knockouts [PMID:25892522]; the curator fields list the species as human. Mouse pair is ortholog-inferred.","localisation_and_range":"WNT2B is annotated as secreted [flag].","caveats":"Binding is shown by tagged co-IP only; the Wnt2b result is an extension in the full text and the abstract is brief. The paper says Fzd7 transmits the signal 'at least in part' [PMID:25892522].","key_references":[{"PMID":"25892522","why":"Fzd7 binds Wnt2b and is needed for stem cells"}],"covers":["LR002043","LR005369"]},"LR006683":{"pair":"WNT2B -> ROR2","headline":"Direct binding: WNT2B-SFRP2 co-immunoprecipitates with ROR2-ECD but not ROR1-ECD (preprint).","interaction_type":"direct binding","direction_and_effect":"Purified WNT2B-SFRP2 co-immunoprecipitated with ROR2-ECD but not ROR1-ECD, like non-canonical WNT5A-SFRP2; ROR2 rescued Ror1/Ror2-double-knockout cells [PMID:39229119].","molecular_requirements":"ROR2 extracellular domain is bound; the empty SFRP2 carrier did not bind, so WNT2B is the contact [PMID:39229119].","affinity_potency":[],"species_and_systems":"Purified human proteins and HEK293 cells [PMID:39229119]. Mouse pair is ortholog-inferred.","localisation_and_range":"WNT2B is annotated as secreted [flag].","caveats":"bioRxiv preprint, not peer reviewed; no affinity value. ROR2 acts as a co-receptor with FZD in this model [PMID:39229119].","key_references":[{"PMID":"39229119","why":"WNT2B-SFRP2 binds ROR2-ECD, not ROR1-ECD"}],"covers":["LR003483","LR006683"]},"LR004982":{"pair":"WNT3 -> FZD1","headline":"Functional evidence from two papers: Hfz1 enhances Wnt3-induced TCF signalling, and FZD1/2/7 knockout abolishes it.","interaction_type":"functional only","direction_and_effect":"Wnt-3a, -3, -1 and less so Wnt-2 cooperated with Hfz1 in a TCF paracrine assay [PMID:10557084]. FZD1, FZD2 and FZD7 are required for Wnt3/3a beta-catenin signalling in HEK293T cells [PMID:28733458]. UniProt also lists WNT3 as an activator [DB:UniProt].","molecular_requirements":"FZD1 acts redundantly with FZD2 and FZD7: re-expressing FZD2 or FZD7 rescued signalling after triple knockout [PMID:28733458].","affinity_potency":[],"species_and_systems":"Human cells: reporter assays in human cells [PMID:10557084] and HEK293T CRISPR mutants [PMID:28733458]. Mouse pair is ortholog-inferred.","localisation_and_range":"WNT3 annotation as secreted is not given in our evidence; localisation not reported.","caveats":"Co-IP of Hfz1 was reported with Wnt-3a and Wnt-5a, so binding alone does not set specificity [PMID:10557084]. One paper read as abstract only.","key_references":[{"PMID":"10557084","why":"Hfz1 enhances Wnt-3 TCF signalling"},{"PMID":"28733458","why":"FZD1/2/7 needed for Wnt3 signalling"}],"covers":["LR001593","LR004982"]},"LR008069":{"pair":"WNT3 -> FZD5:LRP6","headline":"No curated paper supports WNT3 -> FZD5:LRP6; the only record is a database interaction entry.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence.","molecular_requirements":"Not reported in our evidence beyond the complex name.","affinity_potency":[],"species_and_systems":"Species of the database experiment not reported in our evidence; the pair is annotated human.","localisation_and_range":"Ligand is flagged secreted [flag]; range not reported in our evidence.","caveats":"No paper was confirmed for this pair (outcomes: review_only, abstract_insufficient, different_entity). The one IntAct record is a surface plasmon resonance entry for accession pair O75581-P56703 [DB:IntAct] and does not identify the Frizzled member [PMID:31036956].","key_references":[],"covers":["LR008069"]},"LR003488":{"pair":"WNT3 -> ROR2","headline":"Human Ror2 co-immunoprecipitates with Wnt3 and antagonises Wnt3 canonical signalling; binding does not activate Ror2.","interaction_type":"direct binding","direction_and_effect":"Ror2 physically interacts with Wnt3 and Wnt1 by immunoprecipitation; it antagonised Wnt3-mediated stabilisation of cytosolic beta-catenin and inhibited Wnt3 reporter activity, while potentiating Wnt1 reporter activity [PMID:15388793]. Neither ligand altered Ror2 autophosphorylation [PMID:15388793].","molecular_requirements":"Not reported in our evidence beyond Ror2 acting alone in osteoblastic cells.","affinity_potency":[],"species_and_systems":"Human Ror2 in osteoblastic cells [PMID:15388793]; mouse pair is ortholog-inferred.","localisation_and_range":"Ligand is flagged secreted [flag]; range not reported in our evidence.","caveats":"Abstract only; immunoprecipitation does not show direct contact; no affinity. Effect is context-dependent (antagonist for Wnt3, opposite for Wnt1).","key_references":[{"PMID":"15388793","why":"Ror2 binds Wnt3 and antagonises it in osteoblasts"}],"covers":["LR003488","LR006688"]},"LR001598":{"pair":"WNT3 -> RYK","headline":"Wnt3 repels retinal axons via Ryk in a concentration-dependent manner, with Frizzled mediating attraction; functional in vivo evidence only.","interaction_type":"functional only","direction_and_effect":"Wnt3 repulsion of retinal ganglion cell axons is mediated by Ryk, whereas attraction at lower concentrations is mediated by Frizzled(s) [PMID:16280981]. Dominant-negative Ryk shifted axon termination zones medially [PMID:16280981].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Chick optic tectum and mouse superior colliculus; dossier labels ligand human and receptor mouse [PMID:16280981]. Human pair ortholog-inferred. Abstract only.","localisation_and_range":"Wnt3 forms a medial-lateral decreasing gradient in tissue, consistent with a diffusing guidance cue [PMID:16280981].","caveats":"Binding between Wnt3 and Ryk is not shown in the abstract. Outcome is concentration-dependent, repulsive via Ryk.","key_references":[{"PMID":"16280981","why":"Ryk-mediated Wnt3 repulsion in retinotectal mapping"}],"covers":["LR001598","LR004987"]},"LR001589":{"pair":"WNT3A -> FZD7","headline":"WNT3A binds the FZD7 cysteine-rich domain tightly and signals through FZD7 in a rescue system; one source is browser-read.","interaction_type":"direct binding","direction_and_effect":"WNT-3A showed strong binding (++++, KD < 10 nm) to the FZD4/5/7/8 CRDs [PMID:25605717]. Wnt3a induced signaling through a broad spectrum of FZD receptors in FZD-mutant cells [PMID:28733458].","molecular_requirements":"Binding was to FZD CRD-Fc fusions by bio-layer interferometry [PMID:25605717]. Cells with FZD1,2,7 mutated were unresponsive to canonical Wnts and were rescued by FZD/Wnt combinations [PMID:28733458].","affinity_potency":[{"value":"KD < 10 nm","assay":"Bio-layer interferometry, purified WNT-3A on FZD CRD-Fc, FZD4/5/7/8 grouped","system":"purified proteins","cite":"PMID:25605717"}],"species_and_systems":"Curation lists mouse proteins for PMID:25605717 and human for PMID:28733458 (HEK293T CRISPR mutants). Human and mouse versions of the pair are listed.","localisation_and_range":"WNT3A carries a secreted flag and no transmembrane flag [flag], so it acts as a secreted ligand; range is not reported in our evidence.","caveats":"The binding quote from PMID:25605717 is flagged in the curation notes as browser-read, unverifiable, spot-check pending. The KD bound covers FZD4/5/7/8 together, not FZD7 alone. PMID:28733458 was read as abstract only here.","key_references":[{"PMID":"25605717","why":"Bio-layer interferometry: strong WNT-3A binding to FZD CRDs"},{"PMID":"28733458","why":"Functional rescue map including FZD7"}],"covers":["LR001589","LR004978"]},"LR006692":{"pair":"WNT3A -> GPC3","headline":"WNT3A binds the GPC3 protein core directly in pull-down and co-IP; mutation of a groove around F41 abolishes binding.","interaction_type":"direct binding","direction_and_effect":"GPC3 acts as a Wnt co-receptor that promotes Wnt/beta-catenin activation; mutating the groove inhibits Wnt3a binding and beta-catenin activation [PMID:30963603].","molecular_requirements":"Binding is HS-chain independent: GPC3 without heparan sulfate chains still bound Wnt3a, and F41 with W260, Y264 and M269 are needed. The groove matters most when FZD is not abundant [PMID:30963603].","affinity_potency":[],"species_and_systems":"Purified hFc-GPC3 pulled down recombinant human Wnt3a; co-IP in HEK293T cells; HCC xenografts in nude mice [PMID:30963603]. Human pair, mouse version projected from human.","localisation_and_range":"Ligand flagged secreted, GPC3 not flagged secreted [flag]; GPC3 is described as an HSPG co-receptor [PMID:30963603].","caveats":"Binding sites on Wnt3a were mapped partly by docking models; GPC3 also bound Wnt1, Wnt5b and Wnt8a, so it is not Wnt3a-specific [PMID:30963603]. UniProt also lists the interaction [DB:UniProt].","key_references":[{"PMID":"30963603","why":"pull-down, co-IP, mutagenesis of the GPC3 groove"}],"covers":["LR003492","LR006692"]},"LR003497":{"pair":"WNT4 -> FZD1","headline":"WNT4-FZD1 rests on one co-IP result in mouse cells; UniProt says FZD1 is not clearly activated by WNT4.","interaction_type":"direct binding","direction_and_effect":"Co-IP found a Wnt4-Fzd1 binding complex [PMID:31216173].","molecular_requirements":"Complexes with LRP5 and LRP6 were also seen (Wnt4-LRP5, Wnt4-LRP6, LRP5-Fzd1) [PMID:31216173].","affinity_potency":[],"species_and_systems":"Co-IP in MC3T3 (mouse) cells, per curator note [PMID:31216173]. Human pair is ortholog-inferred.","localisation_and_range":"Ligand flagged secreted [flag].","caveats":"Result was browser-read and not spot-checked. UniProt says FZD1 is apparently not activated by WNT4 [DB:UniProt], so effect direction is uncertain.","key_references":[{"PMID":"31216173","why":"co-IP of Wnt4 with Fzd1 in MC3T3 cells"}],"covers":["LR003497","LR006697"]},"LR004991":{"pair":"WNT5A -> FZD2","headline":"Wnt5a binds Fz2 and competes with Wnt3a in vitro and in cells, and Wnt5a-Fz2 signalling acts through Rac and calcium; well supported.","interaction_type":"direct binding","direction_and_effect":"Wnt5a activated Rac, requiring Frizzled2 and Ror1 or Ror2 [PMID:19910923]. Wnt5a also competed with Wnt3a for Fz2 binding, inhibiting the beta-catenin pathway [PMID:19910923]. Xwnt-5a enhanced rat Frizzled-2-driven intracellular calcium release via G-protein subunits [PMID:9389482].","molecular_requirements":"Fz2 and Ror1 or Ror2 were required for Rac activation [PMID:19910923]. The FZD2 CRD alone binds WNT-5A [PMID:25605717]. LRP involvement not reported for this pair in our evidence.","affinity_potency":[{"value":"KD = 22\u201326 nm","assay":"Bio-layer interferometry, WNT-5A binding to FZD CRD-Fc, reported jointly for the FZD1/2/4 CRDs","system":"mouse proteins, in vitro","cite":"PMID:25605717"}],"species_and_systems":"Species not specified for the binding paper [PMID:19910923]; mouse proteins for the BLI data [PMID:25605717]; rat Frizzled-2 with Xenopus Wnt-5a in the calcium study [PMID:9389482]. The dossier includes a mouse pair and a projected human pair.","localisation_and_range":"WNT5A is flagged secreted and not transmembrane [flag], so signalling would be paracrine or autocrine by this annotation.","caveats":"Two of the three papers were read as abstract only. The affinity paper is a browser read with an unverifiable quote [PMID:25605717]. The 1997 study used rat and Xenopus reagents although tagged human [PMID:9389482]. Reactome and BioGRID records support binding [DB:Reactome][DB:BioGRID].","key_references":[{"PMID":"19910923","why":"Wnt5a binds Fz2, competes with Wnt3a, activates Rac"},{"PMID":"25605717","why":"BLI KD for WNT-5A with FZD CRDs"},{"PMID":"9389482","why":"Wnt-5a and Frizzled-2 trigger calcium release via G proteins"}],"covers":["LR001602","LR004991"]},"LR007691":{"pair":"WNT5A -> FZD8:LRP6","headline":"Database-asserted only: a single BioGRID record; no verified paper for the FZD8:LRP6 complex.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence.","molecular_requirements":"BioGRID records LRP6-WNT5A by affinity capture-Western [DB:BioGRID 692083]; FZD8 involvement in this complex is not shown in our evidence.","affinity_potency":[],"species_and_systems":"Species and system not reported in our evidence.","localisation_and_range":"Ligand flagged secreted; FZD8 flagged non-secreted [flag].","caveats":"Four judged papers were review-only or abstract_insufficient, so none verified the pair. Complex assignment rests on a binary record.","key_references":[],"covers":["LR007691"]},"LR008546":{"pair":"WNT5B -> FZD3","headline":"WNT5B, FZD3 and DVL3 interact in NSCLC cells to drive WNT-PCP signalling; one abstract-level paper.","interaction_type":"functional only","direction_and_effect":"Stimulatory: FZD3 recruits DVL3 to the membrane in a WNT5B-dependent manner and activates JNK via RAC1 [PMID:39094673].","molecular_requirements":"DVL3 and its DEP domain are needed; deleting the DEP domain abrogated the effects [PMID:39094673]. LRP co-receptor need not reported in our evidence.","affinity_potency":[],"species_and_systems":"NSCLC specimens and NSCLC cell lines, overexpression and knockdown; cell species not stated in the abstract [PMID:39094673].","localisation_and_range":"Ligand is annotated as secreted [flag], so paracrine or endocrine range is implied by the annotation only.","caveats":"Abstract only. Direct WNT5B-FZD3 binding is not shown, only an interaction among WNT5B, FZD3 and DVL3 [PMID:39094673]. Two further papers were review-only or insufficient.","key_references":[{"PMID":"39094673","why":"WNT5B-FZD3-DVL3 PCP signalling in NSCLC"}],"covers":["LR008546"]},"LR007709":{"pair":"WNT5B -> FZD3:LRP6","headline":"Only FZD3 itself is supported (NSCLC PCP signalling); LRP6 involvement is not shown.","interaction_type":"functional only","direction_and_effect":"Stimulatory through FZD3: WNT5B-dependent DVL3 recruitment and JNK activation via RAC1 in NSCLC cells [PMID:39094673].","molecular_requirements":"The abstract names FZD3 and DVL3, not LRP6; the complex requirement is not reported in our evidence. Since the pathway is described as non-canonical WNT-PCP, LRP6 need is unproven [PMID:39094673].","affinity_potency":[],"species_and_systems":"NSCLC specimens and cell lines; species of cells not stated [PMID:39094673].","localisation_and_range":"Ligand is annotated as secreted [flag], so paracrine or endocrine range is implied by the annotation only.","caveats":"Evidence is for FZD3 alone and the abstract only; the complex pair rests on this one paper. Other papers were review-only or insufficient.","key_references":[{"PMID":"39094673","why":"WNT5B-FZD3-DVL3 signalling in NSCLC"}],"covers":["LR007709"]},"LR006719":{"pair":"WNT7A -> ADGRA2","headline":"WNT7A does not bind ADGRA2 alone in our evidence; the paper shows RECK binds WNT7A and ADGRA2 acts with RECK.","interaction_type":"conflicting","direction_and_effect":"The curated paper reports that WNT7A binds soluble RECK, cell-surface RECK and the GPR124 (ADGRA2):RECK complex, but WNT7A did not appreciably bind sGPR124-Fc and was not pulled down with bSNAP-GPR124 [PMID:30304675]. The ADGRA2 ectodomain mediates RECK/WNT7-induced canonical signalling [PMID:30304675]; UniProt says it works with RECK to let endothelial cells respond to Wnt7 [DB:UniProt].","molecular_requirements":"ADGRA2 needs RECK as the WNT7 binder, with FZD and LRP co-receptors; RECK and WNT7A form a 1:1 complex that stabilises active monomeric WNT7A [PMID:30304675].","affinity_potency":[],"species_and_systems":"Human proteins in HEK293 cells, plus rat brain vessels for the RECK-GPR124 association [PMID:30304675]; the mouse pair is projected from human evidence.","localisation_and_range":"WNT7A is flagged secreted and non-transmembrane [flag]; ADGRA2 is flagged transmembrane [flag]; RECK is GPI-anchored at the cell surface [PMID:30304675].","caveats":"The paper itself shows WNT7A binds RECK, not GPR124 alone, so the direct_binding label for WNT7A to ADGRA2 is not supported by the text shown; the abstract's 'binds the GPR124:RECK complex' is complex-level.","key_references":[{"PMID":"30304675","why":"WNT7A binds RECK and the GPR124:RECK complex, not GPR124 alone"}],"covers":["LR003519","LR006719"]},"LR008078":{"pair":"WNT7A -> FZD5:LRP6","headline":"Functional evidence in rat PC12 cells supports a Frizzled-5.LRP6 route for WNT7A; abstract only.","interaction_type":"functional only","direction_and_effect":"WNT7A can specifically act via a Frizzled-5.LRP6 receptor complex in PC12 cells, antagonised by Dickkopf-1 and Dickkopf-3; readouts were beta-catenin stability and TCF luciferase [PMID:12857724].","molecular_requirements":"Both FZD5 and LRP6 implicated; the cells also express Frizzled-2 and -7 [PMID:12857724].","affinity_potency":[],"species_and_systems":"Rat pheochromocytoma PC12 cells [PMID:12857724].","localisation_and_range":"WNT7A is flagged secreted and non-transmembrane [flag]; LRP6 is flagged transmembrane [flag].","caveats":"Abstract only; functional, not binding, evidence; three review-only rows.","key_references":[{"PMID":"12857724","why":"WNT7A acts via Frizzled-5.LRP6 in PC12 cells"}],"covers":["LR008078"]},"LR006728":{"pair":"WNT7B -> FZD7","headline":"WNT7B-FZD7 is supported by loss-of-function data in neurons; abstract only.","interaction_type":"functional only","direction_and_effect":"Fz7 was identified as the receptor for Wnt7b-mediated dendrite growth; loss of Fz7 prevented Wnt7b from promoting arborisation and caused dendritic defects in mouse hippocampus; signalling induced CaMKII and JNK phosphorylation, non-canonical [PMID:29898920].","molecular_requirements":"No co-receptor reported in our evidence.","affinity_potency":[],"species_and_systems":"Hippocampal neurons and mouse hippocampus in vivo; curator lists human ligand and receptor [PMID:29898920].","localisation_and_range":"Ligand is flagged secreted and non-transmembrane [flag], so paracrine or autocrine action is expected; the paper's own data on range are not reported in our evidence.","caveats":"Abstract only. Functional requirement, not direct binding.","key_references":[{"PMID":"29898920","why":"Fz7 required for Wnt7b dendrite growth"}],"covers":["LR003528","LR006728"]},"LR005378":{"pair":"WNT7B -> FZD8","headline":"WNT7B induces canonical signalling via FZD8 (and FZD5) in a FZD-knockout reporter system; functional, not binding, evidence.","interaction_type":"functional only","direction_and_effect":"Wnt7b induced canonical Wnt signalling via FZD5 and FZD8 in rescue experiments [PMID:28733458].","molecular_requirements":"FZD8 alone sufficed in the rescue setup; no co-receptor requirement is reported in our evidence.","affinity_potency":[],"species_and_systems":"Human ligand and receptor constructs in HEK293 reporter cells lacking multiple FZDs [PMID:28733458]. The mouse pair is projected from human evidence.","localisation_and_range":"WNT ligand is flagged secreted and not transmembrane [flag], so signalling would be paracrine or autocrine; no paper in our evidence measured range.","caveats":"Single paper, a functional rescue map rather than a binding assay. FZD5 and FZD8 are described as highly similar and promiscuous, so paralog redundancy is likely [PMID:28733458].","key_references":[{"PMID":"28733458","why":"Wnt-FZD functional interaction map in HEK293 knockout cells"}],"covers":["LR002052","LR005378"]},"LR008096":{"pair":"WNT7B -> FZD8:LRP6","headline":"Same single 2026 abstract as the FZD8:LRP5 entry; supports WNT7B to FZD8, nothing on LRP6.","interaction_type":"functional only","direction_and_effect":"The authors suggest macrophage-secreted Wnt7b bound the FZD8 receptor on fibroblast-like synoviocytes (FLSs), activating Wnt/beta-catenin signalling [PMID:42393256].","molecular_requirements":"FZD8 only; LRP6 is not mentioned in the available abstract text, so it is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Collagen-induced arthritis mice and macrophage-FLS co-culture [PMID:42393256]. Species of the co-culture cells is not reported in our evidence.","localisation_and_range":"Macrophage-derived Wnt7b acting on neighbouring FLSs (paracrine) [PMID:42393256]; ligand flagged secreted [flag].","caveats":"Abstract only, truncated in the dossier. The evidence for the LRP6 chain is absent; the entry rests on FZD8. The same paper backs the LRP5 variant, so the two complex entries are not independent.","key_references":[{"PMID":"42393256","why":"Wnt7b to FZD8 in macrophage-FLS communication"}],"covers":["LR008096"]},"LR008177":{"pair":"WNT8A -> FZD8:LRP5","headline":"WNT8A signalling via FZD8:LRP5 supported by one functional paper; LRP5 co-receptor is not tested.","interaction_type":"functional only","direction_and_effect":"Wnt8a induced signalling via FZD5 and FZD8 in reporter cells [PMID:28733458].","molecular_requirements":"Evidence concerns the Frizzled chain only; LRP5 involvement is not reported in our evidence.","affinity_potency":[],"species_and_systems":"HEK293-type reporter cells with FZD knockouts [PMID:28733458]; species not stated in this record.","localisation_and_range":"WNT ligand is flagged secreted and not transmembrane [flag], so signalling would be paracrine or autocrine; no paper in our evidence measured range.","caveats":"The complex pair rests on a FZD-only result, so it is chain-only evidence; other judged papers were review_only or abstract_insufficient.","key_references":[{"PMID":"28733458","why":"Wnt-FZD functional interaction map"}],"covers":["LR008177"]},"LR006737":{"pair":"WNT9A -> EGFR","headline":"EGFR is required as a cofactor for WNT9A-FZD9 signalling; functional evidence, with binding to EGFR only suggested.","interaction_type":"functional only","direction_and_effect":"EGFR is required as a cofactor for Wnt9a-Fzd9b signalling; EGFR-mediated phosphorylation of a Fzd9b tail tyrosine promotes internalisation of the signalosome [PMID:31110287]. EGFR knockdown reduced cell-surface Wnt9a binding, including without Fzd9b, which the authors say suggests direct binding [PMID:31110287].","molecular_requirements":"EGFR acts together with FZD9 (Fzd9b in zebrafish) and LRP6; cetuximab, which blocks EGFR ligand binding, dampened the signal [PMID:31110287].","affinity_potency":[],"species_and_systems":"Zebrafish in vivo, human embryonic stem cells and HEK293T cells [PMID:31110287]. The mouse pair is projected from human evidence (ortholog-inferred).","localisation_and_range":"Secreted ligand per the entity annotation flag [flag]; paracrine range is inferred from that flag only, not reported in the papers.","caveats":"Direct Wnt9a-EGFR binding is inferred from knockdown, not measured in our evidence. EGFR acts as a cofactor of FZD9, not as a stand-alone Wnt receptor. Dossier text is from both abstract and excerpts.","key_references":[{"PMID":"31110287","why":"Shows EGFR is a required cofactor for Wnt9a-Fzd9b signalling."}],"covers":["LR003537","LR006737"]},"LR005387":{"pair":"WNT9B -> FZD8","headline":"WNT9B binds mouse Fz8 CRD only weakly by biolayer interferometry and induces FZD8 signalling in a human reporter map.","interaction_type":"direct binding","direction_and_effect":"Wnt9b binds Fz8 CRD only very weakly compared with Wnt3a, Wnt5a and Wnt5b [PMID:20093360]; Wnt9b induced canonical signalling with FZD5 and FZD8 in a reporter assay [PMID:28733458].","molecular_requirements":"Wnt9b binds a different part of the LRP6 extracellular domain (E1E2) from Wnt3a; the Fz8 CRD was the soluble Frizzled fragment tested [PMID:20093360].","affinity_potency":[{"value":"KD 482 nM","assay":"biolayer interferometry (Octet), Wnt9b to Fz8 CRD-Fc","system":"purified mouse Fz8 CRD, purified Wnt9b","cite":"PMID:20093360"}],"species_and_systems":"Binding used purified mouse Fz8 CRD and Wnt (mouse) [PMID:20093360]; signalling in human HEK293 FZD panel [PMID:28733458].","localisation_and_range":"WNT9B is flagged as secreted [flag], so signalling would be paracrine; the receptor is a membrane receptor [flag].","caveats":"Binding is very weak (482 nM) and uses a CRD fragment only; the Wnt5a and Wnt5b KD values (50 nM, 36 nM) in the same paper are tighter [PMID:20093360]. The full-text reporter result is functional only.","key_references":[{"PMID":"20093360","why":"Wnt9b KD 482 nM to Fz8 CRD by biolayer interferometry"},{"PMID":"28733458","why":"WNT9B signals via FZD8 in rescue reporter map"}],"covers":["LR002061","LR005387"]},"LR006746":{"pair":"WNT9B -> LRP5","headline":"WNT9B signalling through LRP5 requires LRP5 together with LRP6 in mouse cells; one abstract-level paper.","interaction_type":"functional only","direction_and_effect":"Wnt1, Wnt9b and Wnt10b require both LRP5 and LRP6 to signal at endogenous levels; curators label it agonist [PMID:22433869].","molecular_requirements":"Both LRP5 and LRP6 are required for this ligand subgroup; Wnt3a prefers LRP6 and needs only one; an LRP5-6 heteromer was documented by IFAST immunoprecipitation [PMID:22433869].","affinity_potency":[],"species_and_systems":"Mouse embryonic fibroblasts, mammary epithelial cells and mammary outgrowths in vivo; human pair is ortholog-inferred [PMID:22433869].","localisation_and_range":"WNT9B is flagged as secreted [flag], so signalling would be paracrine; the receptor is a membrane receptor [flag].","caveats":"Functional requirement only, no direct Wnt9b-LRP5 binding; when either LRP is overexpressed the requirement for both disappears. Abstract level only.","key_references":[{"PMID":"22433869","why":"LRP5 and LRP6 both needed for Wnt9b response"}],"covers":["LR003546","LR006746"]},"LR012389":{"pair":"ZNRF3 -> FZD7:LRP6","headline":"Database-asserted only: ZNRF3 (an E3 ligase) is listed as inhibiting a FZD:LRP receptor complex; no curator-verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Marked inhibitory in the resource, with ZNRF3 acting as a membrane receptor-receptor regulator rather than a classical secreted ligand [flag]. UniProt states ZNRF3 interacts with LRP6, FZD4, FZD5, FZD6 and FZD8 [PMID:22575959][DB:UniProt]; IntAct records anti-bait co-immunoprecipitation (Q9ULT6-O75581) [DB:IntAct]; BioGRID records FZD7 - ZNRF3: Affinity Capture-Western; ZNRF3 - FZD7: Affinity Capture-Western; ZNRF3 - LRP6: Affinity Capture-Western; LRP6 - ZNRF3: Affinity Capture-Western [DB:BioGRID]; Reactome lists ZNRF3,RNF43 binding the FZD:LRP5/6 receptor complex [DB:Reactome]. Functional effect not reported in our evidence.","molecular_requirements":"The listed FZD7 partner is not named in the UniProt statement; LRP6 evidence is present [DB:UniProt]. Whether FZD or LRP alone suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human. Experimental system not reported in our evidence beyond the database assay labels.","localisation_and_range":"ZNRF3 is flagged as a receptor, not secreted [flag]; this is a membrane-level interaction.","caveats":"All papers for this pair are pending or insufficient; support comes only from databases. The pair is a receptor-receptor complex projection and a given FZD paralog may not have been tested individually.","key_references":[],"covers":["LR012389"]},"LR003596":{"pair":"AGT -> AGTR2","headline":"Angiotensin-derived peptide (Ang A / Ang II) binds and activates AT2 (AGTR2); well supported by binding and functional papers, mostly abstract-read.","interaction_type":"direct binding","direction_and_effect":"Agonist at AT2. Ang A has higher affinity for AT2 than Ang II [PMID:17138938], while a later study reports similar affinity for AT1 and AT2 and no AT2 contribution to pressor or renal responses in vivo [PMID:21464395]. In mouse AgRP neurons, Ang-II stimulation was blocked by the AT2R antagonist PD-123319 [PMID:37540598]. In human proximal tubular cells, Ang II/AT2R engagement was linked to apoptosis [PMID:15930094].","molecular_requirements":"Single receptor chain (AGTR2). The ligand is the processed octapeptide (Ang A or Ang II), not full-length AGT; the entity is named angiotensin A [PMID:17138938].","affinity_potency":[],"species_and_systems":"Human recombinant and tissue systems (HEK-293 cells, COS-7 cells) [PMID:21542804][PMID:8185599]; rat kidney and rat/mouse in vivo [PMID:17138938][PMID:21464395]; mouse AgRP neuron recordings [PMID:37540598]. The dossier covers human and mouse pairs, neither ortholog-inferred.","localisation_and_range":"Ligand flagged secreted and receptor flagged transmembrane [flag]; plasma presence of Ang A is reported [PMID:17138938].","caveats":"Most papers were read as abstracts only. Several describe Ang II or Ang A, not AGT itself. Binding at AT2 was functionally silent in one in vivo study [PMID:21464395]. A numeric affinity is not reported in a quotable form in our evidence.","key_references":[{"PMID":"21542804","why":"Systematic peptide binding at AT1R/AT2R in HEK-293 cells"},{"PMID":"17138938","why":"Ang A has higher AT2 affinity than Ang II"},{"PMID":"8185599","why":"Human AT2 cloning with specific angiotensin analog binding in COS-7 cells"}],"covers":["LR000046","LR003596"]},"LR000869":{"pair":"IL17A -> IL17RA","headline":"IL-17A binds IL-17RA, a chain of the IL-17RA/IL-17RC complex; direct binding reported in two abstract-read papers.","interaction_type":"direct binding","direction_and_effect":"Agonist. IL-17A activity is inhibited by soluble IL-17RA, and IL-17 antibodies to the receptor blocked IL-17-induced cytokine production in human fibroblasts [PMID:18684971][PMID:9367539].","molecular_requirements":"Signalling by the cytokines depends on the IL-17RA/IL-17RC complex [PMID:18684971]. UniProt describes IL17RA and IL17RC as forming complexes with 2:1 receptor-to-cytokine stoichiometry and an asymmetric IL17A homodimer with one IL17RA [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human cytokine and human receptor; SPR and bronchial epithelial cell assays [PMID:18684971]; human receptor cloned from a T cell library, foreskin fibroblasts [PMID:9367539]. Mouse pair listed, not ortholog-inferred.","localisation_and_range":"Ligand flagged secreted [flag]; paracrine range follows from that annotation only.","caveats":"Both papers were read as abstracts. The 1997 binding was low affinity [PMID:9367539]; SPR affinities for IL-17RA differ between cytokines but values are not reported in our evidence [PMID:18684971]. The receptor name in the entity is given as interleukin-17C receptor [flag].","key_references":[{"PMID":"18684971","why":"SPR and soluble receptor data for IL-17A with IL-17RA/RC"},{"PMID":"9367539","why":"Cloning of human IL-17R and low-affinity IL-17 binding"}],"covers":["LR000869","LR004299"]},"LR004388":{"pair":"KNG1 -> ITGB2","headline":"Cleaved kininogen (HKa) binds the Mac-1 integrin (ITGAM:ITGB2) directly with nanomolar affinity; single abstract-read paper.","interaction_type":"direct binding","direction_and_effect":"HKa binds Mac-1 and blocks adhesion of Mac-1-transfected cells to fibrinogen and ICAM-1, so it acts as a blocker of Mac-1 adhesion [PMID:10845911].","molecular_requirements":"The ligand is cleaved high molecular weight kininogen (HKa), a KNG1 product. The evidence is for the Mac-1 heterodimer (CD11b/CD18), not ITGB2 alone [PMID:10845911].","affinity_potency":[{"value":"Kd 3.2x10(-9) mol/L","assay":"IAsys resonant mirror optical biosensor, purified Mac-1","system":"cell-free","cite":"PMID:10845911"},{"value":"Kd 62 nmol/L","assay":"labeled HKa binding","system":"Mac-1-transfected HEK 293 cells","cite":"PMID:10845911"}],"species_and_systems":"Human HKa and human Mac-1, in HEK 293 transfectants and a cell-free system [PMID:10845911]. The mouse pair is ortholog-inferred.","localisation_and_range":"Ligand flagged secreted [flag]; BioGRID lists a reconstituted complex [DB:BioGRID].","caveats":"One paper, read as abstract only. ITGB2 pairs with ITGAM here, so the alpha chain is needed.","key_references":[{"PMID":"10845911","why":"Direct HKa-Mac-1 binding by biosensor and cell assays"}],"covers":["LR000966","LR004388"]},"LR002687":{"pair":"GDF6 -> ACVR2A","headline":"Supported by SPR binding and shRNA knockdown; ACVR2A is a lower-affinity type II receptor for GDF6 acting as agonist.","interaction_type":"direct binding","direction_and_effect":"GDF6 (BMP13) is an agonist. Recombinant BMP13 bound ACVR2A by surface plasmon resonance, with BMP12 and BMP2 binding comparably [PMID:21702718]. In MC3T3 cells, ActRIIA shRNA suppressed GDF6 signalling, so ActRIIA is a required type II receptor [PMID:16049014].","molecular_requirements":"Type II receptor with a type I partner: ALK3 or ALK6 overexpression conferred GDF6 signalling, and ALK3 shRNA suppressed it [PMID:16049014]. BMPR2 and ACVR2B also bound BMP13 [PMID:21702718].","affinity_potency":[{"value":"KD (kin) 15.1 nM","assay":"surface plasmon resonance, 1:1 Langmuir fit, rhBMP13 (GDF6) on ACVR2A","system":"recombinant human proteins","cite":"PMID:21702718"}],"species_and_systems":"Human recombinant ligands and receptors for SPR [PMID:21702718]; MC3T3 cells (mouse line, species of experiment not stated in dossier) for knockdown [PMID:16049014]. The mouse pair is ortholog-inferred.","localisation_and_range":"GDF6 is annotated secreted [flag]; ACVR2A transmembrane [flag]; paracrine signalling.","caveats":"Both papers read as abstract only, though SPR excerpts come from full text. The binding paper refers to GDF6 as BMP13. ACVR2A affinity is more than 10-fold weaker than for type I receptors [PMID:21702718].","key_references":[{"PMID":"21702718","why":"SPR binding of BMP13 (GDF6) to ACVR2A with KD."},{"PMID":"16049014","why":"ActRIIA knockdown suppresses GDF6 signalling."}],"covers":["LR002687","LR005952"]}};